async function triggerLibraryRefresh(fullRescan = false) {
  const indicator = document.getElementById('scan-indicator');
  if (!indicator) return;
  if (state.status?.scan_in_progress || state.status?.relations_in_progress) {
    showToast('Library scan is already running.', 'info', 2200);
    return false;
  }
  if (state.status?.covers_in_progress) {
    return false;
  }
  const previousStatus = { ...state.status };
  const action = claimLibraryStatusAction(true);
  state.ui.scanCancellationAcknowledged = false;
  indicator.classList.remove('is-done', 'is-idle');
  indicator.classList.add('is-busy');
  indicator.title = 'Starting library scan...';
  startStatusIndicatorImmediately({
    scan_in_progress: true,
    scan_processed: 0,
    scan_total: 0,
    relations_in_progress: false,
    relations_processed: 0,
    relations_total: 0,
  });
  try {
    const response = await fetch('/refresh-api', {
      method: 'POST',
      headers: { Accept: 'application/json', 'Content-Type': 'application/json' },
      body: JSON.stringify({ full_rescan: Boolean(fullRescan) }),
    });
    const data = await response.json().catch(() => ({}));
    // Reads taken before HTTP acceptance may still contain the pre-start snapshot.
    if (!settleLibraryStatusAction(action)) return false;
    if (response.status === 409 && data?.already_running) {
      updateStatusIndicator(previousStatus);
      showToast('Library scan is already running.', 'info', 2200);
      scheduleStatusPoll(250);
      return false;
    }
    if (!response.ok || data?.ok === false) {
      throw new Error(data?.error || `Refresh failed: ${response.status}`);
    }
    if (fullRescan) {
      state.status = {
        ...state.status,
        scan_in_progress: true,
        scan_mode: 'manual_full_rescan',
      };
    }
    state.wasPollingBusy = true;
    showToast('Library scan started.', 'success', 2200);
    scheduleStatusPoll(250);
    return true;
  } catch (error) {
    if (!settleLibraryStatusAction(action)) return false;
    updateStatusIndicator(previousStatus);
    indicator.classList.remove('is-busy');
    indicator.classList.add('is-done');
    indicator.title = 'Unable to start library scan';
    showToast('Unable to start library scan.', 'error', 3200);
    return false;
  }
}
function claimLocalViewStateNavigation() {
  if(typeof invalidateAdvancedSearchIntent==='function')invalidateAdvancedSearchIntent('local-navigation');
  // Capture before any abort/continuity callback can install another owner.
  const albumPreferenceOwner = typeof getTrackModalAlbumPreferenceLease === 'function' ? getTrackModalAlbumPreferenceLease() : null;
  const rootPageOwner = rootGalleryPageRequest;
  const activeController = state.ui.activeViewRequestController;
  state.ui.viewStateRevision = Number(state.ui.viewStateRevision || 0) + 1;
  state.ui.pendingViewRequest = null;
  state.ui.pendingViewTransition = false;
  state.ui.pendingViewTransitionRequestId = 0;
  // Reentrant successor controls must capture the newly claimed revision.
  if (typeof disposeTrackModalAlbumPreferences === 'function') disposeTrackModalAlbumPreferences(albumPreferenceOwner);
  cancelRootGalleryPageRequest(rootPageOwner);
  if (activeController && typeof activeController.abort === 'function') {
    activeController.abort();
  }
}

function suspendScanPageGalleryCoverLoads() {
  if (Number(state.ui.scanPageCoverLoadSuspensionToken || 0)) return;
  if (
    typeof virtualGrid === 'undefined'
    || !virtualGrid
    || typeof virtualGrid.suspendSelectedArtistCoverLoadsForUserAction !== 'function'
  ) return;
  state.ui.scanPageCoverLoadSuspensionToken = Number(
    virtualGrid.suspendSelectedArtistCoverLoadsForUserAction() || 0,
  );
}

function resumeScanPageGalleryCoverLoads() {
  const token = Number(state.ui.scanPageCoverLoadSuspensionToken || 0);
  state.ui.scanPageCoverLoadSuspensionToken = 0;
  if (
    !token
    || typeof virtualGrid === 'undefined'
    || !virtualGrid
    || typeof virtualGrid.resumeSelectedArtistCoverLoadsAfterUserAction !== 'function'
  ) return;
  virtualGrid.resumeSelectedArtistCoverLoadsAfterUserAction(token);
}


function openScanPage() {
  if (!state.ui.scanPageReturnContext) {
    state.ui.scanPageReturnContext = {
      view: JSON.parse(JSON.stringify(state.view || {})),
      searchDraftQuery: String(state.ui.searchDraftQuery ?? state.view?.query ?? ''),
      url: typeof window !== 'undefined' ? String(window.location?.href || '') : '',
    };
  }
  suspendScanPageGalleryCoverLoads();
  state.ui.forceScanPageVisible = true;
  const searchInput = document.getElementById('search-input');
  if (searchInput) {
    searchInput.value = '';
    if (typeof updateSearchClearAction === 'function') updateSearchClearAction(searchInput);
  }
  renderSidebar();
  renderRelated();
  renderLibraryLoader(state.status, { scanPageVisible: true });
}

function abandonScanPageForNavigation(options = {}) {
  const scanPageWasVisible = Boolean(
    state.ui.scanPageReturnContext
    || state.ui.forceScanPageVisible
  );
  if (!scanPageWasVisible) return false;

  claimLocalViewStateNavigation();
  state.ui.scanPageReturnContext = null;
  state.ui.forceScanPageVisible = false;
  if (typeof unmountLibraryStatusBar === 'function') unmountLibraryStatusBar();
  if (options.clearSelection === true) {
    state.view = {
      ...state.view,
      selected_artist: '',
      all_artists_active: false,
      related_filter_artists: [],
      primary_filter_active: false,
      related_artists: [],
      primary_artist_groups: [],
      family_artist_groups: [],
    };
    state.ui.pendingSidebarSelectedArtist = '';
    state.ui.pendingSidebarAllArtistsActive = false;
    renderSidebar();
    renderRelated();
  }
  return true;
}

function closeScanPage() {
  const returnContext = state.ui.scanPageReturnContext;
  state.ui.forceScanPageVisible = false;
  if (!returnContext) {
    resumeScanPageGalleryCoverLoads();
    renderLibraryLoader(state.status);
    return;
  }
  claimLocalViewStateNavigation();
  const currentViewUsable = typeof isEffectivelyEmptyView !== 'function'
    || !isEffectivelyEmptyView(state.view);
  const retainedViewUsable = returnContext.view
    && (
      typeof isEffectivelyEmptyView !== 'function'
      || !isEffectivelyEmptyView(returnContext.view)
    );
  const restoreRetainedCancelledView = Boolean(
    returnContext.scanCancelled === true
    && retainedViewUsable
  );
  if (
    retainedViewUsable
    && (
      !currentViewUsable
      || restoreRetainedCancelledView
    )
  ) {
    state.view = JSON.parse(JSON.stringify(returnContext.view));
  }
  if(typeof invalidateAdvancedSearchIntent==='function')invalidateAdvancedSearchIntent('query-assignment');
  if(typeof updateGallerySearchDraftQuery==='function')updateGallerySearchDraftQuery(String(returnContext.searchDraftQuery ?? state.view?.query ?? ''));
  else state.ui.searchDraftQuery = String(returnContext.searchDraftQuery ?? state.view?.query ?? '');
  state.ui.scanPageReturnContext = null;
  if (typeof unmountLibraryStatusBar === 'function') unmountLibraryStatusBar();
  const searchInput = document.getElementById('search-input');
  if (searchInput) {
    searchInput.value = state.ui.searchDraftQuery;
    if (typeof updateSearchClearAction === 'function') updateSearchClearAction(searchInput);
  }
  if (
    returnContext.url
    && typeof window !== 'undefined'
    && window.history?.replaceState
    && String(window.location?.href || '') !== returnContext.url
  ) {
    window.history.replaceState(window.history.state, '', returnContext.url);
  }
  const mountedGallery = document.getElementById('artist-groups');
  const retainedGalleryCardsRemainMounted = Boolean(
    returnContext.view
    && typeof hasEquivalentGalleryRenderTopology === 'function'
    && hasEquivalentGalleryRenderTopology(
      returnContext.view.artist_groups,
      state.view?.artist_groups,
    )
    && mountedGallery
    && typeof mountedGallery.querySelectorAll === 'function'
    && mountedGallery.querySelectorAll('.album-card').length > 0
  );
  if (retainedGalleryCardsRemainMounted) {
    renderView({ preserveMountedGallery: true });
  } else {
    renderView();
  }
  resumeScanPageGalleryCoverLoads();
}

async function cancelLibraryScan() {
  if (state.ui.scanCancellationPending) return false;
  const isFullRescan = String(state.status?.scan_mode || '') === 'manual_full_rescan';
  const scanLabel = isFullRescan ? 'full rescan' : 'scan';
  const action = claimLibraryStatusAction(false);
  state.ui.scanCancellationPending = true;
  renderLibraryLoader(state.status, {
    scanPageVisible: Boolean(state.ui.scanPageReturnContext),
  });
  try {
    const response = await fetch('/cancel-refresh-api', {
      method: 'POST',
      headers: { Accept: 'application/json' },
    });
    const data = await response.json();
    if (!settleLibraryStatusAction(action)) return false;
    if (!response.ok || !data?.ok) {
      throw new Error(data?.error || `Failed to cancel ${scanLabel} (${response.status}).`);
    }
    if (!state.ui.scanPageReturnContext) {
      state.ui.forceScanPageVisible = false;
    }
    if (data.cancelled && state.ui.scanPageReturnContext) {
      state.ui.scanPageReturnContext.scanCancelled = true;
    }
    state.ui.scanCancellationAcknowledged = Boolean(data.cancelled);
    state.status = {
      ...state.status,
      scan_in_progress: false,
      scan_mode: 'idle',
    };
    renderLibraryLoader(state.status);
    showToast(
      data.cancelled
        ? `${isFullRescan ? 'Full rescan' : 'Scan'} cancelled.`
        : 'No scan was running.',
      'success',
      2600,
    );
    scheduleStatusPoll(150);
    return Boolean(data.cancelled);
  } catch (error) {
    if (!settleLibraryStatusAction(action)) return false;
    showToast(error?.message || `Failed to cancel ${scanLabel}.`, 'error', 3200);
    return false;
  } finally {
    if (libraryStatusAction === action) {
      state.ui.scanCancellationPending = false;
      renderLibraryLoader(state.status, {
        scanPageVisible: Boolean(state.ui.scanPageReturnContext),
      });
    }
  }
}

async function browseScannedLibrarySnapshot() {
  if (state.ui.browseScannedResultsLoading) return;
  const browseReturnContext = state.ui.scanPageReturnContext;
  const mountedGalleryViewBeforeBrowse = state.view;
  const browseView = {
    ...state.view,
    query: '',
    selected_artist: '',
    all_artists_active: true,
    related_filter_artists: [],
    primary_filter_active: false,
    surface: {
      ...(state.view?.surface || {}),
      active: 'albums',
    },
    surface_request: 'albums',
  };
  const browseUrl = buildApiUrl(browseView);
  const reusableRootBrowseView = typeof getReusableRootBrowseView === 'function'
    ? getReusableRootBrowseView(browseView, browseReturnContext?.view)
    : null;
  const reusableRootBrowseAvailable = Boolean(
    reusableRootBrowseView
    && !isEffectivelyEmptyView(reusableRootBrowseView),
  );
  if (reusableRootBrowseAvailable) {
    claimLocalViewStateNavigation();
    applyViewPayload({
      ...reusableRootBrowseView,
      query: '',
      selected_artist: '',
      all_artists_active: true,
      related_filter_artists: [],
      primary_filter_active: false,
      surface: browseView.surface,
      surface_request: 'albums',
    }, {
      trackSidebarReveal: false,
    });
    state.ui.scanPageReturnContext = null;
    state.ui.forceScanPageVisible = false;
    if (typeof unmountLibraryStatusBar === 'function') unmountLibraryStatusBar();
    if(typeof invalidateAdvancedSearchIntent==='function')invalidateAdvancedSearchIntent('query-assignment');
    if(typeof updateGallerySearchDraftQuery==='function')updateGallerySearchDraftQuery('');
    else state.ui.searchDraftQuery = '';
    const searchInput = document.getElementById('search-input');
    if (searchInput) searchInput.value = '';
    pushBrowserViewState(state.view);
    const mountedGallery = document.getElementById('artist-groups');
    const reusableGalleryRemainsMounted = Boolean(
      mountedGallery
      && typeof mountedGallery.querySelectorAll === 'function'
      && mountedGallery.querySelectorAll('.album-card').length > 0
      && hasEquivalentGalleryRenderTopology(
        mountedGalleryViewBeforeBrowse?.artist_groups,
        reusableRootBrowseView?.artist_groups,
      )
    );
    renderView(reusableGalleryRemainsMounted ? { preserveMountedGalleryChildren: true } : undefined);
    resumeScanPageGalleryCoverLoads();
    const scanRelatedWorkActive = Boolean(
      state.status?.scan_in_progress
      || state.status?.relations_in_progress
      || state.status?.covers_in_progress
    );
    if (scanRelatedWorkActive) {
      return;
    }
  }
  state.ui.browseScannedResultsLoading = true;
  renderLibraryLoader(state.status);
  try {
    if (reusableRootBrowseAvailable) {
      await fetchAndRender(browseUrl, false, {
        preserveScroll: true,
        restartIfSameUrl: true,
        skipPendingViewTransition: true,
      });
      return;
    }
    let browseRendered = await fetchAndRender(browseUrl, false, {
      preserveScroll: true,
      restartIfSameUrl: true,
    });
    let retryCount = 0;
    while (
      browseReturnContext
      && state.ui.scanPageReturnContext === browseReturnContext
      && isEffectivelyEmptyView(state.view)
      && retryCount < BROWSE_SCANNED_MAX_RETRIES
    ) {
      retryCount += 1;
      await new Promise((resolve) => {
        scheduleBrowserTimeout(resolve, BROWSE_SCANNED_RETRY_DELAY_MS);
      });
      browseRendered = await fetchAndRender(browseUrl, false, {
        preserveScroll: true,
        restartIfSameUrl: true,
      });
    }
    if (isEffectivelyEmptyView(state.view)) {
      showToast('No scanned albums are ready to browse yet.', 'info', 2600);
    } else if (
      browseRendered
      && browseReturnContext
      && state.ui.scanPageReturnContext === browseReturnContext
    ) {
      state.ui.scanPageReturnContext = null;
      state.ui.forceScanPageVisible = false;
      if (typeof unmountLibraryStatusBar === 'function') unmountLibraryStatusBar();
      if(typeof invalidateAdvancedSearchIntent==='function')invalidateAdvancedSearchIntent('query-assignment');
      if(typeof updateGallerySearchDraftQuery==='function')updateGallerySearchDraftQuery('');
      else state.ui.searchDraftQuery = '';
      const searchInput = document.getElementById('search-input');
      if (searchInput) searchInput.value = '';
      pushBrowserViewState(state.view);
      renderView();
      resumeScanPageGalleryCoverLoads();
    }
  } catch (error) {
    showToast(error?.message || 'Unable to load scanned albums yet.', 'error', 3200);
  } finally {
    state.ui.browseScannedResultsLoading = false;
    renderLibraryLoader(state.status);
  }
}

function watcherHealthRefreshSignature(status) {
  const health = status?.watcher_health || {};
  const problems = Array.isArray(health.problems) ? health.problems : [];
  return JSON.stringify([
    String(health.state || ''),
    problems.map(problem => [
      String(problem?.root_key || ''),
      String(problem?.state || ''),
      String(problem?.detected_at || ''),
      String(problem?.message || ''),
      Object.entries(problem?.allowed_actions || {}).sort(([left], [right]) => left.localeCompare(right)),
    ]).sort((left, right) => JSON.stringify(left).localeCompare(JSON.stringify(right))),
  ]);
}

async function pollStatus() {
  const sequence = ++statusPollSequence;
  const readRevision = statusReadRevision;
  const startedDuringPendingStart = Boolean(libraryStatusAction?.pendingStart);
  const ownsStatus = () => sequence === statusPollSequence
    && readRevision === statusReadRevision
    && !startedDuringPendingStart;
  let nextPollDelay = null;
  const knownStatus = state.status || {};
  const knownWatcherHealth = watcherHealthRefreshSignature(knownStatus);
  const hadKnownInventoryRevision = Object.prototype.hasOwnProperty.call(
    knownStatus,
    'inventory_mutation_revision',
  );
  const knownInventoryRevision = Number(knownStatus.inventory_mutation_revision || 0);
  const knownBusy = Boolean(
    knownStatus.scan_in_progress
    || knownStatus.relations_in_progress
    || knownStatus.covers_in_progress
  );
  const coverScheduler = typeof galleryCoverLoadScheduler !== 'undefined'
    ? galleryCoverLoadScheduler
    : null;
  try {
    if (
      !knownBusy
      && coverScheduler?.isForegroundIdle?.() === false
      && typeof coverScheduler.whenForegroundIdle === 'function'
    ) {
      await coverScheduler.whenForegroundIdle();
      if (ownsStatus()) nextPollDelay = STATUS_POLL_FOREGROUND_IDLE_RETRY_DELAY_MS;
      return;
    }
    const response = await fetch('/status');
    const data = await readGalleryResponse(response, ownsStatus);
    if (!ownsStatus()) return;
    updateStatusIndicator(data);
    const normalizedStatus = state.status;
    const currentInventoryRevision = Number(
      normalizedStatus.inventory_mutation_revision || 0,
    );
    const inventoryAdvanced = hadKnownInventoryRevision
      && currentInventoryRevision > knownInventoryRevision;
    if (inventoryAdvanced) {
      if (typeof invalidateAllHydratedTrackModalAlbumDetails === 'function') {
        invalidateAllHydratedTrackModalAlbumDetails();
      }
      state.ui.pendingInventoryMutationViewRefresh = true;
    }
    const utility = state.utility;
    const healthChanged = knownWatcherHealth !== watcherHealthRefreshSignature(normalizedStatus);
    if ((utility.loaded || utility.loading) && (inventoryAdvanced || healthChanged)) {
      utility.problematicStatusRefreshRevision = Number(utility.problematicStatusRefreshRevision || 0) + 1;
    }
    const requestedRefreshRevision = Number(utility.problematicStatusRefreshRevision || 0);
    if (!utility.loading && requestedRefreshRevision > Number(utility.problematicStatusSyncedRevision || 0)) {
      try {
        // An earlier in-flight summary cannot satisfy a later status change.
        // Failed/superseded loads return null; keep the change pending for the next poll.
        const refreshedItems = await loadProblematicFiles(true, { preserveSelectedDetail: true });
        if (!ownsStatus()) return;
        if (state.utility === utility && Array.isArray(refreshedItems)) {
          utility.problematicStatusSyncedRevision = requestedRefreshRevision;
        }
      } catch (problematicFilesError) {
        if (!ownsStatus()) return;
        console.error(
          '[AlbumHaven][Watcher] Failed to refresh Problematic Files after a status change.',
          problematicFilesError,
        );
      }
    }
    const statusObservationSequence = recordSuccessfulStatusObservation();

    const logHistoryRevision = String(
      normalizedStatus.log_history_revision ?? '',
    ).trim();
    if (
      logHistoryRevision
      && logHistoryRevision !== String(state.utility.logHistoryRevision || '')
      && typeof syncUtilityLogHistoryRevision === 'function'
    ) {
      try {
        const historySync = syncUtilityLogHistoryRevision(logHistoryRevision);
        Promise.resolve(historySync).catch((historyError) => {
          console.error(
            '[AlbumHaven][History] Failed to synchronize server-recorded history.',
            historyError,
          );
        });
      } catch (historyError) {
        console.error(
          '[AlbumHaven][History] Failed to synchronize server-recorded history.',
          historyError,
        );
      }
    }

    const scanOutcome = String(normalizedStatus.scan_outcome || '').trim().toLowerCase();
    const lastErrorText = scanOutcome === 'running'
      ? ''
      : String(normalizedStatus.last_error || '').trim();
    if (lastErrorText) {
      if (state.ui.lastStatusErrorToastIdentity !== lastErrorText) {
        state.ui.lastStatusErrorToastIdentity = lastErrorText;
      showToast(`Last scan error: ${lastErrorText}`, 'error', 4800);
      }
    } else {
      state.ui.lastStatusErrorToastIdentity = '';
      state.ui.lastStatusErrorHistoryIdentity = '';
    }

    const scanFinalizing = Boolean(normalizedStatus.scan_in_progress)
      && String(normalizedStatus.scan_phase || '').trim().toLowerCase() === 'finalizing';
    const busyNow = normalizedStatus.scan_in_progress || normalizedStatus.relations_in_progress;
    const coverBusyNow = Boolean(normalizedStatus.covers_in_progress);
    const wasPollingBusy = Boolean(state.wasPollingBusy);
    const wasScanFinalizing = Boolean(state.wasScanFinalizing);
    const wasCoverPollingBusy = Boolean(state.wasCoverPollingBusy);
    if (busyNow && state.ui.pendingScanCompletionViewRefreshPromise) {
      clearPendingScanCompletionViewRefresh();
      state.ui.pendingScanCompletionViewRefreshPromise = null;
    }
    if (coverBusyNow && state.ui.pendingCoverCompletionViewRefreshPromise) {
      clearPendingCoverCompletionViewRefresh();
      state.ui.pendingCoverCompletionViewRefreshPromise = null;
    }
    // Keep a terminal transition pending until its owned async effects finish.
    // A newer idle observation can then finish it instead of losing completion.
    if (busyNow) state.wasPollingBusy = true;
    state.wasScanFinalizing = scanFinalizing;
    if (coverBusyNow) state.wasCoverPollingBusy = true;
    if ((!busyNow || scanFinalizing) && !state.ui.scanPageReturnContext) {
      state.ui.forceScanPageVisible = false;
    }
    if (scanFinalizing && !wasScanFinalizing) {
      state.ui.pendingScanCompletionViewRefreshRetryCount = 0;
      state.ui.pendingScanCompletionViewRefreshRetryExhausted = false;
      state.ui.pendingScanCompletionViewRefresh = true;
      state.ui.pendingScanCompletionViewRefreshEligibleRequestId = (
        readActiveScanCompletionPreviewRequestId()
      );
      const scanGeneration = Number(normalizedStatus.scan_generation || 0);
      const settledApplySatisfiesFinalizing = (
        !state.ui.pendingScanCompletionViewRefreshEligibleRequestId
        && settledCanonicalFullViewApplySatisfiesFinalizing(
          scanGeneration,
          statusObservationSequence,
        )
      );
      state.ui.lastSuccessfulCanonicalFullViewApply = null;
      if (settledApplySatisfiesFinalizing) {
        clearPendingScanCompletionViewRefresh();
      } else if (!hasPendingSidebarNavigation()) {
        await dispatchPendingScanCompletionViewRefresh();
        if (!ownsStatus()) return;
      }
    }
    if (wasPollingBusy && !busyNow) {
      const scanWasCancelled = (
        Boolean(state.ui.scanCancellationAcknowledged)
        || String(normalizedStatus.scan_outcome || '').trim().toLowerCase() === 'cancelled'
      );
      if (!state.ui.pendingScanCompletionViewRefreshPromise) {
        clearPendingScanCompletionViewRefresh();
        state.ui.pendingScanCompletionViewRefresh = true;
      }
      if (!hasPendingSidebarNavigation()) {
        await dispatchPendingScanCompletionViewRefresh(true);
        if (!ownsStatus()) return;
      }
      state.ui.scanCancellationAcknowledged = false;
      if (!normalizedStatus.last_error && !scanWasCancelled) {
        showToast('Library scan complete.', 'success', 3200);
      }
      state.ui.pendingInventoryMutationViewRefresh = false;
    }
    state.wasPollingBusy = busyNow;
    state.ui.pendingScanCompletionViewRefreshPromise = null;
    if (wasCoverPollingBusy && !coverBusyNow) {
      if (shouldAutoRefreshViewAfterCoverCompletion()) {
        if (!state.ui.pendingCoverCompletionViewRefreshPromise) {
          clearPendingCoverCompletionViewRefresh();
          state.ui.pendingCoverCompletionViewRefresh = true;
        }
        await dispatchPendingCoverCompletionViewRefresh(true);
        if (!ownsStatus()) return;
      }
      if (state.utility.loaded) {
        await loadProblematicFiles(true);
        if (!ownsStatus()) return;
      }
      showToast('Album covers updated.', 'success', 3200);
    }
    state.wasCoverPollingBusy = coverBusyNow;
    state.ui.pendingCoverCompletionViewRefreshPromise = null;
    if (
      state.ui.pendingInventoryMutationViewRefresh
      && !busyNow
      && !coverBusyNow
      && !state.busy
      && !hasPendingSidebarNavigation()
    ) {
      state.ui.pendingInventoryMutationViewRefresh = false;
      try {
        const refreshApplied = await refreshCurrentViewAfterBackgroundCompletion({
          preserveScroll: true,
          restartIfSameUrl: true,
        });
        if (!ownsStatus()) return;
        if (!refreshApplied) {
          state.ui.pendingInventoryMutationViewRefresh = true;
        } else if (typeof invalidateAllHydratedTrackModalAlbumDetails === 'function') {
          invalidateAllHydratedTrackModalAlbumDetails();
        }
      } catch (inventoryRefreshError) {
        if (!ownsStatus()) return;
        state.ui.pendingInventoryMutationViewRefresh = true;
        console.error(
          '[AlbumHaven][Watcher] Failed to refresh the gallery after an inventory change.',
          inventoryRefreshError,
        );
      }
    }
    nextPollDelay = currentStatusPollDelay();
  } catch (error) {
    if (ownsStatus()) nextPollDelay = 3000;
  } finally {
    // A newer poll owns its continuation. Discarded work must not stop polling
    // or postpone an earlier action read that is already scheduled.
    if (sequence === statusPollSequence && (ownsStatus() || !statusPollTimer)) {
      scheduleStatusPoll(nextPollDelay ?? currentStatusPollDelay());
    }
  }
}

// END js/runtime/gallery-refresh-and-status.js

// BEGIN js/runtime/problematic-album-helpers.js

function formatRuleFieldLabel(field) {
  return String(field || 'problem').replaceAll('_', ' ');
}

function getProblemIgnoreGroupTitle(group) {
  const parts = [];
  if (group.artist) parts.push(group.artist);
  if (group.album) parts.push(group.album);
  if (group.year) parts.push(group.year);
  const title = parts.join(' - ') || 'Unknown album';
  return `${title} (${group.items.length} file${group.items.length === 1 ? '' : 's'})`;
}

function groupProblemIgnoreItems(items) {
  const grouped = new Map();
  items.forEach((item) => {
    const key = String(item?.album_group_key || '').trim()
      || [item?.artist, item?.album].map((value) => String(value || '').trim()).filter(Boolean).join(' :: ')
      || String(item?.path || item?.row_key || '');
    if (!grouped.has(key)) {
      grouped.set(key, {
        key,
        album: String(item?.album || '').trim(),
        artist: String(item?.artist || '').trim(),
        year: String(item?.year || '').trim(),
        items: [],
      });
    }
    grouped.get(key).items.push(item);
  });
  return Array.from(grouped.values())
    .map((group) => ({
      ...group,
      items: group.items.slice().sort((a, b) => String(a?.filename || '').localeCompare(String(b?.filename || ''), undefined, { sensitivity: 'base' })),
    }))
    .sort((a, b) => {
      const artistCompare = String(a.artist || '').localeCompare(String(b.artist || ''), undefined, { sensitivity: 'base' });
      if (artistCompare) return artistCompare;
      return getProblemIgnoreGroupTitle(a).localeCompare(getProblemIgnoreGroupTitle(b), undefined, { sensitivity: 'base' });
    });
}

function getProblematicAlbumDisplayValue(album, field, showConverted) {
  const repairRows = Array.isArray(album?.repair_preview_rows) ? album.repair_preview_rows : [];
  const matchingRow = repairRows.find((row) => row.field === field);
  if (field === 'album') {
    return showConverted
      ? (matchingRow?.repaired || album?.name || album?.raw_name || '')
      : (matchingRow?.original || album?.raw_name || album?.name || '');
  }
  if (field === 'album_artist') {
    return showConverted
      ? (matchingRow?.repaired || album?.album_artist || album?.raw_album_artist || '')
      : (matchingRow?.original || album?.raw_album_artist || album?.album_artist || '');
  }
  return '';
}

function getProblematicTrackDisplayTitle(album, row, showConverted) {
  const convertedTrack = (Array.isArray(album?.tracks) ? album.tracks : [])
    .find((track) => String(track.path || '') === String(row?.path || ''));
  if (row?.field === 'title') {
    return showConverted
      ? (row.repaired || convertedTrack?.title || row.track_title || '')
      : (row.original || row.track_title || convertedTrack?.title || '');
  }
  return showConverted
    ? (convertedTrack?.title || row?.track_title || '')
    : (row?.track_title || convertedTrack?.title || '');
}

function formatRepairFieldLabel(field) {
  const value = String(field || '');
  if (value === 'album_disc_marker') return 'Album + disc number';
  return value.replaceAll('_', ' ');
}

function buildDiscogsSearchUrl(album) {
  const meaningful = (value) => {
    const text = String(value ?? '').trim();
    return text && !['unknown', 'unknown artist', 'unknown album', 'n/a', 'none', 'null'].includes(text.toLowerCase())
      ? text
      : '';
  };
  const artist = meaningful(getProblematicAlbumDisplayValue(album, 'album_artist', true) || album?.album_artist);
  const title = meaningful(getProblematicAlbumDisplayValue(album, 'album', true) || album?.name);
  const year = meaningful(album?.year);
  const query = [artist, title, year].filter(Boolean).join(' ');
  const params = new URLSearchParams({
    q: query || meaningful(album?.raw_album_artist) || meaningful(album?.raw_name) || 'music release',
    type: 'release',
  });
  return `https://www.discogs.com/search/?${params.toString()}`;
}

function getFileTypeFromPath(path) {
  const filename = String(path || '').split(/[\\/]/).pop() || '';
  const dotIndex = filename.lastIndexOf('.');
  if (dotIndex < 0 || dotIndex === filename.length - 1) return '';
  return filename.slice(dotIndex + 1).trim().toUpperCase();
}

function getFilenameFromPath(path) {
  return String(path || '').split(/[\\/]/).pop() || '';
}

function getProblematicAlbumFileTypes(album) {
  if (Array.isArray(album?.file_types) && album.file_types.length) {
    return album.file_types.map((value) => String(value || '')).filter(Boolean);
  }
  return Array.from(new Set((Array.isArray(album?.tracks) ? album.tracks : [])
    .map((track) => getFileTypeFromPath(track.path))
    .filter(Boolean))).sort((a, b) => a.localeCompare(b));
}

function getRepairRowFileType(row) {
  return getFileTypeFromPath(row?.path);
}

// END js/runtime/problematic-album-helpers.js

// BEGIN js/runtime/browser-log-history-store.js

const BROWSER_LOG_HISTORY_DATABASE_NAME = 'album-haven-client-diagnostics';
const BROWSER_LOG_HISTORY_DATABASE_VERSION = 1;
const BROWSER_LOG_HISTORY_STORE_NAME = 'log-history';
const BROWSER_LOG_HISTORY_LIMIT = 250;

function getBrowserLogHistoryNow(options = {}) {
  const value = typeof options.now === 'function' ? options.now() : new Date().toISOString();
  return String(value || new Date().toISOString());
}

function getBrowserLogHistoryRandomUUID(options = {}) {
  if (typeof options.randomUUID === 'function') {
    return String(options.randomUUID());
  }
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return String(crypto.randomUUID());
  }
  return `browser-log-${Date.now()}-${Math.random().toString(16).slice(2)}`;
}

function normalizeBrowserLogHistoryEntry(entry, options = {}) {
  const input = entry && typeof entry === 'object' ? entry : {};
  const now = getBrowserLogHistoryNow(options);
  const timestamp = String(input.timestamp || input.recorded_at || now);
  const stableId = String(input.id || '').trim();
  return {
    ...input,
    id: stableId || getBrowserLogHistoryRandomUUID(options),
    timestamp,
    recorded_at: String(input.recorded_at || timestamp),
    source: 'this_browser',
    source_label: 'This browser',
  };
}

function compareBrowserLogHistoryEntries(left, right) {
  const recordedOrder = String(right?.recorded_at || '')
    .localeCompare(String(left?.recorded_at || ''));
  if (recordedOrder) return recordedOrder;
  const timeOrder = String(right?.timestamp || '')
    .localeCompare(String(left?.timestamp || ''));
  if (timeOrder) return timeOrder;
  return String(right?.id || '').localeCompare(String(left?.id || ''));
}

function mergeBrowserLogHistoryCollections(existingEntries, incomingEntries, options = {}) {
  const byId = new Map();
  const addEntries = (entries) => {
    (Array.isArray(entries) ? entries : []).forEach((entry) => {
      const normalized = normalizeBrowserLogHistoryEntry(entry, options);
      byId.set(normalized.id, normalized);
    });
  };
  addEntries(existingEntries);
  addEntries(incomingEntries);
  return Array.from(byId.values())
    .sort(compareBrowserLogHistoryEntries)
    .slice(0, BROWSER_LOG_HISTORY_LIMIT);
}

async function requestBrowserLogHistoryPersistentStorage(storageManager = (
  typeof navigator !== 'undefined' ? navigator.storage : undefined
)) {
  if (!storageManager || typeof storageManager.persist !== 'function') return false;
  try {
    return Boolean(await storageManager.persist());
  } catch (_error) {
    return false;
  }
}

function createBrowserLogHistoryStore(options = {}) {
  const databaseFactory = options.indexedDB;
  const normalizationOptions = { now: options.now, randomUUID: options.randomUUID };
  let sessionItems = [];
  let indexedDbUnavailable = !databaseFactory || typeof databaseFactory.open !== 'function';
  const persistentStatus = {
    persistent: true,
    storage: 'indexeddb',
    message: 'Stored in this browser.',
  };
  const sessionStatus = {
    persistent: false,
    storage: 'session',
    message: 'History is available for this session and will be lost on reload.',
  };

  function openDatabase() {
    return new Promise((resolve, reject) => {
      if (indexedDbUnavailable) {
        reject(new Error('IndexedDB is unavailable.'));
        return;
      }
      let request;
      try {
        request = databaseFactory.open(
          BROWSER_LOG_HISTORY_DATABASE_NAME,
          BROWSER_LOG_HISTORY_DATABASE_VERSION,
        );
      } catch (error) {
        indexedDbUnavailable = true;
        reject(error);
        return;
      }
      request.onupgradeneeded = () => {
        const database = request.result;
        if (!database.objectStoreNames.contains(BROWSER_LOG_HISTORY_STORE_NAME)) {
          database.createObjectStore(BROWSER_LOG_HISTORY_STORE_NAME, { keyPath: 'id' });
        }
      };
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => {
        indexedDbUnavailable = true;
        reject(request.error || new Error('Unable to open browser log history.'));
      };
      request.onblocked = () => {
        indexedDbUnavailable = true;
        reject(new Error('Browser log history is blocked.'));
      };
    });
  }

  async function merge(entries) {
    const incoming = Array.isArray(entries) ? entries : [];
    if (indexedDbUnavailable) {
      sessionItems = mergeBrowserLogHistoryCollections(sessionItems, incoming, normalizationOptions);
      return { items: sessionItems.slice(), status: { ...sessionStatus } };
    }
    let database;
    try {
      database = await openDatabase();
      const items = await new Promise((resolve, reject) => {
        let mergedItems = [];
        const transaction = database.transaction(BROWSER_LOG_HISTORY_STORE_NAME, 'readwrite');
        const objectStore = transaction.objectStore(BROWSER_LOG_HISTORY_STORE_NAME);
        const readRequest = objectStore.getAll();
        readRequest.onsuccess = () => {
          mergedItems = mergeBrowserLogHistoryCollections(
            readRequest.result,
            incoming,
            normalizationOptions,
          );
          objectStore.clear();
          mergedItems.forEach((item) => objectStore.put(item));
        };
        readRequest.onerror = () => reject(readRequest.error || new Error('Unable to read browser log history.'));
        transaction.oncomplete = () => resolve(mergedItems);
        transaction.onerror = () => reject(transaction.error || new Error('Unable to update browser log history.'));
        transaction.onabort = () => reject(transaction.error || new Error('Browser log history update was aborted.'));
      });
      database.close();
      sessionItems = items.slice();
      return { items, status: { ...persistentStatus } };
    } catch (_error) {
      database?.close?.();
      indexedDbUnavailable = true;
      sessionItems = mergeBrowserLogHistoryCollections(sessionItems, incoming, normalizationOptions);
      return { items: sessionItems.slice(), status: { ...sessionStatus } };
    }
  }

  async function read() {
    if (indexedDbUnavailable) {
      return { items: sessionItems.slice(), status: { ...sessionStatus } };
    }
    let database;
    try {
      database = await openDatabase();
      const items = await new Promise((resolve, reject) => {
        let storedItems = [];
        const transaction = database.transaction(BROWSER_LOG_HISTORY_STORE_NAME, 'readonly');
        const readRequest = transaction.objectStore(BROWSER_LOG_HISTORY_STORE_NAME).getAll();
        readRequest.onsuccess = () => {
          storedItems = mergeBrowserLogHistoryCollections([], readRequest.result, normalizationOptions);
        };
        readRequest.onerror = () => reject(readRequest.error || new Error('Unable to read browser log history.'));
        transaction.oncomplete = () => resolve(storedItems);
        transaction.onerror = () => reject(transaction.error || new Error('Unable to read browser log history.'));
        transaction.onabort = () => reject(transaction.error || new Error('Browser log history read was aborted.'));
      });
      database.close();
      sessionItems = items.slice();
      return { items, status: { ...persistentStatus } };
    } catch (_error) {
      database?.close?.();
      indexedDbUnavailable = true;
      return { items: sessionItems.slice(), status: { ...sessionStatus } };
    }
  }

  return { merge, read };
}

function buildBrowserLogHistoryExportDocument(entries, options = {}) {
  return {
    schema: 'album-haven-log-history',
    version: 1,
    exported_at: getBrowserLogHistoryNow(options),
    sources: [{ id: 'this_browser', label: 'This browser' }],
    items: mergeBrowserLogHistoryCollections([], entries, options),
  };
}

const browserLogHistoryStore = createBrowserLogHistoryStore({
  indexedDB: typeof indexedDB !== 'undefined' ? indexedDB : null,
  now: () => new Date().toISOString(),
  randomUUID: () => getBrowserLogHistoryRandomUUID(),
});

function persistBrowserLogHistoryEntries(entries) {
  return browserLogHistoryStore.merge(entries);
}

function readBrowserLogHistoryEntries() {
  return browserLogHistoryStore.read();
}

async function exportBrowserLogHistory() {
  const result = await readBrowserLogHistoryEntries();
  const exportDocument = buildBrowserLogHistoryExportDocument(result.items);
  const blob = new Blob([`${JSON.stringify(exportDocument, null, 2)}\n`], {
    type: 'application/json;charset=utf-8',
  });
  const objectUrl = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  const filenameTimestamp = exportDocument.exported_at
    .replace(/[:.]/g, '-')
    .replace('T', '_')
    .replace('Z', '');
  anchor.href = objectUrl;
  anchor.download = `album-haven-log-history-${filenameTimestamp}.json`;
  anchor.hidden = true;
  document.body.appendChild(anchor);
  try {
    anchor.click();
  } finally {
    anchor.remove();
    URL.revokeObjectURL(objectUrl);
  }
  return exportDocument;
}

// END js/runtime/browser-log-history-store.js

// BEGIN js/runtime/utility-log-history-query.js

function normalizeUtilityLogHistoryQuery(draft, { now = new Date(), timeZone = Intl.DateTimeFormat().resolvedOptions().timeZone } = {}) {
  const formatter = new Intl.DateTimeFormat('en-CA', { timeZone, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hourCycle: 'h23' });
  const parts = value => Object.fromEntries(formatter.formatToParts(value).filter(part => part.type !== 'literal').map(part => [part.type, Number(part.value)]));
  const parseDate = text => {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(String(text || ''))) throw new Error('Choose a valid date range.');
    const [year, month, day] = text.split('-').map(Number);
    const date = new Date(Date.UTC(year, month - 1, day));
    if (date.getUTCFullYear() !== year || date.getUTCMonth() !== month - 1 || date.getUTCDate() !== day) throw new Error('Choose valid calendar dates.');
    return date;
  };
  const local = parts(new Date(now));
  let start, end;
  if (draft?.preset === 'custom') {
    start = parseDate(draft.fromDate); end = parseDate(draft.toDate);
    if (start > end) throw new Error('The start date must precede the end date.');
  } else {
    const days = { today: 1, '7-days': 7, '30-days': 30 }[draft?.preset];
    if (!days) throw new Error('Choose a date preset.');
    end = new Date(Date.UTC(local.year, local.month - 1, local.day));
    start = new Date(end.getTime() - (days - 1) * 86400000);
  }
  end = new Date(end.getTime() + 86400000);
  const dayBoundaryUtc = date => {
    const target = date.getTime();
    const representedTime = value => {
      const p = parts(new Date(value));
      return Date.UTC(p.year, p.month - 1, p.day, p.hour, p.minute, p.second);
    };
    // Check both sides of offset changes so a repeated midnight uses its first occurrence.
    const midnights = [];
    for (let hours = -48; hours <= 48; hours += 6) {
      const sample = target + hours * 3600000;
      const candidate = target - (representedTime(sample) - sample);
      if (representedTime(candidate) === target) midnights.push(candidate);
    }
    if (midnights.length) return new Date(Math.min(...midnights)).toISOString();
    // Midnight can be skipped. Find the first valid instant reaching this calendar day.
    let before = target / 1000 - 48 * 3600;
    let after = target / 1000 + 48 * 3600;
    while (after - before > 1) {
      const middle = Math.floor((before + after) / 2);
      const p = parts(new Date(middle * 1000));
      if (Date.UTC(p.year, p.month - 1, p.day) < target) before = middle;
      else after = middle;
    }
    return new Date(after * 1000).toISOString();
  };
  const list = value => Array.from(new Set((Array.isArray(value) ? value : []).map(item => String(item).trim()).filter(Boolean))).sort();
  return { from_utc: dayBoundaryUtc(start), to_utc: dayBoundaryUtc(end), sources: list(draft.sources), event_types: list(draft.event_types), text: String(draft.text || '').trim(), event_ids: [] };
}

function createUtilityLogHistoryQueryController({ fetchPage, exportQuery, contextKey, now = () => new Date(), timeZone = Intl.DateTimeFormat().resolvedOptions().timeZone, onChange = () => {}, onAccepted = () => {} }) {
  let epoch = 0, navigationEpoch = 0, context = contextKey, previousSelection = '', temporarySerial = 0, periodCapture = null;
  let state = { query: null, snapshot: null, items: [], selectedEventId: '', temporaryRowId: null, draft: null, stale: false, refreshRequired: false, error: '', loading: false, nextCursor: null, revision: '' };
  const emit = () => onChange({ ...state });
  const capture = async (query, selection, temporary, metadata = {}) => {
    const token = ++epoch;
    const baseToken = Object.keys(query).length === 0 ? ++navigationEpoch : null;
    state.loading = true; state.error = ''; emit();
    try {
      const page = await fetchPage({ query, cursor: null, snapshot: null, page_size: 500 });
      if (token !== epoch) return;
      state = { ...state, query, snapshot: page.snapshot, items: page.items || [], nextCursor: page.next_cursor || null, revision: page.revision || '', selectedEventId: selection, temporaryRowId: temporary, ...metadata, draft: null, stale: false, refreshRequired: false, error: '' };
      onAccepted({ query, items: state.items, page, publishNavigation: baseToken === navigationEpoch });
      if (!selection && temporary) periodCapture = { ...state, loading: false };
    } catch (error) {
      if (token !== epoch) return;
      state.error = error.message || String(error); throw error;
    } finally { if (token === epoch) { state.loading = false; emit(); } }
  };
  return {
    getState: () => ({ ...state }),
    beginDraft(draft = { preset: 'today' }) { state.draft = { ...draft }; emit(); },
    cancelDraft() { state.draft = null; emit(); },
    async applyDraft() {
      if (!state.draft) throw new Error('No query draft is open.');
      const query = normalizeUtilityLogHistoryQuery(state.draft, { now: typeof now === 'function' ? now() : now, timeZone });
      const dates = new Intl.DateTimeFormat(undefined, { timeZone, dateStyle: 'medium' });
      const periodLabel = `${dates.format(new Date(query.from_utc))} – ${dates.format(new Date(new Date(query.to_utc).getTime() - 1))} · ${timeZone}`;
      if (!state.temporaryRowId) previousSelection = state.selectedEventId;
      const row = state.temporaryRowId || `log-query-${++temporarySerial}`;
      return capture(query, '', row, { periodLabel });
    },
    clear() { ++epoch; periodCapture = null; state = { ...state, temporaryRowId: null, periodLabel: undefined, query: null, snapshot: null, items: [], selectedEventId: previousSelection, draft: null, nextCursor: null, loading: false, error: '', stale: false, refreshRequired: false }; emit(); },
    selectEvent(id) { return capture({ event_ids: [String(id)] }, String(id), state.temporaryRowId); },
    selectPeriod() { if (!periodCapture) return; ++epoch; state = { ...periodCapture, draft: null, loading: false }; emit(); },
    refresh() { if (!state.query) return capture({}, '', null); return capture(state.query, state.selectedEventId, state.temporaryRowId); },
    async refreshNavigation() {
      const token = ++navigationEpoch, capturedContext = context;
      const page = await fetchPage({ query: {}, cursor: null, snapshot: null, page_size: 500 });
      if (token !== navigationEpoch || capturedContext !== context) return;
      onAccepted({ query: {}, items: page.items || [], page, navigationOnly: true, publishNavigation: true });
      emit();
    },
    async loadMore() {
      if (!state.nextCursor || state.loading || state.refreshRequired) return;
      const token = epoch;
      const baseToken = Object.keys(state.query || {}).length === 0 ? ++navigationEpoch : null;
      state.loading = true; state.error = ''; emit();
      try {
        const page = await fetchPage({ query: state.query, cursor: state.nextCursor, snapshot: state.snapshot, page_size: 500 });
        if (token !== epoch) return;
        if (page.snapshot !== state.snapshot) throw new Error('The log snapshot changed. Refresh to continue.');
        const items = new Map(state.items.map(item => [item.id, item]));
        (page.items || []).forEach(item => { if (!items.has(item.id)) items.set(item.id, item); });
        state.items = Array.from(items.values()); state.nextCursor = page.next_cursor || null;
        onAccepted({ query: state.query, items: state.items, page, publishNavigation: baseToken === navigationEpoch });
        if (!state.selectedEventId && state.temporaryRowId) periodCapture = { ...state, loading: false };
      } catch (error) { if (token !== epoch) return; state.error = error.message || String(error); if (error.status === 410) state.refreshRequired = true; throw error; }
      finally { if (token === epoch) { state.loading = false; emit(); } }
    },
    markStale(revision) { if (periodCapture && String(revision || '') !== String(periodCapture.revision || '')) periodCapture.stale = true; if (state.snapshot && String(revision || '') !== String(state.revision || '')) { state.stale = true; emit(); } },
    setContext(next) { if (next === context) return; context = next; ++epoch; ++navigationEpoch; previousSelection = ''; periodCapture = null; state = { query: null, snapshot: null, items: [], selectedEventId: '', temporaryRowId: null, draft: null, stale: false, refreshRequired: false, error: '', loading: false, nextCursor: null, revision: '' }; emit(); },
    async exportCurrent() {
      if (!state.query || !state.snapshot || (state.selectedEventId && !state.items.some(item => String(item.id) === state.selectedEventId))) throw new Error('Select an available log query before exporting.');
      const token = epoch;
      try {
        const result = await exportQuery({ query: state.query, snapshot: state.snapshot });
        if (token !== epoch) throw new Error('The log context changed before export completed.');
        return result;
      } catch (error) {
        if (token === epoch) { state.error = error.message || String(error); if (error.status === 410) state.refreshRequired = true; emit(); }
        throw error;
      }
    },
  };
}

// END js/runtime/utility-log-history-query.js

// BEGIN js/runtime/date-range-picker.js

/* Shared themed calendar. Consumers own timezone conversion and submission. */
function buildDateRangePicker({ fromDate = '', toDate = '' } = {}) {
  return `<div class="date-range-picker" data-date-range-picker>
    ${[['fromDate', 'From date', fromDate], ['toDate', 'To date', toDate]].map(([name, label, value]) => `<div class="date-range-picker__field"><span>${label}</span><div class="date-range-picker__control ui-input-action"><input type="text" name="${name}" aria-label="${label}" value="${escapeHtml(value)}" placeholder="mm/dd/yyyy" readonly required>${window.ButtonComponent.renderActionButton({ icon: 'calendar', ariaLabel: `Choose ${label.toLowerCase()}`, attributes: { 'data-calendar-trigger': name, 'aria-haspopup': 'dialog', 'aria-expanded': 'false' } })}</div></div>`).join('')}
  </div>`;
}

function mountDateRangePicker(container) {
  const root = container.querySelector('[data-date-range-picker]');
  let popup, trigger, input, month;
  const close = (restore = false) => {
    if (!popup) return;
    clearTriggerAnchor(popup); popup.remove(); popup = null;
    trigger.setAttribute('aria-expanded', 'false');
    if (restore) trigger.focus();
  };
  const limits = () => ({ min: input.name === 'toDate' ? root.querySelector('[name="fromDate"]').value : '', max: input.name === 'fromDate' ? root.querySelector('[name="toDate"]').value : '' });
  const position = () => {
    if (!popup) return;
    const rect = trigger.getBoundingClientRect(), width = Math.min(292, window.innerWidth - 32);
    popup.style.width = `${width}px`;
    popup.style.left = `${Math.max(16, Math.min(rect.left, window.innerWidth - width - 16))}px`;
    const height = popup.getBoundingClientRect().height;
    popup.style.top = `${Math.max(16, rect.bottom + height + 20 <= window.innerHeight ? rect.bottom + 4 : rect.top - height - 4)}px`;
    syncTriggerAnchor(popup, trigger);
  };
  const render = (key = input.value) => {
    popup.innerHTML = `<div class="calendar-picker__content ui-scrollbar">${buildCalendarMonth({ year: month.getFullYear(), month: month.getMonth(), selected: input.value, ...limits() })}</div>`;
    position();
    (popup.querySelector(`[data-calendar-date="${key}"]:not(:disabled)`) || popup.querySelector('[data-calendar-date]:not(:disabled)') || popup.querySelector('button')).focus();
  };
  const click = event => {
    const button = event.target.closest('[data-calendar-trigger]');
    if (!button) return;
    if (popup && trigger === button) { close(true); return; }
    close(); trigger = button;
    input = root.querySelector(`[name="${button.dataset.calendarTrigger}"]`);
    month = input.value ? new Date(`${input.value}T12:00:00`) : new Date();
    popup = document.createElement('div'); popup.className = 'calendar-picker ui-scrollbar';
    popup.setAttribute('popover', 'manual');
    popup.setAttribute('role', 'dialog'); popup.setAttribute('aria-label', button.getAttribute('aria-label'));
    container.appendChild(popup); trigger.setAttribute('aria-expanded', 'true');
    // Keep the calendar in its form's focus/selection scope, above ancestor clipping.
    popup.showPopover();
    popup.addEventListener('click', e => {
      const date = e.target.closest('[data-calendar-date]'), nav = e.target.closest('[data-calendar-month]');
      if (date && !date.disabled) { input.value = date.dataset.calendarDate; input.dispatchEvent(new Event('input', { bubbles: true })); close(true); }
      else if (nav) { month = new Date(month.getFullYear(), month.getMonth() + Number(nav.dataset.calendarMonth), 1); render(); }
    });
    popup.addEventListener('keydown', e => {
      if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); close(true); return; }
      const day = e.target.closest('[data-calendar-date]'), offset = { ArrowLeft: -1, ArrowRight: 1, ArrowUp: -7, ArrowDown: 7 }[e.key];
      if (!day || !offset) return;
      e.preventDefault();
      const next = new Date(`${day.dataset.calendarDate}T12:00:00`); next.setDate(next.getDate() + offset);
      const key = calendarDateKey(next), { min, max } = limits();
      if ((min && key < min) || (max && key > max)) return;
      month = next; render(key);
    });
    render();
  };
  const outside = e => { if (popup && !popup.contains(e.target) && !trigger.contains(e.target)) close(); };
  root.addEventListener('click', click);
  document.addEventListener('pointerdown', outside, true);
  window.addEventListener('resize', position); window.addEventListener('scroll', position, true);
  return () => {
    close(); root.removeEventListener('click', click); document.removeEventListener('pointerdown', outside, true);
    window.removeEventListener('resize', position); window.removeEventListener('scroll', position, true);
  };
}

function calendarDateKey(date) {
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;
}

function buildCalendarMonth({ year, month, selected = '', min = '', max = '' }) {
  const first = new Date(year, month, 1), today = calendarDateKey(new Date());
  const days = Array.from({ length: first.getDay() }, () => '<span></span>');
  for (let day = 1; day <= new Date(year, month + 1, 0).getDate(); day++) {
    const date = new Date(year, month, day), key = calendarDateKey(date);
    days.push(window.ButtonComponent.renderButton({ label: String(day), className: 'calendar-picker__day', ariaLabel: date.toLocaleDateString(undefined, { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' }), disabled: Boolean((min && key < min) || (max && key > max)), attributes: { 'data-calendar-date': key, 'aria-pressed': String(key === selected), 'aria-current': key === today ? 'date' : null } }));
  }
  return `<div class="calendar-picker__header">${window.ButtonComponent.renderActionButton({ icon: 'previous', ariaLabel: 'Previous month', attributes: { 'data-calendar-month': '-1' } })}<strong aria-live="polite">${escapeHtml(first.toLocaleDateString(undefined, { month: 'long', year: 'numeric' }))}</strong>${window.ButtonComponent.renderActionButton({ icon: 'next', ariaLabel: 'Next month', attributes: { 'data-calendar-month': '1' } })}</div><div class="calendar-picker__weekdays">${Array.from({ length: 7 }, (_, day) => `<span>${escapeHtml(new Date(2023, 0, day + 1).toLocaleDateString(undefined, { weekday: 'short' }))}</span>`).join('')}</div><div class="calendar-picker__days">${days.join('')}</div>`;
}

// END js/runtime/date-range-picker.js

// BEGIN js/runtime/utility-log-history-ui.js

function canExportUtilityLogHistory() {
  return state.utility.allowedActions?.['library.logs.read'] === true && state.utility.allowedActions?.['library.logs.export'] === true;
}

function getUtilityLogHistoryController() {
  const owner = state.utility;
  if (owner.logHistoryController) return owner.logHistoryController;
  let presentation = null;
  owner.logHistoryController = createUtilityLogHistoryQueryController({
    contextKey: owner,
    fetchPage: async ({ query, cursor, snapshot, page_size }) => {
      const params = new URLSearchParams({ page_size: String(page_size) });
      Object.entries(query || {}).forEach(([key, value]) => {
        if (Array.isArray(value)) value.forEach(item => params.append(key, item));
        else if (value) params.set(key, value);
      });
      if (cursor) params.set('cursor', cursor);
      if (snapshot) params.set('snapshot', snapshot);
      const response = await fetch(`/utilities/log-history?${params}`, { cache: 'no-store', headers: { Accept: 'application/json' } });
      const data = await response.json();
      if (!response.ok || data.ok === false) throw Object.assign(new Error(data.error || 'Unable to load log history.'), { status: response.status });
      if (state.utility !== owner) { owner.logHistoryController.setContext({}); return data; }
      return data;
    },
    onAccepted: ({ query, items, page, navigationOnly, publishNavigation }) => {
      if (state.utility !== owner) return;
      if (!navigationOnly && page.snapshot) owner.logHistoryLoaded = true;
      if (!navigationOnly) owner.allowedActions = { ...(owner.allowedActions || {}),
        'library.logs.read': page.allowed_actions?.['library.logs.read'] === true,
        'library.logs.export': page.allowed_actions?.['library.logs.export'] === true };
      if (publishNavigation && !Object.keys(query || {}).length) owner.logHistory = items;
    },
    exportQuery: async request => {
      if (state.utility !== owner || !canExportUtilityLogHistory()) throw new Error('Log export is unavailable.');
      const response = await fetch('/utilities/log-history/export', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(request) });
      const data = await response.json();
      if (!response.ok || data.ok === false) throw Object.assign(new Error(data.error || 'Unable to export logs.'), { status: response.status });
      if (state.utility !== owner) throw new Error('The library changed.');
      return data;
    },
    onChange: value => {
      if (state.utility !== owner) return;
      owner.logHistoryLoading = value.loading;
      owner.logHistoryRevision = value.revision;
      owner.selectedLogHistoryId = value.selectedEventId;
      const nextPresentation = [value.query, value.snapshot, value.items, value.selectedEventId, value.temporaryRowId, value.loading, value.error, value.stale, value.refreshRequired, value.periodLabel, owner.logHistory, owner.allowedActions];
      if (presentation && presentation.every((item, index) => item === nextPresentation[index])) return;
      presentation = nextPresentation;
      const els = getUtilityModalElements();
      if (owner.activeTab === 'log-history' && els.overlay && !els.overlay.hidden) renderUtilityLogHistory();
    },
  });
  return owner.logHistoryController;
}

function formatConsoleLogEvent(item) {
  const labels = { file_count: 'Files', processed: 'Processed', downloaded: 'Downloaded', not_touched: 'Not touched', skipped: 'Skipped', not_found: 'Not found', failed: 'Failed', updated: 'Updated', succeeded: 'Succeeded' };
  const outcomes = Object.entries(labels).filter(([key]) => Number.isFinite(item[key])).map(([key, label]) => `${label}: ${item[key]}`);
  return [item.timestamp, item.action, item.source, [item.artist, item.album, item.title].filter(Boolean).join(' · '), ...outcomes, item.message, item.error].filter(Boolean).join('  ');
}

function getConsoleLogText(items) {
  return (items || []).slice().sort((a, b) => String(a.timestamp || '').localeCompare(String(b.timestamp || '')) || String(a.id).localeCompare(String(b.id))).map(formatConsoleLogEvent).join('\n');
}

function buildConsoleLog(items, { label = 'Console log' } = {}) {
  const ordered = (items || []).slice().sort((a, b) => String(a.timestamp || '').localeCompare(String(b.timestamp || '')) || String(a.id).localeCompare(String(b.id)));
  return `<section class="console-log" aria-label="${escapeHtml(label)}"><div class="console-log__heading"><span>${escapeHtml(label)} · ${ordered.length} events</span>${window.ButtonComponent.renderActionButton({ icon: 'copy', ariaLabel: 'Copy log', attributes: { 'data-log-history-action': 'copy' } })}</div><pre class="console-log__lines" tabindex="0">${ordered.length ? ordered.map(item => {
    const success = item.level === 'success' || (!item.error && /succeeded|completed|saved/i.test(item.action || ''));
    const text = formatConsoleLogEvent(item);
    return `<span class="console-log__line${success ? ' console-log__line--success' : ''}">${escapeHtml(text)}</span>`;
  }).join('\n') : 'No events in this snapshot.'}</pre></section>`;
}

function utilityLogButton(label, action, { disabled = false } = {}) {
  return window.ButtonComponent.renderButton({ label, ariaLabel: label, disabled, attributes: { 'data-log-history-action': action } });
}

function buildUtilityLogHistoryConsole(value) {
  const selected = value.items.find(item => String(item.id) === value.selectedEventId);
  const title = selected ? escapeHtml(selected.action || 'Log entry') : value.temporaryRowId ? 'Logs for selected period' : 'Recent activity';
  return `<div class="utility-log-console-detail"><div class="utility-log-toolbar"><h3>${title}</h3>${canExportUtilityLogHistory() ? utilityLogButton('Export all logs', 'export-draft') : ''}</div>
    ${selected ? `<p>${escapeHtml([formatLogHistoryTimestamp(selected.timestamp), selected.source, selected.artist, selected.album, selected.title].filter(Boolean).join(' · '))}</p>` : value.temporaryRowId ? `<p>${escapeHtml(value.periodLabel || '')}</p>` : ''}
    ${value.stale ? buildOnPageAlertHtml({ severity: 'info', role: 'status', message: 'New activity is available. Refresh to capture it.' }) : ''}
    ${value.error ? buildOnPageAlertHtml({ severity: 'error', title: 'Log history unavailable', message: value.error }) : ''}
    ${buildConsoleLog(value.items)}
    <div class="utility-log-toolbar">${utilityLogButton(value.loading ? 'Loading…' : 'Refresh', 'refresh', { disabled: value.loading })}
    ${value.nextCursor ? utilityLogButton('Load more', 'more', { disabled: value.loading || value.refreshRequired }) : ''}
    ${value.temporaryRowId ? utilityLogButton('Clear period', 'clear') : ''}
    ${canExportUtilityLogHistory() ? utilityLogButton('Export displayed logs', 'export-current', { disabled: !value.snapshot || value.loading }) : ''}</div></div>`;
}

function reconcileUtilityLogHistoryTree(els, value) {
  if (els.list.dataset.utilityNavigationOwner !== 'log-history') {
    els.list.replaceChildren();
    els.list.dataset.utilityNavigationOwner = 'log-history';
  }
  const rows = (state.utility.logHistory || []).map(item => ({ id: String(item.id), item }));
  if (typeof usesMobilePageLayout === 'function' && usesMobilePageLayout()) rows.unshift({ id: 'recent', recent: true });
  if (value.temporaryRowId) rows.unshift({ id: value.temporaryRowId, temporary: true });
  const existing = new Map(Array.from(els.list.querySelectorAll('[data-utility-log-history-id]'), node => [node.getAttribute('data-utility-log-history-id'), node]));
  const wanted = new Set(rows.map(row => row.id));
  for (const [id, node] of existing) if (!wanted.has(id)) node.remove();
  let cursor = els.list.firstElementChild;
  for (const row of rows) {
    let node = existing.get(row.id);
    if (!node) {
      const host = document.createElement('div');
      host.innerHTML = row.recent ? window.NavigationTree.renderItem({ action: true, variant: 'panel', key: 'recent', label: 'Recent activity', subtitle: 'Latest library events', attributes: { 'data-utility-log-history-id': 'recent' } }) : row.temporary ? window.NavigationTree.renderItem({ action: true, variant: 'panel', key: row.id, label: 'Selected period', subtitle: value.periodLabel || '', attributes: { 'data-utility-log-history-id': row.id, 'data-log-query-row': '1' } }) : buildUtilityLogHistoryListItem(row.item, false);
      node = host.firstElementChild;
    }
    if (node !== cursor) els.list.insertBefore(node, cursor);
    cursor = node.nextElementSibling;
    if (row.temporary) window.NavigationTree.updateItem(node, { label: 'Selected period', subtitle: value.periodLabel || '' });
    window.NavigationTree.setItemSelected(node, row.recent ? !value.selectedEventId && !value.temporaryRowId : row.temporary ? Boolean(value.temporaryRowId && !value.selectedEventId) : row.id === value.selectedEventId);
  }
  els.count.textContent = String(rows.length);
}

async function selectUtilityLogHistoryEvent(id) {
  const controller = getUtilityLogHistoryController();
  if (id === 'recent') { controller.clear(); return controller.refresh(); }
  if (id === controller.getState().temporaryRowId) return controller.selectPeriod();
  if (id === controller.getState().selectedEventId) return;
  await controller.selectEvent(id);
}

async function downloadUtilityLogHistory() {
  const data = await getUtilityLogHistoryController().exportCurrent();
  const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
  const url = URL.createObjectURL(blob); const anchor = document.createElement('a');
  anchor.href = url; anchor.download = `album-haven-logs-${new Date().toISOString().slice(0, 10)}.json`;
  anchor.click(); setTimeout(() => URL.revokeObjectURL(url), 1000);
}

function openUtilityLogHistoryQuery(exportAfter = false) {
  if (exportAfter && !canExportUtilityLogHistory()) return;
  const controller = getUtilityLogHistoryController();
  const zone = Intl.DateTimeFormat().resolvedOptions().timeZone;
  if (!exportAfter) {
    const now = new Date();
    const today = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
    let dispose = () => {};
    return showAppFormDialog({
      title: 'Date range', anchor: getUtilityModalElements().problemFilterButton,
      contentHtml: `${buildDateRangePicker({ fromDate: today, toDate: today })}<p class="utility-detail-meta">${escapeHtml(zone)}</p>`,
      submitLabel: 'Apply',
      onMount: content => { dispose = mountDateRangePicker(content); },
      onClose: () => { dispose(); controller.cancelDraft(); },
      onSubmit: async content => {
        controller.beginDraft({ preset: 'custom', fromDate: content.querySelector('[name="fromDate"]').value,
          toDate: content.querySelector('[name="toDate"]').value });
        await controller.applyDraft();
        return true;
      },
    });
  }
  let preset = 'today';
  let disposeCalendar = () => {};
  const types = Array.from(new Set(['Tags edited', 'Library status error', 'Local cover selection persisted', 'Cover art update completed', 'Library indexing failed', ...(state.utility.logHistory || []).map(item => item.action).filter(Boolean)]));
  controller.beginDraft({ preset });
  const contentHtml = `<div class="utility-log-query-form"><p>Timezone: ${escapeHtml(zone)}</p><h4>Date range</h4>
    <div class="utility-log-presets">${[['today', 'Today'], ['7-days', '7 days'], ['30-days', '30 days'], ['custom', 'Custom']].map(([value, label]) => window.ButtonComponent.renderButton({ label, attributes: { 'data-log-preset': value, 'aria-pressed': String(value === preset) } })).join('')}</div>
    <div data-log-custom-dates hidden>${buildDateRangePicker()}</div>
    <h4>Log types</h4><div class="utility-log-type-options">${types.map(value => `<label><input type="checkbox" name="eventType" value="${escapeHtml(value)}" checked> ${escapeHtml(value)}</label>`).join('')}</div>
    <label>Text<input name="text" placeholder="Filter event text"></label></div>`;
  const mount = content => {
    const dates = content.querySelector('[data-log-custom-dates]');
    const syncCalendar = () => {
      disposeCalendar();
      dates.hidden = preset !== 'custom';
      dates.querySelectorAll('input, button').forEach(control => { control.disabled = dates.hidden; });
      disposeCalendar = dates.hidden ? () => {} : mountDateRangePicker(dates);
    };
    syncCalendar();
    content.querySelectorAll('[data-log-preset]').forEach(button => button.addEventListener('click', () => {
      preset = button.getAttribute('data-log-preset');
      content.querySelectorAll('[data-log-preset]').forEach(item => item.setAttribute('aria-pressed', String(item === button)));
      syncCalendar();
    }));

  };
  return showAppFormDialog({ title: exportAfter ? 'Export all logs' : 'Filter log period', anchor: exportAfter ? null : getUtilityModalElements().problemFilterButton, contentHtml, submitLabel: exportAfter ? 'Export logs' : 'Apply', onMount: mount,
    onClose: () => { disposeCalendar(); controller.cancelDraft(); },
    onSubmit: async content => {
      const selectedTypes = Array.from(content.querySelectorAll('[name="eventType"]')).filter(input => input.checked).map(input => input.value);
      if (!selectedTypes.length) throw new Error('Choose at least one log type.');
      controller.beginDraft({ preset, fromDate: content.querySelector('[name="fromDate"]').value, toDate: content.querySelector('[name="toDate"]').value, sources: [], event_types: selectedTypes.length === types.length ? [] : selectedTypes, text: content.querySelector('[name="text"]').value });
      await controller.applyDraft(); if (exportAfter) await downloadUtilityLogHistory(); return true;
    },
  });
}

async function handleUtilityLogHistoryAction(action) {
  const controller = getUtilityLogHistoryController();
  if (action === 'copy') return navigator.clipboard.writeText(getConsoleLogText(controller.getState().items));
  if (action === 'filter') return openUtilityLogHistoryQuery(false);
  if (action === 'export-draft') return openUtilityLogHistoryQuery(true);
  if (action === 'refresh') {
    const hasSelectedQuery = Object.keys(controller.getState().query || {}).length > 0;
    return Promise.all([controller.refresh(), ...(hasSelectedQuery ? [controller.refreshNavigation()] : [])]);
  }
  if (action === 'more') return controller.loadMore();
  if (action === 'clear') { controller.clear(); const id = controller.getState().selectedEventId; return id ? controller.selectEvent(id) : controller.refresh(); }
  if (action === 'export-current') return downloadUtilityLogHistory();
}

// END js/runtime/utility-log-history-ui.js

// BEGIN js/runtime/compact-data-table.js

function buildCompactDataTable(config = {}) {
  const columns = Array.isArray(config.columnsConfig) ? config.columnsConfig : [];
  const rows = Array.isArray(config.rows) ? config.rows : [];
  const headerMode = ['visible', 'screen-reader', 'absent'].includes(config.headers)
    ? config.headers
    : 'visible';
  const density = config.density === 'default' ? 'default' : 'compact';
  const overflow = config.overflow === 'local' ? 'local' : 'none';
  const mobile = config.mobile === 'stack' ? 'stack' : 'preserve';
  const frame = ['outline', 'inset', 'none'].includes(config.frame) ? config.frame : 'inset';
  const gridColumns = String(config.columns || '').trim();
  const actionTrack = String(config.actionTrackWidth || '').trim();
  const narrowColumns = String(config.narrowColumns || '').trim();
  const styleParts = [];
  if (gridColumns) styleParts.push(`--cdt-columns: ${gridColumns}`);
  if (actionTrack) styleParts.push(`--cdt-action-track: ${actionTrack}`);
  if (narrowColumns) styleParts.push(`--cdt-narrow-columns: ${narrowColumns}`);
  const style = styleParts.length ? ` style="${escapeHtml(styleParts.join('; '))}"` : '';
  const ariaLabel = String(config.ariaLabel || '').trim();
  const selection = ['single', 'multiple'].includes(config.selection) ? config.selection : 'none';
  const fallbackIdSeed = ariaLabel || columns.map((column) => column.key || '').filter(Boolean).join('-') || 'table';
  const tableId = String(config.id || fallbackIdSeed)
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9_-]+/g, '-')
    .replace(/^-+|-+$/g, '') || 'compact-data-table';

  const buildCell = (column, cellValue, role) => {
    const cell = role === 'cell' && cellValue && typeof cellValue === 'object'
      ? cellValue
      : { content: cellValue };
    let content = cell?.content || '';
    const actionAttribute = (column.action ? ' data-cdt-action' : '') + (narrowColumns && column.hideWhenNarrow === true ? ' data-cdt-hide-narrow' : '');
    const effectiveHeaderMode = column.header || headerMode;
    // Sorting is opt-in presentation. Consumers retain row order, state and events.
    const sortable = role === 'columnheader' && effectiveHeaderMode === 'visible' && column.sortable === true
      && typeof column.key === 'string' && column.key.trim() !== '';
    const sortDirection = sortable && config.sort?.key === column.key && ['asc', 'desc'].includes(config.sort?.direction)
      ? config.sort.direction : 'default';
    const sortAttribute = sortable
      ? ` aria-sort="${sortDirection === 'asc' ? 'ascending' : sortDirection === 'desc' ? 'descending' : 'none'}"`
      : '';
    if (sortable) {
      const label = String(column.label || column.key);
      const current = sortDirection === 'asc' ? 'ascending' : sortDirection === 'desc' ? 'descending' : 'default order';
      const next = sortDirection === 'asc' ? 'descending order' : sortDirection === 'desc' ? 'default order' : 'ascending order';
      const indicator = sortDirection === 'default'
        ? '<span class="compact-data-table__sort-icon" aria-hidden="true">↕</span>'
        : ButtonComponent.renderIconSvg(sortDirection === 'asc' ? 'ascending' : 'descending', {className: 'compact-data-table__sort-icon'});
      content = ButtonComponent.renderButton({
        label, size: 'small', quiet: true, className: 'compact-data-table__sort',
        disabled: config.sortDisabled === true,
        ariaLabel: `Sort by ${label}: ${current}.${config.sortDisabled === true ? '' : ` Activate for ${next}.`}`,
        attributes: {'data-cdt-sort': column.key, 'data-cdt-sort-direction': sortDirection},
      }).replace('<span class="ui-button__content">', '<span class="ui-button__content"><span class="compact-data-table__sort-label">')
        .replace('</span>', `</span>${indicator}</span>`);
    }
    const headerClass = role === 'columnheader' && effectiveHeaderMode === 'screen-reader'
      ? ' class="sr-only"'
      : '';
    const selected = role === 'cell' && cell.ariaSelected === true ? ' aria-selected="true"' : '';
    const disabled = role === 'cell' && cell.ariaDisabled === true ? ' aria-disabled="true"' : '';
    const ariaLabel = role === 'cell' && String(cell.ariaLabel || '').trim()
      ? ` aria-label="${escapeHtml(cell.ariaLabel)}"`
      : '';
    const headerId = `${tableId}-header-${String(column.key || '').trim().toLowerCase().replace(/[^a-z0-9_-]+/g, '-')}`;
    const headerIdentity = role === 'columnheader'
      ? ` id="${escapeHtml(headerId)}"`
      : '';
    const headerAssociation = role === 'cell' && effectiveHeaderMode !== 'absent' && headerMode !== 'absent'
      ? ` aria-labelledby="${escapeHtml(headerId)}"`
      : '';
    return `<div role="${role}" data-cdt-column="${escapeHtml(column.key || '')}"${headerIdentity}${actionAttribute}${headerClass}${sortAttribute}${selected}${disabled}${ariaLabel}${headerAssociation}>${content}</div>`;
  };

  const header = headerMode === 'absent'
    ? ''
    : `<div role="row" class="compact-data-table-header">${columns
      .map((column) => (
        column.header === 'absent'
          ? `<div data-cdt-column="${escapeHtml(column.key || '')}"${column.action ? ' data-cdt-action' : ''}${narrowColumns && column.hideWhenNarrow === true ? ' data-cdt-hide-narrow' : ''} aria-hidden="true"></div>`
          : buildCell(column, escapeHtml(column.label || ''), 'columnheader')
      ))
      .join('')}</div>`;
  const body = rows.map((row) => {
    const rowClassName = String(row?.className || '')
      .split(/\s+/)
      .map((value) => value.trim())
      .filter((value) => /^[a-zA-Z0-9_-]+$/.test(value))
      .join(' ');
    const selected = row?.ariaSelected === true ? ' aria-selected="true"' : '';
    const disabled = row?.ariaDisabled === true ? ' aria-disabled="true"' : '';
    const busy = row?.ariaBusy === true ? ' aria-busy="true"' : '';
    const tabIndex = row?.tabIndex === 0 || row?.tabIndex === -1
      ? ` tabindex="${row.ariaDisabled === true ? -1 : row.tabIndex}"` : '';
    const dataAttributes = Object.entries(row?.dataAttributes || {}).map(([name, value]) => {
      const normalizedName = String(name || '').trim().toLowerCase();
      return /^[a-z0-9-]+$/.test(normalizedName)
        ? ` data-${normalizedName}="${escapeHtml(value || '')}"`
        : '';
    }).join('');
    if (Object.prototype.hasOwnProperty.call(row || {}, 'fullSpanContent')) {
      const fullSpanLabel = String(row?.ariaLabel || '').trim();
      return `<div role="row" class="compact-data-table-row compact-data-table-row--full-span${rowClassName ? ` ${rowClassName}` : ''}" data-cdt-row-key="${escapeHtml(row?.key || '')}"${dataAttributes}${fullSpanLabel ? ` aria-label="${escapeHtml(fullSpanLabel)}"` : ''}><div role="cell" data-cdt-full-span>${row.fullSpanContent || ''}</div></div>`;
    }
    return `<div role="row" class="compact-data-table-row${rowClassName ? ` ${rowClassName}` : ''}" data-cdt-row-key="${escapeHtml(row?.key || '')}"${dataAttributes}${selected}${disabled}${busy}${tabIndex}>${columns.map((column) => (
      buildCell(column, row?.cells?.[column.key] || '', 'cell')
    )).join('')}</div>`;
  }).join('');

  const empty = !rows.length
    ? `<div data-cdt-empty>${config.emptyHtml || ''}</div>`
    : '';
  const helper = config.helperHtml ? `<div data-cdt-helper>${config.helperHtml}</div>` : '';
  return `<div class="compact-data-table" id="${escapeHtml(tableId)}" role="table"${ariaLabel ? ` aria-label="${escapeHtml(ariaLabel)}"` : ''} data-cdt-headers="${headerMode}" data-cdt-density="${density}" data-cdt-overflow="${overflow}" data-cdt-mobile="${mobile}" data-cdt-frame="${frame}" data-cdt-selection="${selection}"${narrowColumns ? ' data-cdt-narrow="true"' : ''}${style}>${header}<div role="rowgroup" class="compact-data-table-body">${body}</div>${empty}${helper}</div>`;
}

// END js/runtime/compact-data-table.js

// BEGIN js/runtime/album-track-table.js

function buildAlbumTrackPlayButtonHtml(track = {}) {
  if (track.readable === false) return '';
  const trackPath = String(track.path || '');
  const title = String(track.playbackTitle || track.title || 'Track');
  const artist = String(track.artist || '');
  const albumArtist = String(track.albumArtist || track.album_artist || '');
  const album = String(track.album || '');
  const coverPath = String(track.coverPath || track.cover_path || '');
  const durationSeconds = Number(track.durationSeconds || track.duration_seconds || 0);
  const isPlaying = Boolean(track.isPlaying);
  const disabled = track.canPlay === false || track.availability === 'missing';
  const iconName = isPlaying ? 'pause' : 'play';
  const icon = ButtonComponent.renderIconSvg(iconName, {
    className: `album-track-table__play-icon ui-icon--${iconName}`,
  });
  return `<button class="play-track-button album-track-table__play" data-src="/track?path=${encodeURIComponent(trackPath)}" data-track-path="${escapeHtml(trackPath)}" data-inventory-track-ref="${escapeHtml(track.inventory_track_ref || '')}" data-track-title="${escapeHtml(title)}" data-track-artist="${escapeHtml(artist)}" data-track-album-artist="${escapeHtml(albumArtist)}" data-track-album="${escapeHtml(album)}" data-track-cover="${escapeHtml(coverPath)}" data-track-duration-seconds="${durationSeconds}" type="button" aria-label="${isPlaying ? 'Pause track' : 'Play track'}"${disabled ? ' disabled aria-disabled="true"' : ''}>${icon}</button>`;
}

function buildAlbumTrackTableRow(track = {}, index = 0, config = {}) {
  const denied = track.readable === false;
  if (denied) track = {rowKey: track.rowKey, readable: false, selectable: false, title: 'Unavailable track'};
  const readOnly = config.readOnly === true || denied;
  const trackPath = readOnly ? '' : String(track.path || '');
  const classes = ['album-track-table__row'];
  if (track.availability === 'missing') classes.push('album-track-table__row--missing');
  if (!readOnly && track.isCurrent) classes.push('album-track-table__row--current');
  if (!readOnly && track.isPlaying) classes.push('album-track-table__row--playing');
  if (track.isSearchMatch) classes.push('album-track-table__row--search-match');
  if (!readOnly && track.isPlaying && config.playingAnimation !== false) classes.push('album-track-table__row--animated');
  const secondary = String(track.secondaryArtist || track.secondary_artist || '').trim();
  const titleHtml = `<span class="album-track-table__title">${escapeHtml(track.title || '')}${secondary ? `<span class="album-track-table__secondary">${escapeHtml(secondary)}</span>` : ''}</span>`;
  const problemHtml = !readOnly && track.isProblematic
    ? `<button class="track-problem-link" type="button" data-open-track-problematic="1" data-track-path="${escapeHtml(trackPath)}" title="Open this track in Problematic Files" aria-label="Open this track in Problematic Files">!</button>`
    : '';
  const displayPath = readOnly ? '' : String(track.displayPath || track.display_path || trackPath).trim();
  const rowKey = typeof track.rowKey === 'string' && track.rowKey ? track.rowKey : null;
  const selectable = Boolean(rowKey) && track.readable === true && track.selectable !== false;
  return {
    key: config.selection === 'multiple' ? rowKey || ''
      : rowKey || (readOnly ? String(track.id || index + 1) : trackPath || `${index + 1}`),
    className: classes.join(' '),
    ...(config.selection === 'multiple' || denied ? {tabIndex: selectable ? 0 : -1,
      ariaDisabled: !selectable, ariaSelected: selectable && track.isSelected === true} : {}),
    dataAttributes: readOnly ? {} : {
      'track-row-path': trackPath,
      'track-search-match': track.isSearchMatch ? 'true' : '',
      'track-playing': track.isPlaying ? 'true' : '',
    },
    cells: {
      number: { content: `<span class="album-track-table__number-play"><span class="album-track-table__number">${escapeHtml(track.trackNumber || track.track_number || index + 1)}</span>${readOnly ? '' : buildAlbumTrackPlayButtonHtml(track)}</span>` },
      title: { content: titleHtml },
      path: { content: `<span class="album-track-table__path" title="${escapeHtml(displayPath)}">${escapeHtml(displayPath)}</span>` },
      problem: { content: problemHtml },
      rating: {content: config.subjectTaste && track.subjectTasteState === 'available'
        && Object.hasOwn(track, 'subjectRating') && track.subjectRating === null
        ? buildGalleryRatingHtml({value: 0, maximum: 5, label: 'Track unrated', compact: true})
        : escapeHtml(config.subjectTaste && Number.isInteger(track.subjectRating) ? track.subjectRating : '–')},
      love: {content: config.subjectTaste && ['off', 'loved', 'obsessed'].includes(track.subjectLove)
        ? `<span role="img" aria-label="${escapeHtml(track.subjectLove)}">${ButtonComponent.renderIconSvg(`love-${track.subjectLove}`)}</span>`
        : config.subjectTaste ? '–' : '<span data-track-love-cell="1"><span role="img" aria-label="Love unavailable">–</span></span>'},
      duration: { content: `<span class="track-duration" ${readOnly ? '' : `data-track-duration-path="${escapeHtml(trackPath)}" data-original-duration="${escapeHtml(track.originalDuration || track.duration || '')}"`}>${escapeHtml(track.duration || '')}</span>` },
    },
  };
}

function albumTrackTableColumns(config = {}) {
  return [
    {key: 'number', label: '#', required: true, width: 36},
    {key: 'title', label: 'Track', identity: true, width: 100},
    ...(config.showPath ? [{key: 'path', label: 'File path', width: 220, autoMinWidth: 641}] : []),
    ...(config.subjectTaste ? [{key: 'rating', label: 'Rating', width: 52, autoMinWidth: 481}] : []),
    ...(config.showLove !== false || config.subjectTaste ? [{key: 'love', label: 'Love', required: true, width: 36}] : []),
    ...(config.showProblem === true || (config.groups || []).some(group => (group.tracks || []).some(track => track.isProblematic))
      ? [{key: 'problem', label: 'Problem', header: 'absent', action: true, width: 20, autoMinWidth: 641}] : []),
    {key: 'duration', label: 'Length', action: true, required: true, width: 54},
  ];
}

function buildAlbumTrackTableHtml(config = {}) {
  const groups = Array.isArray(config.groups) ? config.groups : [];
  const columnsConfig = albumTrackTableColumns(config);
  const forceGroupLabels = Boolean(config.forceGroupLabels);
  const ariaLabel = String(config.ariaLabel || 'Album tracks').trim() || 'Album tracks';
  const idPrefix = String(config.idPrefix || 'album-track-table').trim() || 'album-track-table';
  const multiDisc = Boolean(config.multiDisc) || groups.length > 1;
  const mainDiscCount = groups.filter((group) => !group?.isBonus).length;
  const tableSections = groups.map((group, groupIndex) => {
    const tracks = Array.isArray(group?.tracks) ? group.tracks : [];
    const label = String(group?.discLabel || (group?.discNumber ? `CD ${group.discNumber}` : '')).trim();
    const showLabel = Boolean(label) && (
      forceGroupLabels
      || (multiDisc && (Boolean(group?.isBonus) || mainDiscCount > 1))
    );
    const table = buildCompactDataTable({
      id: `${idPrefix}-tracks-${groupIndex + 1}`,
      ariaLabel: label ? `${ariaLabel} — ${label}` : ariaLabel,
      headers: groupIndex === 0 ? 'visible' : 'absent',
      columns: config.columns || columnsConfig.map(column => column.identity ? 'minmax(0,1fr)' : `${column.width}px`).join(' '),
      columnsConfig,
      rows: tracks.map((track, index) => buildAlbumTrackTableRow(track, index, config)),
      density: 'compact',
      frame: 'outline',
      overflow: config.overflow || 'local',
      mobile: 'preserve',
      selection: config.selection,
    });
    const sectionKey = typeof group?.sectionKey === 'string' ? group.sectionKey : '';
    const action = config.sectionActions === true && sectionKey
      ? ButtonComponent.renderActionButton({icon: 'more-vertical', presentation: 'bare',
        className: 'album-track-table__section-action', ariaLabel: `Actions for ${label || 'this section'}`,
        title: 'Add section to playlist', disabled: !tracks.length || group.sectionActionDisabled === true
          || tracks.some(track => track.readable === false || track.selectable === false),
        attributes: {'data-playtable-section-action': sectionKey}}) : '';
    const heading = showLabel
      ? `<h4 class="album-track-table__disc-heading">${escapeHtml(label)}</h4>`
      : '';
    const header = action ? `<div class="album-track-table__section-heading">${heading}${action}</div>` : heading;
    return `<section class="album-track-table__disc"${sectionKey ? ` data-playtable-section="${escapeHtml(sectionKey)}"` : ''}>${header}${table}</section>`;
  }).join('');
  const totalLength = String(config.totalLength || '').trim();
  const mainLength = String(config.mainLength || '').trim();
  const bonusLength = String(config.bonusLength || '').trim();
  const summaries = [
    totalLength ? `<div class="album-track-table__aggregate-total">Total Length: ${escapeHtml(totalLength)}</div>` : '',
    mainLength ? `<div class="album-track-table__main-total">Total Main Album Length: ${escapeHtml(mainLength)}</div>` : '',
    bonusLength ? `<div class="album-track-table__bonus-total">Bonus Disc Length: ${escapeHtml(bonusLength)}</div>` : '',
  ].join('');
  return `<div class="album-track-table" data-playing-animation="${config.playingAnimation === false ? 'disabled' : 'enabled'}"><div class="album-track-table__frame">${tableSections}${summaries ? `<div class="album-track-table__total">${summaries}</div>` : ''}</div></div>`;
}

function triggerAlbumTrackPlayActivation(button) {
  if (!button?.classList?.add || !button?.classList?.remove) return;
  button.classList.remove('album-track-table__play--activating');
  void button.offsetWidth;
  button.classList.add('album-track-table__play--activating');
  button.addEventListener?.('animationend', () => {
    button.classList.remove('album-track-table__play--activating');
  }, { once: true });
}

// END js/runtime/album-track-table.js

// BEGIN js/runtime/utility-list-builders.js

function buildUtilityLogHistoryListItem(item, selected) {
  return window.NavigationTree.renderItem({ action: true, variant: 'panel', key: String(item.id), selected,
    label: item.action || 'Activity', subtitle: [item.artist, item.album, item.title].filter(Boolean).join(' · ') || item.source || '',
    year: formatLogHistoryTimestamp(item.timestamp), attributes: { 'data-utility-log-history-id': String(item.id) } });
}

function buildUtilityLogHistoryDetail(item) {
  return buildConsoleLog(item ? [item] : []);
}

function getSelectedUtilityLoop() {
  return (state.utility.loops || []).find((item) => String(item.id || '') === String(state.utility.selectedLoopId || '')) || null;
}

function getSelectedUtilityLoopGroup() {
  const groups = groupUtilityLoops(state.utility.loops || []);
  const selectedGroupKey = String(state.utility.selectedLoopGroupKey || '');
  if (selectedGroupKey) {
    const direct = groups.find((group) => String(group?.key || '') === selectedGroupKey);
    if (direct) return direct;
  }
  const selectedLoop = getSelectedUtilityLoop();
  const selectedKey = selectedLoop ? buildUtilityLoopGroupKey(selectedLoop) : '';
  return groups.find((group) => String(group?.key || '') === selectedKey) || null;
}

function getFilteredUtilityLoops() {
  const query = String(state.utility.loopsSearchQuery || '').trim().toLocaleLowerCase();
  const loops = state.utility.loops || [];
  return query ? loops.filter(loop => [loop.name, loop.title, loop.artist, loop.album]
    .some(value => String(value || '').toLocaleLowerCase().includes(query))) : loops;
}

function buildUtilityLoopMoveActions(loop) {
  if (!canReorderUtilityLoop(loop)) return '';
  return `<span class="utility-loop-reorder-actions" role="group" aria-label="Reorder ${escapeHtml(loop.name || 'Saved loop')}">${['up', 'down'].map(direction => window.ButtonComponent.renderButton({
    label: `Move ${direction}`, size: 'small', ariaLabel: `Move ${loop.name || 'Saved loop'} ${direction}`,
    attributes: { 'data-move-utility-loop': loop.id, 'data-loop-move-direction': direction },
  })).join('')}</span>`;
}

function buildUtilityLoopEntry(loop) {
  const mediaSrc = `/loops/media/${encodeURIComponent(loop.id || '')}`;
  const loopId = escapeHtml(loop.id || '');
  const repeatEnabled = Boolean(state.utility.loopRepeatEnabled) && String(state.utility.selectedLoopId || '') === String(loop.id || '');
  return `
    <section class="utility-loop-entry ${repeatEnabled ? 'is-active' : ''}" data-utility-loop-entry="${escapeHtml(loop.id || '')}" data-loop-song-key="${escapeHtml(buildUtilityLoopGroupKey(loop))}" draggable="${canReorderUtilityLoop(loop)}">
      ${buildUtilityLoopMoveActions(loop)}
      <div class="utility-loop-heading">
        <span class="utility-loop-drag-handle" aria-hidden="true">⋮⋮</span>
        <h3 class="utility-detail-title">${escapeHtml(loop.name || 'Saved loop')}</h3>
        <span class="utility-loop-original-times"><span>Original timestamps</span><strong>${loop.original_start_seconds != null && loop.original_end_seconds != null ? `${formatLoopTime(loop.original_start_seconds, true)} – ${formatLoopTime(loop.original_end_seconds, true)}` : 'Unavailable'}</strong></span>
        ${state.utility.allowedActions?.['library.loops.delete'] === true ? window.ButtonComponent.renderActionButton({ icon: 'delete', semantic: 'destructive', ariaLabel: `Delete ${loop.name || 'Saved loop'}`, title: `Delete ${loop.name || 'Saved loop'}`, className: 'utility-loop-remove', attributes: { 'data-delete-saved-loop': loop.id || '' } }) : ''}
      </div>
      <div class="utility-loop-shell" data-utility-loop-shell="${escapeHtml(loop.id || '')}">
        <audio class="utility-loop-audio" data-loop-audio="${escapeHtml(loop.id || '')}" data-original-src="${mediaSrc}" data-loop-duration="${Math.max(0, Number(loop.duration_seconds) || 0)}" src="${mediaSrc}" preload="none"></audio>
        ${renderPlaybackControlCluster({
          variant: 'saved-loop',
          ownerId: `saved-loop-${String(loop.id || '')}`,
          loopId: String(loop.id || ''),
        })}
        <div class="utility-loop-main" data-saved-loop-main-surface="${loopId}">
          <div class="utility-loop-player-top-row" data-loop-player-top-row>
            <div class="utility-loop-control utility-loop-pitch-control" data-loop-pitch-control="${loopId}" data-loop-pitch-controls="${loopId}" aria-label="Pitch shift">
              <button type="button" data-loop-pitch-step="-1" aria-label="Lower pitch">-</button>
              <span data-loop-pitch-value>0 pst</span>
              <button type="button" data-loop-pitch-step="1" aria-label="Raise pitch">+</button>
            </div>
            <div class="utility-loop-time" data-loop-time="${loopId}">0:00 / 0:00</div>
          </div>
          <div class="utility-loop-timeline-wrap">
            <canvas class="utility-loop-stereo-waveform" data-loop-stereo-waveform="${loopId}" aria-hidden="true" hidden></canvas>
            <input class="utility-loop-timeline" type="range" data-loop-timeline="${escapeHtml(loop.id || '')}" min="0" max="100" step="0.01" value="0" aria-label="Playback position">
            <div class="loop-range-surface" data-loop-range-owner="saved-loop-${loopId}" data-loop-range-surface hidden>
              <canvas class="utility-saved-loop-waveform" data-loop-range-waveform aria-hidden="true"></canvas>
              <div class="loop-range-selection"></div>
              <button class="loop-range-handle is-start" type="button" role="slider" data-loop-range-handle="start" aria-label="Loop start"></button>
              <button class="loop-range-handle is-end" type="button" role="slider" data-loop-range-handle="end" aria-label="Loop end"></button>
            </div>
          </div>
        </div>
        <button class="utility-loop-repeat ${repeatEnabled ? 'is-active' : ''}" type="button" data-toggle-loop-repeat="${escapeHtml(loop.id || '')}" aria-pressed="${repeatEnabled ? 'true' : 'false'}" aria-label="${repeatEnabled ? 'Disable repeat' : 'Enable repeat'}" title="${repeatEnabled ? 'Disable repeat' : 'Enable repeat'}">&#8635;</button>
        ${window.ButtonComponent.renderButton({ label: 'Pitch 0', size: 'small', className: 'utility-loop-pitch-button', ariaLabel: 'Pitch shift', attributes: { 'data-loop-pitch-value-button': loop.id || '', 'aria-haspopup': 'menu', 'aria-expanded': 'false' } })}
        <div class="utility-loop-speed-menu utility-loop-pitch-menu" data-loop-pitch-menu="${loopId}" role="menu" aria-label="Pitch shift" hidden>
          ${Array.from({ length: 25 }, (_, index) => index - 12).map(value => `<button type="button" role="menuitemradio" aria-checked="${value === 0}" data-loop-pitch-option="${value}">${value === 0 ? 'Original pitch' : `${value > 0 ? '+' : ''}${value} semitones`}</button>`).join('')}
        </div>
        <div class="utility-loop-speed-control" data-loop-speed-control="${escapeHtml(loop.id || '')}" aria-label="Playback speed">
          <button class="utility-loop-speed-step" type="button" data-loop-speed-step="-0.05" aria-label="Decrease speed">-</button>
          <button class="utility-loop-speed-value" type="button" data-loop-speed-value-button="${escapeHtml(loop.id || '')}" aria-label="Playback speed" aria-haspopup="menu" aria-expanded="false">1x</button>
          <button class="utility-loop-speed-step" type="button" data-loop-speed-step="0.05" aria-label="Increase speed">+</button>
          <div class="utility-loop-speed-menu" data-loop-speed-menu="${escapeHtml(loop.id || '')}" hidden>
            <button type="button" data-loop-speed-option="0.25">0.25x</button>
            <button type="button" data-loop-speed-option="0.50">0.5x</button>
            <button type="button" data-loop-speed-option="0.75">0.75x</button>
            <button type="button" data-loop-speed-option="1.00">1x</button>
            <button type="button" data-loop-speed-option="1.25">1.25x</button>
            <button type="button" data-loop-speed-option="1.50">1.5x</button>
            <button type="button" data-loop-speed-option="1.75">1.75x</button>
            <button type="button" data-loop-speed-option="2.00">2x</button>
          </div>
        </div>
      </div>
    </section>
  `;
}

function buildUtilityLoopDetail(loopGroup, selectedLoop = null) {
  const group = loopGroup;
  if (!group || !Array.isArray(group.loops) || !group.loops.length) {
    return '<div class="utility-empty-state">Select a saved song to inspect its loops.</div>';
  }
  const representative = group.representativeLoop || group.loops[0];
  const coverHtml = buildUtilityAlbumArtbox(representative, {
    label: `Artwork for ${representative.title || representative.name || 'loop'}`, interactive: true,
  });
  const loopsToRender = group.loops;
  const headerTitle = representative.title || representative.name || 'Saved loops';
  const artistLine = representative.artist || '';
  const albumLine = representative.album || '';
  const yearLine = representative.year ? String(representative.year) : '';
  return `
    <div class="utility-loop-detail utility-loop-group-detail">
      <div class="utility-loop-detail-header">
        <div class="utility-detail-cover utility-loop-sticky-cover">${coverHtml}</div>
        <div class="utility-loop-group-summary">
          <div>
            <h3 class="utility-detail-title">${escapeHtml(headerTitle)}</h3>
            <div class="utility-detail-meta">${escapeHtml(artistLine || 'Unknown artist')}</div>
            <div class="utility-detail-meta">${escapeHtml(albumLine || 'Unknown album')}</div>
            ${yearLine ? `<div class="utility-detail-meta">${escapeHtml(yearLine)}</div>` : ''}
          </div>
          <div class="utility-detail-meta">${escapeHtml(`${group.loops.length} saved loop${group.loops.length === 1 ? '' : 's'}`)}</div>
        </div>
      </div>
      <div class="utility-loop-group-main">
        <div class="utility-loop-entry-list" data-loop-panel-song="${escapeHtml(group.key || '')}">${loopsToRender.map((loop) => buildUtilityLoopEntry(loop)).join('')}</div>
      </div>
    </div>
  `;
}

function buildUtilityAppearanceListItem(key, title, subtitle, selected) {
  return `
    <button class="utility-list-item ${selected ? 'is-active' : ''}" type="button" data-utility-appearance-key="${escapeHtml(key)}">
      <span class="utility-list-item-title">${escapeHtml(title)}</span>
      <span class="utility-list-item-meta">${escapeHtml(subtitle)}</span>
    </button>
  `;
}

function buildUtilityAppearanceDetail() {
  return `
    <div class="utility-rule-detail">
      <div data-appearance-seekbar-editor></div>
    </div>
  `;
}

function buildUtilityIntegrationListItem(item, selected) {
  return window.NavigationTree.renderItem({
    action: true, variant: 'panel', key: String(item?.key || ''), selected,
    label: item?.title || 'Integration',
    attributes: { 'data-utility-integration-key': String(item?.key || '') },
  });
}

function buildLastfmTimeZoneOptions(selectedTimeZone) {
  const selected = String(selectedTimeZone || '').trim();
  const detectedTimeZone = getDetectedBrowserTimeZone();
  const supported = new Set(getSupportedBrowserTimeZones());
  if (detectedTimeZone) supported.add(detectedTimeZone);
  if (selected) supported.add(selected);
  return Array.from(supported)
    .sort((left, right) => left.localeCompare(right, undefined, { sensitivity: 'base' }))
    .map((timeZone) => `<option value="${escapeHtml(timeZone)}" ${timeZone === selected ? 'selected' : ''}>${escapeHtml(timeZone)}</option>`)
    .join('');
}

function buildUtilityIntegrationDetail(item) {
  const button = options => window.ButtonComponent.renderButton(options);
  if (item?.key === 'library') return buildUtilityLibrarySettingsDetail(item);
  if (item?.key === 'local_playlist_import') {
    return `<div class="utility-rule-detail"><h3 class="utility-rule-title">Import Local Playlist</h3><div class="settings-integration-actions">${button({ label: 'Import', disabled: true, attributes: { 'data-local-playlist-import': '1' } })}</div></div>`;
  }
  if (item?.key === 'foobar') {
    if (window.AlbumHavenCapabilities?.allows('account.self.foobar.write') !== true)
      return '<div class="utility-empty-state">Foobar import is unavailable.</div>';
    return `<div class="utility-rule-detail"><h3 class="utility-rule-title">Foobar2000</h3>
      <div data-foobar-import-host><p role="status">Loading import controls…</p></div></div>`;
  }
  if (!item || item.key !== 'lastfm') return '<div class="utility-empty-state">Select an integration.</div>';
  const draft = state.utility.integrationDrafts?.lastfm || {};
  const enabled = item.api_configured && !item.connected;
  const statistics = item.playback_statistics;
  const plays = statistics && Number.isFinite(Number(statistics.local_playcount)) ? String(statistics.local_playcount) : 'Unavailable';
  const seconds = statistics ? Number(statistics.total_listening_seconds) : NaN;
  const minutes = Math.floor(seconds / 60), hours = Math.floor(minutes / 60);
  const duration = Number.isFinite(seconds) && seconds >= 0
    ? `${hours ? `${hours} ${hours === 1 ? 'hour' : 'hours'} ` : ''}${minutes % 60} ${minutes % 60 === 1 ? 'minute' : 'minutes'}` : 'Unavailable';
  const scrobbleState = state.utility.lastfmScrobbles || {};
  const summary = scrobbleState.summary;
  const scrobbled = summary?.scrobbled ?? item.listen_history_count ?? 0;
  const pending = summary?.pending ?? item.pending_scrobble_count ?? 0;
  const lastfmTotal = scrobbleState.loading
    ? 'Loading...'
    : summary?.lastfm_total == null ? 'Unavailable' : String(summary.lastfm_total);
  const scrobbleStatus = item.connected ? `<div class="lastfm-scrobble-status" aria-label="Last.fm scrobble status">
      <p data-lastfm-scrobbled>Scrobbled: ${escapeHtml(String(scrobbled))}</p>
      <p data-lastfm-total>LastFM Total: ${escapeHtml(lastfmTotal)}</p>
      <p data-lastfm-pending>Pending: ${escapeHtml(String(pending))}</p>
    </div>` : '';
  const submitScrobbles = item.connected ? `<div class="settings-lastfm-submit-action">${button({
    label: scrobbleState.submitting ? 'Submitting...' : 'Submit',
    disabled: scrobbleState.submitting || Number(pending) <= 0 || summary?.can_submit !== true,
    attributes: { 'data-submit-lastfm-scrobbles': '1' },
  })}</div>` : '';
  return `<div class="utility-rule-detail"><h3 class="utility-rule-title settings-scrobbling-heading">Last.FM
      ${item.connected ? '<span class="settings-connected-status"><span aria-hidden="true">&#10003;</span><span>Connected</span></span>' : ''}</h3>
    ${scrobbleStatus}
    <form class="lastfm-integration-form" data-lastfm-integration-form="1"><div class="lastfm-credentials-grid">
      <label class="lastfm-inline-field"><span>Username</span><input class="utility-search-input" type="text" value="${escapeHtml(draft.username || item.username || '')}" data-lastfm-field="username" autocomplete="username" placeholder="Username or email" ${enabled ? '' : 'disabled'}></label>
      <label class="lastfm-inline-field"><span>Password</span><input class="utility-search-input" type="password" value="${escapeHtml(draft.password || '')}" data-lastfm-field="password" autocomplete="current-password" placeholder="${item.connected ? 'Disconnect to reconnect' : 'Password'}" ${enabled ? '' : 'disabled'}></label></div>
      <div class="settings-integration-actions">${button({ label: 'Connect Last.FM', type: 'submit', disabled: !enabled, attributes: { 'data-save-lastfm-integration': '1' } })}
      ${button({ label: 'Disconnect', disabled: !item.connected, attributes: { 'data-disconnect-lastfm-integration': '1' } })}</div></form>
      ${!item.api_configured ? '<p class="utility-rule-album-meta">Last.FM connection is unavailable on this server.</p>' : ''}
      <section class="library-settings-section settings-playback-statistics"><h4>Playback statistics</h4><dl><div><dt>Local playcount</dt><dd>${escapeHtml(plays)}</dd></div><div><dt>Total listening time</dt><dd>${escapeHtml(duration)}</dd></div></dl></section>
      ${submitScrobbles}</div>`;
}

function matchesUtilityRuleSearch(item) {
  const query = String(state.utility.rulesSearchQuery || '').trim().toLocaleLowerCase();
  if (!query) return true;
  return [item?.name, item?.artist, item?.album_artist, item?.album, item?.title,
    item?.filename, item?.year, item?.edition, item?.problem_reason, item?.reason]
    .filter(value => value !== null && value !== undefined)
    .join(' ').toLocaleLowerCase().includes(query);
}

function buildVersionExceptionRuleDetail(rule) {
  const albums = (Array.isArray(rule?.albums) ? rule.albums : []).filter(matchesUtilityRuleSearch);
  const table = albums.length ? buildUtilityCompactTable({
    id: 'version-exceptions', ariaLabel: 'Version exceptions',
    columns: 'minmax(220px,1fr) minmax(180px,1fr) 110px',
    columnsConfig: [{ key: 'target', label: 'Artist / Album' }, { key: 'effect', label: 'Rule' }, { key: 'action', label: 'Actions', header: 'screen-reader', action: true }],
    headers: 'visible', density: 'compact', overflow: 'local', mobile: 'stack', frame: 'outline', actionTrackWidth: '110px',
    rows: albums.map(album => ({ key: album.key, cells: {
      target: `<span class="utility-rule-target">${buildUtilityAlbumArtbox(album, { label: `Artwork for ${album.name || 'album'}` })}<span><span class="utility-rule-album-title">${escapeHtml(album.name || album.key || 'Unknown album')}</span><span class="utility-rule-album-meta">${escapeHtml([album.album_artist, album.year].filter(Boolean).join(' · '))}</span></span></span>`,
      effect: escapeHtml(album.edition ? `Edition: ${album.edition}` : 'Excluded from album version tabs'),
      action: ButtonComponent.renderButton({ label: 'Revert rule', className: 'utility-rule-revert', attributes: { 'data-revert-version-exception': album.key || '' } }),
    } })),
  }) : `<p class="utility-detail-meta">${rule?.albums?.length ? 'No version exceptions match your search.' : 'No version exceptions yet.'}</p>`;
  return `<div class="utility-rule-detail"><h3 class="utility-rule-title">${escapeHtml(rule?.title || 'Version exceptions')}</h3><p class="utility-rule-description">${escapeHtml(rule?.description || 'Albums listed here are not counted as versions of another album with the same title.')}</p>${table}</div>`;
}
function buildUtilityCompactTable(config) {
  if (typeof buildCompactDataTable !== 'function') {
    throw new Error('CompactDataTable is not registered.');
  }
  return buildCompactDataTable(config);
}

function buildProblemIgnoresRuleDetail(rule) {
  const albumItems = (Array.isArray(rule?.album_items) ? rule.album_items : []).filter(matchesUtilityRuleSearch);
  const fileItems = (Array.isArray(rule?.file_items) ? rule.file_items : []).filter(matchesUtilityRuleSearch);
  if (Array.isArray(rule?.album_items) || Array.isArray(rule?.file_items)) {
    const columns = 'minmax(220px,.42fr) minmax(180px,.58fr) 88px';
    const columnsConfig = (targetLabel) => [
      { key: 'target', label: targetLabel },
      { key: 'reason', label: 'Reason' },
      { key: 'action', label: 'Actions', header: 'screen-reader', action: true },
    ];
    const table = (items, targetLabel, ariaLabel, id, scope) => buildUtilityCompactTable({
      id,
      ariaLabel,
      columns,
      columnsConfig: columnsConfig(targetLabel),
      headers: 'visible',
      density: 'compact',
      overflow: 'local',
      mobile: 'stack',
      frame: 'outline',
      actionTrackWidth: '88px',
      rows: items.map((item) => {
        const albumDisplay = [item.artist, item.album || item.title, item.year]
          .map((value) => String(value || '').trim())
          .filter(Boolean)
          .join(' - ');
        return {
          key: String(item.row_key || ''),
          ariaBusy: Boolean(item.pending),
          cells: {
            target: `<div class="utility-rule-album-title">${escapeHtml(
              scope === 'album' ? (albumDisplay || 'Unknown album') : (item.filename || 'Unknown file'),
            )}</div>${scope === 'file' && item.album ? `<div class="utility-rule-album-meta">${escapeHtml(item.album)}</div>` : ''}`,
            reason: `<span class="utility-track-problem-chip utility-rule-problem-chip">${escapeHtml(item.problem_reason || item.reason || '')}</span>`,
            action: `<button class="button utility-rule-revert" type="button" data-revert-problem-ignore="${escapeHtml(item.row_key || '')}" ${item.pending ? 'aria-busy="true" disabled' : ''}>Revert rule</button>`,
          },
        };
      }),
    });
    return `
      <div class="utility-rule-detail utility-problem-exclusions-detail">
        <h3 class="utility-rule-title">${escapeHtml(rule?.title || 'Problem exclusions')}</h3>
        <p class="utility-rule-description">${escapeHtml(rule?.description || 'Album or file problems excluded from Problematic Files.')}</p>
        ${!albumItems.length && !fileItems.length ? `<p class="utility-detail-meta">${rule.album_items?.length || rule.file_items?.length ? 'No problem exclusions match your search.' : 'No problem exclusions yet.'}</p>` : ''}
        ${albumItems.length ? `<section class="utility-problem-exclusion-group">
          <h4 class="utility-detail-section-title">ALBUM EXCLUSIONS</h4>
          ${table(albumItems, 'Artist / Album', 'Album exclusions', 'problem-exclusions-album', 'album')}
        </section>` : ''}
        ${fileItems.length ? `<section class="utility-problem-exclusion-group">
          <h4 class="utility-detail-section-title">FILE EXCLUSIONS</h4>
          ${table(fileItems, 'Filename', 'File exclusions', 'problem-exclusions-file', 'file')}
        </section>` : ''}
      </div>
    `;
  }
  const items = (Array.isArray(rule?.items) ? rule.items : []).filter(matchesUtilityRuleSearch);
  const groups = groupProblemIgnoreItems(items);
  const rows = groups.length
    ? groups.map((group) => {
      const content = `
        <div class="utility-rule-album-list">
          ${group.items.map((item) => {
            const title = item.filename || item.row_key || 'Unknown file';
            const reason = String(item.problem_reason || '').trim();
            return `
              <div class="utility-rule-album-row utility-rule-problem-row">
                <div class="utility-rule-album-main">
                  <div class="utility-rule-album-title">${escapeHtml(title)}</div>
                  ${reason ? `<div class="utility-rule-problem-labels"><span class="utility-track-problem-chip utility-rule-problem-chip">${escapeHtml(reason)}</span></div>` : ''}
                </div>
                <button class="button utility-rule-revert" type="button" data-revert-problem-ignore="${escapeHtml(item.row_key || '')}" ${item.pending ? 'aria-busy="true" disabled' : ''}>Revert rule</button>
              </div>
            `;
          }).join('')}
        </div>
      `;
      return buildUtilityCollapsibleSection(
        `rule-problem-ignore:${group.key}`,
        getProblemIgnoreGroupTitle(group),
        content,
      );
    }).join('')
    : '<div class="utility-empty-state">No album or file problems are currently excluded.</div>';
  return `
    <div class="utility-rule-detail">
      <h3 class="utility-rule-title">${escapeHtml(rule?.title || 'Problem exclusions')}</h3>
      <p class="utility-rule-description">${escapeHtml(rule?.description || 'Album or file problems excluded from Problematic Files.')}</p>
      <div class="utility-rule-album-list">${rows}</div>
    </div>
  `;
}

function buildUtilityRuleDetail(rule) {
  if (!rule) {
    return '<div class="utility-empty-state">Select a rule to inspect where it is applied.</div>';
  }
  if (rule.key === 'version-exceptions') {
    return buildVersionExceptionRuleDetail(rule);
  }
  if (rule.key === 'problem-ignores') {
    return buildProblemIgnoresRuleDetail(rule);
  }
  return '<div class="utility-empty-state">No detail view is available for this rule yet.</div>';
}

function openAlbumOnDiscogs(album) {
  if (!album) {
    showRepairAlert('No album selected for Discogs search.', 'error');
    return;
  }
  window.open(buildDiscogsSearchUrl(album), '_blank', 'noopener,noreferrer');
}

function buildUtilityCollapsibleSection(sectionKey, title, contentHtml) {
  const collapsed = Boolean(state.utility.collapsedSections?.[sectionKey]);
  const cardClass = String(sectionKey || '').startsWith('rule-problem-ignore:') ? ' utility-detail-section-card' : '';
  return `
    <div class="utility-detail-section${cardClass} ${collapsed ? 'is-collapsed' : ''}">
      <button class="utility-section-toggle" type="button" data-utility-section-toggle="${escapeHtml(sectionKey)}" aria-expanded="${collapsed ? 'false' : 'true'}">
        <span class="utility-detail-section-title">${escapeHtml(title)}</span>
        <span class="utility-section-chevron" aria-hidden="true">›</span>
      </button>
      <div class="utility-section-content" ${collapsed ? 'hidden' : ''}>
        ${contentHtml}
      </div>
    </div>
  `;
}

function buildDetectedProblemsHtml(album) {
  const albumMissing = String(album?.inventory_status || '').trim().toLowerCase() === 'missing';
  if (albumMissing) {
    const canRemove = Boolean(album?.allowed_actions?.['library.inventory.manage']);
    return `
      <div class="sr-only" data-problem-exclusion-status role="status" tabindex="-1"></div>
      <div class="utility-album-problem-list">
        <div class="utility-problem-level-heading"><span>ALBUM-LEVEL PROBLEMS</span></div>
        <div class="utility-album-problem-content">
          ${buildAlertLabelHtml({ severity: 'error', message: 'Album not found' })}
        </div>
      </div>
      <div class="utility-detected-actions utility-missing-album-actions">
        ${canRemove
          ? '<button class="button confirm-modal-danger" type="button" data-remove-missing-album="1">Remove from Album Haven</button>'
          : '<p>Ask an owner or administrator to remove it.</p>'}
      </div>
    `;
  }
  const rows = (Array.isArray(album?.track_problem_rows) ? album.track_problem_rows : []).map(row => ({ ...row }));
  const proposals = getVisibleProblemSuggestions(album);
  proposals.forEach(proposal => {
    if (!rows.some(row => row.path === proposal.path)) rows.push({ path: proposal.path, filename: getFilenameFromPath(proposal.path), reasons: [], ignorable_reasons: [] });
  });
  const selectedFilters = (state.utility.selectedProblemFilters || []).map(normalizeProblemFilterReason);
  const visibleReason = reason => !selectedFilters.length || selectedFilters.includes(normalizeProblemFilterReason(reason));
  const coverReasons = new Set(['Missing cover art', 'Poor art quality']);
  const albumRows = Array.isArray(album?.album_problem_rows) ? album.album_problem_rows
    : (album.problem_reasons || []).map(reason => ({ reason, row_key: '' }));
  const albumProblems = albumRows.filter(item => visibleReason(item.reason)).map(item => {
    const matching = getIgnorableProblemRows(album).filter(row => normalizeProblemFilterReason(row.reason) === normalizeProblemFilterReason(item.reason));
    const keys = matching.map(row => String(row.row_key || '')).filter(Boolean);
    return buildAlertLabelHtml({
      severity: 'error', message: item.reason === 'Missing year' ? 'Missing year' : item.display_reason || item.reason, interactive: true,
      pressed: keys.length > 0 && keys.every(key => state.utility.problemExclusionSelections?.[key]),
      disabled: !keys.length,
      className: 'utility-problem-exclusion-pill',
      attributes: { 'data-album-problem-type': normalizeProblemFilterReason(item.reason), 'data-problem-exclusion-reason': item.reason },
    });
  }).join('');
  const tableRows = rows.map((row, rowIndex) => {
    const track = (album.tracks || []).find(item => item.path === row.path) || {};
    const reasons = (row.reasons || []).filter(reason => !coverReasons.has(reason) && visibleReason(reason));
    const suggestions = proposals.filter(proposal => proposal.path === row.path);
    if (!reasons.length && !suggestions.length) return null;
    return {
      key: String(row.path || ''), dataAttributes: { 'problematic-track-path': String(row.path || '') },
      cells: {
        filename: `<span class="utility-track-problem-file" data-problematic-track-path="${escapeHtml(row.path || '')}">${escapeHtml(track.title || row.filename || getFilenameFromPath(row.path) || 'Unknown file')}</span><span class="utility-detail-meta">${escapeHtml([track.artist, row.file_type].filter(Boolean).join(' · '))}</span>`,
        reason: `<span class="utility-track-problem-labels">${reasons.map(reason => {
          const match = (row.ignorable_reasons || []).find(item => item.reason === reason);
          const rowKey = String(match?.row_key || '');
          return buildAlertLabelHtml({
            severity: 'error', message: reason, interactive: true, pressed: Boolean(state.utility.problemExclusionSelections?.[rowKey]),
            disabled: !rowKey, className: 'utility-problem-exclusion-pill',
            attributes: { 'data-problem-exclusion-scope': 'file', 'data-problem-exclusion-row-key': rowKey,
              'data-problem-exclusion-reason': normalizeProblemFilterReason(reason), 'data-problem-exclusion-row-index': rowIndex },
          });
        }).join('')}</span>`,
        suggested: `<span class="utility-suggestion-labels">${suggestions.map(proposal => buildAlertLabelHtml({
          severity: 'info', message: formatProblemSuggestionLabel(proposal), interactive: true,
          pressed: Boolean(state.utility.proposalSelections?.[proposal.id]),
          disabled: !album.allowed_actions?.['library.files.edit_tags'] || Boolean(state.utility.proposalApplyBusy),
          className: 'utility-problem-suggestion', attributes: { 'data-problem-suggestion-id': proposal.id, 'data-label-intent': 'proposal' },
        })).join('')}</span>`,
      },
    };
  }).filter(Boolean);
  const table = tableRows.length ? buildUtilityCompactTable({
    id: 'problematic-track-problems', ariaLabel: 'Detected problems',
    columns: 'minmax(180px,1fr) minmax(160px,1fr) minmax(180px,1.2fr)',
    columnsConfig: [{ key: 'filename', label: 'Track / file' }, { key: 'reason', label: 'Problems' }, { key: 'suggested', label: 'Suggested edits' }],
    headers: 'visible', density: 'compact', overflow: 'local', mobile: 'stack', frame: 'outline', rows: tableRows,
  }) : '';
  const separateCandidate = album?.separate_release_candidate;
  const separateKey = String(separateCandidate?.key || '');
  const separateSelected = Boolean(separateKey && state.utility.separateReleaseSelections?.[separateKey]);
  const separateActions = separateKey ? `<label class="utility-separate-release-choice ${separateSelected ? 'is-active' : ''}">
      <input type="checkbox" data-separate-release-key="${escapeHtml(separateKey)}" ${separateSelected ? 'checked' : ''}>
      <span>Separate releases</span><small>${escapeHtml((separateCandidate.years || []).join(' / '))}</small></label>
    ${ButtonComponent.renderButton({ label: 'Apply separate releases', variant: 'primary', className: 'utility-detail-apply', disabled: !separateSelected || !album.allowed_actions?.['library.rules.manage'], attributes: { 'data-open-separate-release-confirm': '1' } })}` : '';
  const selected = Object.values(state.utility.proposalSelections || {}).some(Boolean);
  return `<div class="sr-only" data-problem-exclusion-status role="status" tabindex="-1"></div>
    <div class="utility-album-problem-labels">${albumProblems}</div>
    <h4 class="utility-detail-section-title">Detected problems</h4>
    ${table ? `<div class="utility-detected-table">${table}</div>` : `<p class="utility-detail-meta">${selectedFilters.length ? 'No per-track problems match the selected filters.' : albumRows.length ? 'Only album-level problems found. No per-track problems.' : 'No per-track problems found.'}</p>`}
    ${albumProblems || tableRows.length || separateActions || getIgnoredRepairRowKeys().length ? `<div class="utility-detected-actions">
      ${separateActions}
      ${ButtonComponent.renderButton({ label: 'Create Exception', variant: 'primary', className: 'utility-exception-action', disabled: !getIgnoredRepairRowKeys().length || !album.allowed_actions?.['library.rules.manage'], attributes: { 'data-open-exclusion-confirm': '1' } })}
      ${tableRows.length ? ButtonComponent.renderButton({ label: 'Apply', variant: 'primary', className: 'utility-detail-apply', disabled: !selected || !album.allowed_actions?.['library.files.edit_tags'] || !getApplicableProblemSuggestions().length || Boolean(state.utility.proposalApplyBusy), attributes: { 'data-apply-problem-suggestions': '1' } }) : ''}
    </div>` : ''}`;
}
function buildProblematicAlbumDetail(album) {
  if (!album) {
    return '<div class="utility-empty-state">Select an album to inspect its problematic tags.</div>';
  }
  const reasons = Array.isArray(album.problem_reasons) ? album.problem_reasons : [];
  const showRepairedDisplay = !album.has_encoding_repairs || state.utility.showRepairedDisplay;
  const displayName = getProblematicAlbumDisplayValue(album, 'album', showRepairedDisplay) || 'Unknown Album';
  const displayArtist = getProblematicAlbumDisplayValue(album, 'album_artist', showRepairedDisplay) || 'Unknown Artist';
  const fileTypes = getProblematicAlbumFileTypes(album);
  const fileTypeText = fileTypes.length ? fileTypes.join(', ') : 'Unknown';
  const hasCoverProblemReason = reasons.includes('Missing cover art') || reasons.includes('Poor art quality');
  const coverSrc = buildAlbumDisplayCoverUrl(album);
  const moveActions = getAvailableAlbumMoveActions(album);
  const moveActionsHtml = moveActions.length
    ? `
      <div class="utility-rule-album-list">
        ${moveActions.map((actionConfig) => `
          <div class="utility-rule-album-row">
            <div class="utility-rule-album-main">
              <div class="utility-rule-album-title">${escapeHtml(getAlbumMoveActionLabel(actionConfig))}</div>
              <div class="utility-rule-album-meta">${escapeHtml(actionConfig.destinationPath || `Server-planned ${actionConfig.targetLabel} destination`)}</div>
            </div>
            <button
              class="button utility-detail-move"
              type="button"
              data-move-problematic-album="${escapeHtml(actionConfig.action)}"
            >${escapeHtml(getAlbumMoveActionLabel(actionConfig))}</button>
          </div>
        `).join('')}
      </div>
    `
    : '';
  const cover = buildUtilityAlbumArtbox(album, { label: `Album cover for ${displayName}`, interactive: true, source: coverSrc });
  return `
    <div class="utility-detail-header">
      <div class="utility-detail-cover">${cover}</div>
      <div class="utility-detail-summary">
        <h3 class="utility-detail-title">${escapeHtml(displayName)}</h3>
        <div class="utility-detail-meta">${escapeHtml(displayArtist)}</div>
        <div class="utility-detail-meta">Year: ${escapeHtml(album.year ?? 'Unknown')}</div>
        <div class="utility-detail-meta">Tracks: ${Array.isArray(album.tracks) ? album.tracks.length : 0}</div>
        ${album.edition ? `<div class="utility-detail-meta">Edition: ${escapeHtml(album.edition)}</div>` : ''}
        <div class="utility-detail-meta">File types: ${escapeHtml(fileTypeText)}</div>
        ${album.has_encoding_repairs ? `
          <button class="utility-repair-toggle ${showRepairedDisplay ? 'is-active' : ''}" type="button" data-toggle-problematic-display-repair="1" aria-pressed="${showRepairedDisplay ? 'true' : 'false'}">
            ${showRepairedDisplay ? 'Converted tags' : 'Original tags'}
          </button>
        ` : ''}
      </div>
        <div class="utility-detail-context-actions">
          ${ButtonComponent.renderActionButton({ ariaLabel: 'Open In File Explorer', title: 'Open In File Explorer', iconClass: 'album-details-header__action-icon album-details-header__action-icon--folder', disabled: !album.allowed_actions?.['library.files.open_location'], attributes: { 'data-open-problematic-album-folder': '1' } })}
          ${ButtonComponent.renderActionButton({ ariaLabel: 'Edit Tags', title: 'Edit Tags', icon: 'edit', disabled: !album.allowed_actions?.['library.files.edit_tags'], attributes: { 'data-open-tag-editor': '1' } })}
          ${hasCoverProblemReason ? ButtonComponent.renderActionButton({ ariaLabel: 'Fetch cover', title: 'Fetch cover', icon: 'cover', disabled: !album.allowed_actions?.['library.covers.fetch'], attributes: { 'data-fetch-problematic-cover': '1' } }) : ''}
          ${ButtonComponent.renderActionButton({ ariaLabel: 'Find on Discogs', title: 'Find on Discogs', icon: 'search', attributes: { 'data-find-on-discogs': '1' } })}
        </div>
    </div>
    ${moveActionsHtml ? buildUtilityCollapsibleSection('moves', 'Move Album', moveActionsHtml) : ''}
    ${buildDetectedProblemsHtml(album)}
  `;
}

function getSelectedProblematicAlbum() {
  return (state.utility.problematicFiles || []).find((item) => item.key === state.utility.selectedProblematicKey) || null;
}

function getAlbumTrackPaths(album) {
  const explicitTrackPaths = Array.isArray(album?.track_paths) ? album.track_paths : [];
  if (explicitTrackPaths.length) {
    return new Set(explicitTrackPaths.map((path) => String(path || '')).filter(Boolean));
  }
  return new Set((Array.isArray(album?.tracks) ? album.tracks : [])
    .map((track) => String(track.path || ''))
    .filter(Boolean));
}

function albumsHaveExactTrackMembership(left, right) {
  const leftPaths = getAlbumTrackPaths(left);
  const rightPaths = getAlbumTrackPaths(right);
  return (
    leftPaths.size > 0
    && leftPaths.size === rightPaths.size
    && Array.from(leftPaths).every((path) => rightPaths.has(path))
  );
}

function finalizedAlbumsPreserveOriginalMembership(originalAlbum, finalizedAlbums) {
  if (!originalAlbum || !Array.isArray(finalizedAlbums)) return false;
  return finalizedAlbums.some(
    (album) => albumsHaveExactTrackMembership(originalAlbum, album),
  );
}

function finalizedAlbumsCoverExpectedTrackPaths(originalAlbum, optimisticAlbums, finalizedAlbums) {
  const expectedAlbums = Array.isArray(optimisticAlbums) && optimisticAlbums.length
    ? optimisticAlbums
    : [originalAlbum].filter(Boolean);
  const expectedPaths = new Set();
  expectedAlbums.forEach((album) => {
    getAlbumTrackPaths(album).forEach((path) => expectedPaths.add(path));
  });
  if (!expectedPaths.size || !Array.isArray(finalizedAlbums)) return false;
  const finalizedPaths = new Set();
  finalizedAlbums.forEach((album) => {
    getAlbumTrackPaths(album).forEach((path) => finalizedPaths.add(path));
  });
  return Array.from(expectedPaths).every((path) => finalizedPaths.has(path));
}

function albumsShareTrackPath(left, rightPaths) {
  if (!rightPaths?.size) return false;
  return Array.from(getAlbumTrackPaths(left))
    .some((path) => rightPaths.has(path));
}

function findAlbumByTrackPaths(albums, trackPaths) {
  if (!trackPaths?.size) return null;
  return (albums || []).find((album) => albumsShareTrackPath(album, trackPaths)) || null;
}

function findVisibleAlbumByTrackPaths(trackPaths) {
  if (!trackPaths?.size) return null;
  const match = flattenVisibleAlbums().find(album => albumsShareTrackPath(album, trackPaths));
  if (!match) return null;
  // Track overlap is metadata lookup only, never actor/album-generation proof.
  const metadata = {...match};
  for (const key of ['album_preference', 'album_preference_overlay', 'album_rating', 'rating', 'favorite',
    'is_favorite', 'favorite_override', 'favorite_source', 'taste_state', 'preference_revision',
    'context_ref', 'can_edit', 'can_manage_album_preferences', 'to_listen', 'is_relisten', 'can_toggle_to_listen']) delete metadata[key];
  if (metadata.allowed_actions) {
    metadata.allowed_actions = {...metadata.allowed_actions};
    delete metadata.allowed_actions.can_manage_album_preferences;
  }
  // Do not expose nested personal summaries through this fallback either.
  delete metadata.gallery_list_block;
  delete metadata.duplicate_sources;
  return metadata;
}

function findVisibleAlbumByTrackPath(trackPath) {
  const targetPath = String(trackPath || '');
  if (!targetPath) return null;
  return flattenVisibleAlbums().find((album) => (
    Array.isArray(album?.tracks) && album.tracks.some((track) => String(track.path || '') === targetPath)
  )) || null;
}

function resolveActiveQueueAlbumSnapshot(trackPath) {
  const targetPath = String(trackPath || '');
  const queue = state.player?.playbackQueue;
  const albumSnapshot = queue?.albumSnapshot;
  if (!targetPath || !albumSnapshot || typeof albumSnapshot !== 'object') return null;

  const queueAlbumRef = String(queue.albumRef || '').trim();
  const snapshotAlbumRef = typeof getAlbumIdentity === 'function'
    ? String(getAlbumIdentity(albumSnapshot) || '').trim()
    : '';
  if (!queueAlbumRef || snapshotAlbumRef !== queueAlbumRef) return null;

  const queueHasTrack = Array.isArray(queue.tracks)
    && queue.tracks.some((track) => String(track?.path || '') === targetPath);
  if (!queueHasTrack || !getAlbumTrackPaths(albumSnapshot).has(targetPath)) return null;
  return albumSnapshot;
}

function resolveAlbumForPlayerTrack(track) {
  const targetPath = String(track?.path || '');
  const targetAlbum = String(track?.album || '').trim();
  const targetArtist = String(track?.artist || '').trim();
  const targetAlbumArtist = String(track?.albumArtist || track?.artist || '').trim();

  const candidateSources = [
    flattenVisibleAlbums(),
    Array.isArray(state.modalReleases) ? state.modalReleases : [],
    Array.isArray(state.utility.problematicFiles) ? state.utility.problematicFiles : [],
  ];

  for (const source of candidateSources) {
    const exactTrackMatch = (source || []).find((album) => (
      Array.isArray(album?.tracks) && album.tracks.some((item) => String(item.path || '') === targetPath)
    ));
    if (exactTrackMatch) return exactTrackMatch;
  }

  const activeQueueAlbum = resolveActiveQueueAlbumSnapshot(targetPath);
  if (activeQueueAlbum) return activeQueueAlbum;

  const normalizedAlbum = targetAlbum.toLowerCase();
  const normalizedArtists = new Set([targetArtist, targetAlbumArtist].map((value) => value.toLowerCase()).filter(Boolean));
  if (!normalizedAlbum || !normalizedArtists.size) return null;

  for (const source of candidateSources) {
    const albumMatch = (source || []).find((album) => {
      const albumName = String(album?.name || album?.album || '').trim().toLowerCase();
      const albumArtist = String(album?.album_artist || album?.artist || '').trim().toLowerCase();
      return albumName === normalizedAlbum && normalizedArtists.has(albumArtist);
    });
    if (albumMatch) return albumMatch;
  }
  return null;
}

function getUpdatedAlbumForTrackPaths(updatedAlbums, trackPaths) {
  const candidates = Array.isArray(updatedAlbums) ? updatedAlbums : [];
  return findAlbumByTrackPaths(candidates, trackPaths);
}

function getAlbumPathSignature(album) {
  return Array.from(getAlbumTrackPaths(album)).sort().join('|');
}

function collectVisibleAlbumsUnique() {
  const sources = [state.view.primary_artist_groups, state.view.family_artist_groups, state.view.artist_groups];
  const seen = new Set();
  const seenRuntimeAliases = new Set();
  const albums = [];
  sources.forEach((groups) => {
    (groups || []).forEach((group) => {
      (group.albums || []).forEach((album) => {
        const runtimeAliases = getAlbumRuntimeIdentityAliases(album);
        if (Array.from(runtimeAliases).some((alias) => seenRuntimeAliases.has(alias))) return;
        const signature = getAlbumPathSignature(album) || `${album?.key || ''}::${album?.name || ''}::${album?.album_artist || ''}`;
        if (!signature || seen.has(signature)) return;
        seen.add(signature);
        runtimeAliases.forEach((alias) => seenRuntimeAliases.add(alias));
        albums.push(album);
      });
    });
  });
  return albums;
}

function getAlbumRuntimeIdentityAliases(album) {
  return new Set([
    album?.key,
    album?.album_ref,
    album?.request_key,
    album?.identity_key,
    typeof getAlbumRequestKey === 'function' ? getAlbumRequestKey(album) : '',
    typeof getAlbumIdentity === 'function' ? getAlbumIdentity(album) : '',
  ].map((value) => String(value || '').trim()).filter(Boolean));
}

let tagEditViewMutationGeneration = 0;
const tagEditViewMutationResourceClaims = new Map();
const settledTagEditViewMutations = new Set();

function claimTagEditViewMutation(album, editedTrackPaths = [], updates = {}) {
  if (Object.values(updates || {}).some((edits) => (
    edits && typeof edits === 'object' && Object.keys(edits).length > 0
  ))) {
    state.ui = state.ui || {};
    state.ui.tagEditOptimisticMutationRevision = Number(
      state.ui.tagEditOptimisticMutationRevision || 0,
    ) + 1;
  }
  tagEditViewMutationGeneration += 1;
  const generation = tagEditViewMutationGeneration;
  const resourceKeys = new Set();
  getAlbumRuntimeIdentityAliases(album).forEach((alias) => {
    resourceKeys.add(`album:${alias.toLocaleLowerCase()}`);
  });
  const sourceRelease = {
    albumArtist: String(album?.album_artist || album?.artist || '').trim().toLocaleLowerCase(),
    albumName: String(album?.name || album?.album || '').trim().toLocaleLowerCase(),
    edition: String(album?.edition || '').trim().toLocaleLowerCase(),
    year: String(album?.year ?? '').trim().toLocaleLowerCase(),
  };
  const addReleaseResource = (release) => {
    if (!release.albumArtist || !release.albumName) return;
    resourceKeys.add(
      `release:${release.albumArtist}::${release.albumName}::${release.edition}::${release.year}`,
    );
  };
  addReleaseResource(sourceRelease);
  Object.values(updates || {}).forEach((edits) => {
    if (!edits || typeof edits !== 'object') return;
    addReleaseResource({
      albumArtist: Object.prototype.hasOwnProperty.call(edits, 'album_artist')
        ? String(edits.album_artist || '').trim().toLocaleLowerCase()
        : sourceRelease.albumArtist,
      albumName: Object.prototype.hasOwnProperty.call(edits, 'album')
        ? String(edits.album || '').trim().toLocaleLowerCase()
        : sourceRelease.albumName,
      edition: Object.prototype.hasOwnProperty.call(edits, 'edition')
        ? String(edits.edition || '').trim().toLocaleLowerCase()
        : sourceRelease.edition,
      year: Object.prototype.hasOwnProperty.call(edits, 'year')
        ? String(edits.year ?? '').trim().toLocaleLowerCase()
        : sourceRelease.year,
    });
  });
  [
    ...getAlbumTrackPaths(album),
    ...(Array.isArray(editedTrackPaths) ? editedTrackPaths : []),
  ].forEach((path) => {
    const normalizedPath = String(path || '').trim().toLocaleLowerCase();
    if (normalizedPath) resourceKeys.add(`path:${normalizedPath}`);
  });
  resourceKeys.forEach((resourceKey) => {
    const claims = tagEditViewMutationResourceClaims.get(resourceKey) || [];
    claims.push(generation);
    tagEditViewMutationResourceClaims.set(resourceKey, claims);
  });
  return {
    generation,
    resourceKeys: Array.from(resourceKeys),
  };
}

function tagEditViewMutationStillOwnsResources(claim) {
  const generation = Number(claim?.generation || 0);
  const resourceKeys = Array.isArray(claim?.resourceKeys) ? claim.resourceKeys : [];
  if (!generation || !resourceKeys.length) return true;
  return resourceKeys.every(
    (resourceKey) => {
      const claims = tagEditViewMutationResourceClaims.get(String(resourceKey || '')) || [];
      return claims[claims.length - 1] === generation;
    },
  );
}

function hasPendingTagEditViewMutations() {
  return Array.from(tagEditViewMutationResourceClaims.values()).some(
    (claims) => claims.some((generation) => !settledTagEditViewMutations.has(generation)),
  );
}

function pruneSettledTagEditViewMutationClaims() {
  tagEditViewMutationResourceClaims.forEach((claims, resourceKey) => {
    while (claims.length > 1 && settledTagEditViewMutations.has(claims[0])) {
      claims.shift();
    }
    if (claims.length && claims.every((value) => settledTagEditViewMutations.has(value))) {
      tagEditViewMutationResourceClaims.delete(resourceKey);
    }
  });
  const retainedGenerations = new Set(
    Array.from(tagEditViewMutationResourceClaims.values()).flat(),
  );
  settledTagEditViewMutations.forEach((value) => {
    if (!retainedGenerations.has(value)) settledTagEditViewMutations.delete(value);
  });
}

function settleTagEditViewMutation(claim) {
  const generation = Number(claim?.generation || 0);
  if (!generation) return;
  settledTagEditViewMutations.add(generation);
  pruneSettledTagEditViewMutationClaims();
}

function releaseFailedTagEditViewMutation(claim) {
  const generation = Number(claim?.generation || 0);
  if (!generation) return;
  tagEditViewMutationResourceClaims.forEach((claims, resourceKey) => {
    const remainingClaims = claims.filter((value) => value !== generation);
    if (remainingClaims.length) {
      tagEditViewMutationResourceClaims.set(resourceKey, remainingClaims);
    } else {
      tagEditViewMutationResourceClaims.delete(resourceKey);
    }
  });
  settledTagEditViewMutations.delete(generation);
  pruneSettledTagEditViewMutationClaims();
}

function albumsShareRuntimeIdentityAlias(left, right) {
  const leftAliases = getAlbumRuntimeIdentityAliases(left);
  if (!leftAliases.size) return false;
  return Array.from(getAlbumRuntimeIdentityAliases(right))
    .some((alias) => leftAliases.has(alias));
}

function albumLogicalReleaseBaseMatches(left, right) {
  const normalize = (value) => String(value ?? '').trim().toLocaleLowerCase();
  const leftArtist = normalize(left?.album_artist || left?.artist);
  const rightArtist = normalize(right?.album_artist || right?.artist);
  const leftName = normalize(left?.name || left?.album);
  const rightName = normalize(right?.name || right?.album);
  if (!leftArtist || !rightArtist || !leftName || !rightName) return false;
  return leftArtist === rightArtist
    && leftName === rightName
    && normalize(left?.year) === normalize(right?.year);
}

function albumsHaveCompatibleLogicalEdition(candidate, visibleAlbum) {
  const candidateEdition = String(candidate?.edition || '').trim().toLocaleLowerCase();
  const visibleEdition = String(visibleAlbum?.edition || '').trim().toLocaleLowerCase();
  if (!candidateEdition) return true;
  return Boolean(visibleEdition) && candidateEdition === visibleEdition;
}

function albumsShareLogicalReleaseIdentity(left, right) {
  return albumLogicalReleaseBaseMatches(left, right)
    && albumsHaveCompatibleLogicalEdition(left, right)
    && albumsHaveCompatibleLogicalEdition(right, left);
}

function formatCanonicalAlbumDuration(seconds) {
  const totalSeconds = Math.max(0, Math.floor(Number(seconds) || 0));
  const totalMinutes = Math.floor(totalSeconds / 60);
  const hours = Math.floor(totalMinutes / 60);
  const minutes = totalMinutes % 60;
  if (hours) return `${hours}h ${minutes}m`;
  return `${totalMinutes}m ${String(totalSeconds % 60).padStart(2, '0')}s`;
}

function albumIsDemonstrablyFullyHydrated(album) {
  const tracks = Array.isArray(album?.tracks) ? album.tracks : [];
  if (album?.preview_only === true || !tracks.length) return false;
  const declaredTrackCount = Number(album?.track_count_preview);
  if (
    Number.isFinite(declaredTrackCount)
    && declaredTrackCount > 0
    && declaredTrackCount !== tracks.length
  ) return false;
  const declaredMembershipPaths = Array.isArray(album?.track_paths)
    ? new Set(album.track_paths.map((path) => String(path || '')).filter(Boolean))
    : new Set();
  if (!declaredMembershipPaths.size) return true;
  if (declaredMembershipPaths.size !== tracks.length) return false;
  return tracks.every((track) => declaredMembershipPaths.has(String(track?.path || '')));
}

function mergeVisibleAlbumWithOptimisticCandidate(visibleAlbum, candidate, options = {}) {
  const visibleMembershipPaths = getAlbumTrackPaths(visibleAlbum);
  const candidateMembershipPaths = getAlbumTrackPaths(candidate);
  const replaceCompactMembership = (
    options.replaceCompactMembership === true
    && visibleAlbum?.preview_only === true
    && albumIsDemonstrablyFullyHydrated(candidate)
  );
  const tracks = [];
  const trackIndexesByPath = new Map();
  const appendTrack = (track, incoming = false) => {
    const path = String(track?.path || '');
    if (path && trackIndexesByPath.has(path)) {
      if (incoming) tracks[trackIndexesByPath.get(path)] = track;
      return;
    }
    if (path) trackIndexesByPath.set(path, tracks.length);
    tracks.push(track);
  };
  if (!replaceCompactMembership) {
    (Array.isArray(visibleAlbum?.tracks) ? visibleAlbum.tracks : [])
      .forEach((track) => appendTrack(track));
  }
  (Array.isArray(candidate?.tracks) ? candidate.tracks : [])
    .forEach((track) => appendTrack(track, true));

  const mergedAlbum = {
    ...candidate,
    ...visibleAlbum,
    tracks,
  };
  if (replaceCompactMembership) {
    mergedAlbum.preview_only = false;
    mergedAlbum.track_paths = Array.from(candidateMembershipPaths);
    mergedAlbum.track_count_preview = tracks.length;
  } else if (visibleAlbum?.preview_only === true) {
    const mergedMembershipPaths = new Set([
      ...visibleMembershipPaths,
      ...candidateMembershipPaths,
    ]);
    const visibleDeclaredTrackCount = Number(visibleAlbum?.track_count_preview);
    const candidateAddsDistinctMembership = Array.from(candidateMembershipPaths)
      .filter((path) => !visibleMembershipPaths.has(path)).length;
    mergedAlbum.preview_only = true;
    if (mergedMembershipPaths.size) {
      mergedAlbum.track_paths = Array.from(mergedMembershipPaths);
      mergedAlbum.track_count_preview = Math.max(
        mergedMembershipPaths.size,
        Number.isFinite(visibleDeclaredTrackCount)
          ? visibleDeclaredTrackCount + candidateAddsDistinctMembership
          : 0,
      );
    }
  }
  const shouldRecomputeDuration = tracks.some((track) => Number(track?.duration_seconds || 0) > 0)
    || Object.prototype.hasOwnProperty.call(visibleAlbum || {}, 'total_duration_seconds')
    || Object.prototype.hasOwnProperty.call(candidate || {}, 'total_duration_seconds');
  if (shouldRecomputeDuration) {
    const totalDurationSeconds = tracks.reduce(
      (sum, track) => {
        const duration = Number(track?.duration_seconds || 0);
        return sum + (Number.isFinite(duration) ? Math.max(0, duration) : 0);
      },
      0,
    );
    mergedAlbum.total_duration_seconds = totalDurationSeconds;
    mergedAlbum.total_duration_display = formatCanonicalAlbumDuration(totalDurationSeconds);
  }
  if (visibleAlbum?.preview_only !== true
      && tracks.length
      && (Object.prototype.hasOwnProperty.call(visibleAlbum || {}, 'track_count_preview')
        || Object.prototype.hasOwnProperty.call(candidate || {}, 'track_count_preview'))) {
    mergedAlbum.track_count_preview = tracks.length;
  }
  return mergedAlbum;
}

function preserveVisibleAlbumRuntimeIdentity(visibleAlbum, candidate) {
  const reconciledAlbum = {
    ...visibleAlbum,
    ...candidate,
  };
  ['key', 'album_ref', 'request_key', 'identity_key'].forEach((field) => {
    const stableValue = String(visibleAlbum?.[field] || '').trim();
    if (stableValue) reconciledAlbum[field] = visibleAlbum[field];
  });
  return reconciledAlbum;
}

function coalesceUniqueVisibleLogicalAlbumCandidates(
  candidates,
  visibleAlbums,
  originalAlbum = null,
) {
  return (candidates || []).map((candidate) => {
    const logicalMatches = (visibleAlbums || []).filter((visibleAlbum) => (
      albumLogicalReleaseBaseMatches(candidate, visibleAlbum)
      && albumsHaveCompatibleLogicalEdition(candidate, visibleAlbum)
    ));
    const runtimeMatches = logicalMatches.filter((logicalMatch) => (
      albumsShareRuntimeIdentityAlias(logicalMatch, candidate)
    ));
    const effectiveMatches = runtimeMatches.length ? runtimeMatches : logicalMatches;
    if (effectiveMatches.length !== 1) return candidate;
    const logicalMatch = effectiveMatches[0];
    if (
      originalAlbum
      && logicalMatch?.preview_only === true
      && albumIsDemonstrablyFullyHydrated(candidate)
      && albumsShareLogicalReleaseIdentity(candidate, originalAlbum)
    ) {
      return preserveVisibleAlbumRuntimeIdentity(logicalMatch, candidate);
    }
    if (albumsShareTrackPath(logicalMatch, getAlbumTrackPaths(candidate))) {
      if (
        originalAlbum
        && !albumsShareLogicalReleaseIdentity(candidate, originalAlbum)
      ) {
        return mergeVisibleAlbumWithOptimisticCandidate(logicalMatch, candidate);
      }
      return preserveVisibleAlbumRuntimeIdentity(logicalMatch, candidate);
    }
    if (albumsShareRuntimeIdentityAlias(logicalMatch, candidate)) {
      const visibleTrackPaths = getAlbumTrackPaths(logicalMatch);
      const candidateTrackPaths = getAlbumTrackPaths(candidate);
      const visibleDeclaredTrackCount = Number(logicalMatch?.track_count_preview);
      const previewHasNoDeclaredMembership = (
        logicalMatch?.preview_only === true
        && !visibleTrackPaths.size
        && !(
          Number.isFinite(visibleDeclaredTrackCount)
          && visibleDeclaredTrackCount > 0
        )
      );
      if (
        (!visibleTrackPaths.size || !candidateTrackPaths.size)
        && (
          logicalMatch?.preview_only !== true
          || previewHasNoDeclaredMembership
        )
      ) return candidate;
    }
    return mergeVisibleAlbumWithOptimisticCandidate(logicalMatch, candidate);
  });
}

function enrichChangedLogicalReleaseFromHydratedAlbumIndex(candidate, originalAlbum) {
  if (
    !candidate
    || !originalAlbum
    || albumsShareLogicalReleaseIdentity(candidate, originalAlbum)
  ) {
    return candidate;
  }
  const hydratedMatches = new Set();
  const collectHydratedMatch = (album) => {
    if (
      album
      && album !== candidate
      && album?.preview_only !== true
      && getAlbumTrackPaths(album).size
      && albumsShareLogicalReleaseIdentity(candidate, album)
    ) {
      hydratedMatches.add(album);
    }
  };
  getAlbumRuntimeIdentityAliases(candidate).forEach((alias) => {
    if (typeof getCachedHydratedTrackModalAlbum === 'function') {
      collectHydratedMatch(getCachedHydratedTrackModalAlbum(alias));
    }
    if (typeof state.gallery?.albumIndex?.get === 'function') {
      collectHydratedMatch(state.gallery.albumIndex.get(alias));
    }
  });
  if (hydratedMatches.size !== 1) return candidate;
  const enrichedAlbum = mergeVisibleAlbumWithOptimisticCandidate(
    Array.from(hydratedMatches)[0],
    candidate,
  );
  enrichedAlbum.tracks = orderAlbumTracks(enrichedAlbum.tracks);
  if (Object.prototype.hasOwnProperty.call(enrichedAlbum, 'track_count_preview')) {
    enrichedAlbum.track_count_preview = enrichedAlbum.tracks.length;
  }
  return enrichedAlbum;
}

function enrichFinalizedAlbumsWithCanonicalVisibleProjections(
  finalizedAlbums,
  visibleAlbums,
  options = {},
) {
  const coalescedAlbums = coalesceUniqueVisibleLogicalAlbumCandidates(
    finalizedAlbums,
    visibleAlbums,
  );
  return coalescedAlbums.map((coalescedAlbum, index) => {
    const finalizedAlbum = finalizedAlbums[index];
    const canonicalMatches = (visibleAlbums || []).filter((visibleAlbum) => (
      albumLogicalReleaseBaseMatches(finalizedAlbum, visibleAlbum)
      && albumsHaveCompatibleLogicalEdition(finalizedAlbum, visibleAlbum)
      && (
        albumsShareTrackPath(visibleAlbum, getAlbumTrackPaths(finalizedAlbum))
        || albumsShareRuntimeIdentityAlias(finalizedAlbum, visibleAlbum)
      )
    ));
    if (canonicalMatches.length !== 1) return coalescedAlbum;
    const canonicalCompactAlbum = canonicalMatches[0];
    const finalizedAlbumCanReplaceCompactMembership = (
      canonicalCompactAlbum?.preview_only === true
      && albumIsDemonstrablyFullyHydrated(finalizedAlbum)
    );
    const callerAllowsCompactMembershipReplacement = (
      typeof options.replaceCompactMembership === 'function'
        ? options.replaceCompactMembership(finalizedAlbum, canonicalCompactAlbum) === true
        : !Object.prototype.hasOwnProperty.call(options, 'replaceCompactMembership')
          || options.replaceCompactMembership === true
    );
    const enrichedAlbum = mergeVisibleAlbumWithOptimisticCandidate(
      canonicalCompactAlbum,
      finalizedAlbum,
      {
        replaceCompactMembership: (
          finalizedAlbumCanReplaceCompactMembership
          && callerAllowsCompactMembershipReplacement
        ),
      },
    );
    if (Array.isArray(finalizedAlbum?.tracks) && finalizedAlbum.tracks.length) {
      enrichedAlbum.preview_only = false;
    }
    return enrichedAlbum;
  });
}

function enrichFinalizedAlbumsWithOptimisticModalTracks(finalizedAlbums, optimisticAlbums) {
  return (finalizedAlbums || []).map((finalizedAlbum) => {
    if (Array.isArray(finalizedAlbum?.tracks) && finalizedAlbum.tracks.length) {
      return finalizedAlbum;
    }
    const matchingOptimisticAlbums = (optimisticAlbums || []).filter((optimisticAlbum) => (
      albumsShareLogicalReleaseIdentity(finalizedAlbum, optimisticAlbum)
      && Array.isArray(optimisticAlbum?.tracks)
      && optimisticAlbum.tracks.length
    ));
    if (matchingOptimisticAlbums.length !== 1) return finalizedAlbum;
    const finalizedPaths = getAlbumTrackPaths(finalizedAlbum);
    const optimisticAlbum = matchingOptimisticAlbums[0];
    const optimisticTracks = Array.isArray(optimisticAlbum?.tracks)
      ? optimisticAlbum.tracks
      : [];
    const declaredTrackCount = Number(optimisticAlbum?.track_count_preview);
    const declaredMembershipSize = getAlbumTrackPaths(optimisticAlbum).size;
    const optimisticAlbumIsFullyHydrated = (
      optimisticAlbum?.preview_only !== true
      && (!Number.isFinite(declaredTrackCount) || declaredTrackCount <= optimisticTracks.length)
      && (!declaredMembershipSize || declaredMembershipSize <= optimisticTracks.length)
    );
    if (!optimisticAlbumIsFullyHydrated) return finalizedAlbum;
    const hydratedTracks = optimisticAlbum.tracks.filter((track) => (
      !finalizedPaths.size || finalizedPaths.has(String(track?.path || ''))
    ));
    if (!hydratedTracks.length) return finalizedAlbum;
    return {
      ...mergeVisibleAlbumWithOptimisticCandidate(
        finalizedAlbum,
        { ...optimisticAlbum, tracks: hydratedTracks },
      ),
      preview_only: false,
    };
  });
}

function compareAlbumsWithinGalleryGroup(left, right) {
  const yearCompare = Number(left?.year ?? 9999) - Number(right?.year ?? 9999);
  if (yearCompare) return yearCompare;
  const nameCompare = String(left?.name || '').localeCompare(String(right?.name || ''), undefined, { sensitivity: 'base' });
  if (nameCompare) return nameCompare;
  return String(left?.edition || '').localeCompare(String(right?.edition || ''), undefined, { sensitivity: 'base' });
}

function groupAlbumsForCurrentView(albums) {
  const buckets = new Map();
  (albums || []).forEach((album) => {
    const artist = String(album?.album_artist || '').trim() || 'Unknown Artist';
    if (!buckets.has(artist)) {
      buckets.set(artist, {
        artist,
        artist_display: artist,
        albums: [],
      });
    }
    buckets.get(artist).albums.push(album);
  });
  return Array.from(buckets.values())
    .map((group) => ({
      ...group,
      albums: (group.albums || []).slice().sort(compareAlbumsWithinGalleryGroup),
    }))
    .sort((left, right) => String(left.artist || '').localeCompare(String(right.artist || ''), undefined, { sensitivity: 'base' }));
}

function resolveSelectedArtistFamilyDisplayModeForRuntimeView(view = state.view || {}) {
  return String(
    view?.selected_artist_family_display_mode
      ?? view?.artist_page?.family_display_mode
      ?? 'grouped',
  ).trim().toLowerCase() === 'chronological' ? 'chronological' : 'grouped';
}

function buildSelectedArtistChronologicalGroupsForRuntime(primaryGroups, familyGroups) {
  const seenAlbumKeys = new Set();
  const sortAlbums = (left, right) => {
    const normalizeReleaseDate = (album) => {
      const releaseDate = String(album?.release_date || '').trim();
      if (!releaseDate) return '';
      const parts = releaseDate.split('-');
      if (!parts.length || parts.length > 3 || parts.some((part) => !/^\d+$/.test(part))) {
        return '';
      }
      const year = parts[0].padStart(4, '0');
      const month = (parts[1] || '99').padStart(2, '0');
      const day = (parts[2] || '99').padStart(2, '0');
      return `${year}-${month}-${day}`;
    };
    const normalizeYear = (album) => {
      if (album?.year === null || album?.year === undefined || album?.year === '') return 9999;
      const year = Number(album.year);
      return Number.isInteger(year) ? year : 9999;
    };
    const leftYear = normalizeYear(left);
    const rightYear = normalizeYear(right);
    const leftReleaseKey = normalizeReleaseDate(left) || `${String(leftYear).padStart(4, '0')}-99-99`;
    const rightReleaseKey = normalizeReleaseDate(right) || `${String(rightYear).padStart(4, '0')}-99-99`;
    if (leftReleaseKey !== rightReleaseKey) return leftReleaseKey.localeCompare(rightReleaseKey);
    if (leftYear !== rightYear) return leftYear - rightYear;
    const nameCompare = String(left?.name || '').localeCompare(String(right?.name || ''), undefined, { sensitivity: 'base' });
    if (nameCompare) return nameCompare;
    return String(left?.key || '').localeCompare(String(right?.key || ''), undefined, { sensitivity: 'base' });
  };
  const albums = [...(Array.isArray(primaryGroups) ? primaryGroups : []), ...(Array.isArray(familyGroups) ? familyGroups : [])]
    .flatMap((group) => (Array.isArray(group?.albums) ? group.albums : []))
    .filter((album) => {
      const albumKey = String(album?.key || '').trim();
      if (!albumKey) return true;
      if (seenAlbumKeys.has(albumKey)) return false;
      seenAlbumKeys.add(albumKey);
      return true;
    })
    .sort(sortAlbums);
  if (!albums.length) return [];
  return [{
    artist: 'Chronological',
    artist_display: 'Chronological',
    albums,
  }];
}

function replaceAlbumsInGroupsByTrackPath(groups, updatedAlbums) {
  if (!Array.isArray(groups) || !Array.isArray(updatedAlbums) || !updatedAlbums.length) return groups;
  return groups.map((group) => ({
    ...group,
    albums: (group.albums || []).map((album) => {
      const updatedAlbum = getUpdatedAlbumForTrackPaths(updatedAlbums, getAlbumTrackPaths(album));
      return updatedAlbum || album;
    }),
  }));
}

function patchVisibleAlbumsByTrackPath(updatedAlbums) {
  const candidates = Array.isArray(updatedAlbums) ? updatedAlbums.filter(Boolean) : [];
  if (!candidates.length) return;
  mergeViewPayload({
    artist_groups: replaceAlbumsInGroupsByTrackPath(state.view.artist_groups, candidates),
    primary_artist_groups: replaceAlbumsInGroupsByTrackPath(state.view.primary_artist_groups, candidates),
    family_artist_groups: replaceAlbumsInGroupsByTrackPath(state.view.family_artist_groups, candidates),
  }, { trackSidebarReveal: false });
}

function preserveDocumentScrollPosition(callback) {
  if (typeof callback !== 'function') return;
  const scrollEl = document.scrollingElement || document.documentElement || document.body;
  const galleryScrollEl = document.getElementById('albums-scroll');
  const viewportScroll = getViewportScrollPosition();
  const left = Number(scrollEl?.scrollLeft || viewportScroll.x || 0);
  const top = Number(scrollEl?.scrollTop || viewportScroll.y || 0);
  const galleryLeft = Number(galleryScrollEl?.scrollLeft || 0);
  const galleryTop = Number(galleryScrollEl?.scrollTop || 0);
  const restore = () => {
    if (scrollEl) {
      scrollEl.scrollLeft = left;
      scrollEl.scrollTop = top;
    }
    if (galleryScrollEl) {
      galleryScrollEl.scrollLeft = galleryLeft;
      galleryScrollEl.scrollTop = galleryTop;
    }
    window.scrollTo(left, top);
  };
  callback();
  restore();
  scheduleBrowserAnimationFrame(restore);
}

function albumMatchesRuntimeReplacementIdentity(album, replacementIdentityAliases) {
  if (!replacementIdentityAliases?.size) return false;
  return [
    album?.key,
    album?.album_ref,
    typeof getAlbumRequestKey === 'function' ? getAlbumRequestKey(album) : '',
    typeof getAlbumIdentity === 'function' ? getAlbumIdentity(album) : '',
  ].some((value) => replacementIdentityAliases.has(String(value || '').trim()));
}

function patchAlbumGroupsPreservingMembership(
  groups,
  candidates,
  originalAlbum,
  removalPaths,
  replacementIdentityAliases,
  allowUnmatchedFallback = false,
  allowArbitraryGroupFallback = allowUnmatchedFallback,
) {
  if (!Array.isArray(groups)) return [];
  const originalPaths = getAlbumTrackPaths(originalAlbum);
  const placementsByGroup = new Map();
  const placeCandidate = (candidate) => {
    let placement = null;
    const findPlacement = (predicate) => {
      for (let groupIndex = 0; groupIndex < groups.length; groupIndex += 1) {
        const albums = Array.isArray(groups[groupIndex]?.albums)
          ? groups[groupIndex].albums
          : [];
        const albumIndex = albums.findIndex(predicate);
        if (albumIndex >= 0) return { groupIndex, albumIndex };
      }
      return null;
    };
    placement = findPlacement((album) => (
      albumsShareRuntimeIdentityAlias(album, candidate)
      || albumsShareLogicalReleaseIdentity(album, candidate)
    ));
    if (!placement) {
      const logicalPlacements = [];
      groups.forEach((group, groupIndex) => {
        const albums = Array.isArray(group?.albums) ? group.albums : [];
        albums.forEach((album, albumIndex) => {
          if (
            albumLogicalReleaseBaseMatches(candidate, album)
            && albumsHaveCompatibleLogicalEdition(candidate, album)
          ) {
            logicalPlacements.push({ groupIndex, albumIndex });
          }
        });
      });
      if (logicalPlacements.length === 1) [placement] = logicalPlacements;
    }
    if (!placement) {
      const candidatePaths = getAlbumTrackPaths(candidate);
      placement = findPlacement((album) => albumsShareTrackPath(album, candidatePaths));
    }
    if (!placement && originalAlbum) {
      placement = findPlacement((album) => (
        albumsShareRuntimeIdentityAlias(album, originalAlbum)
        || albumsShareLogicalReleaseIdentity(album, originalAlbum)
        || albumsShareTrackPath(album, originalPaths)
      ));
    }
    if (!placement && allowUnmatchedFallback) {
      const candidateArtist = String(candidate?.album_artist || '').trim();
      const groupIndex = groups.findIndex(
        (group) => String(group?.artist || '').trim() === candidateArtist,
      );
      if (groupIndex >= 0) {
        placement = {
          groupIndex,
          albumIndex: (groups[groupIndex]?.albums || []).length,
        };
      }
    }
    if (!placement && allowArbitraryGroupFallback && groups.length) {
      placement = {
        groupIndex: 0,
        albumIndex: (groups[0]?.albums || []).length,
      };
    }
    if (!placement) return;
    const groupPlacements = placementsByGroup.get(placement.groupIndex) || new Map();
    const slot = groupPlacements.get(placement.albumIndex) || [];
    slot.push(candidate);
    groupPlacements.set(placement.albumIndex, slot);
    placementsByGroup.set(placement.groupIndex, groupPlacements);
  };
  (candidates || []).forEach(placeCandidate);
  return groups.map((group, groupIndex) => {
    const albums = Array.isArray(group?.albums) ? group.albums : [];
    const candidatesByIndex = placementsByGroup.get(groupIndex) || new Map();
    const nextAlbums = [];
    albums.forEach((album, index) => {
      const replacements = candidatesByIndex.get(index);
      if (replacements?.length) {
        nextAlbums.push(...replacements.slice().sort(compareAlbumsWithinGalleryGroup));
      }
      const removeAlbum = Boolean(replacements?.length)
        || albumsShareTrackPath(album, removalPaths)
        || albumMatchesRuntimeReplacementIdentity(album, replacementIdentityAliases);
      if (!removeAlbum) nextAlbums.push(album);
    });
    const trailingReplacements = candidatesByIndex.get(albums.length);
    if (trailingReplacements?.length) {
      nextAlbums.push(...trailingReplacements.slice().sort(compareAlbumsWithinGalleryGroup));
    }
    nextAlbums.sort(compareAlbumsWithinGalleryGroup);
    return {
      ...group,
      artist_display: String(group?.artist_display || group?.artist || ''),
      albums: nextAlbums,
    };
  }).filter((group) => group.albums.length);
}

function getExplicitAlbumArtistEditByPath(tagEdits) {
  const editsByPath = new Map();
  if (!tagEdits || typeof tagEdits !== 'object' || Array.isArray(tagEdits)) {
    return editsByPath;
  }
  Object.entries(tagEdits).forEach(([path, edits]) => {
    if (
      !edits
      || typeof edits !== 'object'
      || !Object.prototype.hasOwnProperty.call(edits, 'album_artist')
    ) {
      return;
    }
    editsByPath.set(
      String(path || ''),
      String(edits.album_artist || '').trim() || 'Unknown Artist',
    );
  });
  return editsByPath;
}

function getCandidateExplicitAlbumArtist(candidate, explicitAlbumArtistByPath) {
  const candidatePaths = getAlbumTrackPaths(candidate);
  for (const [path, albumArtist] of explicitAlbumArtistByPath.entries()) {
    if (candidatePaths.has(path)) return albumArtist;
  }
  return null;
}

function appendMigratedAlbumsToSemanticGroups(groups, migrations, allowArtist) {
  const nextGroups = (Array.isArray(groups) ? groups : []).map((group) => ({
    ...group,
    albums: Array.isArray(group?.albums) ? group.albums.slice() : [],
  }));
  migrations.forEach(({ album, artist }) => {
    if (typeof allowArtist === 'function' && !allowArtist(artist)) return;
    let group = nextGroups.find(
      (candidate) => String(candidate?.artist || '').trim() === artist,
    );
    if (!group) {
      group = {
        artist,
        artist_display: artist,
        albums: [],
      };
      nextGroups.push(group);
    }
    group.albums.push(album);
    group.albums.sort(compareAlbumsWithinGalleryGroup);
  });
  return nextGroups.filter((group) => group.albums.length);
}

function patchAlbumGroupsWithExplicitArtistMigrations(
  groups,
  candidates,
  originalAlbum,
  removalPaths,
  replacementIdentityAliases,
  explicitAlbumArtistByPath,
  allowUnmatchedFallback,
  allowMigrationArtist,
  allowArbitraryGroupFallback = allowUnmatchedFallback,
) {
  const migrations = [];
  const membershipCandidates = [];
  candidates.forEach((candidate) => {
    const artist = getCandidateExplicitAlbumArtist(
      candidate,
      explicitAlbumArtistByPath,
    );
    if (artist === null) {
      membershipCandidates.push(candidate);
      return;
    }
    migrations.push({ album: candidate, artist });
  });
  const patchedGroups = patchAlbumGroupsPreservingMembership(
    groups,
    membershipCandidates,
    originalAlbum,
    removalPaths,
    replacementIdentityAliases,
    allowUnmatchedFallback,
    allowArbitraryGroupFallback,
  );
  return appendMigratedAlbumsToSemanticGroups(
    patchedGroups,
    migrations,
    allowMigrationArtist,
  );
}

function albumIsMountedInGroups(groups, album) {
  if (!album || !Array.isArray(groups)) return false;
  const albumPaths = getAlbumTrackPaths(album);
  return groups.some((group) => (
    (Array.isArray(group?.albums) ? group.albums : []).some((candidate) => (
      albumsShareRuntimeIdentityAlias(candidate, album)
      || albumsShareLogicalReleaseIdentity(candidate, album)
      || albumsShareTrackPath(candidate, albumPaths)
    ))
  ));
}

function synchronizeCurrentViewAlbumIndex() {
  const roleGroups = [
    ...(Array.isArray(state.view.primary_artist_groups)
      ? state.view.primary_artist_groups
      : []),
    ...(Array.isArray(state.view.family_artist_groups)
      ? state.view.family_artist_groups
      : []),
  ];
  const groups = roleGroups.length
    ? roleGroups
    : (Array.isArray(state.view.artist_groups) ? state.view.artist_groups : []);
  if (typeof rebuildAlbumIndex === 'function') {
    rebuildAlbumIndex(groups);
  }
  if (!(state.gallery?.albumIndex instanceof Map)) return;
  groups.forEach((group) => {
    (Array.isArray(group?.albums) ? group.albums : []).forEach((album) => {
      getAlbumRuntimeIdentityAliases(album).forEach((alias) => {
        state.gallery.albumIndex.set(alias, album);
      });
    });
  });
}

function applyUpdatedAlbumsToCurrentView(updatedAlbums, options = {}) {
  const incomingCandidates = Array.isArray(updatedAlbums) ? updatedAlbums.filter(Boolean) : [];
  const originalAlbum = options.originalAlbum || null;
  if (!incomingCandidates.length && !originalAlbum) return [];
  if (options.preserveGrouping) {
    patchVisibleAlbumsByTrackPath(incomingCandidates);
    if (!options.skipRender) {
      if (options.preserveScroll) preserveDocumentScrollPosition(() => renderView({ preserveScroll: true }));
      else renderView();
    }
    return incomingCandidates;
  }
  const visibleAlbums = collectVisibleAlbumsUnique();
  const candidates = coalesceUniqueVisibleLogicalAlbumCandidates(
    incomingCandidates,
    visibleAlbums,
    originalAlbum,
  ).map((candidate) => (
    enrichChangedLogicalReleaseFromHydratedAlbumIndex(candidate, originalAlbum)
  ));
  const removalPaths = new Set();
  candidates.forEach((album) => {
    getAlbumTrackPaths(album).forEach((path) => removalPaths.add(path));
  });
  if (originalAlbum) {
    getAlbumTrackPaths(originalAlbum).forEach((path) => removalPaths.add(path));
  }

  const replacementIdentityAliases = new Set();
  [...candidates, originalAlbum].filter(Boolean).forEach((album) => {
    [
      album.key,
      album.album_ref,
      typeof getAlbumRequestKey === 'function' ? getAlbumRequestKey(album) : '',
      typeof getAlbumIdentity === 'function' ? getAlbumIdentity(album) : '',
    ].forEach((value) => {
      const alias = String(value || '').trim();
      if (alias) replacementIdentityAliases.add(alias);
    });
  });

  const explicitAlbumArtistByPath = getExplicitAlbumArtistEditByPath(options.tagEdits);
  let grouped = state.view.artist_groups?.length
    ? patchAlbumGroupsWithExplicitArtistMigrations(
      state.view.artist_groups,
      candidates,
      originalAlbum,
      removalPaths,
      replacementIdentityAliases,
      explicitAlbumArtistByPath,
      true,
    )
    : groupAlbumsForCurrentView(candidates);
  if (!grouped.length && candidates.length) {
    grouped = groupAlbumsForCurrentView(candidates);
  }

  if (state.view.selected_artist) {
    const selectedArtist = String(state.view.selected_artist || '');
    const selectedArtistFamilyDisplayMode = resolveSelectedArtistFamilyDisplayModeForRuntimeView(state.view);
    const activeRelatedSet = new Set(Array.isArray(state.view.related_filter_artists) ? state.view.related_filter_artists : []);
    const hasMountedRoleGroups = Boolean(
      state.view.primary_artist_groups?.length
      || state.view.family_artist_groups?.length
    );
    const originalAlbumMountedInPrimaryGroups = albumIsMountedInGroups(
      state.view.primary_artist_groups,
      originalAlbum,
    );
    const originalAlbumMountedInFamilyGroups = albumIsMountedInGroups(
      state.view.family_artist_groups,
      originalAlbum,
    );
    const primaryGroups = !hasMountedRoleGroups
      ? grouped.filter((group) => String(group.artist || '') === selectedArtist)
      : patchAlbumGroupsWithExplicitArtistMigrations(
        state.view.primary_artist_groups,
        candidates,
        originalAlbum,
        removalPaths,
        replacementIdentityAliases,
        explicitAlbumArtistByPath,
        !originalAlbumMountedInFamilyGroups,
        (artist) => artist === selectedArtist,
        false,
      );
    const allFamilyGroups = !hasMountedRoleGroups
      ? grouped.filter((group) => String(group.artist || '') !== selectedArtist)
      : patchAlbumGroupsWithExplicitArtistMigrations(
        state.view.family_artist_groups,
        candidates,
        originalAlbum,
        removalPaths,
        replacementIdentityAliases,
        explicitAlbumArtistByPath,
        !originalAlbumMountedInPrimaryGroups,
        (artist) => artist !== selectedArtist,
        false,
      );
    const allFamilyArtists = Array.from(new Set([
      ...(Array.isArray(state.view.related_artists) ? state.view.related_artists : []),
      ...allFamilyGroups
        .map((group) => String(group.artist || '').trim())
        .filter((artist) => artist && artist !== selectedArtist),
    ])).sort((left, right) => left.localeCompare(right, undefined, { sensitivity: 'base' }));
    const visibleFamilyGroups = activeRelatedSet.size
      ? allFamilyGroups.filter((group) => groupMatchesRelatedArtists(group, activeRelatedSet))
      : (state.view.primary_filter_active ? [] : allFamilyGroups);
    const nextPrimaryGroups = (state.view.primary_filter_active || !activeRelatedSet.size) ? primaryGroups : [];
    const nextArtistGroups = selectedArtistFamilyDisplayMode === 'chronological'
      ? buildSelectedArtistChronologicalGroupsForRuntime(nextPrimaryGroups, visibleFamilyGroups)
      : [...nextPrimaryGroups, ...visibleFamilyGroups];
    mergeViewPayload({
      related_artists: allFamilyArtists,
      primary_artist_groups: nextPrimaryGroups,
      family_artist_groups: visibleFamilyGroups,
      artist_groups: nextArtistGroups,
      album_count: (nextPrimaryGroups.reduce((sum, group) => sum + (group.albums || []).length, 0)
        + visibleFamilyGroups.reduce((sum, group) => sum + (group.albums || []).length, 0)),
      artist_count: (nextPrimaryGroups.length + visibleFamilyGroups.length),
    }, { trackSidebarReveal: false });
  } else {
    mergeViewPayload({
      artist_groups: grouped,
      album_count: grouped.reduce((sum, group) => sum + (group.albums || []).length, 0),
      artist_count: grouped.length,
    }, { trackSidebarReveal: false });
  }
  if (options.skipRender) synchronizeCurrentViewAlbumIndex();
  if (!options.skipRender) {
    if (options.preserveScroll) {
      preserveDocumentScrollPosition(() => renderView({ preserveScroll: true }));
    } else {
      renderView();
    }
  }
  return candidates;
}

async function prependUtilityLogHistoryEntry(entry) {
  if (!entry || typeof entry !== 'object') return;
  state.utility.logHistoryController?.markStale(String(entry.revision || 'new-activity'));
}

function applyExplicitFinalizedAlbumArtistEdits(finalizedAlbums, tagEdits) {
  if (!tagEditsExplicitlyChangeAlbumArtist(tagEdits)) return finalizedAlbums;
  return (finalizedAlbums || []).map((album) => {
    let explicitCandidateAlbumArtist = null;
    const tracks = (Array.isArray(album?.tracks) ? album.tracks : []).map((track) => {
      const edits = tagEdits[String(track?.path || '')];
      if (
        !edits
        || typeof edits !== 'object'
        || !Object.prototype.hasOwnProperty.call(edits, 'album_artist')
      ) {
        return track;
      }
      explicitCandidateAlbumArtist = String(edits.album_artist || '').trim();
      return {
        ...track,
        album_artist: explicitCandidateAlbumArtist,
      };
    });
    if (explicitCandidateAlbumArtist === null) return album;
    return {
      ...album,
      album_artist: explicitCandidateAlbumArtist,
      tracks,
    };
  });
}

function claimProblematicSaveTaskMutation(taskId, originalAlbum, expectedAlbumKey = '') {
  const normalizedTaskId = String(taskId || '').trim();
  const selectedKey = String(state.utility?.selectedProblematicKey || '').trim();
  const normalizedExpectedAlbumKey = String(expectedAlbumKey || '').trim();
  if (
    !normalizedTaskId
    || state.utility?.activeTab !== 'problematic-files'
    || !state.utility?.loaded
    || !selectedKey
    || (normalizedExpectedAlbumKey && selectedKey !== normalizedExpectedAlbumKey)
  ) return null;
  const selectedAlbum = (state.utility.problematicFiles || []).find((album) => (
    String(album?.key || '').trim() === selectedKey
  )) || null;
  const originalKey = String(originalAlbum?.key || '').trim();
  if (!selectedAlbum || !originalAlbum || (originalKey !== selectedKey && !albumsShareTrackPath(selectedAlbum, getAlbumTrackPaths(originalAlbum)))) {
    return null;
  }
  const existing = state.utility.problematicMutation;
  if (existing) {
    return String(existing.taskId || '') === normalizedTaskId
      && String(existing.albumKey || '') === selectedKey
      ? existing
      : null;
  }
  const list = typeof getUtilityModalElements === 'function'
    ? getUtilityModalElements()?.list
    : null;
  const mutation = {
    taskId: normalizedTaskId,
    albumKey: selectedKey,
    priorKeys: (state.utility.problematicFiles || []).map((album) => String(album?.key || '')).filter(Boolean),
    priorScrollTop: Number(list?.scrollTop || 0),
    priorScrollHeight: Number(list?.scrollHeight || 0),
  };
  state.utility.problematicMutation = mutation;
  if (typeof renderUtilityModalContent === 'function') renderUtilityModalContent();
  return mutation;
}

async function settleProblematicSaveTaskMutation(taskId, { reconcileSelection = false } = {}) {
  const normalizedTaskId = String(taskId || '').trim();
  const mutation = state.utility?.problematicMutation;
  if (!mutation || String(mutation.taskId || '') !== normalizedTaskId) return false;
  const mutationOwnsView = (
    String(state.utility.selectedProblematicKey || '') === String(mutation.albumKey || '')
  );
  if (reconcileSelection && mutationOwnsView) {
    const items = Array.isArray(state.utility.problematicFiles) ? state.utility.problematicFiles : [];
    const survivingKeys = new Set(items.map((album) => String(album?.key || '')).filter(Boolean));
    const selectedKey = String(mutation.albumKey || '');
    if (survivingKeys.has(selectedKey)) {
      state.utility.selectedProblematicKey = selectedKey;
    } else {
      const priorKeys = Array.isArray(mutation.priorKeys) ? mutation.priorKeys : [];
      const selectedIndex = priorKeys.indexOf(selectedKey);
      const previousSurvivor = selectedIndex > 0
        ? priorKeys.slice(0, selectedIndex).reverse().find((key) => survivingKeys.has(key))
        : '';
      state.utility.selectedProblematicKey = previousSurvivor || String(items[0]?.key || '');
    }
    const survivorKey = String(state.utility.selectedProblematicKey || '');
    const survivor = items.find((album) => String(album?.key || '') === survivorKey) || null;
    if (survivor && survivor.detail_loaded !== true && typeof loadProblematicAlbumDetail === 'function') {
      await loadProblematicAlbumDetail(survivorKey, false, { render: false });
    }
  }
  const priorScrollTop = Number(mutation.priorScrollTop || 0);
  state.utility.problematicMutation = null;
  if (typeof renderUtilityModalContent === 'function') renderUtilityModalContent();
  const list = typeof getUtilityModalElements === 'function'
    ? getUtilityModalElements()?.list
    : null;
  if (list && mutationOwnsView) {
    const targetScrollHeight = Math.max(
      Number(mutation.priorScrollHeight || 0),
      priorScrollTop + Number(list.clientHeight || 0),
    );
    const ownerDocument = list.ownerDocument
      || (typeof document !== 'undefined' ? document : null);
    const retainedContent = ownerDocument?.createElement && typeof list.appendChild === 'function'
      ? ownerDocument.createElement('div')
      : null;
    let retainedContentHeight = Math.max(
      0,
      targetScrollHeight - Number(list.scrollHeight || 0),
    );
    if (retainedContent) {
      retainedContent.setAttribute('data-problematic-scroll-retainer', '');
      retainedContent.setAttribute('aria-hidden', 'true');
      retainedContent.style.flex = `0 0 ${retainedContentHeight}px`;
      retainedContent.style.height = `${retainedContentHeight}px`;
      retainedContent.style.pointerEvents = 'none';
      list.appendChild(retainedContent);
      const releaseRetainedGeometry = () => {
        retainedContent.remove?.();
        list.removeEventListener?.('pointerdown', releaseRetainedGeometry);
        list.removeEventListener?.('wheel', releaseRetainedGeometry);
        list.removeEventListener?.('keydown', releaseRetainedGeometry);
      };
      list.addEventListener?.('pointerdown', releaseRetainedGeometry);
      list.addEventListener?.('wheel', releaseRetainedGeometry, { passive: true });
      list.addEventListener?.('keydown', releaseRetainedGeometry);
    }
    const restoreOwnedScroll = () => {
      if (retainedContent && !retainedContent.isConnected && 'isConnected' in retainedContent) return;
      if (retainedContent) {
        const naturalScrollHeight = Math.max(
          0,
          Number(list.scrollHeight || 0) - retainedContentHeight,
        );
        retainedContentHeight = Math.max(0, targetScrollHeight - naturalScrollHeight);
        retainedContent.style.flex = `0 0 ${retainedContentHeight}px`;
        retainedContent.style.height = `${retainedContentHeight}px`;
      }
      list.scrollTop = priorScrollTop;
    };
    restoreOwnedScroll();
    if (typeof scheduleBrowserAnimationFrame === 'function') {
      scheduleBrowserAnimationFrame(() => {
        restoreOwnedScroll();
        scheduleBrowserAnimationFrame(restoreOwnedScroll);
      });
    }
  }
  return true;
}

async function refreshLoadedProblematicFilesAfterSaveCompletion() {
  if (!state.utility?.loaded && !state.utility?.loading) return false;
  const staleLoadPromise = state.utility.loadPromise;
  if (state.utility.loading && staleLoadPromise) {
    try {
      await staleLoadPromise;
    } catch (error) {
      console.warn(
        '[AlbumHaven][SaveTask] The previous Problematic Files load failed before the completed save refresh.',
        error,
      );
    }
  }
  await loadProblematicFiles(true, { render: false });
  const utilityOverlay = typeof getUtilityModalElements === 'function'
    ? getUtilityModalElements()?.overlay
    : null;
  if (
    !state.utility?.problematicMutation
    && !state.utility?.problematicNavigationActiveToken
    && utilityOverlay?.hidden === false
    && typeof renderUtilityModalContent === 'function'
  ) {
    renderUtilityModalContent();
  }
  return true;
}

async function watchSaveTask(taskId, context = {}) {
  const normalizedId = String(taskId || '').trim();
  if (!normalizedId) return;
  const originalAlbum = context.originalAlbum || null;
  const hasProblematicMutationOriginKey = Object.prototype.hasOwnProperty.call(
    context,
    'problematicMutationOriginKey',
  );
  const problematicMutationOriginKey = String(
    context.problematicMutationOriginKey || '',
  ).trim();
  const problematicMutation = (
    !hasProblematicMutationOriginKey || problematicMutationOriginKey
  )
    ? claimProblematicSaveTaskMutation(
      normalizedId,
      originalAlbum,
      problematicMutationOriginKey,
    )
    : null;
  const hasOriginatingViewStateRevision = Object.prototype.hasOwnProperty.call(
    context,
    'originatingViewStateRevision',
  );
  const originatingViewStateRevision = Number(context.originatingViewStateRevision || 0);
  const tagEditMutationClaim = context.tagEditMutationClaim || (
    hasOriginatingViewStateRevision && originalAlbum
      ? claimTagEditViewMutation(originalAlbum)
      : null
  );
  const originStillOwnsView = () => (
    !hasOriginatingViewStateRevision
    || Number(state.ui?.viewStateRevision || 0) === originatingViewStateRevision
  );
  const originatingViewRequestUrl = String(context.originatingViewRequestUrl || '').trim();
  const currentViewMatchesOriginRequest = () => (
    Boolean(originatingViewRequestUrl)
    && typeof buildApiUrl === 'function'
    && String(buildApiUrl(state.view) || '').trim() === originatingViewRequestUrl
  );
  const mutationStillOwnsOriginResources = () => (
    !tagEditMutationClaim
    || tagEditViewMutationStillOwnsResources(tagEditMutationClaim)
  );
  const canReconcileOriginView = () => (
    originStillOwnsView() && mutationStillOwnsOriginResources()
  );
  const mutationWasSuperseded = () => !mutationStillOwnsOriginResources();
  const absoluteScrollPosition = context.absoluteScrollPosition
    && Number.isFinite(Number(context.absoluteScrollPosition.scrollTop))
    && Number.isFinite(Number(context.absoluteScrollPosition.scrollLeft))
    ? {
      scrollLeft: Number(context.absoluteScrollPosition.scrollLeft),
      scrollTop: Number(context.absoluteScrollPosition.scrollTop),
    }
    : null;
  const renderOptions = context.preserveAbsoluteScroll === true
    ? {
      preserveScroll: true,
      preserveAbsoluteScroll: true,
      ...(absoluteScrollPosition ? { absoluteScrollPosition } : {}),
    }
    : { preserveScroll: true };
  const currentViewRenderOptions = () => (
    originStillOwnsView() || currentViewMatchesOriginRequest()
      ? { ...renderOptions, preserveGalleryOptionsMenu: true }
      : { preserveScroll: true, preserveGalleryOptionsMenu: true }
  );
  const restoreOwnedAbsoluteScroll = () => {
    if (
      !absoluteScrollPosition
      || (!originStillOwnsView() && !currentViewMatchesOriginRequest())
      || typeof document === 'undefined'
      || typeof document.getElementById !== 'function'
    ) return false;
    if (
      typeof virtualGrid !== 'undefined'
      && virtualGrid
      && typeof virtualGrid.restoreOwnedAbsoluteScrollPosition === 'function'
    ) {
      return virtualGrid.restoreOwnedAbsoluteScrollPosition(absoluteScrollPosition);
    }
    const galleryScroll = document.getElementById('albums-scroll');
    if (!galleryScroll) return false;
    galleryScroll.scrollLeft = absoluteScrollPosition.scrollLeft;
    galleryScroll.scrollTop = absoluteScrollPosition.scrollTop;
    return true;
  };
  const providedTerminalPayload = context.terminalPayload
    && typeof context.terminalPayload === 'object'
    && !Array.isArray(context.terminalPayload)
    ? {
      ...context.terminalPayload,
      task_id: String(
        context.terminalPayload.task_id
        || context.terminalPayload.save_task_id
        || normalizedId,
      ).trim(),
      status: String(
        context.terminalPayload.status
        || context.terminalPayload.save_task_status
        || '',
      ).trim().toLowerCase(),
    }
    : null;
  for (let attempt = 0; attempt < 40; attempt += 1) {
    const consumesProvidedTerminalPayload = attempt === 0 && providedTerminalPayload;
    try {
      let data = providedTerminalPayload;
      if (!consumesProvidedTerminalPayload) {
        const response = await fetch(`/utilities/save-task/${encodeURIComponent(normalizedId)}`, { headers: { Accept: 'application/json' } });
        data = await response.json().catch(() => ({}));
        if (!response.ok || !data.ok) {
          throw new Error(data.error || 'Unable to load save task.');
        }
      } else if (!data.ok) {
        throw new Error(data.error || 'Unable to load save task.');
      }
      const responseTaskId = String(data.task_id || '').trim();
      if (responseTaskId && responseTaskId !== normalizedId) {
        await waitForBrowserTimeout(500);
        continue;
      }
      if (data.status === 'completed') {
        const preRefreshVisibleAlbums = collectVisibleAlbumsUnique();
        await refreshLoadedProblematicFilesAfterSaveCompletion();
        const finalizedAlbums = applyExplicitFinalizedAlbumArtistEdits(
          Array.isArray(data.updated_albums) ? data.updated_albums : [],
          context.tagEdits,
        );
        const structuralTagEditRequiresMountedGalleryChildReplacement = (
          tagEditsRequireMountedGalleryChildReplacement(context.tagEdits)
        );
        const finalizedAlbumsKeepOriginalMembership = (
          finalizedAlbumsPreserveOriginalMembership(originalAlbum, finalizedAlbums)
        );
        const structuralTagEditRequiresCanonicalView = (
          structuralTagEditRequiresMountedGalleryChildReplacement
          && finalizedAlbumsKeepOriginalMembership
        );
        const finalizedAlbumsHaveCanonicalRuntimeIdentities = (
          finalizedAlbums.length > 0
          && finalizedAlbums.every((album) => (
            String(album?.request_key || '').trim()
            || String(album?.identity_key || '').trim()
          ))
        );
        const structuralMembershipTransferRequiresCanonicalRefresh = (
          structuralTagEditRequiresMountedGalleryChildReplacement
          && !finalizedAlbumsKeepOriginalMembership
        );
        const finalizedAlbumsCoverOriginalMembership = (
          finalizedAlbumsCoverExpectedTrackPaths(
            originalAlbum,
            context.optimisticAlbums,
            finalizedAlbums,
          )
        );
        const structuralPartialMembershipRequiresCanonicalRefresh = (
          structuralTagEditRequiresMountedGalleryChildReplacement
          && !finalizedAlbumsCoverOriginalMembership
        );
        let modalUpdatedAlbums = finalizedAlbums;
        let viewRefreshed = false;
        let viewReconciledLocally = false;
        if (data.requires_view_refresh) {
          if (
            canReconcileOriginView()
            && finalizedAlbums.length
            && (
              !structuralTagEditRequiresCanonicalView
              || finalizedAlbumsHaveCanonicalRuntimeIdentities
            )
          ) {
            try {
              const reconciledAlbums = applyUpdatedAlbumsToCurrentView(
                finalizedAlbums,
                {
                  skipRender: true,
                  originalAlbum,
                  preserveScroll: true,
                  tagEdits: context.tagEdits,
                },
              );
              if (reconciledAlbums.length) modalUpdatedAlbums = reconciledAlbums;
              renderView({
                ...renderOptions,
                preserveMountedGalleryChildren: true,
              });
              viewReconciledLocally = true;
            } catch (reconciliationError) {
              console.warn(
                '[AlbumHaven][SaveTask] Saved tags, but failed to reconcile the finalized albums locally.',
                reconciliationError,
              );
            }
          }
          if (
            (
              !viewReconciledLocally
              || structuralPartialMembershipRequiresCanonicalRefresh
            )
            && !mutationWasSuperseded()
          ) {
            try {
              let refreshView = state.view;
              const originSearch = context.originatingSearchContext;
              const originalOwner = String(originalAlbum?.album_artist || '').trim().toLowerCase();
              const splitAlbums = Array.isArray(context.optimisticAlbums) ? context.optimisticAlbums : [];
              const restoresAllSearchResults = Boolean(
                canReconcileOriginView()
                && structuralTagEditRequiresMountedGalleryChildReplacement
                && originSearch?.selected_artist_source === 'auto_top_match'
                && !(originSearch.artist_name_match_artists || []).length
                && originalOwner
                && splitAlbums.some(album => String(album?.album_artist || '').trim().toLowerCase() === originalOwner)
                && splitAlbums.some(album => {
                  const owner = String(album?.album_artist || '').trim().toLowerCase();
                  return owner && owner !== originalOwner;
                })
                && originatingViewRequestUrl
                && String(state.view.query || '').trim()
                && parseBrowserUrlState(originatingViewRequestUrl).query === state.view.query
                && !state.view.primary_filter_active
                && !(state.view.related_filter_artists || []).length
              );
              if (restoresAllSearchResults) {
                refreshView = { ...state.view, selected_artist: '', all_artists_active: true };
              }
              viewRefreshed = await fetchAndRender(
                buildApiUrl(refreshView),
                false,
                {
                  ...currentViewRenderOptions(),
                  preserveMountedGalleryChildren: true,
                  ...(!structuralTagEditRequiresCanonicalView
                    ? { retainMountedGalleryIfEquivalent: true }
                    : {}),
                  restartIfSameUrl: true,
                  shouldApplyResponse: () => !mutationWasSuperseded(),
                },
              );
              if (viewRefreshed && restoresAllSearchResults && canReconcileOriginView()) {
                window.history.replaceState(
                  window.AlbumHavenSettingsNavigation.sanitizeHistorySnapshot({ ...window.history.state, ...state.view }),
                  '', buildUrl(state.view),
                );
              }
              if (viewRefreshed && finalizedAlbums.length) {
                modalUpdatedAlbums = enrichFinalizedAlbumsWithCanonicalVisibleProjections(
                  finalizedAlbums,
                  collectVisibleAlbumsUnique(),
                  {
                    replaceCompactMembership: (finalizedAlbum) => (
                      originalAlbum
                      && albumsShareLogicalReleaseIdentity(finalizedAlbum, originalAlbum)
                    ),
                  },
                );
                if (
                  structuralMembershipTransferRequiresCanonicalRefresh
                  && finalizedAlbumsCoverOriginalMembership
                  && canReconcileOriginView()
                ) {
                  const reconciledAlbums = applyUpdatedAlbumsToCurrentView(
                    modalUpdatedAlbums,
                    {
                      skipRender: true,
                      originalAlbum,
                      preserveScroll: true,
                      tagEdits: context.tagEdits,
                    },
                  );
                  if (reconciledAlbums.length) modalUpdatedAlbums = reconciledAlbums;
                }
              }
              if (viewRefreshed && originalAlbum && !modalUpdatedAlbums.length) {
                modalUpdatedAlbums = collectVisibleAlbumsUnique();
              }
            } catch (refreshError) {
              console.warn('[AlbumHaven][SaveTask] Saved tags, but failed to refresh the view.', refreshError);
            }
          }
          if (
            structuralTagEditRequiresCanonicalView
            && !viewRefreshed
            && !viewReconciledLocally
            && canReconcileOriginView()
            && finalizedAlbums.length
          ) {
            const reconciledAlbums = applyUpdatedAlbumsToCurrentView(
              finalizedAlbums,
              {
                skipRender: true,
                originalAlbum,
                preserveScroll: true,
                tagEdits: context.tagEdits,
              },
            );
            if (reconciledAlbums.length) modalUpdatedAlbums = reconciledAlbums;
            renderView({
              ...renderOptions,
              preserveMountedGalleryChildren: true,
            });
            viewReconciledLocally = true;
          }
        } else if (canReconcileOriginView()) {
          const reconciledAlbums = applyUpdatedAlbumsToCurrentView(
            finalizedAlbums,
            {
              skipRender: true,
              originalAlbum,
              preserveScroll: true,
              tagEdits: context.tagEdits,
            },
          );
          if (reconciledAlbums.length) modalUpdatedAlbums = reconciledAlbums;
          renderView(renderOptions);
        } else if (!originStillOwnsView()) {
          try {
            await fetchAndRender(buildApiUrl(state.view), false, currentViewRenderOptions());
          } catch (refreshError) {
            console.warn(
              '[AlbumHaven][SaveTask] Saved tags, but the navigated view could not be refreshed.',
              refreshError,
            );
          }
        }
        if (originalAlbum && canReconcileOriginView()) {
          if (
            structuralMembershipTransferRequiresCanonicalRefresh
            && viewRefreshed
          ) {
            synchronizeCurrentViewAlbumIndex();
          }
          const trackModal = document.getElementById('track-modal');
          const trackModalOpen = Boolean(trackModal && !trackModal.hidden);
          if (!viewRefreshed || trackModalOpen) {
            modalUpdatedAlbums = enrichFinalizedAlbumsWithOptimisticModalTracks(
              modalUpdatedAlbums,
              viewRefreshed && trackModalOpen
                ? preRefreshVisibleAlbums
                : context.optimisticAlbums,
            );
          }
          updateOpenTrackModalAfterTagEdit(
            originalAlbum,
            modalUpdatedAlbums,
            {
              patchVisibleState: !viewRefreshed,
              preserveHydratedModalAfterCanonicalSave: (
                viewRefreshed
                || finalizedAlbumsHaveCanonicalRuntimeIdentities
              ),
            },
          );
          if (
            structuralTagEditRequiresMountedGalleryChildReplacement
            && data.requires_view_refresh
            && !finalizedAlbums.length
            && typeof invalidateHydratedTrackModalAlbumDetails === 'function'
          ) {
            invalidateHydratedTrackModalAlbumDetails([
              originalAlbum,
              ...(Array.isArray(context.optimisticAlbums) ? context.optimisticAlbums : []),
              ...modalUpdatedAlbums,
            ]);
          }
        }
        if (data.log_entry) {
          await prependUtilityLogHistoryEntry(data.log_entry);
        }
        if (problematicMutation) {
          await settleProblematicSaveTaskMutation(normalizedId, { reconcileSelection: true });
        }
        restoreOwnedAbsoluteScroll();
        if (!consumesProvidedTerminalPayload) {
          showRepairAlert('Library view updated from saved files.', 'success', 1000);
        }
        settleTagEditViewMutation(tagEditMutationClaim);
        return;
      }
      if (data.status === 'failed') {
        let viewRefreshed = false;
        if (!mutationWasSuperseded()) {
          try {
            viewRefreshed = await fetchAndRender(
              buildApiUrl(state.view),
              false,
              currentViewRenderOptions(),
            );
          } catch (refreshError) {
            console.warn(
              '[AlbumHaven][SaveTask] Tag edit failed and the compensated view could not be refreshed.',
              refreshError,
            );
          }
        }
        if (!viewRefreshed && originalAlbum && canReconcileOriginView()) {
          applyUpdatedAlbumsToCurrentView(
            [originalAlbum],
            {
              skipRender: true,
              originalAlbum,
              preserveScroll: true,
            },
          );
          renderView(renderOptions);
        }
        if (originalAlbum && canReconcileOriginView()) {
          const reconciledAlbums = viewRefreshed
            ? collectVisibleAlbumsUnique()
            : [originalAlbum];
          updateOpenTrackModalAfterTagEdit(originalAlbum, reconciledAlbums, {
            preserveHydratedModalAfterFailedSave: true,
          });
        }
        if (data.log_entry) {
          try {
            await prependUtilityLogHistoryEntry(data.log_entry);
          } catch (historyError) {
            console.warn('[AlbumHaven][SaveTask] Could not persist the failed tag edit in browser history.', historyError);
          }
        }
        showRepairAlert(
          data.error || 'Tags were saved, but final refresh failed.',
          'error',
          null,
          { logHistoryLink: true },
        );
        if (problematicMutation) settleProblematicSaveTaskMutation(normalizedId);
        releaseFailedTagEditViewMutation(tagEditMutationClaim);
        return;
      }
    } catch (error) {
      if (consumesProvidedTerminalPayload) throw error;
      console.warn('[AlbumHaven][SaveTask] Could not check save task status.', error);
    }
    await waitForBrowserTimeout(500);
  }
  if (problematicMutation) settleProblematicSaveTaskMutation(normalizedId);
  settleTagEditViewMutation(tagEditMutationClaim);
}

function cacheTagEditCandidateAlbums(candidates, sourceAliasOwner, sourceAliases, options = {}) {
  if (typeof cacheHydratedTrackModalAlbum !== 'function') return;
  candidates.filter((candidate) => candidate !== sourceAliasOwner).forEach((candidate) => {
    const candidateRequestKey = String(getAlbumRequestKey(candidate) || '').trim();
    cacheHydratedTrackModalAlbum(candidateRequestKey, candidate, options);
  });
  if (!sourceAliasOwner) return;
  const sourceRequestKey = String(getAlbumRequestKey(sourceAliasOwner) || '').trim();
  cacheHydratedTrackModalAlbum(
    sourceRequestKey,
    sourceAliasOwner,
    { ...options, aliases: sourceAliases },
  );
}

function preserveHydratedModalAfterFailedSave(candidate, originalAlbum, enabled = false) {
  const originalTracks = Array.isArray(originalAlbum?.tracks)
    ? originalAlbum.tracks
    : [];
  if (!enabled || !originalTracks.length) return candidate;
  return {
    ...candidate,
    ...originalAlbum,
    tracks: originalTracks.slice(),
    preview_only: false,
  };
}

function preserveHydratedModalTrackDetails(candidate, originalAlbum, enabled = false) {
  const candidateTracks = Array.isArray(candidate?.tracks) ? candidate.tracks : [];
  const originalTracks = Array.isArray(originalAlbum?.tracks) ? originalAlbum.tracks : [];
  if (!enabled || !originalTracks.length) return candidate;
  if (!candidateTracks.length) {
    const declaredTrackCount = Number(candidate?.track_count_preview || 0);
    if (declaredTrackCount > 0 && declaredTrackCount !== originalTracks.length) {
      return originalAlbum;
    }
    if (declaredTrackCount !== originalTracks.length) return candidate;
    return {
      ...candidate,
      tracks: originalTracks.slice(),
      preview_only: false,
    };
  }
  const originalTracksByPath = new Map(originalTracks.map((track) => [
    String(track?.path || ''),
    track,
  ]));
  let hydratedTrackCount = 0;
  const tracks = candidateTracks.map((track) => {
    const hydratedTrack = originalTracksByPath.get(String(track?.path || ''));
    if (!hydratedTrack) return track;
    hydratedTrackCount += 1;
    return {
      ...hydratedTrack,
      ...track,
    };
  });
  if (!hydratedTrackCount) return candidate;
  return {
    ...candidate,
    tracks,
    preview_only: hydratedTrackCount === candidateTracks.length
      ? false
      : candidate.preview_only,
  };
}

function updateOpenTrackModalAfterTagEdit(originalAlbum, updatedAlbums, options = {}) {
  const trackModal = document.getElementById('track-modal');
  const modalOpen = Boolean(trackModal && !trackModal.hidden);
  const candidates = Array.isArray(updatedAlbums) ? updatedAlbums.filter(Boolean) : [];
  if (!candidates.length) return;
  if (!modalOpen) {
    if (typeof cacheHydratedTrackModalAlbum !== 'function') return;
    const aliases = new Set([
      getAlbumRequestKey(originalAlbum),
      getAlbumIdentity(originalAlbum),
    ].map((alias) => String(alias || '').trim()).filter(Boolean));
    const sourceAliasOwner = candidates.find((candidate) => (
      albumsShareLogicalReleaseIdentity(candidate, originalAlbum)
    )) || candidates[0];
    cacheTagEditCandidateAlbums(candidates, sourceAliasOwner, aliases, {
      tagEditMutationClaim: options.tagEditMutationClaim || null,
    });
    return;
  }
  const currentAlbum = state.modalReleases[state.modalReleaseIndex] || originalAlbum;
  const currentPaths = getAlbumTrackPaths(currentAlbum);
  const originalPaths = getAlbumTrackPaths(originalAlbum);
  const updatedCurrentAlbum = getUpdatedAlbumForTrackPaths(candidates, currentPaths)
    || candidates.find((candidate) => albumsShareRuntimeIdentityAlias(candidate, currentAlbum))
    || null;
  const currentModalBelongsToMutation = (
    currentAlbum === originalAlbum
    || albumsShareRuntimeIdentityAlias(currentAlbum, originalAlbum)
    || albumsShareTrackPath(currentAlbum, originalPaths)
    || (
      updatedCurrentAlbum
      && albumsShareTrackPath(updatedCurrentAlbum, originalPaths)
    )
  );
  const remainingSourceAlbum = albumsShareLogicalReleaseIdentity(currentAlbum, originalAlbum)
    ? candidates.find((candidate) => (
      albumsShareLogicalReleaseIdentity(candidate, originalAlbum)
      && (
        getAlbumTrackPaths(candidate).size
        || Number(candidate?.track_count_preview || 0) > 0
      )
    ))
    : null;
  const updatedAlbum = remainingSourceAlbum
    || updatedCurrentAlbum
    || getUpdatedAlbumForTrackPaths(candidates, originalPaths)
    || candidates[0];
  if (!updatedAlbum) return;
  const failedSaveModalAlbum = preserveHydratedModalAfterFailedSave(
    updatedAlbum,
    originalAlbum,
    options.preserveHydratedModalAfterFailedSave === true
      && currentModalBelongsToMutation,
  );
  const modalAlbum = preserveHydratedModalTrackDetails(
    failedSaveModalAlbum,
    options.preserveHydratedModalAfterCanonicalSave === true
      && currentModalBelongsToMutation
      ? currentAlbum
      : originalAlbum,
    options.preserveHydratedModalAfterCanonicalSave === true
      && currentModalBelongsToMutation,
  );
  if (options.patchVisibleState !== false) {
    patchVisibleAlbumsByTrackPath(candidates);
  }
  const aliases = new Set([
    getAlbumRequestKey(originalAlbum),
    getAlbumIdentity(originalAlbum),
    ...(currentModalBelongsToMutation
      ? [getAlbumRequestKey(currentAlbum), getAlbumIdentity(currentAlbum)]
      : []),
  ].map((alias) => String(alias || '').trim()).filter(Boolean));
  const sourceAliasOwner = candidates.find((candidate) => (
    albumsShareLogicalReleaseIdentity(candidate, originalAlbum)
  )) || updatedAlbum;
  cacheTagEditCandidateAlbums(
    candidates,
    sourceAliasOwner === updatedAlbum ? modalAlbum : sourceAliasOwner,
    aliases,
    {
      tagEditMutationClaim: options.tagEditMutationClaim || null,
    },
  );
  if (!currentModalBelongsToMutation) return;
  const releaseSet = getAlbumReleaseSet(modalAlbum);
  state.modalReleases = releaseSet.releases.length ? releaseSet.releases : [modalAlbum];
  state.modalReleaseIndex = Math.max(0, releaseSet.selectedIndex || 0);
  renderTrackModalRelease(state.modalReleases[state.modalReleaseIndex] || modalAlbum);
}

function updateTrackModalIfStillShowingAlbum(originalAlbum, updatedAlbums) {
  const modalOpen = !document.getElementById('track-modal')?.hidden;
  if (!modalOpen) return;
  const currentAlbum = state.modalReleases[state.modalReleaseIndex] || null;
  if (!currentAlbum) return;
  const currentPaths = getAlbumTrackPaths(currentAlbum);
  const originalPaths = getAlbumTrackPaths(originalAlbum);
  if (!currentPaths.size || !originalPaths.size) return;
  const stillShowingOriginalAlbum = Array.from(currentPaths).some((path) => originalPaths.has(path));
  if (!stillShowingOriginalAlbum) return;
  updateOpenTrackModalAfterTagEdit(originalAlbum, updatedAlbums);
}

function applyRepairResultToProblematicFiles(originalAlbum, updatedAlbum) {
  const originalKey = String(originalAlbum?.key || '');
  const originalPaths = getAlbumTrackPaths(originalAlbum);
  const hasUpdatedAlbum = updatedAlbum && typeof updatedAlbum === 'object' && Object.keys(updatedAlbum).length;
  const updatedKey = hasUpdatedAlbum ? String(updatedAlbum.key || '') : '';
  const previousItems = Array.isArray(state.utility.problematicFiles) ? state.utility.problematicFiles : [];
  const selectedKeyBefore = String(state.utility.selectedProblematicKey || '');
  const selectedIndexBefore = previousItems.findIndex((item) => String(item?.key || '') === selectedKeyBefore);
  let insertedUpdatedAlbum = false;

  const nextItems = (state.utility.problematicFiles || []).reduce((items, item) => {
    const matchesOriginal = (originalKey && item.key === originalKey) || albumsShareTrackPath(item, originalPaths);
    const matchesUpdated = updatedKey && item.key === updatedKey;
    if (matchesOriginal || matchesUpdated) {
      if (hasUpdatedAlbum && !insertedUpdatedAlbum) {
        items.push(updatedAlbum);
        insertedUpdatedAlbum = true;
      }
      return items;
    }
    items.push(item);
    return items;
  }, []);

  if (hasUpdatedAlbum && !insertedUpdatedAlbum) {
    nextItems.push(updatedAlbum);
  }

  state.utility.problematicFiles = nextItems;
  state.utility.loaded = true;
  if (hasUpdatedAlbum) {
    state.utility.selectedProblematicKey = String(updatedAlbum.key || '');
  } else if (selectedIndexBefore >= 0) {
    const previousSurvivor = previousItems.slice(0, selectedIndexBefore).reverse().find((item) => (
      nextItems.some((candidate) => String(candidate?.key || '') === String(item?.key || ''))
    ));
    state.utility.selectedProblematicKey = String(previousSurvivor?.key || '');
  } else {
    state.utility.selectedProblematicKey = '';
  }
  state.utility.showRepairedDisplay = true;
  state.utility.repairSelections = {};
  state.utility.problemExclusionSelections = {};
  state.utility.separateReleaseSelections = {};
  state.utility.pendingRepairAction = '';
  renderUtilityModalContent();
}

function normalizeProblemFilterReason(reason) {
  const normalized = String(reason || '').trim();
  if (normalized === 'Inconsistent year' || normalized.startsWith('Year mismatch')) return 'Year mismatch';
  return normalized.startsWith('Incomplete track order:')
    ? 'Incomplete track order'
    : normalized;
}

function getAlbumProblemFilterReasons(album) {
  return (Array.isArray(album?.problem_reasons) ? album.problem_reasons : [])
    .map((reason) => normalizeProblemFilterReason(reason))
    .filter(Boolean);
}

function getProblemReasonTypes() {
  const reasons = new Set();
  (state.utility.problematicFiles || []).forEach((album) => {
    getAlbumProblemFilterReasons(album).forEach((reason) => {
      if (reason) reasons.add(reason);
    });
  });
  return Array.from(reasons).sort((a, b) => a.localeCompare(b));
}

function albumMatchesProblemFilters(album, selectedFilters = state.utility.selectedProblemFilters || []) {
  const selected = Array.isArray(selectedFilters) ? selectedFilters : [];
  if (!selected.length) return true;
  const reasons = new Set(getAlbumProblemFilterReasons(album));
  return selected.some((reason) => reasons.has(normalizeProblemFilterReason(reason)));
}

function getAlbumProblemFilterSortIndex(album) {
  const selected = state.utility.selectedProblemFilters || [];
  if (!selected.length) return Number.MAX_SAFE_INTEGER;
  const reasons = new Set(getAlbumProblemFilterReasons(album));
  const index = selected.findIndex((reason) => reasons.has(reason));
  return index === -1 ? Number.MAX_SAFE_INTEGER : index;
}

function renderProblemFilterControls(els) {
  const reasonTypes = getProblemReasonTypes();
  const selected = state.utility.selectedProblemFilters || [];
  const selectedSet = new Set(selected);

  if (els.problemFilterButton) {
    const countSuffix = selected.length ? ` (${selected.length})` : '';
    els.problemFilterButton.setAttribute('aria-label', `Filters${countSuffix}`);
    els.problemFilterButton.setAttribute('title', `Filter by problem type${countSuffix}`);
    els.problemFilterButton.classList.toggle('is-active', Boolean(selected.length));
    els.problemFilterButton.setAttribute('aria-expanded', state.utility.problemDropdownOpen ? 'true' : 'false');
    els.problemFilterButton.hidden = false;
    els.problemFilterButton.disabled = !reasonTypes.length;
  }

  if (els.problemFilterMenu) {
    els.problemFilterMenu.hidden = !state.utility.problemDropdownOpen;
    if (state.utility.problemDropdownOpen && typeof syncTriggerAnchor === 'function') {
      if (typeof activateTriggerSurface === 'function') activateTriggerSurface(els.problemFilterMenu, () => {
        state.utility.problemDropdownOpen = false;
        renderProblemFilterControls(els);
      });
      syncTriggerAnchor(els.problemFilterMenu, els.problemFilterButton);
    }
    else if (typeof clearTriggerAnchor === 'function') clearTriggerAnchor(els.problemFilterMenu);
    els.problemFilterMenu.innerHTML = reasonTypes.length
      ? reasonTypes.map((reason) => `
          <button class="utility-problem-filter-option ${selectedSet.has(reason) ? 'is-selected' : ''}" type="button" data-problem-filter-value="${escapeHtml(reason)}" role="option" aria-selected="${selectedSet.has(reason) ? 'true' : 'false'}">
            <span class="utility-problem-filter-check">${selectedSet.has(reason) ? 'on' : ''}</span>
            <span class="utility-problem-filter-label">${escapeHtml(reason)}</span>
          </button>
        `).join('')
      : '<div class="utility-problem-filter-empty">No problem types found.</div>';
  }

  if (els.problemFilterChips) {
    els.problemFilterChips.innerHTML = selected.length
      ? selected.map((reason) => `
          <button class="utility-problem-filter-chip" type="button" data-remove-problem-filter="${escapeHtml(reason)}" title="Remove problem filter">
            <span>${escapeHtml(reason)}</span>
            <span aria-hidden="true">x</span>
          </button>
        `).join('')
      : '';
  }
}

function getFilteredProblematicAlbums() {
  const items = state.utility.problematicFiles || [];
  const query = (state.utility.searchQuery || '').trim().toLowerCase();

  const filtered = items.filter((album) => {
    if (!albumMatchesProblemFilters(album)) return false;
    if (!query) return true;
    const repairRows = Array.isArray(album.repair_preview_rows) ? album.repair_preview_rows : [];
    const trackTitles = Array.isArray(album.tracks) ? album.tracks.map((track) => String(track.title || '')) : [];
    const haystack = [
      String(album.name || ''),
      String(album.raw_name || ''),
      String(album.album_artist || ''),
      String(album.raw_album_artist || ''),
      String(album.year || ''),
      ...(Array.isArray(album.problem_reasons) ? album.problem_reasons.map((reason) => String(reason || '')) : []),
      String(album.search_text || ''),
      ...trackTitles,
      ...repairRows.flatMap((row) => [
        String(row.track_title || ''),
        String(row.original || ''),
        String(row.repaired || ''),
      ]),
    ].join('\n').toLowerCase();
    return haystack.includes(query);
  });

  if (!(state.utility.selectedProblemFilters || []).length) return filtered;
  return filtered.slice().sort((a, b) => (
    getAlbumProblemFilterSortIndex(a) - getAlbumProblemFilterSortIndex(b)
    || String(a.name || '').localeCompare(String(b.name || ''))
    || String(a.album_artist || '').localeCompare(String(b.album_artist || ''))
    || String(a.year || '').localeCompare(String(b.year || ''))
  ));
}

function getProblematicAlbumIssueLabel(album) {
  if (album?.detail_loading_deferred) return 'Loading issues…';
  const count = Array.isArray(album?.problem_reasons) ? album.problem_reasons.length : 0;
  return `${count} issue${count === 1 ? '' : 's'}`;
}

function getSelectedProblematicAlbumFrom(items) {
  return (items || []).find((item) => item.key === state.utility.selectedProblematicKey) || null;
}

function getSelectedUtilityRule() {
  return (state.utility.rules || []).find((item) => item.key === state.utility.selectedRuleKey) || null;
}

function getProblematicAlbumForTrackPath(trackPath) {
  const normalized = String(trackPath || '');
  return (state.utility.problematicFiles || []).find((album) =>
    (Array.isArray(album.problematic_track_paths) && album.problematic_track_paths.includes(normalized))
    || (Array.isArray(album.track_paths) && album.track_paths.includes(normalized))
  ) || null;
}

async function openUtilityModalForTrack(trackPath) {
  const navigationToken = Number(state.utility.problematicNavigationToken || 0) + 1;
  state.utility.problematicNavigationToken = navigationToken;
  state.utility.problematicNavigationActiveToken = navigationToken;
  const ownsNavigation = () => (
    Number(state.utility.problematicNavigationToken || 0) === navigationToken
  );
  try {
    const summaryRequestTokenBeforePendingTasks = Number(
      state.utility.problematicSummaryRequestToken || 0,
    );
    const pendingTasks = Object.values(
      state.utility.pendingProblematicSaveTasks || {},
    ).filter((entry) => (
      Array.isArray(entry?.trackPaths)
      && entry.trackPaths.includes(String(trackPath || ''))
      && entry.promise
      && typeof entry.promise.then === 'function'
    ));
    const optimisticAlbum = pendingTasks
      .flatMap((entry) => (Array.isArray(entry?.optimisticAlbums) ? entry.optimisticAlbums : []))
      .find((candidate) => albumsShareTrackPath(
        candidate,
        new Set([String(trackPath || '')].filter(Boolean)),
      )) || null;
    if (optimisticAlbum) {
      const optimisticKey = String(optimisticAlbum.key || '').trim();
      const existingItems = Array.isArray(state.utility.problematicFiles)
        ? state.utility.problematicFiles
        : [];
      state.utility.problematicFiles = [
        ...existingItems.filter((item) => String(item?.key || '').trim() !== optimisticKey),
        {
          ...optimisticAlbum,
          detail_loading_deferred: optimisticAlbum.detail_loaded !== true,
        },
      ];
      state.utility.loaded = true;
      state.utility.loading = false;
      state.utility.selectedProblematicKey = optimisticKey;
      state.utility.focusedTrackPath = String(trackPath || '');
      state.utility.showRepairedDisplay = true;
      state.utility.deferProblematicAutoSelection = false;
      state.utility.selectedProblemFilters = [];
      state.utility.problemDropdownOpen = false;
      setUtilityActiveTab('problematic-files');
      openUtilityModal({ resetSearch: true, resetSelection: false, forceLoad: false });
    }
    const optimisticDetailPromise = !optimisticAlbum || optimisticAlbum.detail_loaded === true
      ? null
      : Promise.resolve().then(async () => {
        const acceptedPromises = pendingTasks
          .map((entry) => entry?.acceptedPromise)
          .filter((promise) => promise && typeof promise.then === 'function');
        if (acceptedPromises.length) {
          await Promise.allSettled(acceptedPromises);
        }
        if (!ownsNavigation()) return null;
        return loadProblematicAlbumDetail(
          optimisticAlbum?.key || '',
          true,
          { allowMissing: true },
        );
      });
    if (pendingTasks.length) {
      await Promise.allSettled(pendingTasks.map((entry) => entry.promise));
      if (!ownsNavigation()) return;
    }
    if (optimisticDetailPromise) {
      await Promise.allSettled([optimisticDetailPromise]);
      if (!ownsNavigation()) return;
    }
    const summaryWasLoaded = state.utility.loaded;
    const pendingTaskRefreshedSummary = (
      pendingTasks.length > 0
      && Number(state.utility.problematicSummaryRequestToken || 0)
        > summaryRequestTokenBeforePendingTasks
    );
    if (!state.utility.loaded || (pendingTasks.length && !pendingTaskRefreshedSummary)) {
      const loadResult = await loadProblematicFiles(true, { render: false });
      if (loadResult === null || !ownsNavigation()) return;
    }
    let album = getProblematicAlbumForTrackPath(trackPath);
    if (!album && summaryWasLoaded) {
      const refreshResult = await loadProblematicFiles(true, { render: false });
      if (refreshResult === null || !ownsNavigation()) return;
      album = getProblematicAlbumForTrackPath(trackPath);
    }
    if (!ownsNavigation()) return;
    if (!album) {
      showToast('This track is not currently listed in Problematic Files.', 'error', 3200);
      return;
    }
    state.utility.selectedProblematicKey = album.key || '';
    state.utility.focusedTrackPath = String(trackPath || '');
    state.utility.showRepairedDisplay = true;
    state.utility.deferProblematicAutoSelection = false;
    state.utility.selectedProblemFilters = [];
    state.utility.problemDropdownOpen = false;
    setUtilityActiveTab('problematic-files');
    if (!album.detail_loaded) {
      await loadProblematicAlbumDetail(album.key || '', undefined, { render: false });
      if (!ownsNavigation()) return;
    }
    openUtilityModal({ resetSearch: true, resetSelection: false, forceLoad: false });
  } finally {
    if (Number(state.utility.problematicNavigationActiveToken || 0) === navigationToken) {
      state.utility.problematicNavigationActiveToken = 0;
    }
  }
}

function getIgnorableProblemRows(album) {
  const albumRows = Array.isArray(album?.album_problem_rows) ? album.album_problem_rows : [];
  const trackRows = (Array.isArray(album?.track_problem_rows) ? album.track_problem_rows : [])
    .flatMap((row) => Array.isArray(row.ignorable_reasons) ? row.ignorable_reasons : [])
    .filter((item) => String(item.row_key || ''));
  return [...albumRows.filter((item) => String(item?.row_key || '')), ...trackRows];
}

function selectProblemExclusion(rowKey, { toggle = true } = {}) {
  const normalizedKey = String(rowKey || '');
  const alreadySelected = Boolean(
    normalizedKey && state.utility.problemExclusionSelections?.[normalizedKey],
  );
  const selections = { ...(state.utility.problemExclusionSelections || {}) };
  if (normalizedKey && (!toggle || !alreadySelected)) selections[normalizedKey] = true;
  else delete selections[normalizedKey];
  state.utility.problemExclusionSelections = selections;
}

function extendProblemExclusionRange(reason, startIndex, endIndex, selected = true) {
  const album = getSelectedProblematicAlbum();
  const rows = Array.isArray(album?.track_problem_rows) ? album.track_problem_rows : [];
  const normalizedReason = String(reason || '');
  const from = Math.min(Number(startIndex), Number(endIndex));
  const to = Math.max(Number(startIndex), Number(endIndex));
  if (!Number.isInteger(from) || !Number.isInteger(to) || from < 0 || to >= rows.length) return false;
  const keys = [];
  for (let index = from; index <= to; index += 1) {
    const match = (Array.isArray(rows[index]?.ignorable_reasons) ? rows[index].ignorable_reasons : [])
      .find((item) => normalizeProblemFilterReason(item?.reason) === normalizeProblemFilterReason(normalizedReason) && String(item?.row_key || ''));
    if (match) keys.push(String(match.row_key));
  }
  if (!keys.length) return false;
  const selections = { ...(state.utility.problemExclusionSelections || {}) };
  keys.forEach(key => {
    if (selected) selections[key] = true;
    else delete selections[key];
  });
  state.utility.problemExclusionSelections = selections;
  return true;
}

function getRepairRowKeysFromButton(button) {
  const rowKey = button?.getAttribute('data-repair-row-key') || '';
  const rowKeysPayload = button?.getAttribute('data-repair-row-keys') || '';
  let rowKeys = rowKey ? [rowKey] : [];
  if (rowKeysPayload) {
    try {
      const parsed = JSON.parse(rowKeysPayload);
      rowKeys = Array.isArray(parsed) ? parsed.map((value) => String(value || '')).filter(Boolean) : rowKeys;
    } catch (error) {
      console.warn('[AlbumHaven][Utilities] Could not parse problem action row keys.', error);
    }
  }
  return rowKeys;
}

function applyNotProblemChoice(button, choice) {
  const rowKeys = getRepairRowKeysFromButton(button);
  if (!rowKeys.length) return false;
  rowKeys.forEach((key) => {
    state.utility.repairSelections[key] = choice;
  });
  return true;
}

function applyRepairChoice(button, choice) {
  const rowKeys = getRepairRowKeysFromButton(button);
  if (!rowKeys.length) return false;
  const changed = rowKeys.some((key) => state.utility.repairSelections[key] !== choice);
  if (!changed) return false;
  rowKeys.forEach((key) => {
    state.utility.repairSelections[key] = choice;
  });
  return true;
}

function initializeRepairSelections(album) {
  const rows = Array.isArray(album?.repair_preview_rows) ? album.repair_preview_rows : [];
  const ignorableRows = getIgnorableProblemRows(album);
  const nextSelections = {};
  rows.forEach((row) => {
    const rowKey = String(row.row_key || '');
    if (!rowKey) return;
    nextSelections[rowKey] = state.utility.repairSelections[rowKey] || 'repair';
  });
  state.utility.repairSelections = nextSelections;
  const validExclusionKeys = new Set(ignorableRows.map((row) => String(row?.row_key || '')).filter(Boolean));
  state.utility.problemExclusionSelections = Object.fromEntries(
    Object.entries(state.utility.problemExclusionSelections || {})
      .filter(([rowKey, selected]) => selected && validExclusionKeys.has(rowKey)),
  );
}

function getSelectedRepairRowKeys() {
  return Object.entries(state.utility.repairSelections)
    .filter(([, value]) => value === 'repair')
    .map(([key]) => key);
}

function getIgnoredRepairRowKeys() {
  return Object.entries(state.utility.problemExclusionSelections || {})
    .filter(([, selected]) => Boolean(selected))
    .map(([key]) => key);
}

function getSelectedRepairFileCount() {
  return new Set(getSelectedRepairRowKeys().map((value) => String(value).split('::')[0]).filter(Boolean)).size;
}

function getSelectedSeparateReleaseKeys() {
  return Object.entries(state.utility.separateReleaseSelections || {})
    .filter(([, selected]) => Boolean(selected))
    .map(([key]) => key);
}

function openRuleRevertConfirm(rule) {
  state.utility.pendingRuleRevert = rule;
  state.utility.pendingRepairAction = 'revert-rule';
  openRepairConfirmModal();
}
function getVisibleProblemSuggestions(album = getSelectedProblematicAlbum()) {
  const albumKey = String(album?.key || '');
  if (state.utility.proposalAlbumKey && state.utility.proposalAlbumKey !== albumKey) state.utility.proposalSelections = {};
  state.utility.proposalAlbumKey = albumKey;
  const selected = (state.utility.selectedProblemFilters || []).map(normalizeProblemFilterReason);
  const query = String(state.utility.searchQuery || '').trim().toLocaleLowerCase();
  return (Array.isArray(album?.suggested_edits) ? album.suggested_edits : []).filter(proposal => {
    if (!proposal?.id || proposal.eligible === false) return false;
    if (selected.length && !selected.includes(normalizeProblemFilterReason(proposal.reason))) return false;
    if (!query) return true;
    const track = (album.tracks || []).find(item => item.path === proposal.path) || {};
    return [album.name, album.album_artist, track.title, track.artist, proposal.original, proposal.corrected, proposal.path]
      .some(value => String(value || '').toLocaleLowerCase().includes(query));
  });
}

function getApplicableProblemSuggestions() {
  const visible = getVisibleProblemSuggestions();
  const selections = state.utility.proposalSelections || {};
  return visible.filter(proposal => selections[proposal.id]);
}

function toggleProblemSuggestion(id, { selected } = {}) {
  const proposal = getVisibleProblemSuggestions().find(item => item.id === id);
  if (!proposal) return false;
  const selections = { ...(state.utility.proposalSelections || {}) };
  const enabled = selected === undefined ? !selections[id] : Boolean(selected);
  if (enabled) selections[id] = true;
  else delete selections[id];
  state.utility.proposalSelections = selections;
  return true;
}

function getDraggableProblemSuggestions() {
  const proposals = new Map(getVisibleProblemSuggestions().map(item => [item.id, item]));
  return Array.from(document.querySelectorAll('[data-problem-suggestion-id]'))
    .filter(button => !button.disabled)
    .map(button => proposals.get(button.getAttribute('data-problem-suggestion-id')))
    .filter(Boolean);
}

function formatProblemSuggestionLabel(proposal) {
  const label = { album: 'Album', album_artist: 'Album artist', artist: 'Artist', title: 'Title', year: 'Year', track_number: 'Track', disc_number: 'Disc', album_disc_marker: 'Album / disc' }[proposal.field] || proposal.field;
  const original = proposal.original === null || proposal.original === undefined || proposal.original === '' ? 'missing' : String(proposal.original);
  return `${label}: ${original} → ${String(proposal.corrected ?? '')}`;
}

function syncProblemSuggestionSelection() {
  document.querySelectorAll?.('[data-problem-suggestion-id]').forEach(button => {
    button.setAttribute('aria-pressed', state.utility.proposalSelections?.[button.getAttribute('data-problem-suggestion-id')] ? 'true' : 'false');
  });
  const apply = document.querySelector?.('[data-apply-problem-suggestions]');
  if (apply) {
    const label = apply.querySelector?.('.ui-button__content') || apply;
    label.textContent = 'Apply';
    ButtonComponent.setDisabled(apply, !getSelectedProblematicAlbum()?.allowed_actions?.['library.files.edit_tags'] || !getApplicableProblemSuggestions().length || Boolean(state.utility.proposalApplyBusy));
  }
}
function syncProblemExclusionSelection() {
  document.querySelectorAll?.('[data-problem-exclusion-row-key]').forEach(button => {
    button.setAttribute('aria-pressed', state.utility.problemExclusionSelections?.[button.getAttribute('data-problem-exclusion-row-key')] ? 'true' : 'false');
  });
  document.querySelectorAll?.('[data-album-problem-type]').forEach(button => {
    const keys = getIgnorableProblemRows(getSelectedProblematicAlbum()).filter(item => normalizeProblemFilterReason(item.reason) === button.getAttribute('data-album-problem-type')).map(item => item.row_key);
    button.setAttribute('aria-pressed', keys.length && keys.every(key => state.utility.problemExclusionSelections?.[key]) ? 'true' : 'false');
  });
  const action = document.querySelector?.('[data-open-exclusion-confirm]');
  if (action) ButtonComponent.setDisabled(action, !getIgnoredRepairRowKeys().length || !getSelectedProblematicAlbum()?.allowed_actions?.['library.rules.manage']);
}

// END js/runtime/utility-list-builders.js

// BEGIN js/runtime/problem-exclusion-mutations.js

const problemExclusionRequestChains = new Map();

function getProblemExclusionMutationJournal() {
  const utility = state.utility || (state.utility = {});
  if (!utility.problemExclusionMutations) {
    utility.problemExclusionMutations = {
      nextOperationId: 1,
      revision: 0,
      latestByRowKey: {},
      pendingByOperationId: {},
      acknowledgedCreates: [],
    };
  }
  utility.problemExclusionMutations.revision = Number(
    utility.problemExclusionMutations.revision || 0,
  );
  if (!Array.isArray(utility.problemExclusionMutations.acknowledgedCreates)) {
    utility.problemExclusionMutations.acknowledgedCreates = [];
  }
  return utility.problemExclusionMutations;
}

function readProblemExclusionMutationRevision() {
  return Number(getProblemExclusionMutationJournal().revision || 0);
}

function advanceProblemExclusionMutationRevision() {
  const journal = getProblemExclusionMutationJournal();
  journal.revision = Number(journal.revision || 0) + 1;
  return journal.revision;
}

function cloneProblemExclusionValue(value) {
  if (typeof structuredClone === 'function') return structuredClone(value);
  return JSON.parse(JSON.stringify(value));
}

function problemExclusionReason(item) {
  return String(item?.problem_reason || item?.reason || '').trim();
}

function projectProblemExclusionFromAlbum(album, selectedItems) {
  const source = cloneProblemExclusionValue(album || {});
  const items = (Array.isArray(selectedItems) ? selectedItems : [])
    .filter((item) => String(item?.row_key || '').trim());
  const albumRows = Array.isArray(source.album_problem_rows)
    ? source.album_problem_rows
    : [];
  const albumReasons = new Set();
  const selectedAlbumKeys = new Set();
  const selectedFileReasons = new Map();

  items.forEach((item) => {
    const rowKey = String(item.row_key || '').trim();
    if (item.scope === 'album') {
      selectedAlbumKeys.add(rowKey);
      const sourceRow = albumRows.find((row) => String(row?.row_key || '') === rowKey);
      const reason = problemExclusionReason(item) || problemExclusionReason(sourceRow);
      if (reason) albumReasons.add(reason);
      return;
    }
    if (item.scope !== 'file') return;
    const path = String(item.path || '').trim();
    const reason = problemExclusionReason(item);
    if (!path || !reason) return;
    const reasons = selectedFileReasons.get(path) || new Set();
    reasons.add(reason);
    selectedFileReasons.set(path, reasons);
  });

  source.album_problem_rows = albumRows.filter((row) => {
    const rowKey = String(row?.row_key || '').trim();
    return !selectedAlbumKeys.has(rowKey) && !albumReasons.has(problemExclusionReason(row));
  });
  source.track_problem_rows = (Array.isArray(source.track_problem_rows)
    ? source.track_problem_rows
    : []).map((row) => {
    const path = String(row?.path || '').trim();
    const fileReasons = selectedFileReasons.get(path) || new Set();
    const shouldRemoveReason = (reason) => (
      albumReasons.has(String(reason || '').trim())
      || fileReasons.has(String(reason || '').trim())
    );
    return {
      ...row,
      reasons: (Array.isArray(row?.reasons) ? row.reasons : [])
        .filter((reason) => !shouldRemoveReason(reason)),
      ignorable_reasons: (Array.isArray(row?.ignorable_reasons) ? row.ignorable_reasons : [])
        .filter((reasonItem) => !shouldRemoveReason(problemExclusionReason(reasonItem))),
    };
  }).filter((row) => row.reasons.length);

  const retainedReasons = new Set([
    ...source.album_problem_rows.map((row) => problemExclusionReason(row)),
    ...source.track_problem_rows.flatMap((row) => row.reasons || []),
  ].map((reason) => String(reason || '').trim()).filter(Boolean));
  const originalReasonOrder = Array.isArray(source.problem_reasons)
    ? source.problem_reasons
    : [];
  source.problem_reasons = [
    ...originalReasonOrder.filter((reason) => retainedReasons.delete(String(reason || '').trim())),
    ...retainedReasons,
  ];
  source.issue_count = source.problem_reasons.length;

  const optimisticRuleItems = items.map((item) => ({
    ...cloneProblemExclusionValue(item),
    pending: true,
  }));
  return {
    updatedAlbum: source.problem_reasons.length ? source : null,
    optimisticRuleItems,
  };
}

function collectProblemIgnoreItems(rule) {
  const combined = [
    ...(Array.isArray(rule?.items) ? rule.items : []),
    ...(Array.isArray(rule?.album_items)
      ? rule.album_items.map((item) => ({ ...item, scope: item.scope || 'album' }))
      : []),
    ...(Array.isArray(rule?.file_items)
      ? rule.file_items.map((item) => ({ ...item, scope: item.scope || 'file' }))
      : []),
  ];
  const byKey = new Map();
  combined.forEach((item) => {
    const rowKey = String(item?.row_key || '').trim();
    if (rowKey) byKey.set(rowKey, item);
  });
  return Array.from(byKey.values());
}

function replaceProblemIgnoreRule(rules, items) {
  const sourceRules = Array.isArray(rules) ? rules : [];
  const existingIndex = sourceRules.findIndex((rule) => rule?.key === 'problem-ignores');
  const existing = existingIndex >= 0 ? sourceRules[existingIndex] : null;
  const normalizedItems = Array.from(new Map(
    (Array.isArray(items) ? items : [])
      .map((item) => [String(item?.row_key || '').trim(), item])
      .filter(([rowKey]) => rowKey),
  ).values());
  const nextRule = {
    ...(existing || {
      key: 'problem-ignores',
      title: 'Problem exclusions',
      description: 'Album or file problems excluded from Problematic Files.',
    }),
    count: normalizedItems.length,
    items: normalizedItems,
    album_items: normalizedItems.filter((item) => item.scope === 'album'),
    file_items: normalizedItems.filter((item) => item.scope === 'file'),
  };
  if (existingIndex < 0) return [...sourceRules, nextRule];
  return sourceRules.map((rule, index) => (index === existingIndex ? nextRule : rule));
}

function beginProblemExclusionMutation({ kind, items, snapshot }) {
  const journal = getProblemExclusionMutationJournal();
  const id = Number(journal.nextOperationId || 1);
  journal.nextOperationId = id + 1;
  const operation = {
    id,
    kind: kind === 'revert' ? 'revert' : 'create',
    items: (Array.isArray(items) ? items : []).map((item) => cloneProblemExclusionValue(item)),
    snapshot: cloneProblemExclusionValue(snapshot || {}),
  };
  operation.items.forEach((item) => {
    const rowKey = String(item?.row_key || '').trim();
    if (rowKey) journal.latestByRowKey[rowKey] = id;
  });
  journal.pendingByOperationId[id] = operation;
  advanceProblemExclusionMutationRevision();
  return operation;
}

function isLatestProblemExclusionMutation(operation) {
  if (!operation) return false;
  const journal = getProblemExclusionMutationJournal();
  return operation.items.every((item) => (
    Number(journal.latestByRowKey[String(item?.row_key || '')]) === Number(operation.id)
  ));
}

function removeProblemExclusionOperation(operation) {
  const journal = getProblemExclusionMutationJournal();
  delete journal.pendingByOperationId[operation.id];
  operation.items.forEach((item) => {
    const rowKey = String(item?.row_key || '').trim();
    if (Number(journal.latestByRowKey[rowKey]) === Number(operation.id)) {
      delete journal.latestByRowKey[rowKey];
    }
  });
}

function mergePendingProblemExclusionRules(rules) {
  const journal = getProblemExclusionMutationJournal();
  const existingRule = (Array.isArray(rules) ? rules : [])
    .find((rule) => rule?.key === 'problem-ignores');
  const byKey = new Map(
    collectProblemIgnoreItems(existingRule).map((item) => [String(item.row_key || ''), item]),
  );
  Object.values(journal.pendingByOperationId || {})
    .sort((left, right) => Number(left.id) - Number(right.id))
    .forEach((operation) => {
      operation.items.forEach((item) => {
        const rowKey = String(item?.row_key || '').trim();
        if (!rowKey || Number(journal.latestByRowKey[rowKey]) !== Number(operation.id)) return;
        if (operation.kind === 'revert') {
          byKey.delete(rowKey);
        } else {
          byKey.set(rowKey, { ...item, pending: true });
        }
      });
    });
  return replaceProblemIgnoreRule(rules, Array.from(byKey.values()));
}

function settleProblemExclusionMutation(operation, appliedItems = []) {
  if (!operation) return false;
  const latest = isLatestProblemExclusionMutation(operation);
  if (latest && operation.kind === 'create') {
    const operationKeys = new Set(operation.items.map((item) => String(item?.row_key || '')));
    const currentRule = (state.utility.rules || []).find((rule) => rule?.key === 'problem-ignores');
    const retained = collectProblemIgnoreItems(currentRule)
      .filter((item) => !operationKeys.has(String(item?.row_key || '')));
    const authoritative = (Array.isArray(appliedItems) ? appliedItems : [])
      .map((item) => ({ ...item, pending: false }));
    state.utility.rules = replaceProblemIgnoreRule(state.utility.rules, [
      ...retained,
      ...authoritative,
    ]);
    const albumKey = String(operation?.snapshot?.album?.key || '').trim();
    if (albumKey) {
      const journal = getProblemExclusionMutationJournal();
      journal.acknowledgedCreates.push({
        id: Number(operation.id),
        albumKey,
        items: authoritative.map((item) => cloneProblemExclusionValue(item)),
      });
      journal.acknowledgedCreates = journal.acknowledgedCreates.slice(-64);
    }
  }
  removeProblemExclusionOperation(operation);
  state.utility.rules = mergePendingProblemExclusionRules(state.utility.rules);
  advanceProblemExclusionMutationRevision();
  return latest;
}

function restoreProblematicAlbumSnapshot(operation) {
  const album = operation?.snapshot?.album;
  if (!album) return;
  const albumKey = String(album.key || '');
  const items = Array.isArray(state.utility.problematicFiles)
    ? state.utility.problematicFiles.slice()
    : [];
  const currentIndex = items.findIndex((item) => String(item?.key || '') === albumKey);
  if (currentIndex >= 0) items.splice(currentIndex, 1);
  const insertionIndex = Math.min(
    Math.max(Number(operation.snapshot.albumIndex || 0), 0),
    items.length,
  );
  items.splice(insertionIndex, 0, cloneProblemExclusionValue(album));

  let projectedAlbum = items[insertionIndex];
  const journal = getProblemExclusionMutationJournal();
  const acknowledgedSuccessors = (journal.acknowledgedCreates || [])
    .filter((candidate) => (
      Number(candidate.id) > Number(operation.id)
      && String(candidate.albumKey || '') === albumKey
    ));
  const pendingSuccessors = Object.values(journal.pendingByOperationId || {})
    .filter((candidate) => (
      candidate.id !== operation.id
      && candidate.kind === 'create'
      && String(candidate?.snapshot?.album?.key || '') === albumKey
    ));
  [...acknowledgedSuccessors, ...pendingSuccessors]
    .sort((left, right) => Number(left.id) - Number(right.id))
    .forEach((candidate) => {
      if (!projectedAlbum) return;
      projectedAlbum = projectProblemExclusionFromAlbum(
        projectedAlbum,
        candidate.items,
      ).updatedAlbum;
    });
  if (projectedAlbum) items[insertionIndex] = projectedAlbum;
  else items.splice(insertionIndex, 1);
  state.utility.problematicFiles = items;
  state.utility.selectedProblematicKey = projectedAlbum
    ? String(operation.snapshot.selectedProblematicKey || '')
    : '';
}

function rollbackProblemExclusionMutation(operation) {
  if (!operation) return false;
  if (!isLatestProblemExclusionMutation(operation)) {
    removeProblemExclusionOperation(operation);
    return false;
  }
  const operationKeys = new Set(operation.items.map((item) => String(item?.row_key || '')));
  const currentRule = (state.utility.rules || []).find((rule) => rule?.key === 'problem-ignores');
  const retained = collectProblemIgnoreItems(currentRule)
    .filter((item) => !operationKeys.has(String(item?.row_key || '')));
  const priorRuleItems = Array.isArray(operation.snapshot?.ruleItems)
    ? operation.snapshot.ruleItems
    : [];
  state.utility.rules = replaceProblemIgnoreRule(state.utility.rules, [
    ...retained,
    ...priorRuleItems,
  ]);
  if (operation.kind === 'create') restoreProblematicAlbumSnapshot(operation);
  if (operation.kind === 'revert'
      && Object.prototype.hasOwnProperty.call(operation.snapshot || {}, 'loaded')) {
    state.utility.loaded = operation.snapshot.loaded;
  }
  removeProblemExclusionOperation(operation);
  state.utility.rules = mergePendingProblemExclusionRules(state.utility.rules);
  advanceProblemExclusionMutationRevision();
  return true;
}

function buildProblemExclusionItemFromAlbum(album, rowKey) {
  const key = String(rowKey || '').trim();
  const albumRow = (Array.isArray(album?.album_problem_rows) ? album.album_problem_rows : [])
    .find((row) => String(row?.row_key || '') === key);
  if (albumRow) {
    const durableAlbumKey = String(albumRow.album_key || '').trim();
    return {
      ...albumRow,
      row_key: key,
      scope: 'album',
      album_key: durableAlbumKey || String(album?.key || ''),
      artist: String(album?.album_artist || album?.raw_album_artist || ''),
      album: String(album?.name || album?.raw_name || ''),
      year: String(album?.year || ''),
      problem_reason: problemExclusionReason(albumRow),
    };
  }
  for (const row of (Array.isArray(album?.track_problem_rows) ? album.track_problem_rows : [])) {
    const reasonItem = (Array.isArray(row?.ignorable_reasons) ? row.ignorable_reasons : [])
      .find((item) => String(item?.row_key || '') === key);
    if (!reasonItem) continue;
    return {
      ...reasonItem,
      row_key: key,
      scope: 'file',
      path: String(row.path || ''),
      filename: String(row.filename || (typeof getFilenameFromPath === 'function'
        ? getFilenameFromPath(row.path)
        : '')),
      artist: String(album?.album_artist || album?.raw_album_artist || ''),
      album: String(album?.name || album?.raw_name || ''),
      year: String(album?.year || ''),
      problem_reason: problemExclusionReason(reasonItem),
    };
  }
  return null;
}

function applyOptimisticProblemExclusionCard(album, updatedAlbum) {
  const albumKey = String(album?.key || '');
  const current = Array.isArray(state.utility.problematicFiles)
    ? state.utility.problematicFiles
    : [];
  const index = current.findIndex((item) => String(item?.key || '') === albumKey);
  if (index < 0) return;
  state.utility.problematicFiles = updatedAlbum
    ? current.map((item, itemIndex) => (itemIndex === index ? updatedAlbum : item))
    : current.filter((_item, itemIndex) => itemIndex !== index);
  if (!updatedAlbum && String(state.utility.selectedProblematicKey || '') === albumKey) {
    state.utility.selectedProblematicKey = '';
  }
  state.utility.problemExclusionSelections = {};
  state.utility.pendingRepairAction = '';
  state.utility.loaded = true;
}

function scheduleProblemExclusionRequest(operation, request) {
  const keys = operation.items.map((item) => String(item?.row_key || '')).filter(Boolean);
  const predecessors = Array.from(new Set(
    keys.map((key) => problemExclusionRequestChains.get(key)).filter(Boolean),
  ));
  const completion = predecessors.length
    ? Promise.allSettled(predecessors).then(request)
    : request();
  keys.forEach((key) => problemExclusionRequestChains.set(key, completion));
  completion.finally(() => {
    keys.forEach((key) => {
      if (problemExclusionRequestChains.get(key) === completion) {
        problemExclusionRequestChains.delete(key);
      }
    });
  });
  return completion;
}

function effectiveProblemExclusionItems(album, items) {
  const selectedItems = (Array.isArray(items) ? items : []).filter(Boolean);
  const albumRows = new Map((Array.isArray(album?.album_problem_rows) ? album.album_problem_rows : [])
    .map(row => [String(row?.row_key || ''), row]));
  const coveredReasons = new Set();
  selectedItems.forEach(item => {
    const row = albumRows.get(String(item.row_key || ''));
    if (item.scope === 'album' && row
      && item.album_key === String(row.album_key || album?.key || '')) {
      const reason = problemExclusionReason(row);
      if (reason) coveredReasons.add(reason);
    }
  });
  const coveredFiles = new Map();
  (Array.isArray(album?.track_problem_rows) ? album.track_problem_rows : []).forEach(row => {
    (Array.isArray(row?.ignorable_reasons) ? row.ignorable_reasons : []).forEach(item => {
      if (coveredReasons.has(problemExclusionReason(item))) {
        coveredFiles.set(String(item.row_key || ''), String(row.path || ''));
      }
    });
  });
  // Album-label selection also highlights matching file pills. Persist the album
  // rule once: duplicate child rules would survive a later album-rule revert.
  // Independently selected reasons and unknown identities still reach validation.
  return selectedItems.filter(item => item.scope !== 'file'
    || !coveredFiles.has(String(item.row_key || ''))
    || coveredFiles.get(String(item.row_key || '')) !== item.path);
}

async function queueProblemExclusionCreate({ album, items }) {
  const selectedItems = effectiveProblemExclusionItems(album, items);
  const currentRules = state.utility.rules || [];
  const currentRule = currentRules.find((rule) => rule?.key === 'problem-ignores');
  const selectedKeys = new Set(selectedItems.map((item) => String(item?.row_key || '')));
  const albumIndex = (state.utility.problematicFiles || []).findIndex((item) => (
    String(item?.key || '') === String(album?.key || '')
  ));
  const projection = projectProblemExclusionFromAlbum(album, selectedItems);
  const operation = beginProblemExclusionMutation({
    kind: 'create',
    items: projection.optimisticRuleItems,
    snapshot: {
      album,
      albumIndex,
      selectedProblematicKey: state.utility.selectedProblematicKey,
      ruleItems: collectProblemIgnoreItems(currentRule)
        .filter((item) => selectedKeys.has(String(item?.row_key || ''))),
    },
  });
  applyOptimisticProblemExclusionCard(album, projection.updatedAlbum);
  state.utility.rules = mergePendingProblemExclusionRules(currentRules);
  renderUtilityModalContent();
  closeRepairConfirmModal();
  showToast('Problem exclusion queued.', 'success', 2400);

  return scheduleProblemExclusionRequest(operation, async () => {
    try {
      const requestItems = selectedItems.map((item) => (
        item.scope === 'album'
          ? { row_key: item.row_key, scope: 'album', album_key: item.album_key }
          : { row_key: item.row_key, scope: 'file', path: item.path }
      ));
      const response = await fetch('/utilities/rules/problem-ignores', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ items: requestItems }),
      });
      const data = await response.json().catch(() => ({}));
      if (!response.ok || !data.ok) throw new Error(data.error || 'Problem exclusion failed');
      settleProblemExclusionMutation(operation, data.applied_items || []);
      renderUtilityModalContent();
    } catch (error) {
      console.error('[AlbumHaven][Utilities] Failed to save problem exclusion.', error);
      await waitForProblematicUtilityRenderFrame();
      rollbackProblemExclusionMutation(operation);
      renderUtilityModalContent();
      showToast('Failed to save problem exclusion', 'error', 3200);
    }
  });
}

async function queueProblemExclusionRevert(item) {
  const ruleItem = cloneProblemExclusionValue(item || {});
  const operation = beginProblemExclusionMutation({
    kind: 'revert',
    items: [ruleItem],
    snapshot: {
      ruleItems: [ruleItem],
      loaded: state.utility.loaded,
    },
  });
  state.utility.rules = mergePendingProblemExclusionRules(state.utility.rules);
  renderUtilityModalContent();
  showToast('Problem exclusion revert queued.', 'success', 2400);

  return scheduleProblemExclusionRequest(operation, async () => {
    await waitForProblematicUtilityRenderFrame();
    try {
      const response = await fetch('/utilities/rules/problem-ignores/revert', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ row_key: ruleItem.row_key }),
      });
      const data = await response.json().catch(() => ({}));
      if (!response.ok || !data.ok) throw new Error(data.error || 'Problem exclusion revert failed');
      settleProblemExclusionMutation(operation);
      state.utility.problematicSummaryRequestToken = Number(
        state.utility.problematicSummaryRequestToken || 0,
      ) + 1;
      state.utility.loaded = false;
      renderUtilityModalContent();
      return true;
    } catch (error) {
      console.error('[AlbumHaven][Utilities] Failed to revert problem exclusion.', error);
      await waitForProblematicUtilityRenderFrame();
      rollbackProblemExclusionMutation(operation);
      renderUtilityModalContent();
      showToast('Failed to revert problem exclusion', 'error', 3200);
      return false;
    }
  });
}

// END js/runtime/problem-exclusion-mutations.js

// BEGIN js/runtime/library-settings.js

function librarySettingsReadOnlyClient() {
  return typeof isMobileClient === 'function' && isMobileClient();
}

const LIBRARY_SETTINGS_ROOT_CATEGORIES = Object.freeze([
  'main_library_roots',
  'hoarding_library_roots',
  'new_arrivals_roots',
]);

const LIBRARY_SETTINGS_LAYOUT_MODES = Object.freeze(['artist', 'genre/artist', 'album-at-root']);

function getDefaultLibrarySettingsState() {
  return {
    settings: null,
    draft: null,
    loaded: false,
    loading: false,
    loadPromise: null,
    saveBusy: false,
    albumRatingImportBusy: false,
    albumRatingImportResult: null,
    error: '',
    allowedActions: {},
  };
}

function ensureLibrarySettingsState() {
  if (!state.utility.librarySettings || typeof state.utility.librarySettings !== 'object') {
    state.utility.librarySettings = getDefaultLibrarySettingsState();
  }
  if (typeof state.utility.librarySettings.albumRatingImportBusy !== 'boolean') {
    state.utility.librarySettings.albumRatingImportBusy = false;
  }
  if (!Object.prototype.hasOwnProperty.call(state.utility.librarySettings, 'albumRatingImportResult')) {
    state.utility.librarySettings.albumRatingImportResult = null;
  }
  return state.utility.librarySettings;
}

function normalizeLibrarySettingsRootEntry(category, entry, index) {
  const source = entry && typeof entry === 'object' ? entry : {};
  const normalized = {
    id: String(source.id || `${category}-${index + 1}`).trim() || `${category}-${index + 1}`,
    path: String(source.path || ''),
  };
  if (category === 'main_library_roots') {
    const layoutMode = String(source.layout_mode || 'artist').trim();
    normalized.layout_mode = LIBRARY_SETTINGS_LAYOUT_MODES.includes(layoutMode)
      ? layoutMode
      : 'artist';
  }
  return normalized;
}

function normalizeLibrarySettingsPayload(raw) {
  const source = raw && typeof raw === 'object' ? raw : {};
  const normalized = {
    version: Number(source.version || 1) || 1,
    main_library_roots: [],
    hoarding_library_roots: [],
    new_arrivals_roots: [],
    move_policy: {
      preferred_main_write_root: '',
      move_new_arrivals_to: '',
    },
  };
  LIBRARY_SETTINGS_ROOT_CATEGORIES.forEach((category) => {
    const roots = Array.isArray(source[category]) ? source[category] : [];
    normalized[category] = roots.map((entry, index) => normalizeLibrarySettingsRootEntry(category, entry, index));
  });
  const movePolicy = source.move_policy && typeof source.move_policy === 'object' ? source.move_policy : {};
  normalized.move_policy.preferred_main_write_root = String(movePolicy.preferred_main_write_root || '').trim();
  normalized.move_policy.move_new_arrivals_to = String(movePolicy.move_new_arrivals_to || '').trim();
  return normalized;
}

function cloneLibrarySettingsDraft(settings) {
  return normalizeLibrarySettingsPayload(cloneRuntimeJson(settings, {}));
}

function serializeLibrarySettingsDraft(draft) {
  const payload = normalizeLibrarySettingsPayload(draft);
  LIBRARY_SETTINGS_ROOT_CATEGORIES.forEach(category => {
    const blankIds = new Set();
    payload[category] = payload[category].filter(root => {
      if (root.path.trim()) return true;
      blankIds.add(root.id);
      return false;
    });
    const policyKey = category === 'main_library_roots' ? 'preferred_main_write_root' : category === 'hoarding_library_roots' ? 'move_new_arrivals_to' : '';
    if (policyKey && blankIds.has(payload.move_policy[policyKey])) payload.move_policy[policyKey] = '';
  });
  return payload;
}

function countConfiguredLibraryRoots(settings) {
  const normalized = normalizeLibrarySettingsPayload(settings);
  return LIBRARY_SETTINGS_ROOT_CATEGORIES.reduce(
    (total, category) => total + normalized[category].filter((root) => String(root.path || '').trim()).length,
    0,
  );
}

function buildUtilityLibraryIntegrationItem() {
  const librarySettingsState = ensureLibrarySettingsState();
  const configuredRoots = countConfiguredLibraryRoots(librarySettingsState.settings || librarySettingsState.draft || {});
  let statusLabel = 'Configure library roots';
  if (librarySettingsState.loading) {
    statusLabel = 'Loading settings';
  } else if (librarySettingsState.loaded) {
    statusLabel = configuredRoots === 1
      ? '1 root configured'
      : `${configuredRoots} roots configured`;
  }
  return {
    key: 'library',
    title: 'Library',
    description: 'Configure Main Library, Hoard, and New Arrivals roots.',
    status_label: statusLabel,
  };
}

function buildUtilityIntegrationItems() {
  const allows = action => window.AlbumHavenCapabilities?.allows(action) === true;
  const foobarAllowed = allows('account.self.foobar.write');
  const integrations = allows('integration.settings.read')
    ? (Array.isArray(state.utility.integrations) ? state.utility.integrations : [])
      .filter(item => item.key !== 'foobar' || foobarAllowed)
      .map(item => item.key === 'lastfm' ? {...item, title: 'Scrobbling'} : item)
    : [];
  // This is navigation only. Server-owned capabilities decide availability.
  if (foobarAllowed && !integrations.some(item => item.key === 'foobar')) integrations.push({key:'foobar',title:'Foobar2000'});
  return [...(allows('library.settings.read') ? [buildUtilityLibraryIntegrationItem()] : []), ...integrations];
}

async function handleLibrarySettingsIntegrationSelection(integrationKey) {
  if (String(integrationKey || '') !== 'library') return false;
  state.utility.selectedIntegrationKey = 'library';
  await loadUtilityLibrarySettings(!state.utility.librarySettings?.loaded);
  return true;
}

function getLibrarySettingsDraft() {
  const librarySettingsState = ensureLibrarySettingsState();
  if (!librarySettingsState.draft) {
    librarySettingsState.draft = cloneLibrarySettingsDraft(librarySettingsState.settings || {});
  }
  LIBRARY_SETTINGS_ROOT_CATEGORIES.forEach(category => {
    if (!librarySettingsState.draft[category]?.length) librarySettingsState.draft[category] = [normalizeLibrarySettingsRootEntry(category, {}, 0)];
  });
  return librarySettingsState.draft;
}

function buildEmptyLibraryRootDraft(category) {
  const draft = getLibrarySettingsDraft();
  const roots = Array.isArray(draft[category]) ? draft[category] : [];
  let nextIndex = roots.length + 1;
  while (roots.some(root => root.id === `${category}-${nextIndex}`)) nextIndex += 1;
  return normalizeLibrarySettingsRootEntry(category, { id: `${category}-${nextIndex}` }, nextIndex - 1);
}

function addLibraryRootDraftEntry(category) {
  const draft = getLibrarySettingsDraft();
  draft[category] = [...(Array.isArray(draft[category]) ? draft[category] : []), buildEmptyLibraryRootDraft(category)];
  renderUtilityModalContent();
}

function removeLibraryRootDraftEntry(category, index) {
  const draft = getLibrarySettingsDraft();
  const roots = Array.isArray(draft[category]) ? draft[category] : [];
  const removed = roots[index];
  draft[category] = roots.filter((_, itemIndex) => itemIndex !== index);
  if (!draft[category].length) draft[category].push(normalizeLibrarySettingsRootEntry(category, {}, 0));
  if (removed?.id) {
    if (category === 'main_library_roots' && draft.move_policy.preferred_main_write_root === removed.id) {
      draft.move_policy.preferred_main_write_root = '';
    }
    if (category === 'hoarding_library_roots' && draft.move_policy.move_new_arrivals_to === removed.id) {
      draft.move_policy.move_new_arrivals_to = '';
    }
  }
  renderUtilityModalContent();
}

function updateLibraryRootDraftField(category, index, field, value) {
  const draft = getLibrarySettingsDraft();
  const roots = Array.isArray(draft[category]) ? draft[category] : [];
  if (!roots[index]) return;
  roots[index] = {
    ...roots[index],
    [field]: String(value || ''),
  };
}

function updateLibrarySettingsDraftField(field, value) {
  const draft = getLibrarySettingsDraft();
  draft.move_policy = {
    ...(draft.move_policy || {}),
    [field]: String(value || ''),
  };
}

function applyLibrarySettingsRootFieldTarget(target) {
  if (!target) return false;
  updateLibraryRootDraftField(
    target.getAttribute('data-library-root-list') || '',
    Number(target.getAttribute('data-library-root-index') || -1),
    target.getAttribute('data-library-root-field') || '',
    target.value,
  );
  return true;
}

function applyLibrarySettingsFieldTarget(target) {
  if (!target) return false;
  updateLibrarySettingsDraftField(
    target.getAttribute('data-library-settings-field') || '',
    target.value,
  );
  return true;
}

function handleLibrarySettingsClick(event) {
  if (librarySettingsReadOnlyClient() && event.target.closest('[data-add-library-root], [data-remove-library-root], [data-browse-library-root], [data-library-policy-trigger], [id^="library-auto-move-"], [data-save-library-settings], [data-import-album-ratings]')) { event.preventDefault(); return true; }
  const toggle = event.target.closest('[id^="library-auto-move-"]');
  if (toggle) {
    event.preventDefault();
    const owner = ensureLibrarySettingsState();
    if (owner.allowedActions?.['library.settings.manage'] !== true || toggle.disabled) return true;
    const field = toggle.id === 'library-auto-move-main' ? 'preferred_main_write_root' : toggle.id === 'library-auto-move-hoard' ? 'move_new_arrivals_to' : '';
    if (!field) return false;
    owner.moveAutomationDraft ||= {};
    owner.moveAutomationDraft[field] = !owner.moveAutomationDraft[field];
    renderUtilityModalContent();
    document.getElementById?.(toggle.id)?.focus({ preventScroll: true });
    return true;
  }
  const policy = event.target.closest('[data-library-policy-trigger]');
  if (policy) {
    event.preventDefault();
    if (ensureLibrarySettingsState().allowedActions?.['library.settings.manage'] !== true) return true;
    const field = policy.getAttribute('data-library-policy-trigger');
    const category = field === 'preferred_main_write_root' ? 'main_library_roots' : field === 'move_new_arrivals_to' ? 'hoarding_library_roots' : '';
    if (!category) return true;
    const draft = getLibrarySettingsDraft();
    openUtilityChoiceDropdown(policy, {
      matchTriggerWidth: true,
      formats: buildLibrarySettingsRootOptions(draft[category]),
      selected: draft.move_policy[field] || buildLibrarySettingsRootOptions(draft[category])[0]?.value, label: field === 'preferred_main_write_root' ? 'Library destination' : 'Move to Hoard',
      onSelect: value => {
        if (ensureLibrarySettingsState().allowedActions?.['library.settings.manage'] !== true) return false;
        updateLibrarySettingsDraftField(field, value);
      },
    });
    return true;
  }
  const browse = event.target.closest('[data-browse-library-root]');
  if (browse) { event.preventDefault(); browseLibraryRootDraft(browse.getAttribute('data-browse-library-root'), Number(browse.getAttribute('data-library-root-index'))); return true; }
  const foobarHelp = event.target.closest('[data-foobar-help]');
  if (foobarHelp) { event.preventDefault(); openUtilityFoobarGuide(); return true; }
  const foobarFormat = event.target.closest('[data-foobar-format-trigger]');
  if (foobarFormat) { event.preventDefault(); openUtilityFoobarFormats(foobarFormat); return true; }
  const addLibraryRootButton = event.target.closest('[data-add-library-root]');
  if (addLibraryRootButton) {
    event.preventDefault();
    addLibraryRootDraftEntry(addLibraryRootButton.getAttribute('data-add-library-root') || '');
    return true;
  }

  const removeLibraryRootButton = event.target.closest('[data-remove-library-root]');
  if (removeLibraryRootButton) {
    event.preventDefault();
    removeLibraryRootDraftEntry(
      removeLibraryRootButton.getAttribute('data-remove-library-root') || '',
      Number(removeLibraryRootButton.getAttribute('data-library-root-index') || -1),
    );
    return true;
  }

  const reloadLibrarySettingsButton = event.target.closest('[data-reload-library-settings="1"]');
  if (reloadLibrarySettingsButton) {
    event.preventDefault();
    loadUtilityLibrarySettings(true);
    return true;
  }

  const importAlbumRatingsButton = event.target.closest('[data-import-album-ratings="1"]');
  if (importAlbumRatingsButton) {
    event.preventDefault();
    importAlbumRatingsFromFileTags();
    return true;
  }

  const saveLibrarySettingsButton = event.target.closest('[data-save-library-settings="1"]');
  if (saveLibrarySettingsButton) {
    event.preventDefault();
    saveUtilityLibrarySettings();
    return true;
  }

  return false;
}

async function importAlbumRatingsFromFileTags() {
  const librarySettingsState = ensureLibrarySettingsState();
  if (librarySettingsState.albumRatingImportBusy) return false;
  librarySettingsState.albumRatingImportBusy = true;
  librarySettingsState.albumRatingImportResult = null;
  librarySettingsState.error = '';
  renderUtilityModalContent();
  try {
    const response = await fetch('/library-settings/import-album-ratings', {
      method: 'POST',
      headers: { Accept: 'application/json' },
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok || !data.ok) {
      throw new Error(data.error || 'Unable to import album ratings.');
    }
    librarySettingsState.albumRatingImportResult = {
      created: Number(data.created || 0),
      authority_skipped: Number(data.authority_skipped || 0),
      failed: Number(data.failed || 0),
    };
    if (librarySettingsState.albumRatingImportResult.created > 0) {
      try {
        await fetchAndRender(buildApiUrl(state.view), false, { preserveScroll: true });
      } catch (refreshError) {
        console.warn('[AlbumHaven][LibrarySettings] Ratings imported, but failed to refresh the view.', refreshError);
        showToast('Album ratings were imported, but the current view could not be refreshed.', 'warning', 3600);
      }
    }
    renderUtilityModalContent();
    return true;
  } catch (error) {
    console.error('[AlbumHaven][LibrarySettings] Failed to import album ratings.', error);
    librarySettingsState.error = error.message || 'Unable to import album ratings.';
    showToast(librarySettingsState.error, 'error', 3600);
    renderUtilityModalContent();
    return false;
  } finally {
    librarySettingsState.albumRatingImportBusy = false;
    renderUtilityModalContent();
  }
}

function handleLibrarySettingsInput(event) {
  const libraryRootInput = event.target.closest('[data-library-root-field]');
  if (applyLibrarySettingsRootFieldTarget(libraryRootInput)) {
    return true;
  }
  const librarySettingsInput = event.target.closest('[data-library-settings-field]');
  if (applyLibrarySettingsFieldTarget(librarySettingsInput)) {
    return true;
  }
  return false;
}

function handleLibrarySettingsChange(event) {
  const libraryRootSelect = event.target.closest('select[data-library-root-field]');
  if (applyLibrarySettingsRootFieldTarget(libraryRootSelect)) {
    return true;
  }
  const librarySettingsSelect = event.target.closest('select[data-library-settings-field]');
  if (applyLibrarySettingsFieldTarget(librarySettingsSelect)) {
    return true;
  }
  return false;
}

async function loadUtilityLibrarySettings(force = false) {
  const owner = state.utility;
  const librarySettingsState = ensureLibrarySettingsState();
  const ownsPresentation = () => state.utility === owner && owner.librarySettings === librarySettingsState
    && owner.activeTab === 'integrations' && owner.selectedIntegrationKey === 'library'
    && !getUtilityModalElements()?.overlay?.hidden;
  const renderCurrent = () => { if (ownsPresentation()) renderUtilityModalContent(); };
  if (librarySettingsState.loading) {
    renderCurrent();
    return librarySettingsState.loadPromise;
  }
  if (librarySettingsState.loaded && !force) {
    renderCurrent();
    return librarySettingsState.settings;
  }
  librarySettingsState.loading = true;
  librarySettingsState.error = '';
  renderCurrent();
  librarySettingsState.loadPromise = (async () => {
    try {
      const response = await fetch('/library-settings', { headers: { Accept: 'application/json' } });
      const data = await response.json().catch(() => ({}));
      if (!response.ok || !data.ok) {
        throw new Error(data.error || 'Unable to load library settings');
      }
      librarySettingsState.allowedActions = data.allowed_actions || {};
      librarySettingsState.settings = normalizeLibrarySettingsPayload(data.settings);
      librarySettingsState.draft = cloneLibrarySettingsDraft(librarySettingsState.settings);
      librarySettingsState.loaded = true;
      return librarySettingsState.settings;
    } catch (error) {
      console.error('[AlbumHaven][LibrarySettings] Failed to load library settings.', error);
      librarySettingsState.error = error.message || 'Unable to load library settings.';
      if (ownsPresentation()) showToast(librarySettingsState.error, 'error', 3200);
      return null;
    } finally {
      librarySettingsState.loading = false;
      librarySettingsState.loadPromise = null;
      renderCurrent();
    }
  })();
  return librarySettingsState.loadPromise;
}

async function saveUtilityLibrarySettings() {
  const owner = state.utility;
  const librarySettingsState = ensureLibrarySettingsState();
  const ownsContext = () => state.utility === owner && owner.librarySettings === librarySettingsState;
  const ownsPresentation = () => ownsContext() && owner.activeTab === 'integrations'
    && owner.selectedIntegrationKey === 'library' && !getUtilityModalElements()?.overlay?.hidden;
  const renderCurrent = () => { if (ownsPresentation()) renderUtilityModalContent(); };
  if (librarySettingsState.saveBusy || librarySettingsState.allowedActions?.['library.settings.manage'] !== true) return false;
  const statusAction = claimLibraryStatusAction(true);
  librarySettingsState.saveBusy = true;
  librarySettingsState.error = '';
  renderCurrent();
  try {
    const response = await fetch('/library-settings', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ settings: serializeLibrarySettingsDraft(getLibrarySettingsDraft()) }),
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok || !data.ok) throw new Error(data.error || 'Unable to save library settings');
    librarySettingsState.settings = normalizeLibrarySettingsPayload(data.settings);
    librarySettingsState.draft = cloneLibrarySettingsDraft(librarySettingsState.settings);
    librarySettingsState.loaded = true;
    owner.loaded = false;
    owner.problematicFiles = [];
    const ownsStatus = settleLibraryStatusAction(statusAction);
    if (ownsContext() && ownsStatus) {
      if (data.status) {
        updateStatusIndicator(data.status);
        state.wasPollingBusy = Boolean(data.status.scan_in_progress || data.status.relations_in_progress);
        state.wasCoverPollingBusy = Boolean(data.status.covers_in_progress);
        renderLibraryLoader(state.status);
      }
      scheduleStatusPoll(250);
    }
    if (ownsPresentation()) showToast('Library settings saved. Scan started.', 'success', 3200);
    return true;
  } catch (error) {
    settleLibraryStatusAction(statusAction);
    console.error('[AlbumHaven][LibrarySettings] Failed to save library settings.', error);
    librarySettingsState.error = error.message || 'Unable to save library settings.';
    if (ownsPresentation()) showToast(librarySettingsState.error, 'error', 3600);
    return false;
  } finally {
    librarySettingsState.saveBusy = false;
    renderCurrent();
  }
}

function buildLibrarySettingsRootOptions(roots, placeholder) {
  return [...(placeholder ? [{ value: '', label: placeholder }] : []), ...(Array.isArray(roots) ? roots : [])
    .filter(root => String(root?.path || '').trim())
    .map(root => ({ value: String(root.id), label: String(root.path).trim() }))];
}

function buildLibrarySettingsPolicyButton(field, roots, selectedId, label) {
  const choices = buildLibrarySettingsRootOptions(roots);
  if (choices.length <= 1) return `<span data-library-policy-value="${field}">${escapeHtml(choices[0]?.label || 'No library path configured')}</span>`;
  const selectedLabel = choices.find(choice => choice.value === selectedId)?.label || choices[0]?.label;
  return window.ButtonComponent.renderButton({
    label: selectedLabel,
    ariaLabel: label, disabled: librarySettingsReadOnlyClient() || ensureLibrarySettingsState().allowedActions?.['library.settings.manage'] !== true,
    attributes: { 'data-library-policy-trigger': field, 'aria-haspopup': 'menu', 'aria-expanded': 'false' },
  });
}

function buildLibraryMovePolicyRow(field, roots, selectedId, title, destinationLabel, key) {
  const owner = ensureLibrarySettingsState();
  const enabled = owner.moveAutomationDraft?.[field] === true;
  const hasRoots = buildLibrarySettingsRootOptions(roots).length > 0;
  return `<div class="library-settings-move-policy-row">
    ${buildGallerySwitchHtml({ id: `library-auto-move-${key}`, label: title, checked: enabled, disabled: librarySettingsReadOnlyClient() || !hasRoots || owner.allowedActions?.['library.settings.manage'] !== true })}
    ${enabled && hasRoots ? buildLibrarySettingsPolicyButton(field, roots, selectedId, destinationLabel) : ''}
  </div>`;
}

function buildLibrarySettingsRootSection(category, title, description) {
  const draft = getLibrarySettingsDraft();
  const roots = Array.isArray(draft[category]) ? draft[category] : [];
  const canManage = !librarySettingsReadOnlyClient() && ensureLibrarySettingsState().allowedActions?.['library.settings.manage'] === true;
  const canBrowse = canManage && ensureLibrarySettingsState().allowedActions?.['library.filesystem.browse'] === true && ensureLibrarySettingsState().allowedActions?.['library.paths.read'] === true;
  const rows = roots.map((root, index) => `<div class="library-settings-root-row">
    <div class="library-settings-path-control ui-input-action"><input type="text" value="${escapeHtml(root.path || '')}"
      aria-label="${escapeHtml(title)} path ${index + 1}" placeholder="${escapeHtml(title)} folder"
      data-library-root-field="path" data-library-root-list="${escapeHtml(category)}" data-library-root-index="${index}" ${canManage ? '' : 'disabled'}>
      ${window.ButtonComponent.renderActionButton({ariaLabel: `Choose ${title} folder ${index + 1}`, iconClass: 'album-details-header__action-icon album-details-header__action-icon--folder', disabled: !canBrowse,
        attributes: {'data-browse-library-root': category, 'data-library-root-index': index}})}
      ${window.ButtonComponent.renderActionButton({ariaLabel: `Remove ${title} path ${index + 1}`, icon: 'delete', semantic: 'destructive', disabled: !canManage,
        attributes: {'data-remove-library-root': category, 'data-library-root-index': index}})}</div>
    </div>`).join('');

  return `
    <section class="library-settings-section">
      <div class="library-settings-section-heading">
        <div>
          <h4>${escapeHtml(title)}</h4>
          <p>${escapeHtml(description)}</p>
        </div>
        ${window.ButtonComponent.renderButton({label: 'Add path', disabled: !canManage, attributes: {'data-add-library-root': category}})}
      </div>
      <div class="library-settings-root-list">${rows}</div>
    </section>
  `;
}

function buildUtilityLibrarySettingsDetail() {
  const librarySettingsState = ensureLibrarySettingsState();
  if (!librarySettingsState.loaded && !librarySettingsState.error) {
    return '<div class="utility-empty-state">Loading library settings...</div>';
  }
  if (!librarySettingsState.loaded && librarySettingsState.error) {
    return `
      <div class="utility-rule-detail">
        <h3 class="utility-rule-title">Library</h3>
        ${buildOnPageAlertHtml({ severity: 'error', title: 'Library settings unavailable', message: librarySettingsState.error,
          actionsHtml: ButtonComponent.renderButton({ label: 'Retry', attributes: { 'data-reload-library-settings': '1' } }) })}
      </div>
    `;
  }

  const draft = getLibrarySettingsDraft();
  const movePolicy = draft.move_policy || {};
  const importResult = librarySettingsState.albumRatingImportResult;
  return `
    <div class="utility-rule-detail">
      <h3 class="utility-rule-title">Library</h3>
      ${librarySettingsState.error ? buildOnPageAlertHtml({ severity: 'error', title: 'Library settings could not be updated', message: librarySettingsState.error }) : ''}
      ${buildLibrarySettingsRootSection('main_library_roots', 'Main Library', '')}
      ${buildLibrarySettingsRootSection('hoarding_library_roots', 'Hoard', 'Unlistened music.')}
      ${buildLibrarySettingsRootSection('new_arrivals_roots', 'New Arrivals', 'Folders watched for new music.')}
      <section class="library-settings-section">
        <div class="library-settings-section-heading">
          <div>
            <h4>Move policy</h4>
            <p>Choose where albums are moved into your libraries.</p>
          </div>
        </div>
        <div class="library-settings-policy-grid">
          ${buildLibraryMovePolicyRow('preferred_main_write_root', draft.main_library_roots, movePolicy.preferred_main_write_root, 'Auto Move rated albums to Main library', 'Library destination', 'main')}
          ${buildLibraryMovePolicyRow('move_new_arrivals_to', draft.hoarding_library_roots, movePolicy.move_new_arrivals_to, 'Move New Arrivals to Hoard', 'Move to Hoard', 'hoard')}
        </div>
      </section>
      <section class="library-settings-section">
        <div class="library-settings-section-heading">
          <div>
            <h4>Album ratings</h4>
            <p>Copy file-tag ratings into albums that do not already have an app rating. Existing app ratings remain unchanged.</p>
          </div>
          <button class="button button-secondary" type="button" data-import-album-ratings="1" ${librarySettingsReadOnlyClient() || librarySettingsState.albumRatingImportBusy ? 'disabled' : ''}>${librarySettingsState.albumRatingImportBusy ? 'Importing ratings...' : 'Import ratings'}</button>
        </div>
        ${importResult ? `<div class="library-settings-import-result" data-album-rating-import-result="1">Created: ${escapeHtml(importResult.created)} \u00b7 Authority skipped: ${escapeHtml(importResult.authority_skipped)} \u00b7 Failed: ${escapeHtml(importResult.failed)}</div>` : ''}
      </section>
      <div class="confirm-modal-actions">
        <button class="button button-secondary" type="button" data-reload-library-settings="1" ${librarySettingsState.saveBusy ? 'disabled' : ''}>Refresh</button>
        <button class="button ui-button ui-button--primary ui-button--medium" type="button" data-save-library-settings="1" ${librarySettingsReadOnlyClient() || librarySettingsState.saveBusy || librarySettingsState.allowedActions?.['library.settings.manage'] !== true ? 'disabled' : ''}>${librarySettingsState.saveBusy ? 'Saving...' : 'Save library settings'}</button>
      </div>
    </div>
  `;
}


async function browseLibraryRootDraft(category, index) {
  const utility = state.utility, owner = ensureLibrarySettingsState();
  const activeTab = utility.activeTab, selectedKey = utility.selectedIntegrationKey;
  const current = () => state.utility === utility && utility.librarySettings === owner && utility.activeTab === activeTab && utility.selectedIntegrationKey === selectedKey && (typeof document === 'undefined' || !document.getElementById?.('utility-modal')?.hidden);
  if (!LIBRARY_SETTINGS_ROOT_CATEGORIES.includes(category) || owner.allowedActions?.['library.settings.manage'] !== true
      || owner.allowedActions?.['library.filesystem.browse'] !== true || owner.allowedActions?.['library.paths.read'] !== true) return false;
  const root = getLibrarySettingsDraft()[category]?.[index];
  if (!root) return false;
  let selected = '', disposed = false, generation = 0, navigating = false;
  const read = async path => {
    const response = await fetch(`/library-settings/browse?path=${encodeURIComponent(path)}`, {headers: {Accept: 'application/json'}});
    const data = await response.json();
    if (!response.ok || !data.ok) throw new Error(data.error || 'Unable to browse folders.');
    return data;
  };
  try {
    const initial = await read('');
    if (!current() || ensureLibrarySettingsState() !== owner) return false;
    const render = data => `<p>${escapeHtml(data.path || 'Choose a configured location')}</p><div class="settings-folder-list">${data.parent_path ? window.ButtonComponent.renderButton({label: 'Parent folder', attributes: {'data-folder-path': data.parent_path}}) : ''}${(data.entries || []).map(entry => window.ButtonComponent.renderButton({label: entry.name, attributes: {'data-folder-path': entry.path}})).join('')}</div>`;
    const result = await showAppFormDialog({ title: 'Choose library folder', contentHtml: render(initial), submitLabel: 'Choose folder', submitEnabled: false,
      onMount: (content, dialog) => {
        const syncNavigation = () => {
          content.setAttribute?.('aria-busy', String(navigating));
          dialog?.setSubmitEnabled(Boolean(selected) && !navigating);
        };
        const navigate = async event => {
          const button = event.target.closest('[data-folder-path]'); if (!button) return;
          event.preventDefault(); const requestGeneration = ++generation;
          selected = ''; navigating = true; syncNavigation();
          try { const data = await read(button.getAttribute('data-folder-path'));
            if (disposed || requestGeneration !== generation || !current()) return;
            selected = String(data.path || ''); content.innerHTML = render(data);
          } catch (error) { if (!disposed && requestGeneration === generation && current()) showToast(error.message, 'error'); }
          finally { if (!disposed && requestGeneration === generation && current()) { navigating = false; syncNavigation(); } }
        };
        content.addEventListener('click', navigate); owner.pickerCleanup = () => content.removeEventListener('click', navigate);
      },
      onClose: () => { disposed = true; owner.pickerCleanup?.(); delete owner.pickerCleanup; },
      onSubmit: () => { if (navigating) throw new Error('Wait for the folder to finish loading.'); if (!selected) throw new Error('Choose a folder first.'); return selected; },
    });
    if (!result || !current() || ensureLibrarySettingsState() !== owner || getLibrarySettingsDraft()[category]?.[index] !== root) return false;
    root.path = result; renderUtilityModalContent(); return true;
  } catch (error) { if (current()) showToast(error.message || 'Folder picker unavailable.', 'error'); return false; }
}


async function openUtilityFoobarGuide() {
  const utility = state.utility, activeTab = state.utility.activeTab, selectedKey = state.utility.selectedIntegrationKey;
  try {
    const response = await fetch('/utilities/integrations/foobar/help', {headers: {Accept: 'application/json'}});
    const data = await response.json();
    if (!response.ok || !data.ok) throw new Error(data.error || 'Unable to load setup instructions.');
    if (state.utility !== utility || utility.activeTab !== activeTab || utility.selectedIntegrationKey !== selectedKey || (typeof document !== 'undefined' && document.getElementById?.('utility-modal')?.hidden)) return false;
    const sections = (data.sections || []).map(section => `<section><h4>${escapeHtml(section.title)}</h4><div class="settings-guide-copy">${formatUtilityGuideMarkdown(section.body_markdown)}</div></section>`).join('');
    const references = (data.reference_assets || []).filter(asset => String(asset.view_url || '').startsWith('/utilities/integrations/foobar/assets/'))
      .map(asset => `<li><a href="${escapeHtml(asset.view_url)}" target="_blank" rel="noreferrer">${escapeHtml(asset.title)}</a></li>`).join('');
    return await showAppFormDialog({title: 'Foobar2000 setup instructions', mode: 'reading',
      contentHtml: `<article class="settings-reading-guide" tabindex="0" aria-label="Foobar2000 setup instructions">${sections}${references ? `<h4>Reference files</h4><ul>${references}</ul>` : ''}</article>`});
  } catch (error) { if (state.utility === utility) showToast(error.message || 'Unable to load setup instructions.', 'error'); return false; }
}

let utilityFoobarFormatCleanup = null;
