const problematicNavigationRowContent = new WeakMap();

let problematicFilesVirtualList = null;

function disposeProblematicFilesVirtualList() {
  problematicFilesVirtualList?.dispose?.();
  problematicFilesVirtualList = null;
}

function renderProblematicFiles({ preserveProblematicTree = false } = {}) {
  const els = getUtilityModalElements();
  if (!els.overlay || !els.list || !els.detail || !els.count) return;
  bindProblematicFocusUserInput(els);

  const priorListScrollTop = Number(els.list.scrollTop);
  const replaceListContents = (html) => {
    disposeProblematicFilesVirtualList();
    const retainedScrollGeometry = els.list.querySelector?.('[data-problematic-scroll-retainer]') || null;
    els.list.innerHTML = html;
    if (retainedScrollGeometry && typeof els.list.appendChild === 'function') {
      els.list.appendChild(retainedScrollGeometry);
    }
    if (Number.isFinite(priorListScrollTop) && priorListScrollTop > 0) {
      els.list.scrollTop = priorListScrollTop;
    }
  };

  const mobileIndex = typeof usesMobilePageLayout === 'function' && usesMobilePageLayout();
  if (mobileIndex) disposeProblematicFilesVirtualList();
  const virtualListApi = mobileIndex ? null : typeof window !== 'undefined'
    ? window.ProblematicFilesVirtualList
    : globalThis.ProblematicFilesVirtualList;
  const mountedRows = preserveProblematicTree && !virtualListApi?.create
    ? Array.from(els.list.querySelectorAll?.('[data-problematic-album-key]') || []) : [];
  const albumsByKey = new Map((state.utility.problematicFiles || []).map(album => [String(album.key), album]));
  const mountedItems = mountedRows.map(row => albumsByKey.get(row.getAttribute('data-problematic-album-key')));
  const retainTree = mountedRows.length > 0 && mountedItems.every(Boolean);
  const items = retainTree ? mountedItems : getFilteredProblematicAlbums();
  const renderTree = selectedKey => {
    if (!problematicFilesVirtualList && virtualListApi?.create) {
      problematicFilesVirtualList = virtualListApi.create({
        list: els.list,
        renderRow: (album, selected) => buildProblematicAlbumListItem(album, selected),
      });
    }
    if (problematicFilesVirtualList) {
      problematicFilesVirtualList.render(items, selectedKey);
    } else if (!retainTree) {
      replaceListContents(items.map(album => buildProblematicAlbumListItem(album, album.key === selectedKey)).join(''));
    }
    Array.from(els.list.querySelectorAll?.('[data-problematic-album-key]') || []).forEach(row => {
      const album = albumsByKey.get(row.getAttribute('data-problematic-album-key'));
      if (!album) return;
      const selected = album.key === selectedKey;
      const content = getProblematicAlbumNavigationOptions(album, selected);
      if (retainTree || problematicFilesVirtualList) {
        const previous = problematicNavigationRowContent.get(row);
        window.NavigationTree.updateItem(row, {
          ...content,
          artworkHtml: previous && previous.artworkSource === content.artworkSource ? undefined : content.artworkHtml,
        });
        window.NavigationTree.setItemSelected(row, selected);
      }
      problematicNavigationRowContent.set(row, content);
    });
  };
  if (els.sidebarLabel) els.sidebarLabel.textContent = 'Albums';
  els.count.textContent = String(items.length);
  if (els.search) {
    els.search.disabled = false;
    els.search.placeholder = 'Filter artist, album, or track';
    els.search.value = state.utility.searchQuery || '';
  }
  if (els.problemFilterButton) {
    els.problemFilterButton.disabled = false;
    els.problemFilterButton.hidden = false;
  }
  renderProblemFilterControls(els);

  const mutation = state.utility.problematicMutation;
  if (
    mutation
    && String(mutation.albumKey || '') === String(state.utility.selectedProblematicKey || '')
  ) {
    els.detail.setAttribute?.('aria-busy', 'true');
    mountProblematicMutationOverlay(els.detail);
    if (Number.isFinite(Number(mutation.priorScrollTop))) {
      els.list.scrollTop = Number(mutation.priorScrollTop);
    }
    return;
  }
  els.detail.removeAttribute?.('aria-busy');
  els.detail.removeAttribute?.('inert');

  if (state.utility.loading && !state.utility.loaded) {
    replaceListContents('<div class="utility-empty-state compact">Loading...</div>');
    els.detail.innerHTML = '<div class="utility-empty-state">Loading problematic albums...</div>';
    return;
  }

  if (!items.length) {
    replaceListContents('<div class="utility-empty-state compact">No matching problematic albums found.</div>');
    els.detail.innerHTML = '<div class="utility-empty-state">No matching problematic albums found.</div>';
    return;
  }

  const mobilePage = mobileIndex ? mobilePageState.pages.at(-1) : null;
  if (mobileIndex && (mobilePage?.tab !== 'problematic-files' || !mobilePage.utilityDetail)) {
    renderTree('');
    els.detail.innerHTML = '';
    return;
  }

  const selectedProblematicMissing = !state.utility.selectedProblematicKey
    || !items.some((item) => item.key === state.utility.selectedProblematicKey);
  if (selectedProblematicMissing && state.utility.deferProblematicAutoSelection && (state.utility.selectedProblemFilters || []).length) {
    renderTree('');
    els.detail.innerHTML = '<div class="utility-empty-state">Select an album to inspect its problematic tags.</div>';
    return;
  }

  if (selectedProblematicMissing) {
    const focusedTrackPath = String(state.utility.focusedTrackPath || '');
    const focusedAlbum = focusedTrackPath
      ? items.find((item) => (
        (Array.isArray(item?.problematic_track_paths)
          && item.problematic_track_paths.includes(focusedTrackPath))
        || (Array.isArray(item?.track_paths) && item.track_paths.includes(focusedTrackPath))
      )) || null
      : null;
    const priorKeys = Array.isArray(state.utility.problematicMutation?.priorKeys)
      ? state.utility.problematicMutation.priorKeys
      : [];
    const previousIndex = priorKeys.indexOf(state.utility.selectedProblematicKey);
    const priorSurvivor = previousIndex > 0
      ? priorKeys.slice(0, previousIndex).reverse().find((key) => items.some((item) => item.key === key))
      : '';
    state.utility.selectedProblematicKey = focusedAlbum?.key || priorSurvivor || items[0].key;
    state.utility.deferProblematicAutoSelection = false;
    state.utility.showRepairedDisplay = true;
  }

  const selectedAlbum = getSelectedProblematicAlbumFrom(items);
  renderTree(state.utility.selectedProblematicKey);
  if (selectedAlbum?.detail_load_failed) {
    els.detail.innerHTML = buildOnPageAlertHtml({ severity: 'error', title: 'Album details unavailable', message: 'Unable to load the selected problematic album.' });
    return;
  }
  if (!selectedAlbum?.detail_loaded) {
    els.detail.innerHTML = '<div class="utility-empty-state">Loading selected problematic album...</div>';
    if (!selectedAlbum?.detail_loading_deferred) {
      void loadProblematicAlbumDetail(selectedAlbum?.key || '');
    }
    return;
  }
  initializeRepairSelections(selectedAlbum);
  els.detail.innerHTML = buildProblematicAlbumDetail(selectedAlbum);
  if (state.utility.focusedTrackPath) {
    const focusedTrackPath = String(state.utility.focusedTrackPath);
    const scrollFocusedRowsIntoView = () => {
      let albumGeometryReady = false;
      const activeAlbumRow = els.list.querySelector?.('.utility-list-item.is-active');
      activeAlbumRow?.scrollIntoView?.({ block: 'nearest' });
      if (activeAlbumRow?.getBoundingClientRect && els.list.getBoundingClientRect) {
        const listRect = els.list.getBoundingClientRect();
        const activeAlbumRect = activeAlbumRow.getBoundingClientRect();
        albumGeometryReady = listRect.bottom > listRect.top
          && activeAlbumRect.bottom > activeAlbumRect.top;
        if (activeAlbumRect.bottom > listRect.bottom) {
          els.list.scrollTop += Math.ceil(activeAlbumRect.bottom - listRect.bottom);
        } else if (activeAlbumRect.top < listRect.top) {
          els.list.scrollTop -= Math.ceil(listRect.top - activeAlbumRect.top);
        }
      }
      const focusedTrackSelector = `[data-problematic-track-path="${cssEscape(focusedTrackPath)}"]`;
      const focusedTrackMatch = els.detail.querySelector?.(focusedTrackSelector);
      const focusedTrackRow = focusedTrackMatch?.closest?.('[role="row"]') || focusedTrackMatch;
      let trackGeometryReady = false;
      if (focusedTrackRow?.getBoundingClientRect && els.detail.getBoundingClientRect) {
        const detailRect = els.detail.getBoundingClientRect();
        const focusedTrackRect = focusedTrackRow.getBoundingClientRect();
        trackGeometryReady = detailRect.bottom > detailRect.top
          && focusedTrackRect.bottom > focusedTrackRect.top;
        if (focusedTrackRect.bottom > detailRect.bottom) {
          els.detail.scrollTop += Math.ceil(focusedTrackRect.bottom - detailRect.bottom);
        } else if (focusedTrackRect.top < detailRect.top) {
          els.detail.scrollTop -= Math.ceil(detailRect.top - focusedTrackRect.top);
        }
      }
      return {
        focusedTrackRendered: Boolean(focusedTrackRow),
        layoutReady: albumGeometryReady && trackGeometryReady,
      };
    };
    const initialFocusedNavigation = scrollFocusedRowsIntoView();
    const finishFocusedNavigation = (remainingAttempts) => {
      if (String(state.utility.focusedTrackPath || '') !== focusedTrackPath) return;
      const result = scrollFocusedRowsIntoView();
      if (!result.layoutReady &&
        result.focusedTrackRendered
        && remainingAttempts > 1
        && typeof scheduleBrowserAnimationFrame === 'function'
      ) {
        scheduleBrowserAnimationFrame(() => finishFocusedNavigation(remainingAttempts - 1));
      }
    };
    if (initialFocusedNavigation.focusedTrackRendered && typeof scheduleBrowserAnimationFrame === 'function') {
      scheduleBrowserAnimationFrame(() => finishFocusedNavigation(3));
    }
  }
}

const problematicFocusInputContainers = new WeakSet();

function bindProblematicFocusUserInput(els) {
  for (const container of [els.list, els.detail]) {
    if (!container?.addEventListener || problematicFocusInputContainers.has(container)) continue;
    problematicFocusInputContainers.add(container);
    const relinquish = () => {
      if (state.utility.activeTab === 'problematic-files') state.utility.focusedTrackPath = '';
    };
    container.addEventListener('wheel', event => {
      if (!event.ctrlKey && (event.deltaY || event.deltaX)) relinquish();
    }, { passive: true });
    container.addEventListener('touchmove', relinquish, { passive: true });
    container.addEventListener('pointerdown', event => {
      // Scrollbar/background input belongs to the scroller; an ordinary row
      // click must retain deferred track navigation until its own action runs.
      if (event.target === container && event.button === 0) relinquish();
    });
    container.addEventListener('keydown', event => {
      if (event.defaultPrevented || event.altKey || event.metaKey
        || !['ArrowUp', 'ArrowDown', 'PageUp', 'PageDown', 'Home', 'End', ' '].includes(event.key)) return;
      if (event.target?.closest?.('input, textarea, select, [contenteditable]:not([contenteditable="false"]), [role="textbox"], [role="slider"], [role="spinbutton"]')) return;
      if (event.key === ' ' && event.target?.closest?.('button, a[href], [role="button"], [role="checkbox"], [role="switch"]')) return;
      relinquish();
    });
  }
}

function mountProblematicMutationOverlay(detail) {
  const overlayMarkup = `
    <div class="problematic-mutation-overlay" role="status" aria-live="polite">
      <span class="problematic-mutation-spinner" aria-hidden="true"></span>
      <span>Hold on. Your changes are being applied</span>
    </div>
  `;
  if (detail.querySelector?.('.problematic-mutation-overlay')) return;

  const ownerDocument = detail.ownerDocument
    || (typeof document !== 'undefined' ? document : null);
  if (
    ownerDocument?.createElement
    && typeof detail.appendChild === 'function'
  ) {
    const preservedContent = ownerDocument.createElement('div');
    preservedContent.className = 'problematic-mutation-content';
    preservedContent.setAttribute('data-problematic-mutation-content', '');
    preservedContent.setAttribute('inert', '');
    while (detail.firstChild) preservedContent.appendChild(detail.firstChild);

    const overlay = ownerDocument.createElement('div');
    overlay.className = 'problematic-mutation-overlay';
    overlay.setAttribute('role', 'status');
    overlay.setAttribute('aria-live', 'polite');
    const spinner = ownerDocument.createElement('span');
    spinner.className = 'problematic-mutation-spinner';
    spinner.setAttribute('aria-hidden', 'true');
    const message = ownerDocument.createElement('span');
    message.textContent = 'Hold on. Your changes are being applied';
    overlay.appendChild(spinner);
    overlay.appendChild(message);
    detail.appendChild(preservedContent);
    detail.appendChild(overlay);
    return;
  }

  detail.innerHTML = `<div class="problematic-mutation-content" data-problematic-mutation-content inert>${String(detail.innerHTML || '')}</div>`;
  if (typeof detail.insertAdjacentHTML === 'function') {
    detail.insertAdjacentHTML('beforeend', overlayMarkup);
    return;
  }
  detail.innerHTML += overlayMarkup;
}

function reconcileUtilitySectionRows(list, attribute, items, selectedKey, renderItem, trailingMarkup = '') {
  const rows = Array.from(list.querySelectorAll(`[${attribute}]`));
  const scrollTop = list.scrollTop;
  if (!rows.length) {
    list.innerHTML = items.map(item => renderItem(item, item.key === selectedKey)).join('') + trailingMarkup;
  } else {
    const byKey = new Map(rows.map(row => [row.getAttribute(attribute), row]));
    const keys = new Set(items.map(item => item.key));
    rows.forEach(row => { if (!keys.has(row.getAttribute(attribute))) row.remove(); });
    let cursor = list.firstElementChild;
    for (const item of items) {
      let row = byKey.get(item.key);
      if (!row) {
        const holder = document.createElement('div');
        holder.innerHTML = renderItem(item, item.key === selectedKey);
        row = holder.firstElementChild;
      }
      if (row !== cursor) list.insertBefore(row, cursor);
      cursor = row.nextElementSibling;
    }
  }
  list.querySelectorAll(`[${attribute}]`).forEach(row => {
    window.NavigationTree.setItemSelected(row, row.getAttribute(attribute) === selectedKey);
  });
  list.scrollTop = scrollTop;
}

function renderUtilityRules() {
  const els = getUtilityModalElements();
  if (!els.overlay || !els.list || !els.detail || !els.count) return;
  const rules = state.utility.rules || [];
  if (els.sidebarLabel) els.sidebarLabel.textContent = 'Rules';
  els.count.textContent = String(rules.length);
  if (els.search) {
    els.search.value = state.utility.rulesSearchQuery || '';
    els.search.disabled = false;
    els.search.placeholder = 'Filter album, filename, or reason';
  }
  if (els.problemFilterButton) {
    els.problemFilterButton.disabled = true;
    els.problemFilterButton.hidden = true;
  }
  if (els.problemFilterMenu) els.problemFilterMenu.hidden = true;
  if (els.problemFilterChips) els.problemFilterChips.innerHTML = '';

  if (state.utility.rulesLoading) {
    els.list.innerHTML = '<div class="utility-empty-state compact">Loading rules...</div>';
    els.detail.innerHTML = '<div class="utility-empty-state">Loading rules...</div>';
    return;
  }

  if (!rules.length) {
    els.list.innerHTML = '<div class="utility-empty-state compact">No rules found.</div>';
    els.detail.innerHTML = '<div class="utility-empty-state">No rules found.</div>';
    return;
  }

  if (!state.utility.selectedRuleKey || !rules.some((item) => item.key === state.utility.selectedRuleKey)) {
    state.utility.selectedRuleKey = rules[0].key || '';
  }
  const selectedRule = getSelectedUtilityRule();
  reconcileUtilitySectionRows(els.list, 'data-utility-rule-key', rules, state.utility.selectedRuleKey, buildUtilityRuleListItem);
  const rulesByKey = new Map(rules.map(rule => [rule.key, rule]));
  els.list.querySelectorAll('[data-utility-rule-key]').forEach(row => {
    const rule = rulesByKey.get(row.getAttribute('data-utility-rule-key'));
    row.classList.toggle('is-active', rule.key === state.utility.selectedRuleKey);
    for (const [selector, value] of [
      ['.utility-list-item-title', rule.title || 'Rule'],
      ['.utility-list-item-meta', rule.description || ''],
      ['.utility-list-item-issues', `${Number(rule.count || 0)} applied`],
    ]) {
      const field = row.querySelector?.(selector);
      if (field && field.textContent !== value) field.textContent = value;
    }
  });
  els.detail.innerHTML = buildUtilityRuleDetail(selectedRule);
}

function clearUtilityLoopDragState() {
  state.utility.loopDragType = '';
  state.utility.loopDragId = '';
  state.utility.loopDragGroupKey = '';
  state.utility.loopDropType = '';
  state.utility.loopDropTargetId = '';
  state.utility.loopDropGroupKey = '';
  state.utility.loopDropPosition = '';
}

function syncUtilityLoopDragUi() {
  document.querySelectorAll('[data-utility-loop-entry], [data-utility-loop-id]').forEach(node => {
    const id = getUtilityLoopNodeId(node);
    const dragging = id && id === state.utility.loopDragId;
    const dropping = id && id === state.utility.loopDropTargetId;
    node.classList.toggle('is-dragging', Boolean(dragging));
    node.classList.toggle('is-drop-before', Boolean(dropping && state.utility.loopDropPosition === 'before'));
    node.classList.toggle('is-drop-after', Boolean(dropping && state.utility.loopDropPosition === 'after'));
  });
}

function getUtilityLoopNodeId(node) {
  return String(node?.getAttribute('data-utility-loop-entry') || node?.getAttribute('data-utility-loop-id') || '');
}

function syncUtilityLoopMoveButtons() {
  document.querySelectorAll('[data-move-utility-loop]').forEach(button => {
    const id = button.getAttribute('data-move-utility-loop');
    const loop = (state.utility.loops || []).find(item => String(item.id) === id);
    const scope = loop && getUtilityLoopOrderScope(loop.song_key);
    const index = scope?.loops.findIndex(item => String(item.id) === id) ?? -1;
    const direction = button.getAttribute('data-loop-move-direction');
    const unavailable = !scope || Boolean(state.utility.loopOrderPending?.[loop.song_key])
      || (direction === 'up' ? index <= 0 : index >= scope.loops.length - 1);
    button.setAttribute('aria-disabled', String(unavailable));
    // Keep the focused control in the tab order across an optimistic boundary move.
    button.dataset.moveUnavailable = String(unavailable);
  });
}

function updateUtilityLoopDropState(type, targetId, position, groupKey = '') {
  state.utility.loopDropType = String(type || '');
  state.utility.loopDropTargetId = String(targetId || '');
  state.utility.loopDropGroupKey = String(groupKey || '');
  state.utility.loopDropPosition = position === 'after' ? 'after' : position === 'before' ? 'before' : '';
  syncUtilityLoopDragUi();
}

function getUtilityLoopDropPosition(button, clientY) {
  const rect = button.getBoundingClientRect();
  return clientY < rect.top + (rect.height / 2) ? 'before' : 'after';
}

function renderUtilityLoopList(els, loops) {
  const groups = groupUtilityLoops(loops);
  els.list.innerHTML = groups.map((group) => buildUtilityLoopTree(
    group,
    state.utility.selectedLoopGroupKey || getSelectedUtilityLoopGroup()?.key || '',
    state.utility.selectedLoopId || '',
  )).join('') || '<div class="utility-empty-state compact">No matching loops.</div>';
  bindUtilityLoopDragAndDrop();
  syncUtilityLoopDragUi();
}

function bindUtilityLoopDragAndDrop() {
  const clear = () => { clearUtilityLoopDragState(); syncUtilityLoopDragUi(); };
  const payload = () => ({ type: state.utility.loopDragType, id: state.utility.loopDragId, groupKey: state.utility.loopDragGroupKey });
  document.querySelectorAll('[data-loop-tree-song], [data-loop-panel-song]').forEach(container => {
    if (container.dataset.edgeDragBound === '1') return;
    container.dataset.edgeDragBound = '1';
    const edgeTarget = event => {
      if (event.target.closest('[data-utility-loop-id], [data-utility-loop-entry]')) return null;
      const nodes = Array.from(container.querySelectorAll('[data-utility-loop-id], [data-utility-loop-entry]')).filter(node => !node.hidden);
      if (!nodes.length) return null;
      const next = nodes.find(node => event.clientY <= node.getBoundingClientRect().top);
      const node = next || nodes[nodes.length - 1];
      return { target: { type: 'loop', id: getUtilityLoopNodeId(node), groupKey: container.getAttribute('data-loop-tree-song') || container.getAttribute('data-loop-panel-song') }, position: next ? 'before' : 'after' };
    };
    container.addEventListener('dragover', event => {
      const edge = edgeTarget(event);
      if (!edge) {
        if (!event.target.closest('[data-utility-loop-id], [data-utility-loop-entry]')) updateUtilityLoopDropState('', '', '');
        return;
      }
      if (!buildReorderedUtilityLoops(state.utility.loops, payload(), edge.target, edge.position)) {
        updateUtilityLoopDropState('', '', '');
        return;
      }
      event.preventDefault();
      if (event.dataTransfer) event.dataTransfer.dropEffect = 'move';
      updateUtilityLoopDropState('loop', edge.target.id, edge.position, edge.target.groupKey);
    });
    container.addEventListener('drop', async event => {
      const edge = edgeTarget(event);
      if (!edge) return;
      event.preventDefault(); event.stopPropagation();
      const source = payload(); clear();
      await reorderUtilityLoops(source, edge.target, edge.position);
    });
    container.addEventListener('dragleave', event => {
      if (!event.relatedTarget || !container.contains(event.relatedTarget)) updateUtilityLoopDropState('', '', '');
    });
  });
  document.querySelectorAll('[data-utility-loop-entry], [data-utility-loop-id]').forEach(node => {
    const currentLoop = () => (state.utility.loops || []).find(loop => String(loop.id) === getUtilityLoopNodeId(node));
    node.setAttribute('draggable', String(canReorderUtilityLoop(currentLoop())));
    if (node.dataset.dragBound === '1') return;
    node.dataset.dragBound = '1';
    const target = () => ({ type: 'loop', id: getUtilityLoopNodeId(node), groupKey: currentLoop()?.song_key });
    node.addEventListener('dragstart', event => {
      const loop = currentLoop();
      if (!canReorderUtilityLoop(loop) || state.utility.loopOrderPending?.[loop.song_key]
          || event.target?.closest?.('button, input, select, textarea, a, [data-loop-range-surface]')) {
        event.preventDefault(); clear(); return;
      }
      state.utility.loopDragType = 'loop'; state.utility.loopDragId = String(loop.id);
      state.utility.loopDragGroupKey = loop.song_key;
      state.utility.loopSuppressClick = false;
      updateUtilityLoopDropState('', '', '');
      if (event.dataTransfer) {
        event.dataTransfer.effectAllowed = 'move';
        event.dataTransfer.setData('text/plain', JSON.stringify(payload()));
      }
    });
    node.addEventListener('dragover', event => {
      const position = getUtilityLoopDropPosition(node, event.clientY);
      if (!buildReorderedUtilityLoops(state.utility.loops, payload(), target(), position)) {
        updateUtilityLoopDropState('', '', ''); return;
      }
      event.preventDefault();
      if (event.dataTransfer) event.dataTransfer.dropEffect = 'move';
      updateUtilityLoopDropState('loop', getUtilityLoopNodeId(node), position, currentLoop().song_key);
    });
    node.addEventListener('dragleave', event => {
      if (!event.relatedTarget || !node.contains(event.relatedTarget)) updateUtilityLoopDropState('', '', '');
    });
    node.addEventListener('drop', async event => {
      event.preventDefault(); event.stopPropagation?.();
      const source = payload(); const destination = target();
      const position = getUtilityLoopDropPosition(node, event.clientY);
      clear();
      state.utility.loopSuppressClick = true;
      try { return await reorderUtilityLoops(source, destination, position); }
      finally { setTimeout(() => { state.utility.loopSuppressClick = false; }, 0); }
    });
    node.addEventListener('dragend', clear);
  });
  document.querySelectorAll('[data-move-utility-loop]').forEach(button => {
    if (button.dataset.moveBound === '1') return;
    button.dataset.moveBound = '1';
    button.addEventListener('click', event => {
      event.preventDefault(); event.stopPropagation?.();
      if (button.getAttribute('aria-disabled') === 'true') return false;
      return moveUtilityLoop(button.getAttribute('data-move-utility-loop'), button.getAttribute('data-loop-move-direction'));
    });
  });
  if (!state.utility.loopDragDismissBound) {
    state.utility.loopDragDismissBound = true;
    document.addEventListener('keydown', event => { if (event.key === 'Escape') clear(); });
    document.addEventListener('drop', clear);
    document.addEventListener('dragend', clear);
  }
  syncUtilityLoopMoveButtons();
}

function syncUtilityLoopPanelVisibility() {
  if (typeof getMobileLoopPage === 'function' && getMobileLoopPage()?.loopSongId) return;
  const visibleIds = new Set(getFilteredUtilityLoops().map(loop => String(loop.id)));
  const els = getUtilityModalElements();
  els.detail?.querySelectorAll('[data-utility-loop-entry]').forEach(panel => { panel.hidden = !visibleIds.has(getUtilityLoopNodeId(panel)); });
  const empty = visibleIds.size === 0;
  const groupDetail = els.detail?.querySelector('.utility-loop-group-detail');
  const panelList = els.detail?.querySelector('.utility-loop-entry-list');
  if (groupDetail) groupDetail.hidden = empty;
  if (panelList) panelList.hidden = empty;
  let message = els.detail?.querySelector('[data-loop-search-empty]');
  if (empty && !message && els.detail) {
    message = document.createElement('div');
    message.setAttribute('data-loop-search-empty', '1');
    message.setAttribute('class', 'utility-empty-state');
    message.textContent = 'No matching loops.';
    els.detail.appendChild(message);
  }
  if (message) message.hidden = !empty;
}

function filterUtilityLoopViews() {
  if (state.utility.activeTab !== 'loops') return;
  const els = getUtilityModalElements();
  const filtered = getFilteredUtilityLoops();
  if (els.count) els.count.textContent = String(filtered.length);
  if (typeof getMobileLoopPage === 'function' && getMobileLoopPage()) {
    renderUtilityLoopList(els, filtered);
    syncMobileUtilityContext();
    return;
  }
  if (filtered.length && !filtered.some(loop => buildUtilityLoopGroupKey(loop) === state.utility.selectedLoopGroupKey)) {
    state.utility.selectedLoopGroupKey = buildUtilityLoopGroupKey(filtered[0]);
    state.utility.selectedLoopId = String(filtered[0].id);
    renderUtilityLoops();
    return;
  }
  const scroll = els.list?.scrollTop;
  renderUtilityLoopList(els, filtered);
  if (els.list && Number.isFinite(scroll)) els.list.scrollTop = scroll;
  syncUtilityLoopPanelVisibility();
}

function renderUtilityLoops() {
  const els = getUtilityModalElements();
  if (!els.overlay || !els.list || !els.detail || !els.count) return;
  state.utility.loopViewGeneration = Number(state.utility.loopViewGeneration || 0) + 1;
  if (typeof disposeMountedLoopActions === 'function') disposeMountedLoopActions(els.detail);
  if (els.overlay.hidden) return;
  els.detail.classList.add('is-loop-detail');
  const loops = state.utility.loops || [];
  const mobilePage = typeof getMobileLoopPage === 'function' ? getMobileLoopPage() : null;
  const mobileGroup = mobilePage ? resolveMobileLoopSongGroup(mobilePage, loops) : null;
  if (mobilePage && mobilePage.loopSongId && !mobileGroup && state.utility.loopsLoaded
      && !state.utility.loopsLoading && !state.utility.loopsLoadError) mobilePage.loopSongId = '';
  els.overlay.dataset.mobileLoopView = mobilePage?.loopSongId ? 'song' : 'list';
  if (mobilePage) pauseOtherUtilityLoopPlayback(null);
  if (els.sidebarLabel) els.sidebarLabel.textContent = 'Loops';
  const filtered = getFilteredUtilityLoops();
  els.count.textContent = String(filtered.length);
  if (els.search) {
    els.search.value = state.utility.loopsSearchQuery || '';
    els.search.disabled = false;
    els.search.placeholder = 'Filter song, artist, album, or loop';
  }
  if (els.problemFilterButton) {
    els.problemFilterButton.disabled = true;
    els.problemFilterButton.hidden = true;
  }
  if (els.problemFilterMenu) els.problemFilterMenu.hidden = true;
  if (els.problemFilterChips) els.problemFilterChips.innerHTML = '';

  if (state.utility.loopsLoading) {
    els.list.innerHTML = '<div class="utility-empty-state compact">Loading loops...</div>';
    els.detail.innerHTML = '<div class="utility-empty-state">Loading loops...</div>';
    return;
  }

  if (state.utility.loopsLoadError) {
    const errorHtml = buildOnPageAlertHtml({ severity: 'error', title: 'Saved loops unavailable', message: state.utility.loopsLoadError });
    els.list.innerHTML = mobilePage ? errorHtml : '';
    els.detail.innerHTML = errorHtml;
    return;
  }
  if (!loops.length) {
    clearUtilityLoopDragState();
    els.list.innerHTML = '<div class="utility-empty-state compact">No saved loops yet.</div>';
    els.detail.innerHTML = '<div class="utility-empty-state">Create a loop from the bottom player and it will appear here.</div>';
    return;
  }

  if (mobilePage && !mobileGroup) {
    renderUtilityLoopList(els, filtered);
    els.detail.innerHTML = '';
    clearUtilityLoopSpaceOwner();
    restoreMobileLoopListScroll(mobilePage);
    return;
  }
  if (mobileGroup) state.utility.selectedLoopGroupKey = String(mobileGroup.key);
  const groupedLoops = groupUtilityLoops(mobileGroup ? loops : (filtered.length ? filtered : loops));
  if (!state.utility.selectedLoopGroupKey || !groupedLoops.some((group) => String(group.key || '') === String(state.utility.selectedLoopGroupKey || ''))) {
    state.utility.selectedLoopGroupKey = String(groupedLoops[0]?.key || '');
  }
  if (!state.utility.selectedLoopId || !loops.some((item) => String(item.id || '') === String(state.utility.selectedLoopId))) {
    const defaultLoop = groupedLoops.find((group) => String(group.key || '') === String(state.utility.selectedLoopGroupKey || ''))?.loops?.[0] || loops[0];
    state.utility.selectedLoopId = String(defaultLoop?.id || '');
  }
  const selectedGroup = getSelectedUtilityLoopGroup();
  state.utility.selectedLoopDetailMode = 'group';
  renderUtilityLoopList(els, getFilteredUtilityLoops());
  els.detail.innerHTML = buildUtilityLoopDetail(selectedGroup);
  (selectedGroup?.loops || []).forEach((loop) => initializeUtilityLoopPlayer(loop));
  bindUtilityLoopDragAndDrop();
  syncUtilityLoopPanelVisibility();
  updateUtilityLoopRepeatButton(String(state.utility.selectedLoopId || ''));
}

function filterUtilityAppearanceNavigation() {
  const els = getUtilityModalElements();
  const query = String(state.utility.appearanceSearchQuery || '').trim().toLocaleLowerCase();
  let matches = 0;
  els.list?.querySelectorAll('[data-utility-appearance-key]').forEach((row) => {
    const keywords = row.getAttribute?.('data-utility-appearance-key') === 'seekbar' ? ' compact sidebar floating edge slow motion' : '';
    row.hidden = !(String(row.textContent || '') + keywords).toLocaleLowerCase().includes(query);
    if (!row.hidden) matches += 1;
  });
  const empty = els.list?.querySelector('[data-appearance-search-empty]');
  if (empty) empty.hidden = matches !== 0;
  if (els.count) els.count.textContent = String(matches);
}

function renderUtilityAppearance() {
  const els = getUtilityModalElements();
  if (!els.overlay || !els.list || !els.detail || !els.count) return;
  if (els.sidebarLabel) els.sidebarLabel.textContent = 'Appearance';
  els.count.textContent = '5';
  if (els.search) {
    els.search.value = state.utility.appearanceSearchQuery || '';
    els.search.disabled = false;
    els.search.placeholder = 'Search settings';
  }
  if (els.problemFilterButton) {
    els.problemFilterButton.disabled = true;
    els.problemFilterButton.hidden = true;
  }
  if (els.problemFilterMenu) els.problemFilterMenu.hidden = true;
  if (els.problemFilterChips) els.problemFilterChips.innerHTML = '';
  const appearanceKeys = ['backgrounds', 'seekbar', 'selection-accent', 'alerts', 'album-page'];
  if (!appearanceKeys.includes(state.utility.appearanceKey)) state.utility.appearanceKey = 'backgrounds';
  const selectedKey = state.utility.appearanceKey;
  const navigationTree = typeof window !== 'undefined' ? window.NavigationTree : null;
  const labels = { backgrounds: 'Main elements', seekbar: 'Player & Seekbar', 'selection-accent': 'Selection & Hover', alerts: 'Alerts', 'album-page': 'Album page' };
  reconcileUtilitySectionRows(els.list, 'data-utility-appearance-key', appearanceKeys.map(key => ({ key })), selectedKey,
    (item, selected) => navigationTree?.renderItem
      ? navigationTree.renderItem({ key: item.key, label: labels[item.key], variant: 'panel', action: true, selected, attributes: { 'data-utility-appearance-key': item.key } })
      : buildUtilityAppearanceListItem(item.key, labels[item.key], '', selected),
    '<div class="utility-empty-state compact" data-appearance-search-empty hidden>No matching settings.</div>');
  filterUtilityAppearanceNavigation();
  if (selectedKey === 'backgrounds') {
    if (typeof window !== 'undefined') window.AlbumHavenSelectionAccent?.unmount?.();
    if (typeof mountBackgroundAppearanceEditor === 'function') mountBackgroundAppearanceEditor(els.detail);
  } else if (selectedKey === 'selection-accent') {
    const appearance = typeof window !== 'undefined' ? window.AlbumHavenAppearance?.instance : null;
    if (appearance?.mountSelectionAccent) appearance.mountSelectionAccent(els.detail);
    else els.detail.innerHTML = buildOnPageAlertHtml({ severity: 'error', title: 'Appearance unavailable', message: 'Selection & Hover could not be loaded. Reload this page to try again.' });
  } else if (selectedKey === 'alerts') {
    if (typeof window !== 'undefined') window.AlbumHavenSelectionAccent?.unmount?.();
    if (typeof mountAlertsAppearanceEditor === 'function') mountAlertsAppearanceEditor(els.detail);
  } else if (selectedKey === 'album-page') {
    if (typeof window !== 'undefined') window.AlbumHavenSelectionAccent?.unmount?.();
    if (typeof mountAlbumPageAppearanceEditor === 'function') mountAlbumPageAppearanceEditor(els.detail);
  } else {
    if (typeof unmountAppearanceEditors === 'function') unmountAppearanceEditors();
    els.detail.innerHTML = buildUtilityAppearanceDetail();
    if (typeof mountSeekbarAppearanceEditor === 'function') mountSeekbarAppearanceEditor(els.detail);
  }
}

function filterUtilityIntegrationNavigation() {
  const els = getUtilityModalElements();
  const query = String(state.utility.integrationsSearchQuery || '').trim().toLocaleLowerCase();
  let matches = 0;
  els.list?.querySelectorAll('[data-utility-integration-key]').forEach((row) => {
    row.hidden = !String(row.textContent || '').toLocaleLowerCase().includes(query);
    if (!row.hidden) matches += 1;
  });
  let empty = els.list?.querySelector?.('[data-integration-search-empty]');
  if (!empty && matches === 0 && els.list?.insertAdjacentHTML) {
    els.list.insertAdjacentHTML('beforeend', '<div class="utility-empty-state compact" data-integration-search-empty>No matching integrations.</div>');
    empty = els.list.querySelector('[data-integration-search-empty]');
  }
  if (empty) empty.hidden = matches !== 0;
  if (els.count) els.count.textContent = String(matches);
}

function getSelectedUtilityIntegration() {
  return buildUtilityIntegrationItems().find((item) => String(item.key || '') === String(state.utility.selectedIntegrationKey || '')) || null;
}

let utilityFoobarPreviewOwner = null;
let utilityFoobarPreviewGeneration = 0;
// Keep this cleanup entry point for the existing native modal close owner.
// The mounted component is now the account-owned review/confirm import UI.
function disposeUtilityFoobarPreview(message = '') {
  const owner = utilityFoobarPreviewOwner;
  utilityFoobarPreviewGeneration += 1;
  utilityFoobarPreviewOwner = null;
  if (!owner) return;
  owner.observer?.disconnect();
  window.removeEventListener('pagehide', owner.retire);
  document.removeEventListener('album-haven:policy-invalidated', owner.retire);
  document.removeEventListener('album-haven:session-changed', owner.retire);
  try { owner.mounted?.dispose(); } catch { /* Retired callbacks cannot publish. */ }
  owner.mounted = null;
  owner.host.replaceChildren();
  if (message && owner.host.isConnected) {
    const status = document.createElement('p');
    status.setAttribute('role', 'status');
    status.textContent = message;
    owner.host.append(status);
  }
}

function mountUtilityFoobarPreview(els) {
  const host = els.detail.querySelector('[data-foobar-import-host]');
  const contextRoot = document.getElementById('app-shell');
  if (!host || !els.overlay || els.overlay.hidden) return;
  const action = 'account.self.foobar.write';
  const capable = () => window.AlbumHavenCapabilities?.allows(action) === true;
  const marker = contextRoot?.dataset.accountFoobarContext;
  const scope = contextRoot?.dataset.accountFoobarScope;
  const matchingLibraryId = contextRoot?.dataset.accountFoobarMatchingLibraryId || '';
  if (!contextRoot?.isConnected || !/^[a-f0-9]{64}$/.test(marker || '')
      || scope !== 'account-foobar-v1' || !capable()) {
    host.textContent = 'Foobar import controls are unavailable. Check the status of any import already submitted.';
    return;
  }
  const utility = state.utility;
  const token = ++utilityFoobarPreviewGeneration;
  const isCurrent = () => token === utilityFoobarPreviewGeneration
    && utilityFoobarPreviewOwner === owner && state.utility === utility
    && contextRoot.isConnected && document.getElementById('app-shell') === contextRoot
    && contextRoot.ownerDocument === host.ownerDocument
    && contextRoot.dataset.accountFoobarContext === marker
    && contextRoot.dataset.accountFoobarScope === scope
    && (contextRoot.dataset.accountFoobarMatchingLibraryId || '') === matchingLibraryId
    && host.isConnected && els.detail.isConnected && els.overlay.isConnected
    && document.getElementById('utility-modal') === els.overlay
    && getUtilityModalElements().detail === els.detail
    && els.overlay.contains(els.detail) && els.detail.contains(host)
    && els.detail.querySelector('[data-foobar-import-host]') === host
    && !els.overlay.hidden && utility.activeTab === 'integrations'
    && utility.selectedIntegrationKey === 'foobar' && capable();
  const owner = {host, mounted: null, observer: null, isCurrent, retire: null};
  owner.retire = () => {
    if (utilityFoobarPreviewOwner === owner) disposeUtilityFoobarPreview(
      'Foobar import controls were closed. Reopen Settings to check any import already submitted.');
  };
  utilityFoobarPreviewOwner = owner;
  window.addEventListener('pagehide', owner.retire);
  document.addEventListener('album-haven:policy-invalidated', owner.retire);
  document.addEventListener('album-haven:session-changed', owner.retire);
  owner.observer = new MutationObserver(records => {
    const removedOwner = record => record.type === 'childList'
      && [...record.removedNodes].some(node => [contextRoot, els.overlay, els.detail, host]
        .some(owned => node === owned || node.contains?.(owned)));
    const changedContext = record => record.type === 'attributes'
      && (record.target === contextRoot && record.attributeName.startsWith('data-account-foobar-')
        || record.target === els.overlay && record.attributeName === 'hidden');
    if (records.some(record => removedOwner(record) || changedContext(record)) || !isCurrent()) owner.retire();
  });
  // The genuine utility modal is a sibling of #app-shell, not its descendant.
  owner.observer.observe(document.documentElement, {childList: true, subtree: true,
    attributes: true, attributeFilter: ['hidden', 'data-account-foobar-context',
      'data-account-foobar-scope', 'data-account-foobar-matching-library-id']});
  if (!isCurrent()) { owner.retire(); return; }
  const version = encodeURIComponent(String(window.__ALBUM_HAVEN_RUNTIME_ASSET_VERSION__ || ''));
  loadUtilityFoobarImportModule(version).then(module => {
    if (!isCurrent()) { owner.retire(); return; }
    const mounted = module.mountFoobarImport(host, {
      fetch: (...args) => window.fetch(...args), contextRoot,
      allows: requested => requested === action && isCurrent(),
      isCurrent,
      renderButton: options => window.ButtonComponent.renderButton(options),
      renderTable: options => buildUtilityCompactTable(options),
    });
    if (!mounted || typeof mounted.dispose !== 'function') throw new Error('Unavailable component.');
    if (!isCurrent()) { mounted.dispose(); owner.retire(); return; }
    owner.mounted = mounted;
  }).catch(() => {
    if (utilityFoobarPreviewOwner === owner) disposeUtilityFoobarPreview(
      'Foobar import controls are unavailable. Check any import already submitted before trying again.');
  });
}

// Named asset-loader boundary; browser URL and lifecycle remain unchanged.
function loadUtilityFoobarImportModule(version) {
  return import(`/static/js/foobar-import/index.mjs?v=${version}`);
}

function renderUtilityIntegrations() {
  const els = getUtilityModalElements();
  if (!els.overlay || !els.list || !els.detail || !els.count) return;
  const integrations = buildUtilityIntegrationItems();
  if (els.sidebarLabel) els.sidebarLabel.textContent = 'Integrations';
  els.count.textContent = String(integrations.length);
  if (els.search) {
    els.search.value = state.utility.integrationsSearchQuery || '';
    els.search.disabled = false;
    els.search.placeholder = 'Search integrations';
  }
  if (els.problemFilterButton) {
    els.problemFilterButton.disabled = true;
    els.problemFilterButton.hidden = true;
  }
  if (els.problemFilterMenu) els.problemFilterMenu.hidden = true;
  if (els.problemFilterChips) els.problemFilterChips.innerHTML = '';

  if (state.utility.integrationsLoading) {
    disposeUtilityFoobarPreview();
    els.list.innerHTML = '<div class="utility-empty-state compact">Loading integrations...</div>';
    els.detail.innerHTML = '<div class="utility-empty-state">Loading integrations...</div>';
    return;
  }
  if (!state.utility.selectedIntegrationKey || !integrations.some((item) => String(item.key || '') === String(state.utility.selectedIntegrationKey || ''))) {
    state.utility.selectedIntegrationKey = String(integrations[0]?.key || '');
  }
  const selected = getSelectedUtilityIntegration();
  const scrollTop = els.list.scrollTop;
  const existingRows = Array.from(els.list.querySelectorAll('[data-utility-integration-key]'));
  const rowsByKey = new Map(existingRows.map((row) => [row.getAttribute('data-utility-integration-key'), row]));
  if (!existingRows.length) els.list.replaceChildren();
  const keys = new Set(integrations.map((item) => String(item.key || '')));
  existingRows.forEach((row) => {
    if (!keys.has(row.getAttribute('data-utility-integration-key'))) row.remove();
  });
  let cursor = els.list.firstElementChild;
  integrations.forEach((item) => {
    const key = String(item.key || '');
    const isSelected = key === String(state.utility.selectedIntegrationKey || '');
    let row = rowsByKey.get(key);
    if (!row) {
      const holder = document.createElement('div');
      holder.innerHTML = buildUtilityIntegrationListItem(item, isSelected);
      row = holder.firstElementChild;
    }
    if (row !== cursor) els.list.insertBefore(row, cursor);
    window.NavigationTree.setItemSelected(row, isSelected);
    cursor = row.nextElementSibling;
  });
  els.list.scrollTop = scrollTop;
  filterUtilityIntegrationNavigation();
  if (selected?.key === 'foobar' && utilityFoobarPreviewOwner?.host?.isConnected
      && els.detail.contains(utilityFoobarPreviewOwner.host)
      && utilityFoobarPreviewOwner.isCurrent()) return;
  disposeUtilityFoobarPreview();
  els.detail.innerHTML = buildUtilityIntegrationDetail(selected);
  if (selected?.key === 'foobar') mountUtilityFoobarPreview(els);
}

function getSelectedUtilityLogHistoryItem() {
  return (state.utility.logHistory || []).find((item) => String(item.id || '') === String(state.utility.selectedLogHistoryId)) || null;
}

function renderUtilityLogHistory() {
  const els = getUtilityModalElements();
  if (!els.overlay || els.overlay.hidden || !els.list || !els.detail || !els.count || state.utility.activeTab !== 'log-history') return;
  if (els.sidebarLabel) els.sidebarLabel.textContent = 'History';
  const value = getUtilityLogHistoryController().getState();
  if (els.search) { els.search.disabled = false; els.search.readOnly = true; els.search.value = value.temporaryRowId ? value.periodLabel || '' : ''; els.search.placeholder = 'Choose a log period'; }
  if (els.problemFilterButton) { els.problemFilterButton.hidden = false; els.problemFilterButton.disabled = false; els.problemFilterButton.setAttribute('aria-label', 'Period'); els.problemFilterButton.setAttribute('title', 'Choose a log period'); els.problemFilterButton.setAttribute('aria-haspopup', 'dialog'); els.problemFilterButton.setAttribute('aria-controls', 'app-form-modal'); }
  if (els.problemFilterMenu) els.problemFilterMenu.hidden = true;
  if (els.problemFilterChips) els.problemFilterChips.innerHTML = '';
  const scroll = els.list.scrollTop;
  reconcileUtilityLogHistoryTree(els, value);
  els.list.scrollTop = scroll;
  els.detail.innerHTML = buildUtilityLogHistoryConsole(value);
}

function renderUtilityModalContent(options = {}) {
  const els = getUtilityModalElements();
  if (els.search) els.search.readOnly = false;
  if (els.problemFilterButton) { els.problemFilterButton.setAttribute('aria-label', 'Filters'); els.problemFilterButton.setAttribute('title', 'Filter by problem type'); els.problemFilterButton.setAttribute('aria-haspopup', 'listbox'); els.problemFilterButton.setAttribute('aria-controls', 'utility-problem-filter-menu'); }
  const activeTab = state.utility.activeTab || 'problematic-files';
  if (activeTab !== 'integrations' || state.utility.selectedIntegrationKey !== 'foobar') disposeUtilityFoobarPreview();

  if (activeTab !== 'problematic-files') disposeProblematicFilesVirtualList();
  if (activeTab !== 'log-history' && els.list?.dataset
      && els.list.dataset.utilityNavigationOwner !== activeTab) els.list.dataset.utilityNavigationOwner = activeTab;
  if (activeTab !== 'loops' && typeof disposeMountedLoopActions === 'function') disposeMountedLoopActions(els.detail);
  if (activeTab !== 'appearance' && typeof unmountAppearanceEditors === 'function') unmountAppearanceEditors();
  els.overlay?.setAttribute('data-active-tab', activeTab);
  els.detail?.classList.remove('is-loop-detail');
  els.tabs.forEach((tab) => {
    const selected = tab.getAttribute('data-utility-tab') === activeTab;
    tab.classList.toggle('is-active', selected);
    tab.setAttribute('aria-selected', selected ? 'true' : 'false');
    tab.setAttribute('role', 'tab');
    tab.setAttribute('tabindex', selected ? '0' : '-1');
    tab.setAttribute('aria-controls', 'utility-problematic-detail');
  });
  const selectedTab = els.tabs.find(tab => tab.getAttribute('data-utility-tab') === activeTab);
  if (selectedTab?.id) {
    els.detail?.setAttribute('role', 'tabpanel');
    els.detail?.setAttribute('aria-labelledby', selectedTab.id);
  }
  syncUtilityTabAlignment(els);
  if (options.shellOnly === true) {
    if (typeof updateSearchClearAction === 'function') updateSearchClearAction(els.search);
    if (typeof syncMobileUtilityContext === 'function') syncMobileUtilityContext();
    return;
  }
  if (activeTab === 'rules') {
    renderUtilityRules();
  } else if (activeTab === 'loops') {
    renderUtilityLoops();
  } else if (activeTab === 'log-history') {
    renderUtilityLogHistory();
  } else if (activeTab === 'integrations') {
    renderUtilityIntegrations();
  } else if (activeTab === 'appearance') {
    renderUtilityAppearance();
  } else {
    renderProblematicFiles(options);
  }
  if (typeof updateSearchClearAction === 'function') updateSearchClearAction(els.search);
  if (typeof syncMobileUtilityContext === 'function') syncMobileUtilityContext();
}

const utilityTabAlignmentObservers = new WeakMap();
function syncUtilityTabAlignment(els = getUtilityModalElements()) {
  const strip = els.overlay?.querySelector?.('.utility-modal-tabs');
  const header = els.overlay?.querySelector?.('.utility-modal-header');
  if (!strip || !header) return;
  const update = () => {
    const active = strip.querySelector('[aria-selected="true"]');
    if (!active || els.overlay.hidden) return;
    const outer = header.getBoundingClientRect();
    const rect = active.getBoundingClientRect();
    header.style.setProperty('--active-tab-left', `${Math.max(0, rect.left - outer.left)}px`);
    header.style.setProperty('--active-tab-right', `${Math.min(outer.width, rect.right - outer.left)}px`);
  };
  const revealAndUpdate = () => {
    const active = strip.querySelector('[aria-selected="true"]');
    if (active && !els.overlay.hidden && strip.getBoundingClientRect) {
      const visible = strip.getBoundingClientRect();
      const rect = active.getBoundingClientRect();
      const availableWidth = visible.right - visible.left;
      const delta = rect.right - rect.left > availableWidth || rect.left < visible.left
        ? rect.left - visible.left : rect.right > visible.right ? rect.right - visible.right : 0;
      if (delta) strip.scrollLeft += delta;
    }
    update();
  };
  revealAndUpdate();
  if (!utilityTabAlignmentObservers.has(strip)) {
    const observer = typeof ResizeObserver === 'function' ? new ResizeObserver(revealAndUpdate) : null;
    observer?.observe(header);
    observer?.observe(strip);
    els.tabs.forEach(tab => observer?.observe(tab));
    strip.addEventListener('scroll', update, { passive: true });
    utilityTabAlignmentObservers.set(strip, { observer, update });
  }
}

function disposeUtilityTabAlignment(els = getUtilityModalElements()) {
  const strip = els.overlay?.querySelector?.('.utility-modal-tabs');
  if (!strip) return;
  const binding = utilityTabAlignmentObservers.get(strip);
  if (!binding) return;
  binding.observer?.disconnect();
  strip.removeEventListener('scroll', binding.update);
  utilityTabAlignmentObservers.delete(strip);
}

// END js/runtime/utility-renderers-and-actions.js

// BEGIN js/runtime/utility-loop-playback.js

const utilityLoopStereoLoads = new WeakMap();

function updateUtilityLoopStereoWaveform(loopId, audio) {
  const canvas = document.querySelector(`[data-loop-stereo-waveform="${cssEscape(loopId)}"]`);
  if (!canvas || !audio) return;
  const enabled = state.player.appearance?.seekbarMode === 'waveform';
  const editing = Boolean(state.utility.loopEditors?.[loopId]?.active);
  const cached = utilityLoopStereoLoads.get(canvas);
  const peaks = getCachedSavedLoopWaveformPeaks(loopId) || cached?.peaks;
  const coolingDown = cached && !cached.loading && !peaks && Date.now() < cached.retryAt;
  const presented = canvas.isConnected && enabled && !editing && !coolingDown;
  canvas.hidden = !presented;
  canvas.parentElement?.classList.toggle('is-stereo-waveform', presented);
  if (!presented) return;
  if (peaks) {
    const duration = Number(audio.duration) || 0;
    drawCombinedLoopWaveform(canvas, peaks, duration > 0 ? (Number(audio.currentTime) || 0) / duration : 0);
    return;
  }
  if (cached?.loading) return;
  const entry = { peaks: null, loading: true, retryAt: 0 };
  utilityLoopStereoLoads.set(canvas, entry);
  Promise.resolve(loadSavedLoopWaveformPeaks(loopId)).catch(() => null).then(peaks => {
    entry.loading = false;
    entry.peaks = peaks;
    entry.retryAt = Date.now() + 5000;
    if (canvas.isConnected
        && document.querySelector(`[data-loop-stereo-waveform="${cssEscape(loopId)}"]`) === canvas) {
      updateUtilityLoopStereoWaveform(loopId, audio);
    } else {
      canvas.hidden = true;
      canvas.parentElement?.classList.toggle('is-stereo-waveform', false);
    }
  });
}

function refreshUtilityLoopStereoWaveforms() {
  if (state.utility.loopsLoaded && Array.isArray(state.utility.loops)) {
    retainSavedLoopWaveformPeaks(state.utility.loops.map(loop => loop.id));
  }
  document.querySelectorAll('[data-loop-audio]').forEach(audio => {
    updateUtilityLoopStereoWaveform(audio.getAttribute('data-loop-audio'), audio);
  });
}
function isUtilityLoopTextEntry(element) {
  if (!(element instanceof HTMLElement)) return false;
  const tagName = String(element.tagName || '').toUpperCase();
  if (tagName === 'TEXTAREA') return true;
  if (element.isContentEditable) return true;
  if (tagName !== 'INPUT') return false;
  const type = String(element.getAttribute('type') || element.type || '').toLowerCase();
  return type !== 'range';
}

function focusUtilityLoopTimeline(loopId) {
  const timeline = document.querySelector(`[data-loop-timeline="${cssEscape(loopId || '')}"]`);
  if (!(timeline instanceof HTMLElement) || timeline.disabled) return;
  timeline.focus({ preventScroll: true });
}

function claimUtilityLoopSpaceOwnerFromTarget(target) {
  if (!(target instanceof HTMLElement) || isUtilityLoopTextEntry(target)) return false;
  const directLoopId = String(target.getAttribute?.('data-utility-loop-entry') || '');
  const loopEntry = directLoopId ? target : target.closest?.('[data-utility-loop-entry]');
  const loopId = directLoopId || String(loopEntry?.getAttribute?.('data-utility-loop-entry') || '');
  if (!loopId) return false;
  state.utility.loopSpaceOwnerId = loopId;
  return true;
}

function clearUtilityLoopSpaceOwner() {
  state.utility.loopSpaceOwnerId = '';
}

function collapseAllUtilityLoopGroups() {
  state.utility.collapsedLoopGroups = groupUtilityLoops(state.utility.loops || []).reduce((collapsedGroups, group) => {
    const groupKey = String(group?.key || '');
    if (groupKey) collapsedGroups[groupKey] = true;
    return collapsedGroups;
  }, {});
}

function setUtilityActiveTab(nextTab, skipAppearanceGuard = false) {
  if (typeof isMobileClient === 'function' && isMobileClient() && !mobileUtilityTabAllowed(nextTab)) return false;
  const normalizedTab = String(nextTab || 'problematic-files');
  if (typeof window !== 'undefined' && window.AlbumHavenCapabilities && !window.AlbumHavenCapabilities.allowsUtilityTab(normalizedTab)) return state.utility.activeTab;
  if (!skipAppearanceGuard && normalizedTab !== state.utility.activeTab && typeof confirmBackgroundAppearanceLeave === 'function' && !confirmBackgroundAppearanceLeave(() => {
    setUtilityActiveTab(normalizedTab, true);
    if (typeof loadActiveUtilityTab === 'function') loadActiveUtilityTab(true);
    if (typeof renderUtilityModalContent === 'function') renderUtilityModalContent();
  })) return state.utility.activeTab;
  if (state.utility.activeTab === 'loops' && normalizedTab !== 'loops') {
    if (typeof disposeMountedLoopActions === 'function') disposeMountedLoopActions(getUtilityModalElements()?.detail);
    clearUtilityLoopSpaceOwner();
  }
  if (state.utility.activeTab !== 'loops' && normalizedTab === 'loops') {
    collapseAllUtilityLoopGroups();
  }
  state.utility.activeTab = normalizedTab;
  return normalizedTab;
}

function resolveUtilityLoopSpaceOwner() {
  if (state.utility.activeTab !== 'loops') return false;
  const utilityOverlay = getUtilityModalElements()?.overlay;
  if (!utilityOverlay || utilityOverlay.hidden) return false;
  const loopId = String(state.utility.loopSpaceOwnerId || '');
  if (!loopId) return false;
  const audio = document.querySelector(`[data-loop-audio="${cssEscape(loopId)}"]`);
  return audio ? loopId : false;
}

function handleUtilityLoopSpacePlayback(event) {
  claimUtilityLoopSpaceOwnerFromTarget(event?.target);
  const loopId = resolveUtilityLoopSpaceOwner();
  return loopId
    ? toggleUtilityLoopPlayback(loopId, { focusTimelineOnResume: false })
    : false;
}

function seekUtilityLoopPlayback(loopId, deltaSeconds) {
  const audio = document.querySelector(`[data-loop-audio="${cssEscape(loopId || '')}"]`);
  if (!audio) return false;
  const duration = Number(audio.duration) || 0;
  const current = Number(audio.currentTime) || 0;
  const next = Math.max(0, Math.min(duration || Math.max(0, current + deltaSeconds), current + deltaSeconds));
  audio.currentTime = next;
  audio._loopEditPreviousTimeSeconds = next;
  updateUtilityLoopPlayerUi(loopId);
  return true;
}

function pauseOtherUtilityLoopPlayback(activeAudio) {
  document.querySelectorAll('[data-loop-audio]').forEach(otherAudio => {
    if (otherAudio === activeAudio || otherAudio.paused) return;
    otherAudio.pause();
    const otherLoopId = String(otherAudio.getAttribute?.('data-loop-audio') || '');
    if (otherLoopId) updateUtilityLoopPlayerUi(otherLoopId);
  });
}

function toggleUtilityLoopPlayback(loopId, options = {}) {
  const focusTimelineOnResume = options.focusTimelineOnResume !== false;
  const audio = document.querySelector(`[data-loop-audio="${cssEscape(loopId || '')}"]`);
  if (!audio) return false;
  if (audio.paused || audio.ended) {
    pauseOtherUtilityLoopPlayback(audio);
    if (audio.ended) audio.currentTime = 0;
    const globalPlayback = typeof getPlayerPlaybackSnapshot === 'function'
      ? getPlayerPlaybackSnapshot()
      : null;
    const finishLoopPlaybackStart = () => {
      if (focusTimelineOnResume) focusUtilityLoopTimeline(loopId);
    };
    const reportPlaybackFailure = error => {
      if (audio.isConnected === false) return;
      const code = String(error?.name || 'PlaybackError');
      console.warn('[AlbumHaven][Loops] Playback start failed.', { code, mediaErrorCode: audio.error?.code || null });
      showToast('Unable to start loop playback. Please try again.', 'error', 6000);
      updateUtilityLoopPlayerUi(loopId);
    };
    if (
      globalPlayback
      && !globalPlayback.ended
      && typeof pausePlayerPlaybackForHandoff === 'function'
    ) {
      const priorMuted = Boolean(audio.muted);
      const handoff = Promise.resolve(pausePlayerPlaybackForHandoff(globalPlayback));
      audio.muted = true;
      const activatedPlayback = audio.play();
      Promise.all([handoff, activatedPlayback])
        .then(() => {
          audio.muted = priorMuted;
          finishLoopPlaybackStart();
        })
        .catch(error => {
          audio.pause();
          audio.muted = priorMuted;
          reportPlaybackFailure(error);
        });
    } else {
      audio.play().then(finishLoopPlaybackStart).catch(reportPlaybackFailure);
    }
  } else {
    audio.pause();
  }
  updateUtilityLoopPlayerUi(loopId);
  return true;
}

function handleUtilityLoopTimelineKeydown(event, loopId) {
  if (!event || event.defaultPrevented || event.altKey || event.ctrlKey || event.metaKey) return false;
  if (event.key === ' ' || event.key === 'Spacebar' || event.code === 'Space') {
    if (event.isComposing || event.repeat || event.shiftKey) return false;
    event.preventDefault();
    event.stopPropagation?.();
    return toggleUtilityLoopPlayback(loopId, { focusTimelineOnResume: false });
  }
  if (event.key !== 'ArrowLeft' && event.key !== 'ArrowRight') return false;
  const direction = event.key === 'ArrowLeft' ? -1 : 1;
  const stepSeconds = event.shiftKey ? 5 : 1;
  event.preventDefault();
  event.stopPropagation?.();
  return seekUtilityLoopPlayback(loopId, direction * stepSeconds);
}

function handleUtilityLoopKeyboardSeek(event) {
  if (!event || event.defaultPrevented || event.altKey || event.ctrlKey || event.metaKey) return false;
  const target = event.target instanceof HTMLElement ? event.target : null;
  if (!target || isUtilityLoopTextEntry(target)) return false;
  const loopEntry = target.closest?.('[data-utility-loop-entry]');
  const loopId = String(loopEntry?.getAttribute?.('data-utility-loop-entry') || '');
  if (!loopId) return false;
  claimUtilityLoopSpaceOwnerFromTarget(target);
  const handled = handleUtilityLoopTimelineKeydown(event, loopId);
  const isSpace = event.key === ' ' || event.key === 'Spacebar' || event.code === 'Space';
  if (handled && !isSpace) focusUtilityLoopTimeline(loopId);
  return handled;
}

function initializeUtilityLoopPlayer(loop) {
  if (!loop) return;
  const loopId = String(loop.id || '');
  const audio = document.querySelector(`[data-loop-audio="${cssEscape(loopId)}"]`);
  if (!audio) return;
  if (audio.dataset.bound === '1') {
    mountSavedLoopControls(loopId);
    return;
  }
  const playButton = document.querySelector(`[data-loop-play="${cssEscape(loopId)}"]`);
  const timeline = document.querySelector(`[data-loop-timeline="${cssEscape(loopId)}"]`);
  const loopEntry = playButton?.closest?.('[data-utility-loop-entry]')
    || timeline?.closest?.('[data-utility-loop-entry]');
  audio.dataset.bound = '1';
  audio.dataset.speed = '1';
  audio.dataset.pitch = '0';
  audio.dataset.appliedPitch = '0';
  audio._loopEditPreviousTimeSeconds = Number(audio.currentTime) || 0;
  if ('preservesPitch' in audio) audio.preservesPitch = true;
  playButton?.addEventListener('click', () => {
    claimUtilityLoopSpaceOwnerFromTarget(playButton);
    toggleUtilityLoopPlayback(loopId);
  });
  loopEntry?.addEventListener('focusin', (event) => {
    claimUtilityLoopSpaceOwnerFromTarget(event.target);
  });
  timeline?.addEventListener('keydown', (event) => {
    handleUtilityLoopTimelineKeydown(event, loopId);
  });
  timeline?.addEventListener('input', () => {
    audio.currentTime = Number(timeline.value) || 0;
    audio._loopEditPreviousTimeSeconds = audio.currentTime;
    updateUtilityLoopPlayerUi(loopId);
  });
  audio.addEventListener('loadedmetadata', () => {
    updateUtilityLoopPlayerUi(loopId);
    updateUtilityLoopAudioRate(loopId);
  });
  audio.addEventListener('play', () => updateUtilityLoopPlayerUi(loopId));
  audio.addEventListener('pause', () => updateUtilityLoopPlayerUi(loopId));
  audio.addEventListener('timeupdate', () => {
    noteSavedLoopWholeRangePlaybackProgress(loopId, audio);
    updateUtilityLoopPlayerUi(loopId);
  });
  audio.addEventListener('ended', () => {
    if (state.utility.loopRepeatEnabled && String(state.utility.selectedLoopId || '') === loopId) {
      noteSavedLoopWholeRangeWrap(loopId);
      audio.currentTime = 0;
      audio._loopEditPreviousTimeSeconds = 0;
      audio.play().catch(() => {});
      return;
    }
    updateUtilityLoopPlayerUi(loopId);
  });
  mountSavedLoopControls(loopId);
  updateUtilityLoopRepeatButton(loopId);
  updateUtilityLoopPlayerUi(loopId);
  if (!state.utility.loopKeyboardSeekBound) {
    document.addEventListener('keydown', handleUtilityLoopKeyboardSeek);
    state.utility.loopKeyboardSeekBound = true;
  }
}

function updateUtilityLoopRepeatButton() {
  const activeLoopId = String(state.utility.selectedLoopId || '');
  const repeatEnabled = Boolean(state.utility.loopRepeatEnabled)
    && Boolean(activeLoopId);
  document.querySelectorAll('[data-toggle-loop-repeat]').forEach((button) => {
    const buttonLoopId = String(button.getAttribute('data-toggle-loop-repeat') || '');
    const isActive = repeatEnabled && buttonLoopId === activeLoopId;
    const audio = document.querySelector(
      `[data-loop-audio="${cssEscape(buttonLoopId)}"]`,
    );
    if (audio) audio.loop = false;
    const label = isActive ? 'Disable repeat' : 'Enable repeat';
    button.classList.toggle('is-active', isActive);
    button.setAttribute('aria-pressed', isActive ? 'true' : 'false');
    button.setAttribute('aria-label', label);
    button.setAttribute('title', label);
  });
}

function updateUtilityLoopAudioRate(loopId) {
  const selector = `[data-loop-audio="${cssEscape(loopId || '')}"]`;
  const audio = document.querySelector(selector);
  if (!audio) return;
  const speed = Number(audio.dataset.speed || '1') || 1;
  const pitch = Number(audio.dataset.pitch || '0') || 0;
  audio.playbackRate = Math.max(0.25, Math.min(2, Math.round(speed * 20) / 20));
  if ('preservesPitch' in audio) audio.preservesPitch = true;
  const speedValue = document.querySelector(`[data-loop-speed-value-button="${cssEscape(loopId || '')}"]`);
  const pitchValue = document.querySelector(`[data-loop-pitch-control="${cssEscape(loopId || '')}"] [data-loop-pitch-value]`);
  if (speedValue) speedValue.textContent = `${speed.toFixed(2).replace(/\.?0+$/, '')}x`;
  document.querySelectorAll(`[data-loop-speed-menu="${cssEscape(loopId || '')}"] [data-loop-speed-option]`).forEach((button) => {
    const optionValue = Number(button.getAttribute('data-loop-speed-option') || 0);
    button.classList.toggle('is-active', Math.abs(optionValue - speed) < 0.001);
    button.setAttribute('aria-checked', String(Math.abs(optionValue - speed) < 0.001));
  });
  if (pitchValue) pitchValue.textContent = `${pitch > 0 ? '+' : ''}${pitch} pst`;
  const pitchButton = document.querySelector(`[data-loop-pitch-value-button="${cssEscape(loopId || '')}"]`);
  if (pitchButton) {
    (pitchButton.querySelector('.ui-button__content') || pitchButton).textContent = `Pitch ${pitch > 0 ? '+' : ''}${pitch}`;
    pitchButton.setAttribute('aria-busy', String(audio.dataset.pitchPending === 'true'));
  }
  document.querySelectorAll(`[data-loop-pitch-menu="${cssEscape(loopId || '')}"] [data-loop-pitch-option]`).forEach(button => {
    button.setAttribute('aria-checked', String(Number(button.dataset.loopPitchOption) === pitch));
  });
}

// A phone picker unfolds from its button edge; selected-option scrolling never
// determines the surface position. Bounds exclude app chrome and the player.
function resolveUtilityLoopMenuPlacement(anchor, menu, bounds) {
  const above = Math.max(0, anchor.top - bounds.top);
  const below = Math.max(0, bounds.bottom - anchor.bottom);
  const down = below >= menu.height || below >= above;
  const height = Math.min(menu.height, down ? below : above);
  const width = Math.min(menu.width, Math.max(0, bounds.right - bounds.left));
  return {
    edge: down ? 'top' : 'bottom', height, width,
    top: down ? anchor.bottom : anchor.top - height,
    left: Math.max(bounds.left, Math.min(anchor.right - width, bounds.right - width)),
  };
}

function positionUtilityLoopSpeedMenu(loopId, setting = 'speed') {
  const trigger = document.querySelector(`[data-loop-${setting}-value-button="${cssEscape(loopId || '')}"]`);
  const menu = document.querySelector(`[data-loop-${setting}-menu="${cssEscape(loopId || '')}"]`);
  if (!trigger || !menu || menu.hidden) return;
  const activeOption = menu.querySelector('[aria-checked="true"], .is-active') || menu.querySelector('button');
  if (!activeOption) return;

  menu.style.visibility = 'hidden';
  menu.style.maxHeight = '';
  menu.style.left = '0px';
  menu.style.top = '0px';

  const triggerRect = trigger.getBoundingClientRect();
  const menuRect = menu.getBoundingClientRect();

  if (menu.classList.contains('is-mobile-loop-menu')) {
    const viewport = window.visualViewport;
    const viewportTop = viewport?.offsetTop || 0;
    const viewportBottom = viewportTop + (viewport?.height || window.innerHeight);
    const playerTop = document.querySelector('.global-player')?.getBoundingClientRect().top ?? viewportBottom;
    const barBottom = document.querySelector('.app-bar')?.getBoundingClientRect().bottom || 0;
    const left = viewport?.offsetLeft || 0;
    const placement = resolveUtilityLoopMenuPlacement(triggerRect, menuRect, {
      left: left + 8, right: left + (viewport?.width || window.innerWidth) - 8,
      top: Math.max(viewportTop, barBottom) + 8, bottom: Math.min(viewportBottom, playerTop) - 8,
    });
    menu.style.width = `${placement.width}px`;
    menu.style.maxHeight = `${placement.height}px`;
    menu.style.left = `${placement.left}px`;
    menu.style.top = `${placement.top}px`;
    const list = menu.querySelector('.utility-loop-menu-options') || menu;
    list.scrollTop = Math.max(0, activeOption.offsetTop - (list.clientHeight - activeOption.getBoundingClientRect().height) / 2);
    menu.style.visibility = '';
    if (typeof syncTriggerAnchor === 'function') syncTriggerAnchor(menu, trigger);
    return;
  }

  const padding = 8;
  const playerTop = document.querySelector('.global-player')?.getBoundingClientRect().top || window.innerHeight;
  const bottom = Math.min(window.innerHeight, playerTop);
  const optionHeight = activeOption.getBoundingClientRect().height;
  const selectedCenter = activeOption.offsetTop + optionHeight / 2;
  const triggerCenter = triggerRect.top + triggerRect.height / 2;
  const top = Math.max(padding, Math.min(triggerCenter - selectedCenter, bottom - padding - optionHeight));
  const popupHeight = Math.max(optionHeight, Math.min(menuRect.height, bottom - padding - top));
  menu.style.maxHeight = `${popupHeight}px`;
  const left = Math.max(padding, Math.min(triggerRect.right - menuRect.width, window.innerWidth - padding - menuRect.width));
  menu.style.left = `${left}px`;
  menu.style.top = `${top}px`;
  menu.scrollTop = Math.max(0, selectedCenter - (triggerCenter - top));
  menu.style.visibility = '';
  if (!menu.classList.contains('is-mobile-loop-menu') && typeof syncTriggerAnchor === 'function') syncTriggerAnchor(menu, trigger);
}

// The desktop speed menu and phone Pitch/Speed buttons share the same audio
// owners. Portal phone pickers out of the size-contained card so they neither
// clip nor displace another player; only one disclosure can own focus at a time.
let activeUtilityLoopSetting = null;
function closeUtilityLoopSettingMenu(returnFocus = false) {
  const active = activeUtilityLoopSetting;
  if (!active) return;
  activeUtilityLoopSetting = null;
  active.events.abort();
  active.menu.hidden = true;
  active.trigger.setAttribute('aria-expanded', 'false');
  if (typeof clearTriggerAnchor === 'function') clearTriggerAnchor(active.menu);
  active.menu.classList.remove('is-mobile-loop-menu');
  active.menu.replaceChildren(...active.optionList.childNodes);
  for (const name of ['width', 'max-height', 'left', 'top', 'visibility']) active.menu.style.removeProperty(name);
  if (active.parent.isConnected) active.parent.appendChild(active.menu);
  else active.menu.remove();
  if (returnFocus && active.trigger.isConnected) active.trigger.focus({ preventScroll: true });
}
function toggleUtilityLoopSettingMenu(loopId, setting, keyboard = false) {
  if (!['speed', 'pitch'].includes(setting)) return;
  const trigger = document.querySelector(`[data-loop-${setting}-value-button="${cssEscape(loopId)}"]`);
  const menu = document.querySelector(`[data-loop-${setting}-menu="${cssEscape(loopId)}"]`);
  if (!trigger || !menu) return;
  const wasOpen = activeUtilityLoopSetting?.menu === menu;
  closeUtilityLoopSettingMenu(false);
  if (wasOpen) return;
  updateUtilityLoopAudioRate(loopId);
  const parent = menu.parentElement;
  const style = getComputedStyle(trigger.closest('.utility-loop-entry'));
  for (const [target, source] of [['--loop-menu-surface', '--appearance-card'], ['--loop-menu-ink', '--appearance-ink'], ['--loop-menu-line', '--appearance-line'], ['--loop-menu-accent', '--appearance-play']]) {
    menu.style.setProperty(target, style.getPropertyValue(source));
  }
  // Scroll the options independently so the shared outline/bridge stays attached.
  const optionList = document.createElement('div');
  optionList.className = 'utility-loop-menu-options';
  optionList.append(...menu.childNodes);
  menu.appendChild(optionList);
  const events = new AbortController();
  activeUtilityLoopSetting = { menu, trigger, parent, optionList, events };
  if (typeof activateTriggerSurface === 'function') activateTriggerSurface(menu, () => closeUtilityLoopSettingMenu(false));
  menu.classList.add('is-mobile-loop-menu');
  menu.setAttribute('role', 'menu');
  menu.setAttribute('aria-label', setting === 'speed' ? 'Playback speed' : 'Pitch shift');
  menu.querySelectorAll('button').forEach(button => button.setAttribute('role', 'menuitemradio'));
  document.body.appendChild(menu);
  menu.hidden = false;
  trigger.setAttribute('aria-expanded', 'true');
  positionUtilityLoopSpeedMenu(loopId, setting);

  const options = () => [...menu.querySelectorAll('button:not(:disabled)')];
  if (keyboard) (menu.querySelector('[aria-checked="true"]') || options()[0])?.focus({ preventScroll: true });
  document.addEventListener('pointerdown', event => {
    if (!menu.contains(event.target) && !trigger.contains(event.target)) closeUtilityLoopSettingMenu(false);
  }, { capture: true, signal: events.signal });
  document.addEventListener('keydown', event => {
    if (event.key === 'Escape') {
      event.preventDefault(); event.stopImmediatePropagation(); closeUtilityLoopSettingMenu(true);
    } else if (event.key === 'Tab') {
      closeUtilityLoopSettingMenu(true);
    } else if (menu.contains(event.target) && ['ArrowDown', 'ArrowUp', 'Home', 'End'].includes(event.key)) {
      event.preventDefault(); event.stopImmediatePropagation();
      const buttons = options(), index = buttons.indexOf(document.activeElement);
      const next = event.key === 'Home' ? 0 : event.key === 'End' ? buttons.length - 1
        : (index + (event.key === 'ArrowDown' ? 1 : -1) + buttons.length) % buttons.length;
      buttons[next]?.focus();
    }
  }, { capture: true, signal: events.signal });
  document.addEventListener('scroll', event => {
    if (!menu.contains(event.target)) closeUtilityLoopSettingMenu(false);
  }, { capture: true, passive: true, signal: events.signal });
  window.addEventListener('resize', () => closeUtilityLoopSettingMenu(false), { signal: events.signal });
}

function updateUtilityLoopPlayerUi(loopId) {
  const id = String(loopId || '');
  const elements = getSavedLoopRangeElements(loopId);
  const audio = elements.audio;
  if (!audio) return;
  const playButton = document.querySelector(`[data-loop-play="${cssEscape(loopId || '')}"]`);
  const timeline = elements.timeline;
  const time = elements.playbackTime;
  const duration = Number(audio.duration) || Number(audio.dataset.loopDuration) || 0;
  const current = Number(audio.currentTime) || 0;
  if (timeline) {
    timeline.max = String(Math.max(duration, 0.1));
    timeline.value = String(Math.min(current, duration || current));
    timeline.style?.setProperty('--loop-progress', `${duration > 0 ? Math.min(100, current / duration * 100) : 0}%`);
  }
  updateUtilityLoopStereoWaveform(id, audio);
  const waveform = state.utility.savedLoopWaveforms?.[id];
  if (elements.canvas && waveform && state.utility.loopEditors?.[id]?.active) {
    drawCombinedLoopWaveform(elements.canvas, waveform, duration > 0 ? current / duration : 0);
  }
  if (time && !state.utility.loopEditors?.[id]?.active) {
    time.textContent = `${formatLoopTime(current)} / ${formatLoopTime(duration)}`;
  }
  if (playButton) {
    if (typeof usesMobilePageLayout === 'function' && usesMobilePageLayout()) {
      const glyph = audio.paused ? 'play' : 'pause';
      if (playButton.dataset.loopGlyph !== glyph) playButton.innerHTML = ButtonComponent.renderIconSvg(glyph);
      playButton.dataset.loopGlyph = glyph;
    } else {
      const icon = audio.paused ? '\u25B6' : '\u23F8';
      if (playButton.textContent !== icon) playButton.textContent = icon;
      delete playButton.dataset.loopGlyph;
    }
    playButton.setAttribute('aria-label', audio.paused ? 'Play' : 'Pause');
  }
}

const utilityLoopPitchPreviewRequestTokens = new WeakMap();

async function renderUtilityLoopPitchPreview(loopId, semitones) {
  const audio = document.querySelector(`[data-loop-audio="${cssEscape(loopId || '')}"]`);
  const pitchValue = document.querySelector(`[data-loop-pitch-control="${cssEscape(loopId || '')}"] [data-loop-pitch-value]`);
  if (!audio) return;
  const requestToken = Symbol('utility-loop-pitch-preview');
  utilityLoopPitchPreviewRequestTokens.set(audio, requestToken);
  const isLatestRequest = () => utilityLoopPitchPreviewRequestTokens.get(audio) === requestToken;
  const pitch = Math.max(-12, Math.min(12, Number(semitones) || 0));
  const wasPlayingWhenRequested = !audio.paused && !audio.ended;
  const previousPitch = audio.dataset.appliedPitch || '0';
  audio.dataset.pitch = String(pitch);
  audio.dataset.pitchPending = 'true';
  if (pitchValue) pitchValue.textContent = 'Rendering...';
  updateUtilityLoopAudioRate(loopId);
  try {
    const response = await fetch('/loops/pitch-preview', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ loop_id: loopId, semitones: pitch }),
    });
    const data = await response.json().catch(() => ({}));
    if (!isLatestRequest()) return;
    if (!response.ok || !data.ok) {
      throw new Error(data.error || 'Failed to render pitch preview');
    }
    const nextSrc = data.media_url || audio.dataset.originalSrc || '';
    audio.dataset.appliedPitch = String(pitch);
    const endedWhilePending = wasPlayingWhenRequested && audio.paused && audio.ended;
    const shouldResume = (!audio.paused && !audio.ended) || endedWhilePending;
    const previousTime = endedWhilePending
      ? 0
      : Math.max(0, Number(audio.currentTime) || 0);
    if (nextSrc && audio.getAttribute('src') !== nextSrc) {
      audio.addEventListener('loadedmetadata', () => {
        if (!isLatestRequest()) return;
        const duration = Number(audio.duration);
        audio.currentTime = Number.isFinite(duration) && duration >= 0
          ? Math.min(previousTime, duration)
          : previousTime;
        if (shouldResume) audio.play().catch(() => {});
      }, { once: true });
      audio.setAttribute('src', nextSrc);
      audio.load();
    } else if (shouldResume) {
      if (endedWhilePending) audio.currentTime = 0;
      audio.play().catch(() => {});
    }
  } catch (error) {
    if (!isLatestRequest()) return;
    audio.dataset.pitch = previousPitch;
    console.error('[AlbumHaven][Loops] Failed to render pitch preview.', error);
    showToast(error.message || 'Failed to render pitch preview.', 'error', 4200);
  } finally {
    if (isLatestRequest()) {
      delete audio.dataset.pitchPending;
      updateUtilityLoopAudioRate(loopId);
    }
  }
}

function getSavedLoopRangeElements(loopId) {
  const id = cssEscape(loopId || '');
  const root = document.querySelector(`[data-loop-range-owner="saved-loop-${id}"]`);
  const main = document.querySelector(`[data-saved-loop-main-surface="${id}"]`);
  return {
    root,
    main,
    actionRoot: document.querySelector(`[data-loop-action-owner="saved-loop-${id}"]`),
    audio: document.querySelector(`[data-loop-audio="${id}"]`),
    canvas: root?.querySelector('[data-loop-range-waveform]'),
    surface: root?.matches?.('[data-loop-range-surface]') ? root : root?.querySelector('[data-loop-range-surface]'),
    timeline: main?.querySelector('[data-loop-timeline]'),
    playbackTime: main?.querySelector('[data-loop-time]'),
    boundaryTimes: main?.querySelector('[data-loop-range-times]'),
  };
}

function getSavedLoopExpiryOwnerId(loopId) {
  return `saved-loop-${String(loopId || '')}`;
}

function noteSavedLoopWholeRangeWrap(loopId) {
  const id = String(loopId || '');
  if (!state.utility.loopEditors?.[id]?.active) return false;
  return loopEditSessionExpiryController.noteUntouchedWholeRangeWrap(
    getSavedLoopExpiryOwnerId(id),
  );
}

function noteSavedLoopWholeRangePlaybackProgress(loopId, audio) {
  if (!audio) return false;
  const currentSeconds = Math.max(0, Number(audio.currentTime) || 0);
  const previousSeconds = Math.max(0, Number(audio._loopEditPreviousTimeSeconds) || 0);
  const durationSeconds = getSavedLoopEditDuration(loopId);
  audio._loopEditPreviousTimeSeconds = currentSeconds;
  if (audio.paused || !Number.isFinite(durationSeconds) || durationSeconds <= 0) return false;
  const nearEndSeconds = Math.max(0, durationSeconds - Math.min(0.5, durationSeconds * 0.1));
  const nearStartSeconds = Math.min(0.5, durationSeconds * 0.1);
  const crossedNativeRepeatBoundary = Boolean(audio.loop)
    && previousSeconds >= durationSeconds / 2
    && currentSeconds < durationSeconds / 2
    && currentSeconds < previousSeconds;
  if (
    !crossedNativeRepeatBoundary
    && (previousSeconds < nearEndSeconds || currentSeconds > nearStartSeconds)
  ) return false;
  return noteSavedLoopWholeRangeWrap(loopId);
}

function getSavedLoopRangeDuration(loopId, elements = getSavedLoopRangeElements(loopId)) {
  const loop = (state.utility.loops || []).find((item) => String(item.id || '') === String(loopId || ''));
  const audioDuration = Number(elements.audio?.duration);
  const sourceDuration = Number(loop?.duration_seconds);
  if (Number.isFinite(audioDuration) && audioDuration > 0) {
    return Number.isFinite(sourceDuration) && sourceDuration > 0 ? Math.min(audioDuration, sourceDuration) : audioDuration;
  }
  return Number.isFinite(sourceDuration) ? Math.max(0, sourceDuration) : 0;
}

function getSavedLoopEditDuration(loopId, elements = getSavedLoopRangeElements(loopId)) {
  const id = String(loopId || '');
  const editor = state.utility.loopEditors?.[id];
  const frozenDuration = Number(editor?.durationSeconds);
  if ((editor?.active || state.utility.savedLoopEditorBusy?.[id])
      && Number.isFinite(frozenDuration) && frozenDuration > 0) {
    return frozenDuration;
  }
  return getSavedLoopRangeDuration(id, elements);
}

function setSavedLoopEditorBusy(loopId, busy) {
  const id = String(loopId || '');
  state.utility.savedLoopEditorBusy ||= {};
  if (busy) state.utility.savedLoopEditorBusy[id] = true;
  else delete state.utility.savedLoopEditorBusy[id];
  const actionRoot = getSavedLoopRangeElements(id).actionRoot;
  actionRoot?._loopActionController?.update({
    enabled: true, canCreate: state.loopCreateAllowed === true, active: Boolean(state.utility.loopEditors?.[id]?.active), busy: Boolean(busy),
  });
  actionRoot?.setAttribute('aria-busy', busy ? 'true' : 'false');
}

function syncSavedLoopRange(loopId, range) {
  const id = String(loopId || '');
  const elements = getSavedLoopRangeElements(id);
  const durationSeconds = getSavedLoopEditDuration(id, elements);
  let startSeconds = Math.max(0, Math.min(durationSeconds, Number(range?.startSeconds) || 0));
  let endSeconds = Math.max(0, Math.min(durationSeconds, Number(range?.endSeconds) || 0));
  if (startSeconds > endSeconds) [startSeconds, endSeconds] = [endSeconds, startSeconds];
  const minimum = Math.min(0.01, durationSeconds || 0.01);
  if (durationSeconds > 0 && endSeconds - startSeconds < minimum) {
    if (endSeconds + minimum <= durationSeconds) endSeconds += minimum;
    else startSeconds = Math.max(0, endSeconds - minimum);
  }
  const normalized = { startSeconds, endSeconds };
  state.utility.loopEditors ||= {};
  state.utility.loopEditors[id] = {
    ...(state.utility.loopEditors[id] || {}),
    ...normalized,
    durationSeconds,
  };
  if (elements.playbackTime) {
    elements.playbackTime.textContent = `${formatLoopTime(startSeconds, true)} - ${formatLoopTime(endSeconds, true)}`;
  }
  return state.utility.loopEditors[id];
}

function renewSavedLoopExpiryAfterBoundaryEdit(loopId, range) {
  const id = String(loopId || '');
  const editor = state.utility.loopEditors?.[id];
  if (!editor?.active) return false;
  const nextStart = Number(range?.startSeconds);
  const nextEnd = Number(range?.endSeconds);
  const startChanged = Number.isFinite(nextStart)
    && Math.abs(nextStart - Number(editor.startSeconds)) > 0.000001;
  const endChanged = Number.isFinite(nextEnd)
    && Math.abs(nextEnd - Number(editor.endSeconds)) > 0.000001;
  if (!startChanged && !endChanged) return false;
  return loopEditSessionExpiryController.renewAfterBoundaryEdit(
    getSavedLoopExpiryOwnerId(id),
  );
}

function expireSavedLoopCreation(loopId) {
  const id = String(loopId || '');
  if (!state.utility.loopEditors?.[id]?.active) return false;
  cancelSavedLoopCreation(id);
  const audio = getSavedLoopRangeElements(id).audio;
  if (audio && !audio.paused) audio.pause();
  updateUtilityLoopPlayerUi(id);
  return true;
}

function startSavedLoopExpirySession(loopId) {
  const id = String(loopId || '');
  loopEditSessionExpiryController.start({
    ownerId: getSavedLoopExpiryOwnerId(id),
    onExpire: () => expireSavedLoopCreation(id),
  });
}

function setSavedLoopEditMode(loopId, active) {
  const id = String(loopId || '');
  const elements = getSavedLoopRangeElements(id);
  const editor = state.utility.loopEditors?.[id] || syncSavedLoopRange(id, {
    startSeconds: 0, endSeconds: getSavedLoopRangeDuration(id, elements),
  });
  editor.active = Boolean(active);
  elements.main?.classList.toggle('is-loop-editing', editor.active);
  if (elements.surface) elements.surface.hidden = !editor.active;
  if (elements.timeline) elements.timeline.hidden = false;
  if (elements.playbackTime) elements.playbackTime.hidden = false;
  if (elements.boundaryTimes) elements.boundaryTimes.hidden = true;
  elements.actionRoot?._loopActionController?.update({
    enabled: true,
    canCreate: state.loopCreateAllowed === true,
    active: editor.active,
    busy: Boolean(state.utility.savedLoopEditorBusy?.[id]),
  });
  elements.actionRoot?.setAttribute('data-loop-action-state', editor.active ? 'editing' : 'idle');
  const reconciledRange = elements.root?._loopRangeController?.render(editor);
  if (reconciledRange) syncSavedLoopRange(id, reconciledRange);
  if (!editor.active) updateUtilityLoopPlayerUi(id);
}

function cancelSavedLoopCreation(loopId) {
  const id = String(loopId || '');
  loopEditSessionExpiryController.stop(getSavedLoopExpiryOwnerId(id));
  state.utility.savedLoopOpenEpoch ||= {};
  state.utility.savedLoopOpenEpoch[id] = (Number(state.utility.savedLoopOpenEpoch[id]) || 0) + 1;
  setSavedLoopEditMode(id, false);
  if (state.utility.savedLoopWaveforms) delete state.utility.savedLoopWaveforms[id];
}

function cancelActiveSavedLoopCreation() {
  const activeEditor = Object.entries(state.utility.loopEditors || {})
    .find(([, editor]) => Boolean(editor?.active));
  if (!activeEditor) return false;
  cancelSavedLoopCreation(activeEditor[0]);
  return true;
}

function handleSavedLoopEditKeydown(event) {
  if (
    !event
    || event.key !== 'Enter'
    || event.defaultPrevented
    || event.isComposing
    || event.repeat
    || event.altKey
    || event.ctrlKey
    || event.metaKey
    || event.shiftKey
    || state.utility.activeTab !== 'loops'
  ) return false;
  const utilityOverlay = getUtilityModalElements()?.overlay;
  if (!utilityOverlay || utilityOverlay.hidden) return false;
  const activeEditor = Object.entries(state.utility.loopEditors || {})
    .find(([, editor]) => Boolean(editor?.active));
  if (!activeEditor) return false;
  const target = event.target instanceof HTMLElement ? event.target : null;
  const tagName = String(target?.tagName || '').toUpperCase();
  const inputType = String(target?.getAttribute?.('type') || target?.type || '').toLowerCase();
  const rangeHandle = target?.getAttribute?.('data-loop-range-handle');
  const nativeAction = ['BUTTON', 'A', 'SELECT'].includes(tagName)
    || (tagName === 'INPUT' && inputType !== 'range')
    || Boolean(target?.closest?.('button:not([data-loop-range-handle]), a, select, [role="button"], [role="menuitem"]'));
  if (nativeAction && !rangeHandle) return false;
  const isTextEntry = tagName === 'TEXTAREA'
    || Boolean(target?.isContentEditable)
    || (tagName === 'INPUT'
      && !['button', 'checkbox', 'color', 'file', 'hidden', 'radio', 'range', 'reset', 'submit'].includes(inputType));
  const targetDialog = target?.closest?.('[role="dialog"], dialog, [aria-modal="true"]') || null;
  if (isTextEntry || (targetDialog && !utilityOverlay.contains?.(target))) return false;
  event.preventDefault();
  event.stopPropagation?.();
  void createLoopFromSavedLoop(activeEditor[0]);
  return true;
}

function mountSavedLoopControls(loopId) {
  const id = String(loopId || '');
  const elements = getSavedLoopRangeElements(id);
  if (!elements.root || !elements.actionRoot) return elements;
  if (!elements.actionRoot._loopActionController) {
    elements.actionRoot._loopActionController = mountLoopEditActionControl({
      root: elements.actionRoot,
      enabled: true,
      canCreate: state.loopCreateAllowed === true,
      active: Boolean(state.utility.loopEditors?.[id]?.active),
      busy: Boolean(state.utility.savedLoopEditorBusy?.[id]),
      onEnter: () => openSavedLoopCreation(id),
      onCreate: () => createLoopFromSavedLoop(id),
      onCancel: () => cancelSavedLoopCreation(id),
    });
    elements.actionRoot.dataset.loopActionsBound = '1';
  }
  if (!elements.root._loopRangeController) {
    elements.root._loopRangeController = createLoopRangeController({
      root: elements.root,
      getDuration: () => getSavedLoopEditDuration(id),
      getRange: () => state.utility.loopEditors?.[id] || {
        startSeconds: 0, endSeconds: getSavedLoopEditDuration(id),
      },
      onRangeInteractionStart: () => {
        loopEditSessionExpiryController.renewAfterBoundaryEdit(`saved-loop-${id}`);
      },
      onRangePreview: (range) => {
        renewSavedLoopExpiryAfterBoundaryEdit(id, range);
        syncSavedLoopRange(id, range);
      },
      onRangeCommit: (range) => {
        renewSavedLoopExpiryAfterBoundaryEdit(id, range);
        syncSavedLoopRange(id, range);
      },
      onSeek: (seconds) => {
        if (!elements.audio) return;
        elements.audio.currentTime = Math.max(0, Math.min(
          getSavedLoopEditDuration(id),
          Number(seconds) || 0,
        ));
        elements.audio._loopEditPreviousTimeSeconds = elements.audio.currentTime;
        updateUtilityLoopPlayerUi(id);
      },
      onCancel: () => cancelSavedLoopCreation(id),
    });
  }
  setSavedLoopEditMode(id, Boolean(state.utility.loopEditors?.[id]?.active));
  return elements;
}

async function openSavedLoopCreation(loopId) {
  if (state.loopCreateAllowed === false) return;
  const id = String(loopId || '');
  const loop = (state.utility.loops || []).find((item) => String(item.id || '') === id);
  if (!loop || state.utility.savedLoopEditorBusy?.[id]) return false;
  state.utility.savedLoopOpenEpoch ||= {};
  const openEpoch = (Number(state.utility.savedLoopOpenEpoch[id]) || 0) + 1;
  state.utility.savedLoopOpenEpoch[id] = openEpoch;
  const sessionDurationSeconds = getSavedLoopRangeDuration(id);
  state.utility.loopEditors ||= {};
  state.utility.loopEditors[id] = {
    ...(state.utility.loopEditors[id] || {}),
    durationSeconds: sessionDurationSeconds,
  };
  setSavedLoopEditorBusy(id, true);
  let elements = null;
  try {
    elements = mountSavedLoopControls(id);
    syncSavedLoopRange(id, { startSeconds: 0, endSeconds: sessionDurationSeconds });
    const mountedActionController = elements.actionRoot?._loopActionController;
    const waveform = await loadSavedLoopWaveformPeaks(id);
    if (elements.actionRoot?._loopActionController !== mountedActionController) return false;
    if (!waveform) throw new Error('Failed to load saved loop waveform.');
    if (state.utility.savedLoopOpenEpoch[id] !== openEpoch
        || (typeof getUtilityModalElements === 'function' && getUtilityModalElements()?.overlay?.hidden)
        || (state.utility.activeTab && state.utility.activeTab !== 'loops')) return false;
    const currentElements = getSavedLoopRangeElements(id);
    if (currentElements.root !== elements.root) {
      elements = mountSavedLoopControls(id);
      if (!elements.root) return false;
      syncSavedLoopRange(id, state.utility.loopEditors[id]);
    }
    state.utility.savedLoopWaveforms ||= {};
    state.utility.savedLoopWaveforms[id] = waveform;
    const audioDuration = Number(elements.audio?.duration) || sessionDurationSeconds;
    const currentTime = Number(elements.audio?.currentTime) || 0;
    drawCombinedLoopWaveform(elements.canvas, waveform, audioDuration > 0 ? currentTime / audioDuration : 0);
    elements.root?._loopRangeController?.render(state.utility.loopEditors[id]);
    setSavedLoopEditMode(id, true);
    startSavedLoopExpirySession(id);
    return true;
  } catch (error) {
    if (state.utility.savedLoopOpenEpoch[id] !== openEpoch
        || (typeof getUtilityModalElements === 'function' && getUtilityModalElements()?.overlay?.hidden)
        || (state.utility.activeTab && state.utility.activeTab !== 'loops')) return false;
    setSavedLoopEditMode(id, false);
    console.error('[AlbumHaven][Loops] Failed to open saved-loop editor.', error);
    showToast(error.message || 'Failed to open loop editor.', 'error', 4200);
    return false;
  } finally {
    setSavedLoopEditorBusy(id, false);
  }
}

async function createLoopFromSavedLoop(loopId) {
  if (state.loopCreateAllowed === false) return;
  const loop = (state.utility.loops || []).find((item) => String(item.id || '') === String(loopId || ''));
  if (!loop) return;
  const id = String(loopId || '');
  if (state.utility.savedLoopEditorBusy?.[id]) return;
  const pendingRange = state.utility.loopEditors?.[id];
  if (pendingRange?.active) {
    const pendingStart = Number(pendingRange.startSeconds);
    const pendingEnd = Number(pendingRange.endSeconds);
    if (!Number.isFinite(pendingStart) || !Number.isFinite(pendingEnd)
        || pendingStart < 0 || pendingEnd <= pendingStart) {
      showToast('Enter a valid loop start and end.', 'error', 3200);
      return;
    }
  }
  const elements = mountSavedLoopControls(id);
  if (!state.utility.loopEditors?.[id]?.active) return openSavedLoopCreation(id);
  const startSeconds = Number(state.utility.loopEditors[id].startSeconds);
  const endSeconds = Number(state.utility.loopEditors[id].endSeconds);
  const duration = getSavedLoopRangeDuration(loopId, elements);
  if (!Number.isFinite(startSeconds) || !Number.isFinite(endSeconds)
      || startSeconds < 0 || endSeconds > duration || endSeconds <= startSeconds) {
    showToast('Enter a valid loop start and end.', 'error', 3200);
    return;
  }
  setSavedLoopEditorBusy(id, true);
  try {
    const name = String(await showLoopNameDialog() || '').trim();
    if (!name) return;
    const response = await fetch('/loops/create', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        name,
        source_loop_id: loop.id,
        start_seconds: startSeconds,
        end_seconds: endSeconds,
      }),
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok || !data.ok) throw new Error(data.error || 'Failed to save loop');
    state.utility.loopMutationGeneration = Number(state.utility.loopMutationGeneration || 0) + 1;
    state.utility.loops = Array.isArray(data.loops) ? data.loops : state.utility.loops;
    state.utility.selectedLoopId = String(data.loop?.id || state.utility.selectedLoopId || '');
    state.utility.selectedLoopGroupKey = data.loop ? buildUtilityLoopGroupKey(data.loop) : state.utility.selectedLoopGroupKey;
    state.utility.selectedLoopDetailMode = 'group';
    state.utility.loopsLoaded = true;
    setSavedLoopEditMode(id, false);
    loopEditSessionExpiryController.stop(getSavedLoopExpiryOwnerId(id));
    renderUtilityModalContent();
    showToast('Loop saved.', 'success', 2600);
  } catch (error) {
    console.error('[AlbumHaven][Loops] Failed to create loop from saved loop.', error);
    showToast(error.message || 'Failed to create loop.', 'error', 4200);
  } finally {
    setSavedLoopEditorBusy(id, false);
  }
}

async function deleteSavedLoop(loopId, { confirmed = false } = {}) {
  const id = String(loopId || '');
  if (!id || state.utility.allowedActions?.['library.loops.delete'] === false) return false;
  const loop = (state.utility.loops || []).find((item) => String(item.id || '') === id);
  if (!loop) return false;
  const deletedGroupKey = loop ? buildUtilityLoopGroupKey(loop) : '';
  const name = loop?.name || 'this loop';
  if (!confirmed && !await showLoopDeleteConfirmDialog(name)) return false;
  const audio = document.querySelector(`[data-loop-audio="${cssEscape(id)}"]`);
  audio?.pause();
  try {
    const response = await fetch('/loops/delete', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ loop_id: id }),
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok || !data.ok) throw new Error(data.error || 'Failed to remove loop');
    loopEditSessionExpiryController.stop(getSavedLoopExpiryOwnerId(id));
    state.utility.loopMutationGeneration = Number(state.utility.loopMutationGeneration || 0) + 1;
    state.utility.loops = Array.isArray(data.loops) ? data.loops : (state.utility.loops || []).filter((item) => String(item.id || '') !== id);
    state.utility.loopsLoaded = true;
    const replacementInGroup = deletedGroupKey
      ? (state.utility.loops || []).find((item) => buildUtilityLoopGroupKey(item) === deletedGroupKey)
      : null;
    state.utility.selectedLoopId = String(replacementInGroup?.id || state.utility.loops[0]?.id || '');
    state.utility.selectedLoopGroupKey = String(replacementInGroup ? buildUtilityLoopGroupKey(replacementInGroup) : groupUtilityLoops(state.utility.loops || [])[0]?.key || '');
    state.utility.selectedLoopDetailMode = 'group';
    renderUtilityModalContent();
    showToast('Loop removed.', 'success', 2400);
    return true;
  } catch (error) {
    console.error('[AlbumHaven][Loops] Failed to remove loop.', error);
    showToast(error.message || 'Failed to remove loop.', 'error', 4200);
    return false;
  }
}

function getUtilityLoopOrderScope(songKey, loops = state.utility.loops || []) {
  const members = loops.filter(loop => loop.song_key === songKey);
  const revision = members[0]?.order_revision;
  if (!members.length || !members.every(loop => canReorderUtilityLoop(loop) && loop.order_revision === revision)) return null;
  return { songKey, revision, loops: members };
}

function replaceUtilityLoopSong(loops, songKey, members) {
  const next = [];
  let inserted = false;
  for (const loop of loops) {
    if (loop.song_key !== songKey) next.push(loop);
    else if (!inserted) { next.push(...members); inserted = true; }
  }
  if (!inserted) next.push(...members);
  return next;
}

function buildReorderedUtilityLoops(loops, draggedItem, targetItem, position) {
  if (!['before', 'after'].includes(position) || draggedItem?.type !== 'loop' || targetItem?.type !== 'loop') return null;
  const songKey = String(draggedItem.groupKey || '');
  if (!songKey || songKey !== targetItem.groupKey || draggedItem.id === targetItem.id) return null;
  const scope = getUtilityLoopOrderScope(songKey, loops);
  if (!scope) return null;
  const members = scope.loops.slice();
  const from = members.findIndex(loop => String(loop.id) === String(draggedItem.id));
  if (from < 0 || !members.some(loop => String(loop.id) === String(targetItem.id))) return null;
  const [moving] = members.splice(from, 1);
  const to = members.findIndex(loop => String(loop.id) === String(targetItem.id));
  members.splice(to + (position === 'after' ? 1 : 0), 0, moving);
  if (members.every((loop, index) => loop.id === scope.loops[index].id)) return null;
  return replaceUtilityLoopSong(loops, songKey, members);
}

function captureUtilityLoopOrderView(songKey) {
  const els = getUtilityModalElements();
  return { songKey, panel: els.detail?.querySelector('.utility-loop-entry-list'), detail: els.detail,
    generation: Number(state.utility.loopViewGeneration || 0) };
}

function isUtilityLoopOrderViewCurrent(view) {
  const els = getUtilityModalElements();
  return state.utility.activeTab === 'loops' && !els.overlay?.hidden
    && String(state.utility.selectedLoopGroupKey || '') === view.songKey
    && Number(state.utility.loopViewGeneration || 0) === view.generation
    && view.panel && els.detail === view.detail
    && els.detail?.querySelector('.utility-loop-entry-list') === view.panel;
}

function createUtilityLoopMarkupNode(html) {
  const host = document.createElement('div');
  host.innerHTML = html;
  return host.firstElementChild;
}

function moveUtilityLoopNode(parent, node, before = null) {
  if (node === before || (node.parentNode === parent && node.nextElementSibling === before)) return;
  if (typeof parent.moveBefore === 'function' && node.parentNode === parent) {
    parent.moveBefore(node, before);
    return;
  }
  // Native media retains playback across this synchronous move; do not seek or restart it.
  parent.insertBefore(node, before);
}

function reconcileUtilityLoopOrderView(view, members) {
  if (!isUtilityLoopOrderViewCurrent(view)) return;
  const els = getUtilityModalElements();
  const focused = document.activeElement;
  const scrolls = [els.list, els.detail].filter(Boolean).map(node => [node, node.scrollTop]);
  const before = new Map(Array.from(view.panel.children, node => [node, node.getBoundingClientRect().top]));
  const ids = new Set(members.map(loop => String(loop.id)));
  const panels = new Map(Array.from(view.panel.querySelectorAll('[data-utility-loop-entry]'), node => [node.getAttribute('data-utility-loop-entry'), node]));
  for (const [id, node] of panels) {
    if (ids.has(id)) continue;
    if (typeof disposeMountedLoopActions === 'function') disposeMountedLoopActions(node);
    if (typeof loopEditSessionExpiryController !== 'undefined') loopEditSessionExpiryController.stop(`saved-loop-${id}`);
    node.querySelector('[data-loop-audio]')?.pause();
    node.remove();
    delete state.utility.loopEditors?.[id];
  }
  let panelCursor = view.panel.firstElementChild;
  for (const loop of members) {
    const id = String(loop.id);
    const node = panels.get(id) || createUtilityLoopMarkupNode(buildUtilityLoopEntry(loop));
    if (!node) continue;
    moveUtilityLoopNode(view.panel, node, panelCursor);
    panelCursor = node.nextElementSibling;
    if (!panels.has(id)) initializeUtilityLoopPlayer(loop);
  }
  const treeChildren = Array.from(els.list?.querySelectorAll('[data-utility-loop-id]') || [])
    .filter(node => node.getAttribute('data-utility-loop-group-key') === view.songKey);
  const treeParent = treeChildren[0]?.parentNode || Array.from(els.list?.querySelectorAll('[data-loop-tree-song]') || [])
    .find(node => node.getAttribute('data-loop-tree-song') === view.songKey);
  if (treeParent) {
    const existing = new Map(treeChildren.map(node => [node.getAttribute('data-utility-loop-id'), node]));
    const visibleIds = new Set(getFilteredUtilityLoops().map(loop => String(loop.id)));
    for (const [id, node] of existing) if (!ids.has(id) || !visibleIds.has(id)) node.remove();
    let treeCursor = treeParent.firstElementChild;
    for (const loop of members) {
      if (!visibleIds.has(String(loop.id))) continue;
      const node = existing.get(String(loop.id)) || createUtilityLoopMarkupNode(buildUtilityLoopTreeChild(loop, view.songKey));
      if (node) {
        moveUtilityLoopNode(treeParent, node, treeCursor);
        treeCursor = node.nextElementSibling;
      }
    }
  }
  if (!(typeof matchMedia === 'function' && matchMedia('(prefers-reduced-motion: reduce)').matches)) {
    for (const node of Array.from(view.panel.children)) {
      const delta = before.has(node) ? before.get(node) - node.getBoundingClientRect().top : 0;
      if (delta) node.animate?.([{ transform: `translateY(${delta}px)` }, { transform: 'translateY(0)' }], { duration: 220, easing: 'ease-out' });
    }
  }
  if (focused && document.activeElement !== focused && els.overlay?.contains?.(focused)) focused.focus?.({ preventScroll: true });
  scrolls.forEach(([node, scrollTop]) => { node.scrollTop = scrollTop; });
  syncUtilityLoopPanelVisibility();
  bindUtilityLoopDragAndDrop();
  syncUtilityLoopMoveButtons();
}

function normalizeUtilityLoopOrderResponse(data, songKey) {
  if (data?.song_key !== songKey || !Number.isSafeInteger(data.order_revision) || data.order_revision < 0
      || !Array.isArray(data.ordered_ids) || !Array.isArray(data.loops)) return null;
  const ids = data.ordered_ids;
  if (ids.some(id => typeof id !== 'string' || !id) || new Set(ids).size !== ids.length || data.loops.length !== ids.length) return null;
  const byId = new Map(data.loops.map(loop => [String(loop?.id || ''), loop]));
  if (byId.size !== ids.length || ids.some(id => !byId.has(id) || byId.get(id).song_key !== songKey)) return null;
  return ids.map(id => ({ ...byId.get(id), order_revision: data.order_revision }));
}

async function moveUtilityLoop(loopId, direction) {
  if (!['up', 'down'].includes(direction)) return false;
  const loop = (state.utility.loops || []).find(item => String(item.id) === String(loopId));
  const scope = loop && getUtilityLoopOrderScope(loop.song_key);
  if (!scope) return false;
  const index = scope.loops.findIndex(item => item.id === loop.id);
  const target = scope.loops[index + (direction === 'up' ? -1 : 1)];
  if (!target) return false;
  return reorderUtilityLoops({ type: 'loop', id: loop.id, groupKey: scope.songKey },
    { type: 'loop', id: target.id, groupKey: scope.songKey }, direction === 'up' ? 'before' : 'after');
}

async function reorderUtilityLoops(draggedItem, targetItem, position) {
  const previousLoops = (state.utility.loops || []).slice();
  const nextLoops = buildReorderedUtilityLoops(previousLoops, draggedItem, targetItem, position);
  if (!nextLoops) return false;
  const songKey = String(draggedItem.groupKey);
  const scope = getUtilityLoopOrderScope(songKey, previousLoops);
  state.utility.loopOrderPending ||= {};
  if (state.utility.loopOrderPending[songKey]) return false;
  const utilityOwner = state.utility;
  const dataGeneration = Number(utilityOwner.loopDataGeneration || 0);
  utilityOwner.loopMutationGeneration = Number(utilityOwner.loopMutationGeneration || 0) + 1;
  const ownsCache = () => state.utility === utilityOwner && Number(state.utility.loopDataGeneration || 0) === dataGeneration;
  const token = {};
  state.utility.loopOrderPending[songKey] = token;
  const view = captureUtilityLoopOrderView(songKey);
  const ordered = nextLoops.filter(loop => loop.song_key === songKey);
  state.utility.loops = nextLoops;
  reconcileUtilityLoopOrderView(view, ordered);
  try {
    const response = await fetch('/loops/reorder', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        song_key: songKey, expected_revision: scope.revision,
        ordered_ids: ordered.map(loop => String(loop.id)),
      }),
    });
    const data = await response.json().catch(() => ({}));
    const authoritative = normalizeUtilityLoopOrderResponse(data, songKey);
    if ((!response.ok || !data.ok) && response.status !== 409) throw new Error(data.error || 'Failed to reorder loops');
    if (!authoritative) throw new Error('Unable to reconcile saved loop order. Reload Loops and try again.');
    const currentRevision = (state.utility.loops || []).find(loop => loop.song_key === songKey)?.order_revision;
    if (ownsCache() && Number.isSafeInteger(currentRevision) && data.order_revision >= currentRevision) {
      state.utility.loops = replaceUtilityLoopSong(state.utility.loops || [], songKey, authoritative);
      reconcileUtilityLoopOrderView(view, authoritative);
    }
    if (response.status === 409) showToast('Loop order changed. The latest order is shown; try your move again.', 'error', 4200);
    return response.ok && data.ok === true;
  } catch (error) {
    const current = (state.utility.loops || []).filter(loop => loop.song_key === songKey);
    if (ownsCache() && current.length && current.every(loop => loop.order_revision === scope.revision)) {
      state.utility.loops = replaceUtilityLoopSong(state.utility.loops || [], songKey, scope.loops);
      reconcileUtilityLoopOrderView(view, scope.loops);
    }
    showToast(error.message || 'Failed to reorder loops.', 'error', 4200);
    return false;
  } finally {
    if (utilityOwner.loopOrderPending[songKey] === token) delete utilityOwner.loopOrderPending[songKey];
    syncUtilityLoopMoveButtons();
    clearUtilityLoopDragState();
    syncUtilityLoopDragUi();
  }
}

// END js/runtime/utility-loop-playback.js

// BEGIN js/runtime/tag-editor-reorder.js

function getTagEditorReorderInsertionBefore(rows, draggedPath, clientY) {
  const dragged = String(draggedPath || '');
  const pointerY = Number(clientY);
  return (Array.isArray(rows) ? rows : [])
    .filter((row) => String(row?.path || '') !== dragged)
    .find((row) => pointerY < Number(row?.top || 0) + (Number(row?.height || 0) / 2))
    ?.path || null;
}

function reorderTagEditorTracksByPath(tracks, draggedPath, beforePath = null) {
  const current = Array.isArray(tracks) ? tracks : [];
  const dragged = String(draggedPath || '');
  const sourceIndex = current.findIndex((track) => String(track?.path || '') === dragged);
  if (sourceIndex < 0) return current.slice();
  const next = current.slice();
  const [moved] = next.splice(sourceIndex, 1);
  const target = String(beforePath || '');
  const targetIndex = target
    ? next.findIndex((track) => String(track?.path || '') === target)
    : next.length;
  next.splice(targetIndex < 0 ? next.length : targetIndex, 0, moved);
  return next;
}

// END js/runtime/tag-editor-reorder.js

// BEGIN js/runtime/utility-loaders-and-cover-lookup.js

async function loadProblematicFiles(force = false, options = {}) {
  const shouldRender = () => options.render !== false && state.utility.activeTab === 'problematic-files';
  const shouldRenderInitialPage = () => (
    options.renderInitialPage === true
    && state.utility.activeTab === 'problematic-files'
    && !String(state.utility.searchQuery || '').trim()
    && !(state.utility.selectedProblemFilters || []).length
  );
  const canRenderBoundedPage = () => (
    !String(state.utility.searchQuery || '').trim()
    && !(state.utility.selectedProblemFilters || []).length
  );
  const navigationOwnsRendering = () => Boolean(
    state.utility.problematicNavigationActiveToken,
  );
  if (state.utility.loading) {
    const pendingLoad = state.utility.loadPromise;
    const result = await pendingLoad;
    if (pendingLoad && !state.utility.loaded
      && pendingLoad.problematicSummaryRequestToken !== Number(state.utility.problematicSummaryRequestToken || 0)) {
      return loadProblematicFiles(force, options);
    }
    return result;
  }
  if (state.utility.loaded && !force) {
    if (shouldRender() && !navigationOwnsRendering()) renderUtilityModalContent();
    return;
  }
  state.utility.loading = true;
  state.utility.problematicFilesComplete = false;
  const requestToken = Number(state.utility.problematicSummaryRequestToken || 0) + 1;
  state.utility.problematicSummaryRequestToken = requestToken;
  if (shouldRender() && !navigationOwnsRendering()) renderUtilityModalContent();
  let requestPromise = null;
  requestPromise = (async () => {
    const startedAt = getProblematicUtilityNow();
    let requestMs = 0;
    let parseMs = 0;
    let stateCommitMs = 0;
    let initialDetailKey = '';
    let initialDetailMerged = false;
    let responseStatus = 0;
    let loadSucceeded = false;
    let loadError = '';
    let boundedPayloadCommitted = false;
    try {
      const fetchSummary = async (url) => {
        const requestStartedAt = getProblematicUtilityNow();
        const response = await fetch(url, { headers: { Accept: 'application/json' } });
        requestMs += roundProblematicUtilityMs(getProblematicUtilityNow() - requestStartedAt);
        responseStatus = Number(response.status || 0);
        const parseStartedAt = getProblematicUtilityNow();
        let data;
        try {
          data = await response.json();
        } finally {
          parseMs += roundProblematicUtilityMs(getProblematicUtilityNow() - parseStartedAt);
        }
        if (!response.ok) {
          throw new Error(readProblematicPayloadError(data, 'Unable to load problematic files.'));
        }
        return data;
      };
      const commitSummary = (data, preserveSelectedDetail) => {
        const { summaryItems, initialDetail, operationalItems } = validateProblematicSummaryPayload(data);
        const stateCommitStartedAt = getProblematicUtilityNow();
        initialDetailKey = String(initialDetail?.key || '').trim();
        const selectedKey = String(state.utility.selectedProblematicKey || '');
        const selectedDetail = preserveSelectedDetail
          ? state.utility.problematicFiles.find(item => item.key === selectedKey && item.detail_loaded === true)
          : null;
        const selectedSummary = selectedDetail && selectedKey !== initialDetailKey
          ? summaryItems.find(item => item.key === selectedKey) : null;
        initialDetailMerged = false;
        state.utility.problematicFiles = summaryItems.map((item) => {
          if (initialDetailKey && String(item?.key || '').trim() === initialDetailKey) {
            initialDetailMerged = true;
            return { ...item, ...initialDetail, detail_loaded: true };
          }
          return item === selectedSummary ? selectedDetail : item;
        });
        state.utility.libraryWatchHealthProblems = operationalItems;
        state.utility.detailLoadPromises = {};
        state.utility.loaded = true;
        stateCommitMs += roundProblematicUtilityMs(getProblematicUtilityNow() - stateCommitStartedAt);
        return { selectedKey, selectedDetail, selectedSummary };
      };

      let data = await fetchSummary('/utilities/problematic-files?limit=50');
      if (Number(state.utility.problematicSummaryRequestToken || 0) !== requestToken) return null;
      let committedSelection = commitSummary(data, options.preserveSelectedDetail === true);
      boundedPayloadCommitted = data.complete === false;
      if (boundedPayloadCommitted) {
        state.utility.problematicFilesComplete = false;
        const completePayloadPromise = fetchSummary('/utilities/problematic-files');
        if (canRenderBoundedPage()
            && ((shouldRender() && !navigationOwnsRendering()) || shouldRenderInitialPage())) {
          renderUtilityModalContent();
          await waitForProblematicUtilityRenderFrame();
        }
        data = await completePayloadPromise;
        if (Number(state.utility.problematicSummaryRequestToken || 0) !== requestToken) return null;
        committedSelection = commitSummary(data, true);
      }
      state.utility.problematicFilesComplete = true;
      loadSucceeded = true;
      const { selectedKey, selectedDetail, selectedSummary } = committedSelection;
      if (selectedSummary) {
        const detailRequest = loadProblematicAlbumDetail(selectedKey, true, { render: false });
        const detailRequestToken = Number(state.utility.problematicDetailRequestToken || 0);
        const refreshedDetail = await detailRequest;
        if (Number(state.utility.problematicSummaryRequestToken || 0) !== requestToken) return null;
        if (!refreshedDetail) {
          const stillOwnsDetail = Number(state.utility.problematicDetailRequestToken || 0) === detailRequestToken;
          // Discard retained stale detail, but never replace a newer navigation result.
          state.utility.problematicFiles = state.utility.problematicFiles.map(item => (
            item.key === selectedKey && (item === selectedDetail || stillOwnsDetail)
              ? { ...selectedSummary, detail_load_failed: stillOwnsDetail && state.utility.selectedProblematicKey === selectedKey }
              : item
          ));
        }
      }
      return state.utility.problematicFiles;
    } catch (error) {
      if (Number(state.utility.problematicSummaryRequestToken || 0) !== requestToken) return null;
      loadError = String(error?.message || error || 'Unable to load problematic files.');
      console.error('[AlbumHaven][Utilities] Failed to load problematic files.', error);
      if (!boundedPayloadCommitted) {
        state.utility.problematicFiles = [];
        state.utility.libraryWatchHealthProblems = [];
        state.utility.detailLoadPromises = {};
      }
      state.utility.loaded = false;
      state.utility.problematicFilesComplete = false;
      showToast('Unable to load problematic files.', 'error', 3200);
      return null;
    } finally {
      const stillOwner = Number(state.utility.problematicSummaryRequestToken || 0) === requestToken;
      // A mutation can invalidate payload ownership while this request still
      // owns the loading slot. Release that slot without touching a newer load.
      if (state.utility.loadPromise === requestPromise) {
        state.utility.loading = false;
        state.utility.loadPromise = null;
      }
      if (state.utility.completeLoadPromise === requestPromise) {
        state.utility.completeLoadPromise = null;
      }
      if (stillOwner) {
        const renderStartedAt = getProblematicUtilityNow();
        if (shouldRender() && !navigationOwnsRendering()) {
          renderUtilityModalContent();
          await waitForProblematicUtilityRenderFrame();
        }
        recordProblematicUtilityDiagnostics('summary', {
          itemCount: Array.isArray(state.utility.problematicFiles) ? state.utility.problematicFiles.length : 0,
          ok: loadSucceeded,
          status: responseStatus,
          error: loadError || null,
          initialDetailKey,
          initialDetailMerged,
          requestMs,
          parseMs,
          stateCommitMs,
          renderMs: roundProblematicUtilityMs(getProblematicUtilityNow() - renderStartedAt),
          totalMs: roundProblematicUtilityMs(getProblematicUtilityNow() - startedAt),
        });
      }
    }
  })();
  requestPromise.problematicSummaryRequestToken = requestToken;
  state.utility.loadPromise = requestPromise;
  state.utility.completeLoadPromise = requestPromise;
  return requestPromise;
}

async function waitForProblematicFilesComplete() {
  if (state.utility.problematicFilesComplete !== false) return true;
  const pending = state.utility.completeLoadPromise || state.utility.loadPromise;
  if (!pending) return false;
  await pending;
  return state.utility.problematicFilesComplete === true;
}

async function loadProblematicAlbumDetail(albumKey, force = false, options = {}) {
  const normalizedKey = String(albumKey || '').trim();
  if (!normalizedKey) return null;
  const currentAlbum = (state.utility.problematicFiles || []).find((item) => String(item?.key || '') === normalizedKey) || null;
  if (currentAlbum?.detail_loaded === true && !force) {
    return currentAlbum;
  }
  if (currentAlbum?.detail_load_failed === true && !force) {
    return null;
  }
  const existingPromise = state.utility.detailLoadPromises?.[normalizedKey];
  if (
    existingPromise
    && Number(existingPromise.problematicDetailRequestToken || 0)
      === Number(state.utility.problematicDetailRequestToken || 0)
  ) {
    return existingPromise;
  }
  const requestToken = Number(state.utility.problematicDetailRequestToken || 0) + 1;
  state.utility.problematicDetailRequestToken = requestToken;
  const nextPromise = Promise.resolve().then(async () => {
    const startedAt = getProblematicUtilityNow();
    let requestMs = 0;
    let parseMs = 0;
    let stateCommitMs = 0;
    let responseStatus = 0;
    let loadSucceeded = false;
    let loadError = '';
    try {
      const requestStartedAt = getProblematicUtilityNow();
      const response = await fetch(`/utilities/problematic-files/detail?album_key=${encodeURIComponent(normalizedKey)}`, {
        headers: { Accept: 'application/json' },
      });
      requestMs = roundProblematicUtilityMs(getProblematicUtilityNow() - requestStartedAt);
      responseStatus = Number(response.status || 0);
      const parseStartedAt = getProblematicUtilityNow();
      let data;
      try {
        data = await response.json();
      } finally {
        parseMs = roundProblematicUtilityMs(getProblematicUtilityNow() - parseStartedAt);
      }
      if (!response.ok && options.allowMissing === true && responseStatus === 404) {
        return null;
      }
      if (!response.ok) {
        throw new Error(readProblematicPayloadError(data, 'Unable to load problematic album detail.'));
      }
      const detail = validateProblematicDetailPayload(data, normalizedKey);
      if (
        state.utility.detailLoadPromises?.[normalizedKey] !== nextPromise
        || Number(state.utility.problematicDetailRequestToken || 0) !== requestToken
        || String(state.utility.selectedProblematicKey || '') !== normalizedKey
      ) return null;
      const stateCommitStartedAt = getProblematicUtilityNow();
      state.utility.problematicFiles = (state.utility.problematicFiles || []).map((item) => (
        String(item?.key || '') === normalizedKey
          ? {
            ...item,
            ...detail,
            detail_loaded: true,
            detail_load_failed: false,
          }
          : item
      ));
      loadSucceeded = true;
      stateCommitMs = roundProblematicUtilityMs(getProblematicUtilityNow() - stateCommitStartedAt);
      return (state.utility.problematicFiles || []).find((item) => String(item?.key || '') === normalizedKey) || null;
    } catch (error) {
      if (Number(state.utility.problematicDetailRequestToken || 0) !== requestToken) return null;
      loadError = String(error?.message || error || 'Unable to load problematic album detail.');
      console.error('[AlbumHaven][Utilities] Failed to load problematic album detail.', error);
      if (state.utility.detailLoadPromises?.[normalizedKey] === nextPromise) {
        state.utility.problematicFiles = (state.utility.problematicFiles || []).map((item) => (
          String(item?.key || '') === normalizedKey
            ? { ...item, detail_load_failed: true }
            : item
        ));
        showToast('Unable to load the selected problematic album.', 'error', 3200);
      }
      return null;
    } finally {
      if (state.utility.detailLoadPromises?.[normalizedKey] === nextPromise) {
        delete state.utility.detailLoadPromises[normalizedKey];
      }
      let renderMs = 0;
      if (
        Number(state.utility.problematicDetailRequestToken || 0) === requestToken
        &&
        options.render !== false
        &&
        state.utility.activeTab === 'problematic-files'
        && String(state.utility.selectedProblematicKey || '') === normalizedKey
      ) {
        const renderStartedAt = getProblematicUtilityNow();
        renderUtilityModalContent({ preserveProblematicTree: true });
        await waitForProblematicUtilityRenderFrame();
        renderMs = roundProblematicUtilityMs(getProblematicUtilityNow() - renderStartedAt);
      }
      recordProblematicUtilityDiagnostics('detail', {
        albumKey: normalizedKey,
        ok: loadSucceeded,
        status: responseStatus,
        error: loadError || null,
        requestMs,
        parseMs,
        stateCommitMs,
        renderMs,
        totalMs: roundProblematicUtilityMs(getProblematicUtilityNow() - startedAt),
        detailLoaded: Boolean((state.utility.problematicFiles || []).find((item) => String(item?.key || '') === normalizedKey)?.detail_loaded),
      });
    }
  });
  nextPromise.problematicDetailRequestToken = requestToken;
  state.utility.detailLoadPromises[normalizedKey] = nextPromise;
  return nextPromise;
}

function isProblematicPayloadObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function readProblematicPayloadError(payload, fallback) {
  return isProblematicPayloadObject(payload) && String(payload.error || '').trim()
    ? String(payload.error).trim()
    : fallback;
}

function validateProblematicSummaryPayload(payload) {
  if (!isProblematicPayloadObject(payload)) {
    throw new Error('Problematic Files summary response must be a JSON object.');
  }
  if (payload.ok === false) {
    throw new Error(readProblematicPayloadError(payload, 'Unable to load problematic files.'));
  }
  if (!Array.isArray(payload.items)) {
    throw new Error('Problematic Files summary response must include an items array.');
  }
  if (payload.items.some((item) => !isProblematicPayloadObject(item))) {
    throw new Error('Problematic Files summary items must be JSON objects.');
  }
  if (payload.items.some((item) => item.detail_loaded !== false)) {
    throw new Error('Problematic Files summary items must be marked as not detail loaded.');
  }
  const itemKeys = new Set(payload.items.map((item) => String(item.key || '').trim()));
  if (itemKeys.has('')) {
    throw new Error('Problematic Files summary items must include non-empty keys.');
  }
  const rawOperationalItems = Array.isArray(payload.operational_items)
    ? payload.operational_items
    : [];
  if (rawOperationalItems.some((item) => !isProblematicPayloadObject(item))) {
    throw new Error('Problematic Files operational items must be JSON objects.');
  }
  const operationalItems = rawOperationalItems.map((item) => {
    const stateValue = String(item.state || '').trim();
    const rootKey = String(item.root_key || '').trim();
    if (
      ![
        'overflow',
        'reconciliation_failed',
        'root_unavailable',
        'stable_write_unavailable',
      ].includes(stateValue)
      || !/^root_[a-f0-9]{16}$/.test(rootKey)
    ) {
      throw new Error('Problematic Files operational item is invalid.');
    }
    return {
      state: stateValue,
      root_key: rootKey,
      detected_at: String(item.detected_at || ''),
      message: 'Some library changes may have been missed.',
      allowed_actions: item?.allowed_actions?.['library.refresh'] === true
        ? { 'library.refresh': true }
        : {},
    };
  });
  const initialDetailValue = payload.initial_detail;
  if (initialDetailValue === undefined || initialDetailValue === null) {
    return { summaryItems: payload.items, initialDetail: null, operationalItems };
  }
  if (!isProblematicPayloadObject(initialDetailValue)) {
    throw new Error('Problematic Files initial detail must be a JSON object or null.');
  }
  const initialDetailKey = String(initialDetailValue.key || '').trim();
  if (!initialDetailKey || !itemKeys.has(initialDetailKey)) {
    throw new Error('Problematic Files initial detail key must match a summary item.');
  }
  return {
    summaryItems: payload.items,
    initialDetail: validateProblematicDetailPayload(initialDetailValue, initialDetailKey),
    operationalItems,
  };
}

function validateProblematicDetailPayload(payload, requestedKey) {
  if (!isProblematicPayloadObject(payload)) {
    throw new Error('Problematic Files detail response must be a JSON object.');
  }
  if (payload.ok === false) {
    throw new Error(readProblematicPayloadError(payload, 'Unable to load problematic album detail.'));
  }
  const responseKey = String(payload.key || '').trim();
  if (!responseKey || responseKey !== requestedKey) {
    throw new Error('Problematic Files detail response key does not match the requested album.');
  }
  if (payload.detail_loaded !== true) {
    throw new Error('Problematic Files detail response must be marked as detail loaded.');
  }
  const requiredArrayFields = [
    'tracks',
    'repair_preview_rows',
    'track_problem_rows',
    'problematic_track_paths',
  ];
  const invalidArrayField = requiredArrayFields.find((field) => !Array.isArray(payload[field]));
  if (invalidArrayField) {
    throw new Error(`Problematic Files detail response must include a ${invalidArrayField} array.`);
  }
  return payload;
}

function getProblematicUtilityNow() {
  if (typeof window?.performance?.now === 'function') {
    return window.performance.now();
  }
  return Date.now();
}

function roundProblematicUtilityMs(value) {
  return Math.round(Number(value || 0) * 100) / 100;
}

function buildProblematicUtilityDiagnosticsStore() {
  const existing = state.utility.problematicDiagnostics;
  if (existing && typeof existing === 'object') {
    if (!existing.detailLoads || typeof existing.detailLoads !== 'object') {
      existing.detailLoads = {};
    }
    return existing;
  }
  state.utility.problematicDiagnostics = {
    summaryLoad: null,
    detailLoads: {},
    lastDetailLoad: null,
  };
  return state.utility.problematicDiagnostics;
}

function recordProblematicUtilityDiagnostics(kind, payload) {
  const diagnostics = buildProblematicUtilityDiagnosticsStore();
  const normalizedPayload = {
    ...payload,
    recordedAt: new Date().toISOString(),
  };
  if (kind === 'summary') {
    diagnostics.summaryLoad = normalizedPayload;
  } else if (kind === 'detail') {
    const albumKey = String(normalizedPayload.albumKey || '');
    if (albumKey) {
      diagnostics.detailLoads[albumKey] = normalizedPayload;
    }
    diagnostics.lastDetailLoad = normalizedPayload;
  }
  console.info('[AlbumHaven][Utilities][Diagnostics]', {
    kind,
    ...normalizedPayload,
  });
  return normalizedPayload;
}

function waitForProblematicUtilityRenderFrame() {
  return new Promise((resolve) => {
    scheduleBrowserAnimationFrame(() => {
      scheduleBrowserAnimationFrame(() => {
        scheduleBrowserAnimationFrame(resolve);
      });
    });
  });
}

async function fetchCoverForAlbum(album, options = {}) {
  if (!album) {
    showToast('No album selected for cover fetch.', 'error', 3200);
    return;
  }
  try {
    console.log('[AlbumHaven][Covers] Starting manual single cover fetch.', {
      albumArtist: album.album_artist || '',
      albumName: album.name || album.album || '',
      year: album.year || null,
      trackCount: Array.isArray(album.tracks) ? album.tracks.length : 0,
      options,
    });
    const response = await fetch('/utilities/fetch-cover', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ album }),
    });
    const data = await response.json().catch(() => ({}));
    console.log('[AlbumHaven][Covers] Manual single cover fetch HTTP response.', {
      status: response.status,
      ok: response.ok,
      body: data,
    });
    if (!response.ok || !data.ok) {
      throw new Error(data.error || 'Failed to fetch cover art');
    }
    console.log('[AlbumHaven][Covers] Manual single cover fetch response:', data);
    const updatedAlbums = Array.isArray(data.updated_albums)
      ? data.updated_albums
      : [data.updated_album].filter(Boolean);
    if (Number(data.downloaded_count || 0) > 0) {
      markAlbumCoverPathsFresh(updatedAlbums);
    }
    applyUpdatedAlbumsToCurrentView(updatedAlbums, { originalAlbum: album, preserveScroll: true, preserveGrouping: true });
    updateTrackModalIfStillShowingAlbum(album, updatedAlbums);
    if (options.refreshProblematicFiles !== false) {
      await loadProblematicFiles(true);
    }
    showToast(
      Number(data.downloaded_count || 0) > 0
        ? 'Cover art updated.'
        : `Cover was not updated${data.job_result?.reason ? `: ${String(data.job_result.reason).replaceAll('_', ' ')}` : ''}.`,
      Number(data.downloaded_count || 0) > 0 ? 'success' : 'error',
      3200,
    );
  } catch (error) {
    console.error('[AlbumHaven][Utilities] Failed to fetch cover art.', error);
    showToast(error.message || 'Failed to fetch cover art.', 'error', 3200);
  }
}

async function fetchCoverForProblematicAlbum(album) {
  await fetchCoverForAlbum(album, { refreshProblematicFiles: true });
}

async function performAlbumMove(album, action, options = {}) {
  if (!album) {
    showToast('No album selected for move.', 'error', 3200);
    return false;
  }
  const actionConfig = getAlbumMoveActionConfig(album, action);
  if (!actionConfig?.available) {
    const blockedReason = actionConfig?.blockedReasons?.[0] || 'This move action is no longer available.';
    showToast(blockedReason, 'error', 3200);
    return false;
  }
  if (!options.skipConfirm && !showBrowserConfirm(buildAlbumMoveConfirmMessage(album, actionConfig))) {
    return false;
  }

  try {
    const response = await fetch('/utilities/move-album', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        confirmed: true,
        album_key: String(album.key || ''),
        action: actionConfig.action,
      }),
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok || !data.ok) {
      throw new Error(data.error || 'Failed to move album');
    }

    const updatedAlbums = Array.isArray(data.updated_albums)
      ? data.updated_albums.filter(Boolean)
      : [data.updated_album].filter(Boolean);
    updateTrackModalIfStillShowingAlbum(album, updatedAlbums);
    if (state.utility.loaded || data.updated_problematic_album !== undefined) {
      applyRepairResultToProblematicFiles(album, data.updated_problematic_album || null);
    }
    const requiresViewRefresh = data.requires_view_refresh !== undefined
      ? Boolean(data.requires_view_refresh)
      : Boolean(data.move_task?.requires_view_refresh ?? true);
    if (requiresViewRefresh) {
      await fetchAndRender(buildApiUrl(state.view), false, { preserveScroll: true });
    }
    showToast(`Album moved to ${actionConfig.targetLabel}.`, 'success', 3200);
    return true;
  } catch (error) {
    console.error('[AlbumHaven][Utilities] Failed to move album.', error);
    showToast(error.message || 'Failed to move album.', 'error', 3200);
    return false;
  }
}

async function fetchUnsuccessfulAlbumCovers() {
  const previousStatus = { ...state.status };
  const statusAction = claimLibraryStatusAction(true);
  try {
    console.log('[AlbumHaven][Covers] Starting manual bulk cover fetch.');
    startStatusIndicatorImmediately({
      covers_in_progress: true,
      covers_processed: 0,
      covers_total: 0,
      covers_downloaded: 0,
      covers_current_folder: '',
    });
    const response = await fetch('/utilities/fetch-covers-unsuccessful', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ force_search: true }),
    });
    const data = await response.json().catch(() => ({}));
    console.log('[AlbumHaven][Covers] Manual bulk cover fetch HTTP response.', {
      status: response.status,
      ok: response.ok,
      queuedCount: data.queued_count,
      currentFolder: data.current_folder,
      queuedAfterIndexing: data.queued_after_indexing,
      processed: data.processed_count,
      downloaded: data.downloaded_count,
      failed: data.failed_count,
      mode: data.mode,
      started: data.started,
      alreadyRunning: data.already_running,
      forceSearchUsed: data.force_search_used,
      sampleJobResults: Array.isArray(data.job_results) ? data.job_results.slice(0, 10) : [],
    });
    if (!response.ok || !data.ok) {
      throw new Error(data.error || 'Failed to fetch album covers');
    }
    if (!settleLibraryStatusAction(statusAction)) return;
    if (data.queued_after_indexing) {
      updateStatusIndicator({
        ...state.status,
        scan_in_progress: true,
        scan_processed: Number(state.status?.scan_processed || 0),
        scan_total: Number(state.status?.scan_total || 0),
        covers_in_progress: false,
        covers_processed: 0,
        covers_total: 0,
        covers_downloaded: 0,
        covers_current_folder: '',
        pending_cover_refresh_after_scan: true,
      });
      state.wasPollingBusy = true;
      scheduleStatusPoll(250);
      return;
    }
    updateStatusIndicator({
      ...state.status,
      covers_in_progress: true,
      covers_processed: 0,
      covers_total: Number(data.queued_count || 0),
      covers_downloaded: 0,
      covers_current_folder: String(data.current_folder || ''),
      pending_cover_refresh_after_scan: false,
    });
    if (data.already_running) {
      state.wasCoverPollingBusy = true;
      scheduleStatusPoll(250);
      return;
    }
    state.wasCoverPollingBusy = true;
    scheduleStatusPoll(250);
  } catch (error) {
    if (settleLibraryStatusAction(statusAction)) updateStatusIndicator(previousStatus);
    console.error('[AlbumHaven][Utilities] Failed to fetch unresolved album covers.', error);
    showToast(error.message || 'Failed to fetch album covers.', 'error', 3200);
  }
}

async function cancelAlbumCoverScan() {
  const previousStatus = { ...state.status };
  const statusAction = claimLibraryStatusAction(false);
  let cancellationStatus = null;
  try {
    console.log('[AlbumHaven][Covers] Cancelling bulk cover fetch.');
    updateStatusIndicator({
      ...state.status,
      covers_in_progress: false,
      covers_current_folder: '',
      pending_cover_refresh_after_scan: false,
    });
    cancellationStatus = state.status;
    const response = await fetch('/utilities/cancel-cover-scan', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
    });
    const data = await response.json().catch(() => ({}));
    console.log('[AlbumHaven][Covers] Cancel bulk cover fetch response.', {
      status: response.status,
      ok: response.ok,
      cancelled: data.cancelled,
      coversInProgress: data.covers_in_progress,
    });
    if (!response.ok || !data.ok) {
      throw new Error(data.error || 'Failed to cancel album cover scan');
    }
    settleLibraryStatusAction(statusAction);
  } catch (error) {
    if (settleLibraryStatusAction(statusAction) && state.status === cancellationStatus) {
      updateStatusIndicator(previousStatus);
    }
    console.error('[AlbumHaven][Utilities] Failed to cancel album cover scan.', error);
    showToast(error.message || 'Failed to cancel album cover scan.', 'error', 3200);
  }
}


async function loadUtilityRules(force = false) {
  if (state.utility.rulesLoading) return state.utility.rulesLoadPromise;
  if (state.utility.rulesLoaded && !force) {
    renderUtilityModalContent();
    return;
  }
  const mutationRevision = typeof readProblemExclusionMutationRevision === 'function'
    ? readProblemExclusionMutationRevision()
    : 0;
  state.utility.rulesLoading = true;
  renderUtilityModalContent();
  state.utility.rulesLoadPromise = (async () => {
    try {
      const response = await fetch('/utilities/rules', { headers: { Accept: 'application/json' } });
      const data = await response.json();
      if (
        typeof readProblemExclusionMutationRevision === 'function'
        && readProblemExclusionMutationRevision() !== mutationRevision
      ) return;
      state.utility.rules = mergePendingProblemExclusionRules(
        Array.isArray(data.rules) ? data.rules : [],
      );
      if (Array.isArray(data.ignored_version_keys)) {
        mergeViewPayload({
          ignored_version_keys: data.ignored_version_keys,
        }, { trackSidebarReveal: false });
      }
      state.utility.rulesLoaded = true;
    } catch (error) {
      console.error('[AlbumHaven][Utilities] Failed to load rules.', error);
      state.utility.rules = mergePendingProblemExclusionRules([]);
      showToast('Unable to load utility rules.', 'error', 3200);
    } finally {
      state.utility.rulesLoading = false;
      state.utility.rulesLoadPromise = null;
      renderUtilityModalContent();
    }
  })();
  return state.utility.rulesLoadPromise;
}

async function loadUtilityLoops(force = false) {
  const utility = state.utility;
  if (utility.loopsLoading) return utility.loopsLoadPromise;
  if (utility.loopsLoaded && utility.loopsActionProjectionLoaded === true && !force) {
    renderUtilityModalContent();
    return;
  }
  const generation = Number(utility.loopDataGeneration || 0) + 1;
  utility.loopDataGeneration = generation;
  const mutationGeneration = Number(utility.loopMutationGeneration || 0);
  const isCurrent = () => state.utility === utility
    && Number(utility.loopDataGeneration || 0) === generation
    && Number(utility.loopMutationGeneration || 0) === mutationGeneration;
  utility.loopsLoading = true;
  utility.loopsLoadError = '';
  renderUtilityModalContent();
  const loadPromise = (async () => {
    try {
      const response = await fetch('/utilities/loops', { headers: { Accept: 'application/json' } });
      const data = await response.json();
      if (!isCurrent()) return;
      if (!response.ok || !data.ok) throw new Error(data.error || 'Unable to load saved loops');
      utility.allowedActions = { ...(utility.allowedActions || {}) };
      for (const action of ['library.loops.read', 'library.loops.create', 'library.loops.delete', 'library.loops.reorder']) {
        utility.allowedActions[action] = data.allowed_actions?.[action] === true;
      }
      utility.loopsActionProjectionLoaded = true;
      state.loopCreateAllowed = utility.allowedActions['library.loops.create'] === true;
      if (typeof syncLoopCreateCapability === 'function') syncLoopCreateCapability();
      utility.loops = Array.isArray(data.loops) ? data.loops : [];
      utility.loopsLoaded = true;
      const groupedLoops = groupUtilityLoops(utility.loops || []);
      collapseAllUtilityLoopGroups();
      const selectedGroup = groupedLoops.find(group => String(group.key || '') === String(utility.selectedLoopGroupKey || '')) || groupedLoops[0];
      utility.selectedLoopGroupKey = String(selectedGroup?.key || '');
      if (!(selectedGroup?.loops || []).some(loop => String(loop.id || '') === String(utility.selectedLoopId || ''))) {
        utility.selectedLoopId = String(selectedGroup?.loops?.[0]?.id || '');
      }
      utility.selectedLoopDetailMode = 'group';
    } catch (error) {
      if (!isCurrent()) return;
      console.error('[AlbumHaven][Loops] Failed to load loops.', error);
      utility.loopsLoadError = 'Unable to load saved loops. Reopen the Loops tab to retry.';
      showToast('Unable to load saved loops.', 'error', 3200);
    } finally {
      if (utility.loopsLoadPromise === loadPromise) {
        utility.loopsLoading = false;
        utility.loopsLoadPromise = null;
      }
      if (isCurrent() && utility.activeTab === 'loops') renderUtilityModalContent();
    }
  })();
  utility.loopsLoadPromise = loadPromise;
  return loadPromise;
}

function normalizeUtilityLogHistoryRevision(value) {
  return String(value ?? '').trim();
}

async function loadUtilityLogHistory(force = false) {
  const controller = getUtilityLogHistoryController();
  if (state.utility.logHistoryLoaded && !force) { renderUtilityLogHistory(); return { revision: controller.getState().revision }; }
  if (controller.getState().loading) return state.utility.logHistoryLoadPromise;
  const owner = state.utility;
  owner.logHistoryLoadPromise = controller.refresh().then(() => ({ revision: controller.getState().revision })).catch(() => null).finally(() => { owner.logHistoryLoadPromise = null; });
  return owner.logHistoryLoadPromise;
}

async function syncUtilityLogHistoryRevision(revision) {
  state.utility.logHistoryTargetRevision = normalizeUtilityLogHistoryRevision(revision);
  state.utility.logHistoryController?.markStale(revision);
  return { revision: state.utility.logHistoryRevision };
}

function ensureLastfmScrobbleState() {
  state.utility.lastfmScrobbles = state.utility.lastfmScrobbles || {
    summary: null, loading: false, submitting: false, loadPromise: null, requestGeneration: 0,
  };
  state.utility.lastfmScrobbles.requestGeneration = Number(state.utility.lastfmScrobbles.requestGeneration || 0);
  return state.utility.lastfmScrobbles;
}

function invalidateLastfmScrobbleSummary() {
  const owner = ensureLastfmScrobbleState();
  owner.requestGeneration += 1;
  owner.summary = null;
  owner.loading = false;
  owner.loadPromise = null;
  return owner;
}

function normalizeLastfmScrobbleSummary(payload, fallback = {}) {
  const nonnegativeInteger = (value, defaultValue = 0) => {
    const parsed = Number(value);
    return Number.isInteger(parsed) && parsed >= 0 ? parsed : defaultValue;
  };
  const hasProviderTotal = Object.prototype.hasOwnProperty.call(payload || {}, 'lastfm_total');
  const providerTotal = hasProviderTotal ? payload.lastfm_total : fallback.lastfm_total;
  const hasPending = Object.prototype.hasOwnProperty.call(payload || {}, 'pending');
  const pending = hasPending ? payload.pending : payload?.pending_after;
  return {
    scrobbled: nonnegativeInteger(
      payload?.scrobbled,
      nonnegativeInteger(fallback.scrobbled, nonnegativeInteger(fallback.listen_history_count)),
    ),
    lastfm_total: providerTotal == null ? null : nonnegativeInteger(providerTotal, null),
    pending: nonnegativeInteger(
      pending,
      nonnegativeInteger(fallback.pending, nonnegativeInteger(fallback.pending_scrobble_count)),
    ),
    can_submit: typeof payload?.can_submit === 'boolean'
      ? payload.can_submit
      : fallback.can_submit === true,
  };
}

async function loadLastfmScrobbleSummary(lastfm, { replace = false, preserveOnError = false } = {}) {
  const owner = ensureLastfmScrobbleState();
  if (!lastfm?.connected) {
    invalidateLastfmScrobbleSummary();
    return null;
  }
  if (owner.loading && !replace) return owner.loadPromise;
  const requestGeneration = ++owner.requestGeneration;
  owner.loading = true;
  renderUtilityModalContent();
  const loadPromise = (async () => {
    try {
      const response = await fetch('/utilities/integrations/lastfm/scrobbles', { headers: { Accept: 'application/json' } });
      const data = await response.json().catch(() => ({}));
      if (!response.ok || !data.ok) throw new Error(data.error || 'Failed to load Last.fm scrobble status');
      if (state.utility.lastfmScrobbles === owner && owner.requestGeneration === requestGeneration) {
        owner.summary = normalizeLastfmScrobbleSummary(data, lastfm);
      }
      return owner.summary;
    } catch (error) {
      console.error('[AlbumHaven][Integrations] Failed to load Last.fm scrobble status.', error);
      if (
        state.utility.lastfmScrobbles === owner
        && owner.requestGeneration === requestGeneration
        && !(preserveOnError && owner.summary)
      ) {
        owner.summary = normalizeLastfmScrobbleSummary({}, lastfm);
      }
      return owner.summary;
    } finally {
      if (state.utility.lastfmScrobbles === owner && owner.requestGeneration === requestGeneration) {
        owner.loading = false;
        owner.loadPromise = null;
        renderUtilityModalContent();
      }
    }
  })();
  owner.loadPromise = loadPromise;
  return loadPromise;
}

async function loadUtilityIntegrations(force = false) {
  if (window.AlbumHavenCapabilities?.allows('integration.settings.read') !== true) {
    state.utility.integrations = [];
    state.utility.integrationsLoaded = false;
    state.utility.integrationsLoading = false;
    renderUtilityModalContent();
    return;
  }
  if (state.utility.integrationsLoading) return state.utility.integrationsLoadPromise;
  if (state.utility.integrationsLoaded && !force) {
    renderUtilityModalContent();
    const lastfm = state.utility.integrations.find((item) => String(item?.key || '') === 'lastfm');
    void loadLastfmScrobbleSummary(lastfm, { replace: true, preserveOnError: true });
    return;
  }
  state.utility.integrationsLoading = true;
  renderUtilityModalContent();
  state.utility.integrationsLoadPromise = (async () => {
    try {
      const response = await fetch('/utilities/integrations', { headers: { Accept: 'application/json' } });
      const data = await response.json();
      if (window.AlbumHavenCapabilities?.allows('integration.settings.read') !== true) {
        state.utility.integrations = [];
        return;
      }
      state.utility.integrations = Array.isArray(data.integrations) ? data.integrations : [];
      state.utility.integrationsLoaded = true;
      const lastfm = state.utility.integrations.find((item) => String(item?.key || '') === 'lastfm');
      if (lastfm && !String(state.utility.integrationDrafts?.lastfm?.username || '').trim()) {
        state.utility.integrationDrafts.lastfm.username = String(lastfm.username || '');
      }
      await reconcileLastfmTimeZoneDraft(lastfm);
      state.utility.integrationsLoading = false;
      renderUtilityModalContent();
      void loadLastfmScrobbleSummary(lastfm);
    } catch (error) {
      console.error('[AlbumHaven][Integrations] Failed to load integrations.', error);
      state.utility.integrations = [];
      showToast('Unable to load integrations.', 'error', 3200);
    } finally {
      state.utility.integrationsLoading = false;
      state.utility.integrationsLoadPromise = null;
      renderUtilityModalContent();
    }
  })();
  return state.utility.integrationsLoadPromise;
}

function getLastfmTimeZoneDraftProvenance() {
  state.utility.integrationDraftProvenance = state.utility.integrationDraftProvenance || {};
  const existing = state.utility.integrationDraftProvenance.lastfmTimezone;
  if (existing) return existing;
  const draftValue = String(state.utility.integrationDrafts?.lastfm?.timezone || '').trim();
  const provenance = {
    source: draftValue ? 'dirty' : '',
    value: draftValue,
  };
  state.utility.integrationDraftProvenance.lastfmTimezone = provenance;
  return provenance;
}

function markLastfmTimeZoneDraftDirty() {
  const provenance = getLastfmTimeZoneDraftProvenance();
  provenance.source = 'dirty';
  provenance.value = String(state.utility.integrationDrafts?.lastfm?.timezone || '').trim();
}

function markLastfmTimeZoneDraftSaved(timezone) {
  const provenance = getLastfmTimeZoneDraftProvenance();
  provenance.source = 'saved';
  provenance.value = String(timezone || '').trim();
}

async function persistDetectedLastfmTimeZone(timezone, provenance) {
  try {
    const response = await fetch('/utilities/integrations/lastfm', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        timezone,
        save_timezone_only: true,
      }),
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok || !data.ok) {
      throw new Error(data.error || 'Failed to save detected timezone');
    }
    state.utility.integrations = (state.utility.integrations || [])
      .filter((item) => String(item?.key || '') !== 'lastfm');
    state.utility.integrations.unshift(data.integration);
    const currentDraft = String(state.utility.integrationDrafts?.lastfm?.timezone || '').trim();
    if (provenance.source === 'detected' && currentDraft === timezone) {
      const savedTimeZone = String(data.integration?.user_timezone || timezone).trim();
      state.utility.integrationDrafts.lastfm.timezone = savedTimeZone;
      provenance.source = 'saved';
      provenance.value = savedTimeZone;
    }
  } catch (error) {
    console.warn('[AlbumHaven][Integrations] Failed to save detected timezone.', error);
  }
}

async function reconcileLastfmTimeZoneDraft(lastfm) {
  const draft = state.utility.integrationDrafts.lastfm;
  const provenance = getLastfmTimeZoneDraftProvenance();
  const currentDraft = String(draft.timezone || '').trim();
  if (
    provenance.source !== 'dirty'
    && provenance.value
    && currentDraft !== provenance.value
  ) {
    provenance.source = 'dirty';
    provenance.value = currentDraft;
  }
  if (provenance.source === 'dirty') return;

  const savedTimeZone = String(lastfm?.user_timezone || '').trim();
  if (savedTimeZone) {
    draft.timezone = savedTimeZone;
    provenance.source = 'saved';
    provenance.value = savedTimeZone;
    return;
  }

  const detectedTimeZone = String(getDetectedBrowserTimeZone() || 'UTC').trim() || 'UTC';
  draft.timezone = detectedTimeZone;
  provenance.source = 'detected';
  provenance.value = detectedTimeZone;
  await persistDetectedLastfmTimeZone(detectedTimeZone, provenance);
}

function handleLocalPlaylistImportFileSelection(file) {
  state.utility.localPlaylistImport = {
    ...(state.utility.localPlaylistImport || {}),
    selectedFile: file || null,
    selectedFileName: file?.name || '',
    error: '',
    lastAnalysis: null,
  };
  renderUtilityModalContent();
}

async function runLocalPlaylistImportAnalysis() {
  const importState = state.utility.localPlaylistImport || {};
  if (importState.analyzeBusy) return;
  const selectedFile = importState.selectedFile || null;
  if (!selectedFile) {
    state.utility.localPlaylistImport = {
      ...importState,
      error: 'Select a local playlist file before running analysis.',
      lastAnalysis: null,
    };
    renderUtilityModalContent();
    return;
  }
  state.utility.localPlaylistImport = {
    ...importState,
    analyzeBusy: true,
    error: '',
  };
  renderUtilityModalContent();
  try {
    const formData = new FormData();
    formData.append('playlist_file', selectedFile);
    const selectedIntegration = typeof getSelectedUtilityIntegration === 'function'
      ? getSelectedUtilityIntegration()
      : null;
    const analyzeRoute = String(selectedIntegration?.analyze_route || '/utilities/imports/local-playlists/analyze');
    const response = await fetch(analyzeRoute, {
      method: 'POST',
      body: formData,
      headers: { Accept: 'application/json' },
    });
    const data = await response.json();
    if (!response.ok || data?.ok === false) {
      throw new Error(String(data?.error || 'Unable to analyze the selected local playlist.'));
    }
    state.utility.localPlaylistImport = {
      ...state.utility.localPlaylistImport,
      selectedFile,
      selectedFileName: selectedFile?.name || '',
      analyzeBusy: false,
      error: '',
      lastAnalysis: data.analysis || null,
    };
  } catch (error) {
    console.error('[AlbumHaven][LocalPlaylistImport] Failed to analyze playlist.', error);
    state.utility.localPlaylistImport = {
      ...state.utility.localPlaylistImport,
      selectedFile,
      selectedFileName: selectedFile?.name || '',
      analyzeBusy: false,
      error: String(error?.message || 'Unable to analyze the selected local playlist.'),
      lastAnalysis: null,
    };
    showToast('Unable to analyze the selected local playlist.', 'error', 3200);
  } finally {
    renderUtilityModalContent();
  }
}

function loadActiveUtilityTab(force = false) {
  if (typeof window !== 'undefined' && window.AlbumHavenCapabilities && !window.AlbumHavenCapabilities.allowsUtilityTab(state.utility.activeTab)) return null;
  if (state.utility.activeTab === 'rules') {
    return loadUtilityRules(force);
  }
  if (state.utility.activeTab === 'loops') {
    return loadUtilityLoops(force);
  }
  if (state.utility.activeTab === 'log-history') {
    return loadUtilityLogHistory(force);
  }
  if (state.utility.activeTab === 'integrations') {
    loadUtilityIntegrations(force);
    if (state.utility.selectedIntegrationKey === 'library') {
      loadUtilityLibrarySettings(force);
    }
    return null;
  }
  if (state.utility.activeTab === 'appearance') {
    renderUtilityModalContent();
    return null;
  }
  return loadProblematicFiles(force);
}

function scheduleUtilityOpenLoad(force = false, delay = 0) {
  if (state.utility.pendingOpenLoadTimer) {
    clearBrowserTimeout(state.utility.pendingOpenLoadTimer);
    state.utility.pendingOpenLoadTimer = 0;
  }
  state.utility.pendingOpenLoadTimer = scheduleBrowserTimeout(() => {
    state.utility.pendingOpenLoadTimer = 0;
    loadActiveUtilityTab(force);
  }, delay);
}

function deferActiveStartupViewForUtilityModal() {
  const ui = state.ui;
  const controller = ui?.activeViewRequestController;
  const hydrationTier = String(ui?.activeViewRequestStartupHydrationTier || '');
  if (
    !ui?.activeViewRequestStartupRefresh
    || hydrationTier === 'sidebar'
    || !String(ui.activeViewRequestUrl || '').trim()
    || !controller
    || typeof controller.abort !== 'function'
  ) {
    return false;
  }
  ui.deferredUtilityViewRequest = {
    url: ui.activeViewRequestUrl,
    push: Boolean(ui.activeViewRequestPush),
    originatingViewStateRevision: Number(ui.viewStateRevision || 0),
    options: {
      startupRefresh: true,
      startupHydrationTier: hydrationTier || 'full',
      preserveScroll: true,
      skipPendingViewTransition: true,
    },
  };
  const sequence = Number(ui.utilityViewPreemptionSequence || 0) + 1;
  ui.utilityViewPreemptionSequence = sequence;
  ui.utilityViewPreemptions = [
    ...(Array.isArray(ui.utilityViewPreemptions) ? ui.utilityViewPreemptions : []),
    Object.freeze({
      normalizedUrl: ui.activeViewRequestUrl,
      reason: 'utility-modal-preemption',
      sequence,
    }),
  ].slice(-24);
  controller.abort();
  return true;
}

function resumeDeferredUtilityViewRequest() {
  const deferredRequest = state.ui?.deferredUtilityViewRequest;
  if (!deferredRequest?.url) return false;
  const originatingViewStateRevision = Number(
    deferredRequest.originatingViewStateRevision || 0,
  );
  if (originatingViewStateRevision !== Number(state.ui.viewStateRevision || 0)) {
    if (state.ui.deferredUtilityViewRequest === deferredRequest) {
      state.ui.deferredUtilityViewRequest = null;
    }
    return false;
  }
  const resumeOptions = {
    ...(deferredRequest.options || {}),
    interruptCurrent: false,
  };
  if (state.busy || String(state.ui.activeViewRequestUrl || '').trim()) {
    if (state.ui.pendingViewRequest) return false;
    state.ui.pendingViewRequest = {
      url: deferredRequest.url,
      push: deferredRequest.push,
      options: resumeOptions,
      originatingViewStateRevision,
    };
    if (state.ui.deferredUtilityViewRequest === deferredRequest) {
      state.ui.deferredUtilityViewRequest = null;
    }
    return true;
  }
  const restartPromise = fetchAndRender(
    deferredRequest.url,
    deferredRequest.push,
    resumeOptions,
  );
  Promise.resolve(restartPromise).then((acquiredAndRendered) => {
    if (
      acquiredAndRendered
      && state.ui.deferredUtilityViewRequest === deferredRequest
    ) {
      state.ui.deferredUtilityViewRequest = null;
    }
  }).catch(() => {
    // Retain the deferred request so a later close or released request slot can retry it.
  });
  return true;
}

let utilityCoverLoadSuspensionToken = 0;
let utilityOpenGeneration = 0;

function scheduleUtilityModalOpenWorkAfterPaint(generation, forceLoad) {
  const run = () => {
    const els = getUtilityModalElements();
    if (generation !== utilityOpenGeneration || !els.overlay || els.overlay.hidden) return;
    renderUtilityModalContent();
    if (!forceLoad) return;
    loadActiveUtilityTab(true);
  };
  if (typeof scheduleBrowserAnimationFrame !== 'function') {
    run();
    return;
  }
  scheduleBrowserAnimationFrame(() => scheduleBrowserAnimationFrame(run));
}

function openUtilityModal({ resetSearch = true, resetSelection = true, forceLoad = true } = {}) {
  if (typeof deferAppFormPageReplacement === 'function'
    && deferAppFormPageReplacement(() => openUtilityModal({resetSearch, resetSelection, forceLoad}))) return;
  if (typeof isMobileClient === 'function' && isMobileClient() && !mobileUtilityTabAllowed(state.utility.activeTab)) state.utility.activeTab = 'appearance';
  const els = getUtilityModalElements();
  if (!els.overlay) return;
  if (typeof window !== 'undefined' && window.AlbumHavenCapabilities) {
    const permittedTab = window.AlbumHavenCapabilities.resolveUtilityTab(state.utility.activeTab);
    if (!permittedTab) return;
    setUtilityActiveTab(permittedTab);
    if (state.utility.activeTab !== permittedTab) return;
  }
  if (typeof presentMobileUtilityPage === 'function') presentMobileUtilityPage();
  document.getElementById('track-modal')?.classList.remove('is-above-settings');
  if (
    !utilityCoverLoadSuspensionToken
    && typeof virtualGrid !== 'undefined'
    && virtualGrid
    && typeof virtualGrid.suspendSelectedArtistCoverLoadsForUserAction === 'function'
  ) {
    utilityCoverLoadSuspensionToken = virtualGrid.suspendSelectedArtistCoverLoadsForUserAction();
  }
  deferActiveStartupViewForUtilityModal();
  els.overlay.hidden = false;
  document.body.classList.add('modal-open');
  if (state.utility.activeTab === 'loops') {
    collapseAllUtilityLoopGroups();
  }
  if (resetSelection) {
    state.utility.selectedProblematicKey = '';
    state.utility.pendingRepairKey = '';
  state.utility.pendingProblemSuggestions = null;
  state.utility.pendingRuleRevert = null;
    state.utility.pendingRepairAction = '';
    state.utility.focusedTrackPath = '';
    state.utility.showRepairedDisplay = true;
    state.utility.repairSelections = {};
    state.utility.problemExclusionSelections = {};
    state.utility.separateReleaseSelections = {};
    state.utility.selectedProblemFilters = [];
    state.utility.problemDropdownOpen = false;
    state.utility.collapsedSections = {
      detected: false,
      suggested: false,
      details: false,
    };
  }
  if (resetSearch) {
    state.utility.searchQuery = '';
  }
  if (state.utility.pendingOpenLoadTimer) {
    clearBrowserTimeout(state.utility.pendingOpenLoadTimer);
    state.utility.pendingOpenLoadTimer = 0;
  }
  utilityOpenGeneration += 1;
  scheduleUtilityModalOpenWorkAfterPaint(utilityOpenGeneration, forceLoad);
}

function openUtilityLogHistoryTab(entryId = '') {
  const canOpen = () => typeof window === 'undefined' || !window.AlbumHavenCapabilities
    || window.AlbumHavenCapabilities.allowsUtilityTab('log-history');
  if (!canOpen()) return;
  const owner = state.utility;
  const open = () => {
    if (state.utility !== owner || !canOpen()) return;
    if (setUtilityActiveTab('log-history', true) !== 'log-history') return;
    openUtilityModal({ resetSearch: false, resetSelection: false, forceLoad: !entryId });
    if (!entryId) return;
    const controller = getUtilityLogHistoryController();
    // Base navigation has its own ownership generation; it cannot replace this
    // explicitly requested event's console/export capture.
    if (!owner.logHistory?.length) controller.refreshNavigation().catch(() => {});
    return controller.selectEvent(entryId).catch(() => null);
  };
  if (owner.activeTab !== 'log-history' && typeof confirmBackgroundAppearanceLeave === 'function'
      && !confirmBackgroundAppearanceLeave(open)) return;
  return open();
}

async function saveLastfmIntegration() {
  const draft = state.utility.integrationDrafts?.lastfm || { username: '', password: '', timezone: '' };
  try {
    const response = await fetch('/utilities/integrations/lastfm', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        username: String(draft.username || '').trim(),
        password: String(draft.password || ''),
        timezone: String(draft.timezone || '').trim(),
      }),
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok || !data.ok) {
      state.utility.logHistoryLoaded = false;
      throw new Error(data.error || 'Failed to connect Last.fm');
    }
    state.utility.integrations = (state.utility.integrations || []).filter((item) => String(item?.key || '') !== 'lastfm');
    state.utility.integrations.unshift(data.integration);
    state.utility.integrationsLoaded = true;
    state.utility.selectedIntegrationKey = 'lastfm';
    state.utility.integrationDrafts.lastfm = {
      username: String(data.integration?.username || draft.username || '').trim(),
      password: '',
      timezone: String(data.integration?.user_timezone || draft.timezone || getDetectedBrowserTimeZone() || 'UTC'),
    };
    markLastfmTimeZoneDraftSaved(state.utility.integrationDrafts.lastfm.timezone);
    await loadLastfmScrobbleSummary(data.integration, { replace: true });
    showToast('Last.fm connected.', 'success', 2600);
  } catch (error) {
    console.error('[AlbumHaven][Integrations] Failed to connect Last.fm.', error);
    showToast(error.message || 'Failed to connect Last.fm.', 'error', 3600);
  }
}

