async function submitPendingLastfmScrobbles() {
  const owner = ensureLastfmScrobbleState();
  const lastfm = (state.utility.integrations || []).find((item) => String(item?.key || '') === 'lastfm');
  if (owner.submitting || !lastfm?.connected || Number(owner.summary?.pending) <= 0 || owner.summary?.can_submit !== true) return false;
  const submitGeneration = ++owner.requestGeneration;
  owner.loading = false;
  owner.loadPromise = null;
  owner.submitting = true;
  renderUtilityModalContent();
  try {
    const response = await fetch('/utilities/integrations/lastfm/scrobbles/submit', {
      method: 'POST',
      headers: { Accept: 'application/json' },
    });
    const data = await response.json().catch(() => ({}));
    if (state.utility.lastfmScrobbles === owner && owner.requestGeneration === submitGeneration) {
      owner.summary = normalizeLastfmScrobbleSummary(data, owner.summary || lastfm);
      renderUtilityModalContent();
      await loadLastfmScrobbleSummary(lastfm, { replace: true, preserveOnError: true });
    }
    if (!response.ok || !data.ok) {
      state.utility.logHistoryLoaded = false;
      showRepairAlert(data.error || 'Album Haven could not submit pending Last.fm scrobbles.', 'error', null);
      return false;
    }
    showToast('Pending Last.fm scrobbles submitted.', 'success', 2600);
    return true;
  } catch (error) {
    console.error('[AlbumHaven][Integrations] Failed to submit pending Last.fm scrobbles.', error);
    state.utility.logHistoryLoaded = false;
    if (state.utility.lastfmScrobbles === owner && owner.requestGeneration === submitGeneration) {
      await loadLastfmScrobbleSummary(lastfm, { replace: true, preserveOnError: true });
    }
    showRepairAlert(error.message || 'Album Haven could not submit pending Last.fm scrobbles.', 'error', null);
    return false;
  } finally {
    if (state.utility.lastfmScrobbles === owner) {
      owner.submitting = false;
      renderUtilityModalContent();
    }
  }
}

function closeUtilityModal(skipAppearanceGuard = false) {
  if (skipAppearanceGuard !== true && typeof confirmBackgroundAppearanceLeave === 'function' && !confirmBackgroundAppearanceLeave(() => closeUtilityModal(true))) return;
  if (typeof disposeUtilityFoobarPreview === 'function') disposeUtilityFoobarPreview();
  if (typeof dismissMobilePage === 'function' && dismissMobilePage('utilities')) return;
  if (typeof unmountAppearanceEditors === 'function') unmountAppearanceEditors();
  if (typeof disposeMountedLoopActions === 'function') disposeMountedLoopActions(getUtilityModalElements()?.detail);
  const els = getUtilityModalElements();
  if (!els.overlay) return;
  utilityOpenGeneration += 1;
  if (typeof disposeUtilityTabAlignment === 'function') disposeUtilityTabAlignment(els);
  state.utility.problemDropdownOpen = false;
  if (els.problemFilterMenu) {
    els.problemFilterMenu.hidden = true;
    if (typeof clearTriggerAnchor === 'function') clearTriggerAnchor(els.problemFilterMenu);
  }
  els.problemFilterButton?.setAttribute?.('aria-expanded', 'false');
  state.utility.problematicNavigationToken = Number(state.utility.problematicNavigationToken || 0) + 1;
  state.utility.problematicNavigationActiveToken = 0;
  if (typeof clearUtilityLoopSpaceOwner === 'function') {
    clearUtilityLoopSpaceOwner();
  }
  document.querySelectorAll('.utility-loop-audio').forEach((audio) => {
    audio.pause();
  });
  els.overlay.hidden = true;
  const trackModalOpen = !document.getElementById('track-modal')?.hidden;
  const lightboxOpen = !document.getElementById('image-lightbox')?.hidden;
  if (!trackModalOpen && !lightboxOpen) {
    document.body.classList.remove('modal-open');
  }
  resumeDeferredUtilityViewRequest();
  const coverLoadSuspensionToken = utilityCoverLoadSuspensionToken;
  utilityCoverLoadSuspensionToken = 0;
  if (
    coverLoadSuspensionToken
    && typeof virtualGrid !== 'undefined'
    && virtualGrid
    && typeof virtualGrid.resumeSelectedArtistCoverLoadsAfterUserAction === 'function'
  ) {
    virtualGrid.resumeSelectedArtistCoverLoadsAfterUserAction(coverLoadSuspensionToken);
  }
}

let repairConfirmReturnFocus = null;

function openSavedLoopDeleteConfirm(loopId) {
  const loop = (state.utility.loops || []).find(item => String(item.id || '') === String(loopId || ''));
  if (!loop || state.utility.allowedActions?.['library.loops.delete'] !== true) return false;
  const els = getRepairConfirmElements();
  if (!els.overlay) return false;
  state.utility.pendingSavedLoopDeleteId = String(loop.id);
  state.utility.pendingRepairAction = 'saved-loop-delete';
  els.overlay.removeAttribute?.('data-confirm-mode');
  els.dialog?.setAttribute?.('aria-labelledby', 'repair-confirm-title');
  els.dialog?.setAttribute?.('aria-describedby', 'repair-confirm-text');
  if (els.title) { els.title.hidden = false; els.title.textContent = 'Delete saved loop?'; }
  if (els.text) els.text.textContent = `Delete “${loop.name || 'Saved loop'}”? The saved loop will be removed.`;
  if (els.cancel) { els.cancel.textContent = 'No'; els.cancel.disabled = false; }
  if (els.accept) { els.accept.textContent = 'Yes'; els.accept.disabled = false; }
  repairConfirmReturnFocus = document.activeElement?.focus ? document.activeElement : null;
  els.overlay.hidden = false;
  document.body.classList.add('modal-open');
  els.cancel?.focus?.();
  return true;
}

function openRepairConfirmModal() {
  const els = getRepairConfirmElements();
  if (!els.overlay) return;
  const action = state.utility.pendingRepairAction || 'repair';
  if (action === 'suggestions') {
    const pending = state.utility.pendingProblemSuggestions;
    if (!pending?.proposals?.length) return;
    els.overlay.removeAttribute?.('data-confirm-mode');
    els.dialog?.setAttribute?.('aria-labelledby', 'repair-confirm-title');
    els.dialog?.setAttribute?.('aria-describedby', 'repair-confirm-text');
    if (els.title) { els.title.hidden = false; els.title.textContent = 'Apply suggested edits?'; }
    if (els.text) els.text.textContent = pending.proposals.map(proposal => {
      const track = (getSelectedProblematicAlbum()?.tracks || []).find(item => item.path === proposal.path);
      return `${track?.title || getFilenameFromPath(proposal.path)} — ${formatProblemSuggestionLabel(proposal)}`;
    }).join('\n');
    if (els.cancel) { els.cancel.textContent = 'Cancel'; els.cancel.disabled = false; }
    if (els.accept) { els.accept.textContent = 'Apply'; els.accept.disabled = false; }
    repairConfirmReturnFocus = document.activeElement?.focus ? document.activeElement : null;
    els.overlay.hidden = false;
    document.body.classList.add('modal-open');
    els.cancel?.focus?.();
    return;
  }
  if (action === 'revert-rule') {
    const pending = state.utility.pendingRuleRevert;
    if (!pending) return;
    const rule = (state.utility.rules || []).find(item => item.key === 'version-exceptions');
    const target = pending.item || (rule?.albums || []).find(item => item.key === pending.key) || {};
    const label = target.target_label || target.filename || target.album || target.name || pending.key;
    els.overlay.removeAttribute?.('data-confirm-mode');
    els.dialog?.setAttribute?.('aria-labelledby', 'repair-confirm-title');
    els.dialog?.setAttribute?.('aria-describedby', 'repair-confirm-text');
    if (els.title) { els.title.hidden = false; els.title.textContent = 'Revert rule?'; }
    if (els.text) els.text.textContent = `Revert the rule for ${label}? ${pending.kind === 'problem-exclusion' ? 'This problem can appear again in Problems.' : 'This album can appear in version groups again.'}`;
    if (els.cancel) els.cancel.textContent = 'No';
    if (els.accept) { els.accept.textContent = 'Yes'; els.accept.disabled = false; }
    repairConfirmReturnFocus = document.activeElement?.focus ? document.activeElement : null;
    els.overlay.hidden = false;
    document.body.classList.add('modal-open');
    els.cancel?.focus?.();
    return;
  }
  const selectedRows = action === 'repair' ? getSelectedRepairRowKeys() : [];
  const ignoredRows = action === 'detected' ? getIgnoredRepairRowKeys() : [];
  const separateRows = action === 'separate-release' ? getSelectedSeparateReleaseKeys() : [];
  const actionPaths = new Set([...selectedRows, ...ignoredRows].map((value) => String(value).split('::')[0]).filter(Boolean));
  const isExclusionConfirmation = action === 'detected' && ignoredRows.length > 0;
  if (isExclusionConfirmation) {
    els.overlay.setAttribute?.('data-confirm-mode', 'exclusion');
  } else {
    els.overlay.removeAttribute?.('data-confirm-mode');
  }
  if (els.dialog) {
    els.dialog.setAttribute('aria-labelledby', isExclusionConfirmation ? 'repair-confirm-text' : 'repair-confirm-title');
    if (isExclusionConfirmation) {
      els.dialog.removeAttribute('aria-describedby');
    } else {
      els.dialog.setAttribute('aria-describedby', 'repair-confirm-text');
    }
  }
  if (els.title) {
    els.title.hidden = isExclusionConfirmation;
    els.title.textContent = isExclusionConfirmation ? '' : 'Repair local files';
  }
  if (els.cancel) els.cancel.textContent = 'Cancel';
  if (els.text) {
    if (selectedRows.length) {
      els.text.textContent = actionPaths.size > 1
        ? `This will try to repair ${actionPaths.size} local files with the selected fixes. Are you sure?`
        : 'This will try to repair your local file with the selected fix. Are you sure?';
      if (els.accept) els.accept.textContent = 'Yes, repair files';
    } else if (separateRows.length) {
      els.text.textContent = 'This will treat the selected year mismatch as separate releases and rebuild the album list. Are you sure?';
      if (els.accept) els.accept.textContent = 'Yes, apply';
    } else if (isExclusionConfirmation) {
      const album = getSelectedProblematicAlbum();
      const selected = new Set(ignoredRows);
      const targets = [];
      (album?.album_problem_rows || []).filter(item => selected.has(item.row_key)).forEach(item => targets.push(`${album.name || 'Album'} — ${item.display_reason || item.reason}`));
      (album?.track_problem_rows || []).forEach(row => (row.ignorable_reasons || []).filter(item => selected.has(item.row_key)).forEach(item => targets.push(`${row.filename || getFilenameFromPath(row.path)} — ${item.reason}`)));
      els.text.textContent = `Create an exclusion rule for ${targets.join('; ')}? These problems will be hidden. You can revert this rule in Rules.`;
      if (els.accept) els.accept.textContent = 'Create Exception';
    } else {
      els.text.textContent = 'No problem exclusions are selected.';
      if (els.accept) els.accept.textContent = 'Yes, apply';
    }
  }
  repairConfirmReturnFocus = document.activeElement?.focus
    ? document.activeElement
    : null;
  els.overlay.hidden = false;
  document.body.classList.add('modal-open');
}

function closeRepairConfirmModal() {
  const els = getRepairConfirmElements();
  if (!els.overlay) return;
  els.overlay.hidden = true;
  state.utility.pendingSavedLoopDeleteId = '';
  state.utility.pendingRepairKey = '';
  state.utility.pendingProblemSuggestions = null;
  state.utility.pendingRuleRevert = null;
  state.utility.pendingRepairAction = '';
  const trackModalOpen = !document.getElementById('track-modal')?.hidden;
  const lightboxOpen = !document.getElementById('image-lightbox')?.hidden;
  const utilityModalOpen = !document.getElementById('utility-modal')?.hidden;
  if (!trackModalOpen && !lightboxOpen && !utilityModalOpen) {
    document.body.classList.remove('modal-open');
  }
  const returnFocus = repairConfirmReturnFocus;
  repairConfirmReturnFocus = null;
  returnFocus?.focus?.();
}

function showRepairProgressOverlay(fileCount = 0, title = 'Repairing tags') {
  const els = getRepairProgressElements();
  if (!els.overlay) return;
  if (els.title) {
    els.title.textContent = title;
  }
  if (els.text) {
    els.text.textContent = fileCount > 1
      ? `Applying selected changes to ${fileCount} local files...`
      : 'Applying selected changes...';
  }
  els.overlay.hidden = false;
  document.body.classList.add('modal-open');
}

function hideRepairProgressOverlay() {
  const els = getRepairProgressElements();
  if (!els.overlay) return;
  els.overlay.hidden = true;
  const trackModalOpen = !document.getElementById('track-modal')?.hidden;
  const lightboxOpen = !document.getElementById('image-lightbox')?.hidden;
  const utilityModalOpen = !document.getElementById('utility-modal')?.hidden;
  const repairConfirmOpen = !document.getElementById('repair-confirm-modal')?.hidden;
  const tagEditorOpen = !document.getElementById('tag-editor-modal')?.hidden;
  const tagEditConfirmOpen = !document.getElementById('tag-edit-confirm-modal')?.hidden;
  if (!trackModalOpen && !lightboxOpen && !utilityModalOpen && !repairConfirmOpen && !tagEditorOpen && !tagEditConfirmOpen) {
    document.body.classList.remove('modal-open');
  }
}

function getTagEditorTracks(album, mode = 'problematic') {
  const tracks = Array.isArray(album?.tracks) ? album.tracks : [];
  if (mode === 'all') return tracks;
  const problemPaths = new Set((Array.isArray(album?.track_problem_rows) ? album.track_problem_rows : [])
    .map((row) => String(row.path || ''))
    .filter(Boolean));
  if (!problemPaths.size) return tracks;
  return tracks.filter((track) => problemPaths.has(String(track.path || '')));
}

function getTrackTagInitialValues(track, album) {
  const usesTrackOwnedIdentity = album?.tag_editor_collection === true;
  return {
    artist: usesTrackOwnedIdentity
      ? String(track?.tag_artist ?? track?.artist ?? '')
      : String(track?.tag_artist || track?.artist || album?.album_artist || ''),
    album_artist: usesTrackOwnedIdentity
      ? String(track?.album_artist ?? '')
      : String(track?.album_artist || album?.raw_album_artist || album?.album_artist || track?.artist || ''),
    album: usesTrackOwnedIdentity || Object.prototype.hasOwnProperty.call(track || {}, 'album')
      ? String(track?.album ?? '')
      : String(album?.raw_name || album?.name || ''),
    title: String(track?.title || ''),
    genre: String(track?.genre || ''),
    year: String(track?.year ?? album?.year ?? ''),
    track_number: String(track?.track_number ?? ''),
    disc_number: String(track?.disc_number ?? ''),
    exception_type: String(track?.exception_type || ''),
    edition: String(track?.edition || album?.edition || ''),
    album_rating: String(track?.album_rating ?? album?.album_rating ?? ''),
  };
}

function buildChangedTagEditorUpdates(album, tracks, valuesByPath) {
  const updates = {};
  (tracks || []).forEach((track) => {
    const path = String(track?.path || '');
    if (!path) return;
    const currentValues = valuesByPath?.[path];
    if (!currentValues || typeof currentValues !== 'object') return;
    const initialValues = getTrackTagInitialValues(track, album);
    const changedFields = {};
    Object.keys(initialValues).forEach((field) => {
      const nextValue = String(currentValues[field] ?? '');
      const initialValue = String(initialValues[field] ?? '');
      if (nextValue !== initialValue) {
        changedFields[field] = nextValue;
      }
    });
    if (Object.keys(changedFields).length) {
      updates[path] = changedFields;
    }
  });
  return updates;
}

function applyTagEditsToNonAlbumView(album, updates) {
  const view = state.view || (state.view = {});
  const currentTracks = Array.isArray(view.non_album_tracks)
    ? view.non_album_tracks.slice()
    : [];
  const tracksByPath = new Map(
    (Array.isArray(album?.tracks) ? album.tracks : [])
      .map((track) => [String(track?.path || ''), track])
      .filter(([path]) => path),
  );
  const nextByPath = new Map(
    currentTracks
      .map((track) => [String(track?.path || ''), track])
      .filter(([path]) => path),
  );
  Object.entries(updates || {}).forEach(([path, edits]) => {
    const hasAlbumEdit = Object.prototype.hasOwnProperty.call(edits || {}, 'album');
    const hasExceptionEdit = Object.prototype.hasOwnProperty.call(edits || {}, 'exception_type');
    if (!hasAlbumEdit && !hasExceptionEdit) return;
    const normalizedPath = String(path || '');
    if (!normalizedPath) return;
    const track = tracksByPath.get(normalizedPath) || nextByPath.get(normalizedPath) || {};
    const albumName = hasAlbumEdit
      ? String(edits.album || '').trim()
      : String(
        Object.prototype.hasOwnProperty.call(track, 'album')
          ? track.album || ''
          : album?.raw_name || album?.name || '',
      ).trim();
    const exceptionType = hasExceptionEdit
      ? String(edits.exception_type || '').trim()
      : String(track?.exception_type || '').trim();
    if (albumName && !exceptionType) {
      nextByPath.delete(normalizedPath);
      return;
    }
    nextByPath.set(normalizedPath, {
      ...track,
      ...edits,
      path: normalizedPath,
      artist: String(track?.artist || album?.album_artist || 'Unknown Artist'),
      title: String(edits.title || track?.title || 'Unknown track'),
      album: albumName,
      exception_type: exceptionType,
      reason_label: exceptionType,
      display_path: String(track?.display_path || normalizedPath),
    });
  });
  view.non_album_tracks = Array.from(nextByPath.values());
  return view.non_album_tracks;
}

function normalizeCommittedTrackTagValues(values) {
  const nextValues = { ...(values || {}) };
  ['year', 'track_number', 'disc_number', 'album_rating'].forEach((field) => {
    if (Object.prototype.hasOwnProperty.call(nextValues, field)) {
      nextValues[field] = parseOptionalInteger(nextValues[field]);
    }
  });
  if (Object.prototype.hasOwnProperty.call(nextValues, 'exception_type')) {
    nextValues.exception_type = String(nextValues.exception_type || '').trim();
  }
  if (Object.prototype.hasOwnProperty.call(nextValues, 'edition')) {
    nextValues.edition = String(nextValues.edition || '').trim();
  }
  return nextValues;
}

function installCommittedTagValues(album, committedValues) {
  if (!committedValues || typeof committedValues !== 'object' || Array.isArray(committedValues)) {
    return;
  }
  const tagEditor = state.tagEditor || (state.tagEditor = {});
  const editorValues = tagEditor.values || (tagEditor.values = {});
  const trackCollections = [
    Array.isArray(album?.tracks) ? album.tracks : [],
    Array.isArray(tagEditor.tracks) ? tagEditor.tracks : [],
    Array.isArray(tagEditor.album?.tracks) ? tagEditor.album.tracks : [],
  ];
  const currentNonAlbumTracks = Array.isArray(state.view?.non_album_tracks)
    ? state.view.non_album_tracks
    : [];
  trackCollections.push(currentNonAlbumTracks);

  Object.entries(committedValues).forEach(([path, values]) => {
    const normalizedPath = String(path || '');
    if (!normalizedPath || !values || typeof values !== 'object' || Array.isArray(values)) return;
    editorValues[normalizedPath] = {
      ...(editorValues[normalizedPath] || {}),
      ...Object.fromEntries(
        Object.entries(values).map(([field, value]) => [field, String(value ?? '')]),
      ),
    };
    const normalizedValues = normalizeCommittedTrackTagValues(values);
    const seen = new Set();
    trackCollections.forEach((tracks) => {
      tracks.forEach((track) => {
        if (!track || seen.has(track) || String(track.path || '') !== normalizedPath) return;
        seen.add(track);
        Object.assign(track, normalizedValues);
      });
    });
  });

  applyTagEditsToNonAlbumView(album, committedValues);
}

function getTagEditorPendingIconMarkup() {
  return `
    <span class="tag-editor-track-pending" data-tag-editor-pending="1" role="img" aria-label="Pending changes" title="Pending changes">
      <svg viewBox="0 0 16 16" focusable="false" aria-hidden="true">
        <path d="M4 1h8M4 15h8M5 2v2.2c0 1.1.6 2.1 1.6 2.6L8 7.5l1.4-.7c1-.5 1.6-1.5 1.6-2.6V2M5 14v-2.2c0-1.1.6-2.1 1.6-2.6L8 8.5l1.4.7c1 .5 1.6 1.5 1.6 2.6V14"/>
      </svg>
    </span>`;
}

function syncTagEditorPendingChanges() {
  const els = getTagEditorElements();
  const pending = buildChangedTagEditorUpdates(
    state.tagEditor.album,
    state.tagEditor.tracks || [],
    state.tagEditor.values || {},
  );
  const pendingPaths = new Set(Object.keys(pending));
  if (els.albumInput) {
    els.albumInput.removeAttribute('aria-invalid');
    els.albumInput.removeAttribute('aria-describedby');
  }
  if (els.applyButton) {
    els.applyButton.disabled = pendingPaths.size === 0;
  }
  els.list?.querySelectorAll('[data-tag-editor-track]').forEach((button) => {
    const path = String(button.getAttribute('data-tag-editor-track') || '');
    const marker = button.querySelector('[data-tag-editor-pending="1"]');
    if (pendingPaths.has(path) && !marker) {
      button.insertAdjacentHTML('beforeend', getTagEditorPendingIconMarkup());
    } else if (!pendingPaths.has(path) && marker) {
      marker.remove();
    }
  });
  return pending;
}

function parseOptionalInteger(value) {
  const text = String(value ?? '').trim();
  if (!text) return null;
  const parsed = Number.parseInt(text, 10);
  return Number.isFinite(parsed) ? parsed : null;
}

function buildOptimisticUpdatedAlbumsFromEdits(album, updates) {
  const sourceTracks = deepCloneJson(Array.isArray(album?.tracks) ? album.tracks : []) || [];
  if (!sourceTracks.length) return [];
  const sourceTrackRows = Array.isArray(album?.track_rows) ? album.track_rows : null;
  const sourceTrackRowByPath = new Map(
    (sourceTrackRows || [])
      .map((row) => {
        const path = String(row?.path || row?.track_ref || '').trim();
        return path ? [path, row] : null;
      })
      .filter(Boolean),
  );
  const sourceTrackPaths = new Set(
    sourceTracks.map((track) => String(track?.path || '')).filter(Boolean),
  );
  const visibleSourceAlbum = findVisibleAlbumByTrackPaths(sourceTrackPaths);
  const sourceAlbumPreference = album?.album_preference
    || visibleSourceAlbum?.album_preference
    || null;
  const sourceKey = String(album?.key || '').trim().toLowerCase();
  const sourceSeparateReleaseMarkerIndex = sourceKey.indexOf('::year::');
  const sourceSeparateReleaseBaseKey = sourceSeparateReleaseMarkerIndex >= 0
    ? sourceKey.slice(0, sourceSeparateReleaseMarkerIndex)
    : '';
  const updatedTracks = sourceTracks.map((track) => {
    const path = String(track?.path || '');
    const edits = updates?.[path];
    const inheritedEdition = String(track?.edition || album?.edition || '').trim();
    if (!edits || typeof edits !== 'object') {
      return {
        ...track,
        edition: inheritedEdition || null,
      };
    }
    const hasYearEdit = Object.prototype.hasOwnProperty.call(edits, 'year');
    return {
      ...track,
      ...edits,
      year: hasYearEdit ? parseOptionalInteger(edits.year) : parseOptionalInteger(track?.year ?? album?.year),
      track_number: Object.prototype.hasOwnProperty.call(edits, 'track_number') ? parseOptionalInteger(edits.track_number) : track.track_number,
      disc_number: Object.prototype.hasOwnProperty.call(edits, 'disc_number') ? parseOptionalInteger(edits.disc_number) : track.disc_number,
      album_rating: Object.prototype.hasOwnProperty.call(edits, 'album_rating') ? parseOptionalInteger(edits.album_rating) : track.album_rating,
      edition: Object.prototype.hasOwnProperty.call(edits, 'edition')
        ? String(edits.edition || '').trim()
        : (inheritedEdition || null),
      exception_type: Object.prototype.hasOwnProperty.call(edits, 'exception_type') ? String(edits.exception_type || '').trim() : track.exception_type,
    };
  });

  const grouped = new Map();
  updatedTracks.forEach((track) => {
    if (String(track?.exception_type || '').trim()) return;
    const albumArtist = String(track?.album_artist || album?.album_artist || '').trim();
    const albumName = String(track?.album ?? album?.name ?? '').trim();
    if (!albumName) return;
    const edits = updates?.[String(track?.path || '')];
    const hasEditionEdit = Boolean(
      edits
      && typeof edits === 'object'
      && Object.prototype.hasOwnProperty.call(edits, 'edition')
    );
    const edition = String(
      hasEditionEdit ? track?.edition : (track?.edition || album?.edition || ''),
    ).trim();
    const hasYearEdit = Boolean(
      edits
      && typeof edits === 'object'
      && Object.prototype.hasOwnProperty.call(edits, 'year')
    );
    const year = parseOptionalInteger(hasYearEdit ? track?.year : (album?.year ?? track?.year));
    const groupingKey = [
      albumArtist.toLowerCase(),
      albumName.toLowerCase(),
      edition.toLowerCase(),
      year != null ? String(year) : '',
    ].join('::');
    const canonicalKeyParts = [
      albumArtist.toLowerCase(),
      albumName.toLowerCase(),
    ];
    if (edition) canonicalKeyParts.push(edition.toLowerCase());
    const canonicalBaseKey = canonicalKeyParts.join('::');
    if (sourceSeparateReleaseBaseKey === canonicalBaseKey && year != null) {
      canonicalKeyParts.push('year', String(year).toLowerCase());
    }
    if (!grouped.has(groupingKey)) {
      let albumPreference = deepCloneJson(sourceAlbumPreference);
      const preferenceRating = parseOptionalInteger(albumPreference?.rating);
      const visiblePreferenceRating = parseOptionalInteger(
        visibleSourceAlbum?.album_preference?.rating,
      );
      const legacyRating = parseOptionalInteger(track?.album_rating)
        ?? parseOptionalInteger(album?.album_rating)
        ?? parseOptionalInteger(visibleSourceAlbum?.album_rating);
      const normalizedRating = preferenceRating ?? visiblePreferenceRating ?? legacyRating;
      if (normalizedRating != null) {
        if (!albumPreference || typeof albumPreference !== 'object' || Array.isArray(albumPreference)) {
          albumPreference = {};
        }
        albumPreference.rating = normalizedRating;
      }
      grouped.set(groupingKey, {
        key: canonicalKeyParts.join('::'),
        name: albumName,
        album_artist: albumArtist,
        cover_path: track?.cover_path || album?.cover_path || null,
        remote_cover_url: track?.remote_cover_url || album?.remote_cover_url || null,
        remote_cover_thumbnail_url: track?.remote_cover_thumbnail_url || album?.remote_cover_thumbnail_url || null,
        remote_cover_source: track?.remote_cover_source || album?.remote_cover_source || null,
        remote_cover_source_label: track?.remote_cover_source_label || album?.remote_cover_source_label || null,
        remote_cover_album_url: track?.remote_cover_album_url || album?.remote_cover_album_url || null,
        remote_cover_width: track?.remote_cover_width || album?.remote_cover_width || null,
        remote_cover_height: track?.remote_cover_height || album?.remote_cover_height || null,
        year,
        release_date: String(album?.release_date || '').trim(),
        edition: edition || null,
        album_rating: normalizedRating ?? 0,
        album_preference: albumPreference,
        total_duration_seconds: 0,
        total_duration_display: '',
        tracks: [],
        ...(sourceTrackRows ? { track_rows: [] } : {}),
      });
    }
    const bucket = grouped.get(groupingKey);
    bucket.tracks.push(track);
    const sourceTrackRow = sourceTrackRowByPath.get(String(track?.path || '').trim());
    const invalidatesServerTrackRow = Boolean(
      edits
      && ['artist', 'album_artist', 'title'].some((field) => (
        Object.prototype.hasOwnProperty.call(edits, field)
      )),
    );
    if (sourceTrackRow && !invalidatesServerTrackRow && Array.isArray(bucket.track_rows)) {
      bucket.track_rows.push(deepCloneJson(sourceTrackRow));
    }
    bucket.total_duration_seconds += Number(track?.duration_seconds || 0);
    if (!bucket.cover_path && track?.cover_path) bucket.cover_path = track.cover_path;
    if (!bucket.remote_cover_url && track?.remote_cover_url) {
      bucket.remote_cover_url = track.remote_cover_url;
      bucket.remote_cover_thumbnail_url = track?.remote_cover_thumbnail_url || track.remote_cover_url;
      bucket.remote_cover_source = track?.remote_cover_source || null;
      bucket.remote_cover_source_label = track?.remote_cover_source_label || null;
      bucket.remote_cover_album_url = track?.remote_cover_album_url || null;
      bucket.remote_cover_width = track?.remote_cover_width || null;
      bucket.remote_cover_height = track?.remote_cover_height || null;
    }
    if (!bucket.album_rating) bucket.album_rating = parseOptionalInteger(track?.album_rating) || 0;
  });

  const groupedAlbums = Array.from(grouped.values());
  const groupedAlbumBaseKeyCounts = groupedAlbums.reduce((counts, groupedAlbum) => {
    const key = String(groupedAlbum?.key || '');
    const yearMarkerIndex = key.indexOf('::year::');
    const baseKey = yearMarkerIndex >= 0 ? key.slice(0, yearMarkerIndex) : key;
    counts.set(baseKey, Number(counts.get(baseKey) || 0) + 1);
    return counts;
  }, new Map());
  groupedAlbums.forEach((groupedAlbum) => {
    const key = String(groupedAlbum?.key || '');
    const yearMarkerIndex = key.indexOf('::year::');
    const baseKey = yearMarkerIndex >= 0 ? key.slice(0, yearMarkerIndex) : key;
    const year = parseOptionalInteger(groupedAlbum?.year);
    if (year != null && Number(groupedAlbumBaseKeyCounts.get(baseKey) || 0) > 1) {
      groupedAlbum.key = `${baseKey}::year::${year}`;
    }
  });

  return groupedAlbums
    .map((bucket) => {
      const tracks = bucket.tracks.slice().sort((left, right) => {
        const discCompare = Number(left?.disc_number ?? 999) - Number(right?.disc_number ?? 999);
        if (discCompare) return discCompare;
        const trackCompare = Number(left?.track_number ?? 999) - Number(right?.track_number ?? 999);
        if (trackCompare) return trackCompare;
        return String(left?.title || '').localeCompare(String(right?.title || ''), undefined, { sensitivity: 'base' });
      });
      const distinctTrackArtists = new Map();
      tracks.forEach((track) => {
        const artist = String(track?.artist || '').trim();
        const key = artist.toLocaleLowerCase();
        if (artist && !distinctTrackArtists.has(key)) distinctTrackArtists.set(key, artist);
      });
      const destinationAlbumArtistKey = String(bucket.album_artist || '').trim().toLocaleLowerCase();
      const promotesSoleCompilationArtist = (
        ['va', 'v.a.', 'various artists', 'various artist', 'various'].includes(destinationAlbumArtistKey)
        && distinctTrackArtists.size === 1
      );
      const promotedAlbumArtist = promotesSoleCompilationArtist
        ? Array.from(distinctTrackArtists.values())[0]
        : '';
      const promotedAlbumArtistKey = promotedAlbumArtist.toLocaleLowerCase();
      const trackRows = Array.isArray(bucket.track_rows)
        ? bucket.track_rows.map((row) => {
          if (!promotedAlbumArtist) return row;
          const secondaryCredits = String(row?.secondary_artist || '')
            .split(/\s+\/\s+/)
            .map((credit) => credit.trim())
            .filter((credit) => credit && credit.toLocaleLowerCase() !== promotedAlbumArtistKey);
          return {
            ...row,
            secondary_artist: secondaryCredits.join(' / ') || null,
          };
        })
        : null;
      return {
        ...bucket,
        ...(promotedAlbumArtist ? {
          album_artist: promotedAlbumArtist,
          key: [promotedAlbumArtistKey, ...String(bucket.key || '').split('::').slice(1)].join('::'),
        } : {}),
        ...(trackRows ? { track_rows: trackRows } : {}),
        preview_only: false,
        track_count_preview: tracks.length,
        track_paths: tracks.map((track) => String(track?.path || '')).filter(Boolean),
        total_duration_display: formatCanonicalAlbumDuration(bucket.total_duration_seconds),
        tracks,
      };
    })
    .sort((left, right) => String(left.album_artist || '').localeCompare(String(right.album_artist || ''), undefined, { sensitivity: 'base' }));
}

function getSelectedTagEditorPaths(tracks) {
  const validPaths = new Set((tracks || []).map((track) => String(track.path || '')).filter(Boolean));
  let selectedPaths = Array.isArray(state.tagEditor.selectedPaths)
    ? state.tagEditor.selectedPaths.map((path) => String(path || '')).filter((path) => validPaths.has(path))
    : [];
  if (!Array.isArray(state.tagEditor.selectedPaths) && state.tagEditor.selectedPath && validPaths.has(String(state.tagEditor.selectedPath))) {
    selectedPaths = [String(state.tagEditor.selectedPath)];
  }
  if (!Array.isArray(state.tagEditor.selectedPaths) && !selectedPaths.length && tracks.length) {
    selectedPaths = [String(tracks[0].path || '')].filter(Boolean);
  }
  state.tagEditor.selectedPaths = selectedPaths;
  state.tagEditor.selectedPath = selectedPaths[0] || '';
  return selectedPaths;
}

function getTagEditorTrackPathAt(index) {
  const track = (state.tagEditor.tracks || [])[index];
  return String(track?.path || '');
}

function getTagEditorTrackIndex(path) {
  return (state.tagEditor.tracks || []).findIndex((track) => String(track.path || '') === String(path || ''));
}

function getTagEditorRangePaths(startPath, endPath) {
  const startIndex = getTagEditorTrackIndex(startPath);
  const endIndex = getTagEditorTrackIndex(endPath);
  if (startIndex < 0 || endIndex < 0) return [String(endPath || '')].filter(Boolean);
  const first = Math.min(startIndex, endIndex);
  const last = Math.max(startIndex, endIndex);
  const paths = [];
  for (let index = first; index <= last; index += 1) {
    const path = getTagEditorTrackPathAt(index);
    if (path) paths.push(path);
  }
  return paths;
}

function setTagEditorSelectedPaths(paths, anchorPath = '') {
  const seen = new Set();
  const validPaths = new Set((state.tagEditor.tracks || []).map((track) => String(track.path || '')).filter(Boolean));
  const selectedPaths = (paths || [])
    .map((path) => String(path || ''))
    .filter((path) => path && validPaths.has(path) && !seen.has(path) && seen.add(path));
  state.tagEditor.selectedPaths = selectedPaths;
  state.tagEditor.selectedPath = state.tagEditor.selectedPaths[0] || '';
  state.tagEditor.anchorPath = anchorPath || state.tagEditor.anchorPath || state.tagEditor.selectedPath;
  state.tagEditor.autoNumberStatus = '';
}

function selectTagEditorTrack(path, event = {}) {
  const normalizedPath = String(path || '');
  if (!normalizedPath) return;
  const selectedPaths = getSelectedTagEditorPaths(state.tagEditor.tracks || []);
  const anchorPath = state.tagEditor.anchorPath || selectedPaths[0] || normalizedPath;
  if (event.shiftKey) {
    const rangePaths = getTagEditorRangePaths(anchorPath, normalizedPath);
    setTagEditorSelectedPaths(event.ctrlKey || event.metaKey ? [...selectedPaths, ...rangePaths] : rangePaths, anchorPath);
    return;
  }
  if (event.ctrlKey || event.metaKey) {
    const alreadySelected = selectedPaths.includes(normalizedPath);
    const nextPaths = alreadySelected && selectedPaths.length > 1
      ? selectedPaths.filter((selectedPath) => selectedPath !== normalizedPath)
      : [...selectedPaths, normalizedPath];
    setTagEditorSelectedPaths(nextPaths, normalizedPath);
    return;
  }
  setTagEditorSelectedPaths([normalizedPath], normalizedPath);
}

function getTagEditorFieldDisplayValue(field, selectedPaths) {
  const valuesByPath = state.tagEditor.values || {};
  const selectedValues = selectedPaths.map((path) => String(valuesByPath[path]?.[field] ?? ''));
  if (!selectedValues.length) return { value: '', mixed: false };
  const firstValue = selectedValues[0];
  const mixed = selectedValues.some((value) => value !== firstValue);
  return { value: mixed ? '' : firstValue, mixed };
}

function renderTagEditorArtwork(selectedPaths) {
  const els = getTagEditorElements();
  if (!els.artwork) return;
  const firstSelectedPath = selectedPaths[0] || '';
  const track = (state.tagEditor.tracks || []).find((item) => String(item.path || '') === firstSelectedPath);
  const coverPath = track?.cover_path || state.tagEditor.album?.cover_path || '';
  const label = getFilenameFromPath(firstSelectedPath) || track?.title || 'selected track';
  els.artwork.innerHTML = coverPath
    ? `<img src="/cover?path=${encodeURIComponent(coverPath)}" alt="Artwork for ${escapeHtml(label)}">`
    : '<div class="tag-editor-artwork-placeholder">No artwork</div>';
}

function stageTagEditorTrackOrder(tracks) {
  const orderedTracks = Array.isArray(tracks) ? tracks : [];
  orderedTracks.forEach((track, index) => {
    const path = String(track?.path || '');
    if (!path) return;
    state.tagEditor.values[path] = {
      ...(state.tagEditor.values[path] || {}),
      track_number: String(index + 1),
    };
  });
  state.tagEditor.autoNumberActive = false;
  state.tagEditor.autoNumberAppliedSelectionSignature = '';
  state.tagEditor.autoNumberTrackNumberSnapshots = {};
}

function applyTagEditorTrackReorder(draggedPath, beforePath = null) {
  const previous = Array.isArray(state.tagEditor.tracks) ? state.tagEditor.tracks : [];
  const reordered = reorderTagEditorTracksByPath(previous, draggedPath, beforePath);
  if (reordered.every((track, index) => track === previous[index])) return false;
  state.tagEditor.tracks = reordered;
  stageTagEditorTrackOrder(reordered);
  renderTagEditor();
  syncTagEditorAutoNumberControls();
  return true;
}

function clearTagEditorReorderCue() {
  const list = getTagEditorElements().list;
  list?.classList?.remove('is-reorder-end');
  list?.querySelectorAll?.('[data-tag-editor-track]').forEach((row) => {
    row.classList?.remove('is-reorder-before', 'is-reorder-dragged');
  });
  state.tagEditor.reorder = null;
}

function showTagEditorReorderCue(beforePath = null) {
  const list = getTagEditorElements().list;
  if (!list) return;
  list.classList.remove('is-reorder-end');
  list.querySelectorAll('[data-tag-editor-track]').forEach((row) => {
    const path = String(row.getAttribute('data-tag-editor-track') || '');
    row.classList.toggle('is-reorder-before', Boolean(beforePath) && path === String(beforePath));
    row.classList.toggle('is-reorder-dragged', path === String(state.tagEditor.reorder?.draggedPath || ''));
  });
  if (!beforePath) list.classList.add('is-reorder-end');
  if (state.tagEditor.reorder) state.tagEditor.reorder.beforePath = beforePath || null;
}

function renderTagEditor(options = {}) {
  const els = getTagEditorElements();
  if (!els.overlay || !els.list || !els.form) return;
  const album = state.tagEditor.album;
  const tracks = state.tagEditor.tracks || [];
  if (!album || !tracks.length) return;

  const selectedPaths = getSelectedTagEditorPaths(tracks);
  const selectedPathSet = new Set(selectedPaths);

  if (els.subtitle) {
    els.subtitle.textContent = `${album.tag_editor_title || album.name || 'Album'} - ${tracks.length} file${tracks.length === 1 ? '' : 's'} in editor - ${selectedPaths.length} selected`;
  }
  renderTagEditorArtwork(selectedPaths);
  if (els.autoNumberButton) {
    els.autoNumberButton.disabled = selectedPaths.length < 2;
  }
  if (els.autoNumberStatus) {
    els.autoNumberStatus.textContent = String(state.tagEditor.autoNumberStatus || '');
  }

  const existingTrackButtons = options.preserveTrackList
    ? Array.from(els.list.querySelectorAll('[data-tag-editor-track]'))
    : [];
  const canPreserveTrackList = existingTrackButtons.length === tracks.length
    && tracks.every((track, index) => (
      String(existingTrackButtons[index]?.getAttribute('data-tag-editor-track') || '')
      === String(track.path || '')
    ));
  if (canPreserveTrackList) {
    existingTrackButtons.forEach((button) => {
      const path = String(button.getAttribute('data-tag-editor-track') || '');
      const isSelected = selectedPathSet.has(path);
      button.classList.toggle('is-active', isSelected);
      button.querySelector?.('.tag-editor-track-select')
        ?.setAttribute?.('aria-pressed', isSelected ? 'true' : 'false');
    });
  } else {
    const rows = tracks.map((track) => {
      const path = String(track.path || '');
      const fileType = getFileTypeFromPath(path);
      const filename = getFilenameFromPath(path) || track.title || path;
      return `
        <div class="tag-editor-track ${selectedPathSet.has(path) ? 'is-active' : ''}" role="listitem" data-tag-editor-track="${escapeHtml(path)}" title="${escapeHtml(path)}">
          <span class="tag-editor-track-accent" aria-hidden="true"></span>
          <button class="tag-editor-reorder-grip" type="button" draggable="true" data-tag-editor-reorder-grip="${escapeHtml(path)}" aria-label="Reorder ${escapeHtml(filename)}; use Arrow Up or Arrow Down"><span aria-hidden="true">⋮⋮</span></button>
          <button class="tag-editor-track-select" type="button" aria-pressed="${selectedPathSet.has(path) ? 'true' : 'false'}">
            <span class="tag-editor-track-title">${escapeHtml(filename)}</span>
            ${fileType ? `<span class="utility-repair-file-type">${escapeHtml(fileType)}</span>` : ''}
          </button>
        </div>
      `;
    });
    els.list.setAttribute('role', 'list');
    els.list.setAttribute('aria-label', 'Files to edit');
    els.list.innerHTML = rows.join('');
  }

  els.form.querySelectorAll('[data-tag-field]').forEach((input) => {
    const field = input.getAttribute('data-tag-field') || '';
    const displayValue = getTagEditorFieldDisplayValue(field, selectedPaths);
    input.disabled = selectedPaths.length === 0;
    input.value = displayValue.value;
    input.placeholder = displayValue.mixed ? 'Mixed values' : '';
  });
  syncTagEditorPendingChanges();
}

// END js/runtime/utility-loaders-and-cover-lookup.js

// BEGIN js/runtime/cover-lookup-modal-and-drawer.js

function getCoverLookupModalElements() {
  return {
    overlay: document.getElementById('cover-lookup-modal'),
    body: document.getElementById('cover-lookup-modal-body'),
    subtitle: document.getElementById('cover-lookup-modal-subtitle'),
    status: document.getElementById('cover-lookup-modal-status'),
    findBetter: document.getElementById('cover-lookup-find-better-button'),
    saveRemote: document.getElementById('cover-lookup-save-remote-button'),
    pastedUrls: document.getElementById('cover-lookup-pasted-urls'),
  };
}

const MAX_COVER_LOOKUP_STAGED_IMAGES = 8;
const MAX_COVER_LOOKUP_IMAGE_BYTES = 10 * 1024 * 1024;

function revokeCoverLookupPastedImageUrls() {
  const items = [
    ...(Array.isArray(state.coverLookup.modal.pastedImages) ? state.coverLookup.modal.pastedImages : []),
    ...(Array.isArray(state.coverLookup.modal.manualImageAttachments) ? state.coverLookup.modal.manualImageAttachments : []),
  ];
  items.forEach((item) => {
    const objectUrl = String(item?.object_url || '').trim();
    if (objectUrl.startsWith('blob:')) {
      try {
        URL.revokeObjectURL(objectUrl);
      } catch (_error) {
        // Ignore revoked or invalid object URLs.
      }
    }
  });
}

function buildCoverLookupPastedImageId() {
  return `pasted:${Date.now()}:${Math.random().toString(36).slice(2, 10)}`;
}

function fileToDataUrl(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result || ''));
    reader.onerror = () => reject(new Error('Failed to read pasted image.'));
    reader.readAsDataURL(file);
  });
}

async function addPastedImageToCoverLookup(file) {
  if (window.AlbumHavenCapabilities && !window.AlbumHavenCapabilities.allows('library.covers.upload')) return;
  if (!(file instanceof Blob) || !String(file.type || '').startsWith('image/')) {
    throw new Error('Choose an image file.');
  }
  if (Number(file.size || 0) > MAX_COVER_LOOKUP_IMAGE_BYTES) {
    throw new Error('Images must be 10 MB or smaller.');
  }
  const stagedCount = (Array.isArray(state.coverLookup.modal.pastedImages)
    ? state.coverLookup.modal.pastedImages.length : 0)
    + (Array.isArray(state.coverLookup.modal.manualImageAttachments)
      ? state.coverLookup.modal.manualImageAttachments.length : 0);
  if (stagedCount >= MAX_COVER_LOOKUP_STAGED_IMAGES) {
    throw new Error(`You can stage up to ${MAX_COVER_LOOKUP_STAGED_IMAGES} images.`);
  }
  const dataUrl = await fileToDataUrl(file);
  if (!dataUrl) {
    throw new Error('Failed to read pasted image.');
  }
  const objectUrl = URL.createObjectURL(file);
  const nextItem = {
    id: buildCoverLookupPastedImageId(),
    filename: String(file.name || 'Pasted image').trim() || 'Pasted image',
    album: 'Pasted image',
    resolution: 'Clipboard image',
    width: 0,
    height: 0,
    object_url: objectUrl,
    data_url: dataUrl,
    mime_type: String(file.type || 'image/png').trim() || 'image/png',
    size_bytes: Number(file.size || 0) || 0,
  };
  state.coverLookup.modal.manualImageAttachments = [
    ...(Array.isArray(state.coverLookup.modal.manualImageAttachments)
      ? state.coverLookup.modal.manualImageAttachments : []),
    nextItem,
  ];
  state.coverLookup.modal.statusText = 'Image ready to extract.';
  state.coverLookup.modal.statusTone = 'neutral';
  renderCoverLookupModal();
  return true;
}

async function addCoverLookupFiles(files) {
  const candidates = Array.from(files || []);
  let added = 0;
  for (const file of candidates) {
    await addPastedImageToCoverLookup(file);
    added += 1;
  }
  return added;
}

function removePastedImageFromCoverLookup(imageId) {
  const id = String(imageId || '').trim();
  const items = Array.isArray(state.coverLookup.modal.pastedImages)
    ? state.coverLookup.modal.pastedImages : [];
  const removed = items.find(item => String(item?.id || '') === id);
  if (!removed) return false;
  const objectUrl = String(removed.object_url || '').trim();
  if (objectUrl.startsWith('blob:')) URL.revokeObjectURL(objectUrl);
  state.coverLookup.modal.pastedImages = items.filter(item => String(item?.id || '') !== id);
  if (String(state.coverLookup.modal.pendingPastedImageId || '') === id) {
    state.coverLookup.modal.pendingPastedImageId = '';
  }
  renderCoverLookupModal();
  return true;
}

function removeCoverLookupPendingAttachment(imageId) {
  const id = String(imageId || '').trim();
  const items = Array.isArray(state.coverLookup.modal.manualImageAttachments)
    ? state.coverLookup.modal.manualImageAttachments : [];
  const removed = items.find(item => String(item?.id || '') === id);
  if (!removed) return false;
  const objectUrl = String(removed.object_url || '').trim();
  if (objectUrl.startsWith('blob:')) URL.revokeObjectURL(objectUrl);
  state.coverLookup.modal.manualImageAttachments = items.filter(
    item => String(item?.id || '') !== id,
  );
  renderCoverLookupModal();
  return true;
}

function extractCoverLookupPendingAttachments() {
  const attachments = Array.isArray(state.coverLookup.modal.manualImageAttachments)
    ? state.coverLookup.modal.manualImageAttachments : [];
  if (!attachments.length) return 0;
  state.coverLookup.modal.pastedImages = [
    ...attachments,
    ...(Array.isArray(state.coverLookup.modal.pastedImages)
      ? state.coverLookup.modal.pastedImages : []),
  ];
  state.coverLookup.modal.manualImageAttachments = [];
  return attachments.length;
}

async function handleCoverLookupClipboardPaste(clipboardData) {
  const items = Array.from(clipboardData?.items || []);
  const imageItem = items.find((item) => String(item?.type || '').startsWith('image/'));
  if (!imageItem || typeof imageItem.getAsFile !== 'function') {
    return false;
  }
  const file = imageItem.getAsFile();
  if (!(file instanceof Blob)) {
    return false;
  }
  await addPastedImageToCoverLookup(file);
  return true;
}

function getCoverLookupDeleteConfirmElements() {
  return {
    overlay: document.getElementById('cover-lookup-delete-confirm-modal'),
    text: document.getElementById('cover-lookup-delete-confirm-text'),
  };
}

function buildCoverLookupAlbumSubtitle(album) {
  if (!album) return '';
  return [album.album_artist || '', album.name || '', album.year || ''].filter(Boolean).join(' - ');
}

function buildTrackPathSignature(album) {
  const tracks = Array.isArray(album?.tracks) ? album.tracks : [];
  return tracks.map((track) => String(track?.path || '')).filter(Boolean).sort().join('::');
}

function buildRemoteCoverLookupPreviewUrl(url) {
  const raw = String(url || '').trim();
  if (!raw) return '';
  return `/utilities/cover-lookup/remote-image?url=${encodeURIComponent(raw)}`;
}

function buildRemoteCoverLookupImageUrl(url, key = '') {
  const raw = String(url || '').trim();
  if (!raw) return '';
  const params = new URLSearchParams({ url: raw });
  if (key) params.set('key', String(key));
  return `/utilities/cover-lookup/remote-image?${params.toString()}`;
}

function buildRemoteCoverLookupDisplayUrl(item, preferredUrl, key = '') {
  const raw = String(preferredUrl || '').trim();
  if (!raw) return '';
  return buildRemoteCoverLookupImageUrl(raw, key);
}

function buildCoverLookupSearchQuery(album) {
  return [album?.album_artist || '', album?.name || '', album?.year || '', 'album cover']
    .filter(Boolean)
    .join(' ')
    .trim();
}

function buildCoverLookupImageSearchUrl(engine, album) {
  const query = encodeURIComponent(buildCoverLookupSearchQuery(album));
  if (engine === 'yandex') {
    return `https://yandex.com/images/search?text=${query}`;
  }
  return `https://www.google.com/search?tbm=isch&q=${query}`;
}

function logCoverLookupTaskDebug(context, task) {
  if (!task || typeof task !== 'object') return;
  const possibleMatches = Array.isArray(task.possible_matches) ? task.possible_matches : [];
  console.log(`[AlbumHaven][CoverLookup] ${context}`, {
    id: String(task.id || ''),
    status: String(task.status || ''),
    progress: Number(task.progress || 0),
    progress_label: String(task.progress_label || ''),
    message: String(task.message || ''),
    possible_matches_count: possibleMatches.length,
    possible_matches: possibleMatches,
  });
}

function reconcileCoverLookupRemoteSelection(possibleMatches) {
  const matches = Array.isArray(possibleMatches) ? possibleMatches : [];
  const selectedRemoteId = String(state.coverLookup.modal.selectedRemoteId || '');
  const selectedMatchExists = selectedRemoteId
    && matches.some((candidate) => String(candidate?.id || '') === selectedRemoteId);
  if (selectedMatchExists) return;
  state.coverLookup.modal.selectedRemoteId = '';
  if (
    String(state.coverLookup.modal.pendingLocalPath || '')
    || String(state.coverLookup.modal.pendingPastedImageId || '')
  ) {
    return;
  }
  const selectableMatches = matches.filter((candidate) => (
    String(candidate?.id || '').trim()
    && String(candidate?.art_kind || 'cover') === 'cover'
    && !Boolean(candidate?.display_only)
  ));
  if (selectableMatches.length) {
    state.coverLookup.modal.selectedRemoteId = String(selectableMatches[0].id);
  }
}

function normalizeCoverLookupCandidateSnapshot(value) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return null;
  const searchGeneration = String(value.search_generation || '').trim();
  const diagnostic = String(value.diagnostic || '').trim();
  if (!searchGeneration && !diagnostic) return null;
  return {
    ...value,
    search_generation: searchGeneration,
    diagnostic,
    search_kind: String(value.search_kind || '').trim(),
    status: String(value.status || '').trim(),
    revision: Math.max(0, Number(value.revision || 0) || 0),
    updated_at: String(value.updated_at || '').trim(),
    best_candidate_id: String(value.best_candidate_id || '').trim(),
    has_unseen_automatic_improvement: Boolean(
      value.has_unseen_automatic_improvement ?? value.unseen_automatic_improvement,
    ),
    candidates: sanitizeCoverLookupPossibleMatches(value.candidates),
  };
}

function getCoverLookupCandidateSource(task, candidateSnapshot) {
  const normalizedTask = task && typeof task === 'object' ? task : null;
  const normalizedSnapshot = normalizeCoverLookupCandidateSnapshot(candidateSnapshot);
  if (!normalizedTask) {
    return normalizedSnapshot ? {
      candidates: normalizedSnapshot.candidates,
      generation: normalizedSnapshot.search_generation,
      bestCandidateId: normalizedSnapshot.best_candidate_id,
      revision: normalizedSnapshot.revision,
      status: normalizedSnapshot.status,
    } : null;
  }
  const taskGeneration = String(normalizedTask.id || '').trim();
  const taskCandidates = sanitizeCoverLookupPossibleMatches(normalizedTask.possible_matches);
  if (
    normalizedSnapshot
    && normalizedSnapshot.search_generation !== taskGeneration
    && taskCandidates.length === 0
  ) {
    return {
      candidates: normalizedSnapshot.candidates,
      generation: normalizedSnapshot.search_generation,
      bestCandidateId: normalizedSnapshot.best_candidate_id,
      revision: normalizedSnapshot.revision,
      status: normalizedSnapshot.status,
    };
  }
  if (
    normalizedSnapshot
    && normalizedSnapshot.search_generation === taskGeneration
    && (
      taskCandidates.length === 0
      || coverLookupCandidateTimestamp(normalizedSnapshot.updated_at)
        > coverLookupCandidateTimestamp(normalizedTask.candidate_updated_at)
    )
  ) {
    return {
      candidates: normalizedSnapshot.candidates,
      generation: normalizedSnapshot.search_generation,
      bestCandidateId: normalizedSnapshot.best_candidate_id,
      revision: normalizedSnapshot.revision,
      status: normalizedSnapshot.status,
    };
  }
  return {
    candidates: taskCandidates,
    generation: taskGeneration,
    bestCandidateId: String(normalizedTask.best_candidate_id || '').trim(),
    revision: Math.max(0, Number(normalizedTask.candidate_revision || 0) || 0),
    status: String(normalizedTask.status || '').trim(),
  };
}

function coverLookupCandidateTimestamp(value) {
  const timestamp = Date.parse(String(value || '').trim());
  return Number.isFinite(timestamp) ? timestamp : 0;
}

function applyCoverLookupCandidateSource(candidateSource) {
  if (!candidateSource) return;
  const modal = state.coverLookup.modal;
  const generation = String(candidateSource.generation || '').trim();
  if (generation !== String(modal.candidateGeneration || '').trim()) {
    modal.candidateGeneration = generation;
    modal.remoteSelectionOverrideGeneration = '';
    modal.remoteSelectionOverrideCandidateId = '';
    modal.remoteSelectionOverrideUrl = '';
  }
  const possibleMatches = sanitizeCoverLookupPossibleMatches(candidateSource.candidates);
  modal.possibleMatches = possibleMatches;
  const hasPendingNonRemoteSelection = Boolean(
    String(modal.pendingLocalPath || '')
    || String(modal.pendingPastedImageId || '')
    || (modal.localCovers || []).some((cover) => Boolean(cover?.is_active))
    || String(modal.activeLocalSelectionPath || '')
    || String(getCoverLookupActiveLocalPath() || '')
  );
  const userOverrodeThisGeneration = Boolean(
    generation
    && String(modal.remoteSelectionOverrideGeneration || '') === generation
  );
  const bestCandidateId = String(candidateSource.bestCandidateId || '').trim();
  const bestCandidateIsSelectable = bestCandidateId && possibleMatches.some((candidate) => (
    String(candidate?.id || '') === bestCandidateId
    && String(candidate?.art_kind || 'cover') === 'cover'
    && !Boolean(candidate?.display_only)
  ));
  if (userOverrodeThisGeneration) {
    const overrideCandidateId = String(
      modal.remoteSelectionOverrideCandidateId || modal.selectedRemoteId || '',
    );
    const overrideUrl = normalizeCoverLookupCandidateUrl(
      modal.remoteSelectionOverrideUrl || '',
    ).toLowerCase();
    const selectedOverride = possibleMatches.find((candidate) => (
      String(candidate?.id || '') === overrideCandidateId
      || (
        overrideUrl
        && normalizeCoverLookupCandidateUrl(candidate?.url).toLowerCase() === overrideUrl
      )
    ));
    modal.selectedRemoteId = String(selectedOverride?.id || '');
    return;
  }
  if (hasPendingNonRemoteSelection) {
    modal.selectedRemoteId = '';
    return;
  }
  if (bestCandidateIsSelectable) {
    modal.selectedRemoteId = bestCandidateId;
    return;
  }
  reconcileCoverLookupRemoteSelection(possibleMatches);
}

function applyCoverLookupGalleryPayload(gallery) {
  if (!gallery || typeof gallery !== 'object') return;
  const incomingLocalCovers = Array.isArray(gallery.local_covers) ? gallery.local_covers : [];
  const savedSource = String(gallery.selected_source_path || '');
  const candidates = [...incomingLocalCovers, ...(Array.isArray(gallery.other_art) ? gallery.other_art : [])];
  const incomingActiveLocalCover = !gallery.remote_cover
    ? candidates.find(cover => savedSource && String(cover?.path || '') === savedSource)
      || candidates.find(cover => Boolean(cover?.is_active) && cover?.path)
    : null;
  if (incomingActiveLocalCover) {
    state.coverLookup.modal.activeLocalSelectionPath = String(incomingActiveLocalCover.path);
    const revision = String(incomingActiveLocalCover.cover_revision || '').trim();
    if (revision && !state.coverLookup.modal.saving
        && revision === String(state.coverLookup.modal.album?.cover_revision || '').trim()) {
      markAlbumCoverPathsFresh([{ cover_path: incomingActiveLocalCover.path, cover_revision: revision }]);
    }
  }
  state.coverLookup.modal.remoteCover = gallery.remote_cover && typeof gallery.remote_cover === 'object' ? gallery.remote_cover : null;
  // The canonical copy is not a second artwork choice when the server verified
  // an identical source. Keep the real sources visible and the saved source selected.
  state.coverLookup.modal.localCovers = incomingLocalCovers.filter(cover => !(
    incomingActiveLocalCover && String(cover?.path || '') === String(gallery.active_cover_path || '')
    && String(cover?.path || '') !== String(incomingActiveLocalCover.path)
  ));
  state.coverLookup.modal.otherArt = Array.isArray(gallery.other_art) ? gallery.other_art : [];
  const task = gallery.task && typeof gallery.task === 'object' ? gallery.task : null;
  const candidateSnapshot = normalizeCoverLookupCandidateSnapshot(gallery.candidate_snapshot);
  state.coverLookup.modal.candidateSnapshot = candidateSnapshot;
  const candidateSource = getCoverLookupCandidateSource(task, candidateSnapshot);
  if (candidateSource) {
    const previousGeneration = String(state.coverLookup.modal.candidateGeneration || '').trim();
    applyCoverLookupCandidateSource(candidateSource);
    const firstLoadOfGeneration = previousGeneration !== String(candidateSource.generation || '').trim();
    const terminalCandidateSource = ['completed', 'failed', 'canceled'].includes(
      String(candidateSource.status || '').trim(),
    );
    const hasActiveLocalCover = state.coverLookup.modal.localCovers.some((cover) => Boolean(cover?.is_active));
    if (
      firstLoadOfGeneration
      && terminalCandidateSource
      && hasActiveLocalCover
      && !state.coverLookup.modal.remoteCover
    ) {
      state.coverLookup.modal.selectedRemoteId = '';
      state.coverLookup.modal.remoteSelectionOverrideGeneration = '';
      state.coverLookup.modal.remoteSelectionOverrideCandidateId = '';
      state.coverLookup.modal.remoteSelectionOverrideUrl = '';
    }
  }
  const activeCandidateGeneration = String(
    state.coverLookup.modal.candidateGeneration || '',
  ).trim();
  const userOverrodeActiveGeneration = Boolean(
    activeCandidateGeneration
    && String(state.coverLookup.modal.remoteSelectionOverrideGeneration || '')
      === activeCandidateGeneration
  );
  if (state.coverLookup.modal.remoteCover && !userOverrodeActiveGeneration) {
    state.coverLookup.modal.selectedRemoteId = '';
  }
  if (task) {
    state.coverLookup.modal.statusText = String(task.message || task.progress_label || '');
    state.coverLookup.modal.statusTone = getCoverLookupStatusTone(task);
    logCoverLookupTaskDebug('Gallery payload task update.', task);
  } else if (candidateSnapshot) {
    state.coverLookup.modal.statusText = String(candidateSnapshot.diagnostic || '');
    state.coverLookup.modal.statusTone = candidateSnapshot.status === 'failed' ? 'error' : 'neutral';
  }
}

async function markCoverLookupAutomaticImprovementSeen(candidateSnapshot) {
  const snapshot = normalizeCoverLookupCandidateSnapshot(candidateSnapshot);
  const album = state.coverLookup.modal.album;
  const session = coverLookupModalSession;
  const albumSnapshot = album?.cover_candidate_snapshot;
  const modalSnapshot = state.coverLookup.modal.candidateSnapshot;
  const automaticRevision = Math.max(0, Number(snapshot?.automatic_improvement_revision || 0) || 0);
  const seenRevision = Math.max(0, Number(snapshot?.seen_automatic_improvement_revision || 0) || 0);
  if (
    !album
    || !snapshot
    || !Boolean(snapshot.has_unseen_automatic_improvement)
    || automaticRevision <= seenRevision
  ) return;
  const seenToken = `${snapshot.search_generation}:${automaticRevision}`;
  if (String(state.coverLookup.modal.seenCandidateImprovementToken || '') === seenToken) return;
  state.coverLookup.modal.seenCandidateImprovementToken = seenToken;
  const requestOwner = {};
  coverLookupSeenRequests.set(album, requestOwner);
  try {
    const response = await fetch('/utilities/cover-lookup/gallery/mark-seen', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ album }),
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok || !data.ok) {
      throw new Error(data.error || 'Failed to mark cover candidate update as seen');
    }
    const markedSnapshot = normalizeCoverLookupCandidateSnapshot(data.candidate_snapshot) || {
      ...snapshot,
      seen_automatic_improvement_revision: automaticRevision,
      has_unseen_automatic_improvement: false,
    };
    const ownsResource = coverLookupSeenRequests.get(album) === requestOwner;
    const ownsModal = ownsResource && session === coverLookupModalSession
      && state.coverLookup.modal.album === album
      && state.coverLookup.modal.seenCandidateImprovementToken === seenToken
      && state.coverLookup.modal.candidateSnapshot === modalSnapshot;
    const overlay = getCoverLookupModalElements().overlay;
    const albumIsOpen = state.coverLookup.modal.album === album && overlay && !overlay.hidden;
    if (ownsResource && album.cover_candidate_snapshot === albumSnapshot
        && (!albumIsOpen || ownsModal)) {
      album.cover_candidate_snapshot = markedSnapshot;
    }
    if (!ownsModal) return;
    state.coverLookup.modal.candidateSnapshot = markedSnapshot;
    if (typeof document !== 'undefined' && typeof document.querySelector === 'function') {
      const lookupButton = document.querySelector('[data-open-track-modal-cover-lookup]');
      if (lookupButton) {
        lookupButton.classList?.remove('has-unseen-automatic-improvement');
        lookupButton.setAttribute?.('aria-label', 'Open cover art look up gallery');
      }
    }
  } catch (error) {
    if (coverLookupSeenRequests.get(album) === requestOwner
        && session === coverLookupModalSession && state.coverLookup.modal.album === album
        && state.coverLookup.modal.seenCandidateImprovementToken === seenToken) {
      state.coverLookup.modal.seenCandidateImprovementToken = '';
    }
    console.warn('[AlbumHaven][CoverLookup] Failed to mark automatic candidate update as seen.', error);
  } finally {
    if (coverLookupSeenRequests.get(album) === requestOwner) coverLookupSeenRequests.delete(album);
  }
}

function getCoverLookupActiveLocalPath() {
  const retainedPath = String(state.coverLookup.modal.activeLocalSelectionPath || '');
  if (retainedPath) return retainedPath;
  if (state.coverLookup.modal.remoteCover && typeof state.coverLookup.modal.remoteCover === 'object') {
    return '';
  }
  const localCandidates = [
    ...(Array.isArray(state.coverLookup.modal.localCovers) ? state.coverLookup.modal.localCovers : []),
    ...(Array.isArray(state.coverLookup.modal.otherArt) ? state.coverLookup.modal.otherArt : []),
  ];
  const activeItem = localCandidates.find((item) => Boolean(item?.is_active) && item?.path);
  if (activeItem?.path) {
    return String(activeItem.path);
  }
  return String(
    state.coverLookup.modal.album?.cover_path
      || state.coverLookup.modal.album?.art_path
      || ''
  );
}

