        if (state.player.coverLoadId !== loadId || isPlaybackLockedByAnotherTab()
          || state.player.current !== track || !isPlaybackOwnershipScopeCurrent(coverScope)
          || getActivePlaybackOwnershipHandle() !== coverClaim) return;
