  ui.recentSearchQueries = [
    value,
    ...readRecentSearchQueries().filter((item) => item.toLocaleLowerCase() !== key),
  ].slice(0, RECENT_SEARCH_LIMIT);
  setSessionStorageItem(scope.storageKey, JSON.stringify(ui.recentSearchQueries));
